var PTS3=[{"id":5834,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, че може да премине направо или да завие надясно?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24064.png","v":null,"a":[{"t":"на жълтия автомобил","ok":true,"i":null,"es":"para el coche AMARILLO"},{"t":"на синия автомобил","ok":true,"i":null,"es":"para el coche AZUL"},{"t":"на червения автомобил","ok":false,"i":null,"es":"para el coche ROJO"},{"t":"на зеления автомобил","ok":false,"i":null,"es":"para el coche VERDE"}],"es":"¿Para qué conductores la señal del agente significa paso PERMITIDO? (2 correctas)","explain":"PARA EL COCHE AMARILLO Y PARA EL COCHE AZUL. Dos correctas.\n\nQUÉ VES. Un AGENTE en el centro del cruce con los BRAZOS BAJADOS. Está de cara al coche ROJO (le muestra el pecho) y de espaldas al VERDE. El AMARILLO (a la izquierda) y el AZUL (a la derecha) lo ven de COSTADO.\n\nCÓMO SE LEE AL AGENTE CON LOS BRAZOS EXTENDIDOS O BAJADOS:\n• Si te muestra el COSTADO (izquierdo o derecho): puedes seguir RECTO o girar a la DERECHA.\n• Si te muestra el PECHO o la ESPALDA: prohibido pasar.\n\nPOR ESO pueden seguir recto o girar a la derecha el amarillo y el azul, que ven sus costados. El rojo (pecho) y el verde (espalda) tienen que parar.\n\n«EL ROJO» y «EL VERDE» son los cebos: están justo delante y detrás del agente, que es justo la posición que obliga a parar.\n\nCLAVE: costado = paso (recto y derecha); pecho o espalda = parar. Ver Leyes → «Quién manda sobre quién»."},{"id":5837,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, че може да премине направо или да завие надясно?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24081.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"para el coche ROJO"},{"t":"на зеления автомобил","ok":true,"i":null,"es":"para el coche VERDE"},{"t":"на жълтия автомобил","ok":false,"i":null,"es":"para el coche AMARILLO"},{"t":"на синия автомобил","ok":false,"i":null,"es":"para el coche AZUL"}],"es":"¿Para qué conductores la señal del agente significa paso PERMITIDO? (2 correctas)","explain":"⚠️ TRAMPA color: el rojo Y el verde pueden pasar. El amarillo y el azul deben esperar. Esta posición del agente es diferente a la de ID 5834."},{"id":5839,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, че преминаването е забранено във всички посоки?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24291.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"para el coche ROJO"},{"t":"на зеления автомобил","ok":true,"i":null,"es":"para el coche VERDE"},{"t":"на жълтия автомобил","ok":false,"i":null,"es":"para el coche AMARILLO"},{"t":"на синия автомобил","ok":false,"i":null,"es":"para el coche AZUL"}],"es":"¿Para qué conductores la señal del agente significa paso PROHIBIDO? (2 correctas)","explain":"⚠️ TRAMPA: PROHIBIDO para rojo Y verde. Permitido para amarillo y azul. La pregunta pregunta quién NO puede pasar — inverso a 5837."},{"id":5841,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, че преминаването е забранено във всички посоки?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24340.png","v":null,"a":[{"t":"на жълтия автомобил","ok":true,"i":null,"es":"para el coche AMARILLO"},{"t":"на синия автомобил","ok":true,"i":null,"es":"para el coche AZUL"},{"t":"на червения автомобил","ok":false,"i":null,"es":"para el coche ROJO"},{"t":"на зеления автомобил","ok":false,"i":null,"es":"para el coche VERDE"}],"es":"¿Para qué conductores la señal del agente significa paso PROHIBIDO? (2 correctas)","explain":"⚠️ TRAMPA: PROHIBIDO para amarillo Y azul. Permitido para rojo y verde. La pregunta pregunta quién NO puede pasar — inverso a 5834."},{"id":5845,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24421.png","v":null,"a":[{"t":"преминаването ми е забранено","ok":true,"i":null,"es":"me está PROHIBIDO pasar"},{"t":"мога да завия надясно","ok":false,"i":null,"es":"puedo girar a la derecha"},{"t":"мога да завия наляво","ok":false,"i":null,"es":"puedo girar a la izquierda"},{"t":"мога да завия в обратна посока","ok":false,"i":null,"es":"puedo dar la vuelta"}],"es":"La señal del agente regulador significa que:","explain":"Cuando el agente tiene el brazo extendido hacia ti, significa STOP — prohibido pasar. Es la señal de parada del regulador de tráfico."},{"id":5847,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25090.png","v":null,"a":[{"t":"преминаването ми е забранено","ok":true,"i":null,"es":"me está PROHIBIDO pasar"},{"t":"мога да завия надясно","ok":false,"i":null,"es":"puedo girar a la derecha"},{"t":"мога да завия наляво","ok":false,"i":null,"es":"puedo girar a la izquierda"},{"t":"мога да завия в обратна посока","ok":false,"i":null,"es":"puedo dar la vuelta"}],"es":"La señal del agente regulador significa que:","explain":"STOP — prohibido pasar. El agente de frente con brazo extendido hacia ti siempre significa parada obligatoria."},{"id":5850,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/35032.png","v":null,"a":[{"t":"мога да премина направо","ok":true,"i":null,"es":"continuar RECTO"},{"t":"мога да завия надясно","ok":true,"i":null,"es":"girar a la DERECHA"},{"t":"мога да завия наляво","ok":false,"i":null,"es":"girar a la IZQUIERDA"},{"t":"мога да завия в обратна посока","ok":false,"i":null,"es":"dar la VUELTA"}],"es":"La señal del agente regulador significa que puedo: (2 correctas)","explain":"⚠️ TRAMPA: con brazos extendidos lateralmente, los de frente/detrás pueden recto Y derecha. Girar a la izquierda y dar la vuelta = prohibidos."},{"id":5853,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/35066.png","v":null,"a":[{"t":"мога да премина направо","ok":true,"i":null,"es":"continuar RECTO"},{"t":"мога да завия надясно","ok":true,"i":null,"es":"girar a la DERECHA"},{"t":"мога да завия наляво","ok":false,"i":null,"es":"girar a la IZQUIERDA"},{"t":"мога да завия в обратна посока","ok":false,"i":null,"es":"dar la VUELTA"}],"es":"La señal del agente regulador significa que puedo: (2 correctas)","explain":"PUEDO SEGUIR RECTO Y PUEDO GIRAR A LA DERECHA. Dos correctas.\n\nQUÉ VES. Un AGENTE en el cruce, con los BRAZOS BAJADOS, que te muestra su COSTADO.\n\nCÓMO SE LEE AL AGENTE CON LOS BRAZOS EXTENDIDOS O BAJADOS:\n• Si te muestra el COSTADO (izquierdo o derecho): puedes seguir RECTO o girar a la DERECHA.\n• Si te muestra el PECHO o la ESPALDA: prohibido pasar.\n\n«GIRAR A LA IZQUIERDA» y «DAR LA VUELTA» son los cebos: con el agente de costado solo se permite recto y derecha.\n\nCLAVE: costado = recto y derecha, nada más. Compárala con la 5834 (la misma posición vista desde varios coches). Ver Leyes → «Quién manda sobre quién»."},{"id":5857,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, значението на който е „Преминаването е разрешено”?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/36480.png","v":null,"a":[{"t":"на синия автомобил","ok":true,"i":null,"es":"para el coche AZUL"},{"t":"на червения автомобил","ok":false,"i":null,"es":"para el coche ROJO"},{"t":"на зеления автомобил","ok":false,"i":null,"es":"para el coche VERDE"},{"t":"на жълтия автомобил","ok":false,"i":null,"es":"para el coche AMARILLO"}],"es":"¿Para qué conductor la señal del agente tiene el significado de '¡Atención, para!'?","explain":"⚠️ TRAMPA: STOP para el AZUL — el agente tiene el brazo apuntando hacia él. Los demás colores pueden pasar o esperar según su posición."},{"id":5859,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, значението на който е „Преминаването е разрешено”?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/36529.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"para el coche ROJO"},{"t":"на зеления автомобил","ok":false,"i":null,"es":"para el coche VERDE"},{"t":"на жълтия автомобил","ok":false,"i":null,"es":"para el coche AMARILLO"},{"t":"на синия автомобил","ok":false,"i":null,"es":"para el coche AZUL"}],"es":"¿Para qué conductor la señal del agente tiene el significado de '¡Atención, para!'?","explain":"⚠️ TRAMPA: STOP para el ROJO en esta posición específica del agente. Diferente a ID 5857 donde era el azul."},{"id":5867,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, значението на който е „Преминаването е забранено”?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/36578.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"para el coche ROJO"},{"t":"на зеления автомобил","ok":true,"i":null,"es":"para el coche VERDE"},{"t":"на жълтия автомобил","ok":true,"i":null,"es":"para el coche AMARILLO"},{"t":"на синия автомобил","ok":false,"i":null,"es":"para el coche AZUL"}],"es":"¿Para qué conductores la señal del agente significa '¡Atención, para!'? (3 correctas)","explain":"⚠️ TRAMPA: STOP para rojo, verde Y amarillo — tres coches. Solo el azul puede pasar. Cuando tres de cuatro deben parar, identifica al único que puede pasar."},{"id":5869,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, значението на който е „Преминаването е забранено”?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/36662.png","v":null,"a":[{"t":"на зеления автомобил","ok":true,"i":null,"es":"para el coche VERDE"},{"t":"на жълтия автомобил","ok":true,"i":null,"es":"para el coche AMARILLO"},{"t":"на синия автомобил","ok":true,"i":null,"es":"para el coche AZUL"},{"t":"на червения автомобил","ok":false,"i":null,"es":"para el coche ROJO"}],"es":"¿Para qué conductores la señal del agente significa paso PERMITIDO? (3 correctas)","explain":"⚠️ TRAMPA: paso permitido para verde, amarillo Y azul. Solo el rojo debe esperar. Tres de cuatro pueden pasar."},{"id":5871,"bg":"Сигналът на регулировчика означава, че е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/37240.png","v":null,"a":[{"t":"разрешено да завия наляво","ok":true,"i":null,"es":"permitido girar a la izquierda"},{"t":"разрешено да премина направо","ok":true,"i":null,"es":"permitido continuar recto"},{"t":"забранено да завия надясно","ok":false,"i":null,"es":"prohibido girar a la derecha"},{"t":"забранено да завия в обратна посока","ok":false,"i":null,"es":"prohibido girar en sentido contrario"}],"es":"La señal del agente regulador significa que está: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: con esta posición del agente puedes recto Y girar a la izquierda. Girar a la derecha y dar la vuelta están prohibidos en este caso."},{"id":5873,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/37386.png","v":null,"a":[{"t":"преминаването ми е забранено","ok":true,"i":null,"es":"me está PROHIBIDO pasar"},{"t":"е разрешено да завия надясно","ok":false,"i":null,"es":"puedo girar a la derecha"},{"t":"е разрешено да завия наляво","ok":false,"i":null,"es":"puedo girar a la izquierda"},{"t":"е разрешено да завия в обратна посока","ok":false,"i":null,"es":"puedo dar la vuelta"}],"es":"La señal del agente regulador significa que:","explain":"Señal de STOP del regulador — prohibido pasar. Similar a la señal #30 (ID 5845). Cuando el agente te para, debes esperar su indicación."},{"id":5876,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/37468.png","v":null,"a":[{"t":"преминаването ми е забранено","ok":true,"i":null,"es":"me está PROHIBIDO pasar"},{"t":"е разрешено да завия надясно","ok":false,"i":null,"es":"puedo girar a la derecha"},{"t":"е разрешено да завия наляво","ok":false,"i":null,"es":"puedo girar a la izquierda"},{"t":"е разрешено да завия в обратна посока","ok":false,"i":null,"es":"puedo dar la vuelta"}],"es":"La señal del agente regulador significa que:","explain":"Agente con brazo extendido hacia ti = STOP, prohibido pasar. Igual que las preguntas similares del Set 1."},{"id":5882,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/37566.png","v":null,"a":[{"t":"преминаването ми е забранено","ok":true,"i":null,"es":"me está PROHIBIDO pasar"},{"t":"е разрешено да завия надясно","ok":false,"i":null,"es":"puedo girar a la derecha"},{"t":"е разрешено да завия наляво","ok":false,"i":null,"es":"puedo girar a la izquierda"},{"t":"е разрешено да завия в обратна посока","ok":false,"i":null,"es":"puedo dar la vuelta"}],"es":"La señal del agente regulador significa que:","explain":"Agente con brazo extendido = STOP para quien lo tiene de frente. Memoriza: el brazo del agente es una barrera imaginaria que no puedes cruzar."},{"id":5885,"bg":"Значението на този сигнал на регулировчика е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39187.png","v":null,"a":[{"t":"„Внимание, спри!”","ok":true,"i":null,"es":"'¡Atención, para!'"},{"t":"„Премини с повишено внимание”","ok":false,"i":null,"es":"'Pasa con precaución'"},{"t":"„Внимание”","ok":false,"i":null,"es":"'¡Atención!'"},{"t":"„Пропусни движещите се по пресичания път”","ok":false,"i":null,"es":"'Cede el paso a los que cruzan'"}],"es":"El significado de esta señal del agente regulador es:","explain":"Agente con brazo levantado = '¡Atención, para!' (Внимание, спри). Es la señal de advertencia previa al STOP. Diferente al brazo extendido que es directamente STOP."},{"id":5888,"bg":"Значението на този сигнал на регулировчика е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39253.png","v":null,"a":[{"t":"„Внимание, спри!”","ok":true,"i":null,"es":"'¡Atención, para!'"},{"t":"„Премини с повишено внимание”","ok":false,"i":null,"es":"'Pasa con precaución'"},{"t":"„Внимание”","ok":false,"i":null,"es":"'¡Atención!'"},{"t":"„Пропусни движещите се по пресичания път”","ok":false,"i":null,"es":"'Deja pasar a los que vienen por la vía cruzada'"}],"es":"El significado de esta señal del agente regulador es:","explain":"Esta señal específica del regulador (brazo levantado) significa STOP — para y espera. Diferente al brazo extendido lateralmente."},{"id":5891,"bg":"Значението на този немигащ сигнал на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39865.png","v":null,"a":[{"t":"„Преминаването е забранено”","ok":true,"i":null,"es":"'El paso está PROHIBIDO'"},{"t":"„Преминаването е разрешено”","ok":false,"i":null,"es":"'El paso está permitido'"},{"t":"„Внимание!”","ok":false,"i":null,"es":"'¡Atención!'"},{"t":"„Внимание, спри!”","ok":false,"i":null,"es":"'¡Atención, para!'"}],"es":"El significado de esta señal fija del semáforo es:","explain":"«EL PASO ESTÁ PROHIBIDO». Una sola correcta.\n\nQUÉ VES. Un semáforo con la luz ROJA encendida, fija.\n\nROJO FIJO = «ПРЕМИНАВАНЕТО Е ЗАБРАНЕНО». Es la prohibición de pasar.\n\n«¡ATENCIÓN, PARA!» es el nombre oficial del ÁMBAR fijo, no del rojo. Es el cebo principal: los dos impiden entrar, pero cada luz tiene su nombre.\n\n«¡ATENCIÓN!» es el ámbar INTERMITENTE.\n\n«EL PASO ESTÁ PERMITIDO» es el verde.\n\nCLAVE: memoriza los cuatro nombres: rojo = paso prohibido; ámbar fijo = atención, para; ámbar intermitente = atención; verde = paso permitido. Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":5895,"bg":"Значението на този сигнал на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/40074.png","v":null,"a":[{"t":"„Забранено е преминаването направо или завиването надясно”","ok":true,"i":null,"es":"'Prohibido continuar recto o girar a la derecha'"},{"t":"„Забранено е навлизането в кръстовището за всички участници в движението”","ok":false,"i":null,"es":"'Prohibida la entrada para todos los participantes'"},{"t":"„Забранено е преминаването, освен на ППС, преминаващи направо или завиващи надясно”","ok":false,"i":null,"es":"'Prohibido pasar excepto los que van recto o giran a la derecha'"}],"es":"El significado de esta señal de semáforo es:","explain":"«PROHIBIDO CONTINUAR RECTO O GIRAR A LA DERECHA». Una sola correcta.\n\nQUÉ VES. Un semáforo con la luz ROJA encendida y, dibujadas en negro sobre ella, FLECHAS hacia arriba y hacia la derecha.\n\nUNA LUZ CON FLECHAS SOLO AFECTA A ESAS DIRECCIONES. El rojo con flechas de recto y derecha prohíbe precisamente seguir recto y girar a la derecha. No dice nada de la izquierda.\n\n«PROHIBIDA LA ENTRADA PARA TODOS» es el cebo: sería un rojo sin flechas.\n\n«PROHIBIDO PASAR EXCEPTO LOS QUE VAN RECTO O GIRAN A LA DERECHA» es justo lo contrario: lee las flechas como permitidas cuando están en rojo.\n\nCLAVE: las flechas dicen a qué direcciones se aplica el color de la luz. Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":5900,"bg":"Значението на този сигнал на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41967.png","v":null,"a":[{"t":"„Преминаването е забранено”","ok":true,"i":null,"es":"'El paso está PROHIBIDO'"},{"t":"„Преминаването е разрешено”","ok":false,"i":null,"es":"'El paso está permitido'"},{"t":"„Внимание!”","ok":false,"i":null,"es":"'¡Atención!'"},{"t":"„Внимание, спри!”","ok":false,"i":null,"es":"'¡Atención, para!'"}],"es":"El significado de esta señal de semáforo es:","explain":"⚠️ TRAMPA: semáforo rojo = PROHIBIDO. Parece obvio pero aparece frecuentemente en el examen para asegurarse de que sabes exactamente el nombre de cada señal."},{"id":5906,"bg":"Значението на този сигнал на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42214.png","v":null,"a":[{"t":"„Преминаването е разрешено”","ok":true,"i":null,"es":"'El paso está permitido'"},{"t":"„Разрешено е преминаването във всички посоки”","ok":false,"i":null,"es":"'Permitido pasar en todas las direcciones'"},{"t":"„Разрешено е преминаването направо и надясно”","ok":false,"i":null,"es":"'Permitido pasar recto y a la derecha'"}],"es":"El significado de esta señal de semáforo es:","explain":"Semáforo verde estándar = paso permitido en la dirección indicada. No significa todas las direcciones ni solo recto+derecha."},{"id":5914,"bg":"Този сигнал на светофара означава, че е забранено навлизането в кръстовището на ППС, които:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43602.png","v":null,"a":[{"t":"преминават направо","ok":true,"i":null,"es":"continúan recto"},{"t":"завиват наляво","ok":true,"i":null,"es":"giran a la izquierda"},{"t":"завиват надясно","ok":false,"i":null,"es":"giran a la derecha"}],"es":"Esta señal de semáforo significa que está PROHIBIDO entrar en la intersección a los vehículos que: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: El semáforo con flecha indica qué movimientos están prohibidos. Los que van recto y los que giran a la izquierda están bloqueados. Girar a la derecha puede estar permitido."},{"id":5915,"bg":"Жълтата мигаща светлина:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43915.png","v":null,"a":[{"t":"означава „Внимание”","ok":true,"i":null,"es":"significa '¡Atención!'"},{"t":"предупреждава водачите да бъдат внимателни и предпазливи","ok":true,"i":null,"es":"advierte a los conductores que sean atentos y precavidos"},{"t":"означава, че преминаването без спиране е забранено","ok":false,"i":null,"es":"significa que pasar sin detenerse está prohibido"},{"t":"указва, че движението се регулира от регулировчик","ok":false,"i":null,"es":"indica que el tráfico lo regula un agente"}],"es":"La luz amarilla parpadeante: (2 correctas)","explain":"SIGNIFICA «¡ATENCIÓN!» Y ADVIERTE A LOS CONDUCTORES QUE SEAN ATENTOS Y PRECAVIDOS. Dos correctas.\n\nQUÉ VES. Un semáforo con la luz ÁMBAR encendida (la pregunta indica que es INTERMITENTE).\n\nÁMBAR INTERMITENTE = «¡ATENCIÓN!». El cruce no está regulado por el semáforo en ese momento: pasas con precaución, aplicando las señales de prioridad o la regla de la derecha.\n\n«PASAR SIN DETENERSE ESTÁ PROHIBIDO» es el cebo: confunde el intermitente con un STOP.\n\n«EL TRÁFICO LO REGULA UN AGENTE» no tiene relación con esta luz.\n\nCLAVE: ámbar intermitente = atención; ámbar fijo = atención, para. Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":5918,"bg":"Значението на жълтата мигаща светлина на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43915.png","v":null,"a":[{"t":"„Внимание”","ok":true,"i":null,"es":"'¡Atención!'"},{"t":"„Преминаването е забранено”","ok":false,"i":null,"es":"'Paso prohibido'"},{"t":"„Внимание, спри!”","ok":false,"i":null,"es":"'¡Atención, para!'"},{"t":"„Преминаването без спиране е забранено”","ok":false,"i":null,"es":"'Paso sin detenerse prohibido'"}],"es":"El significado de la luz amarilla parpadeante del semáforo es:","explain":"«¡ATENCIÓN!». Una sola correcta.\n\nQUÉ VES. Un semáforo con la luz ÁMBAR encendida (la pregunta indica que es INTERMITENTE).\n\nÁMBAR INTERMITENTE = «ВНИМАНИЕ» (¡ATENCIÓN!). El semáforo no regula el cruce en ese momento: pasas con precaución, aplicando las señales o la regla de la derecha.\n\n«¡ATENCIÓN, PARA!» es el nombre del ámbar FIJO. Es el cebo principal.\n\n«PASO PROHIBIDO» es el rojo. «PASAR SIN DETENERSE ESTÁ PROHIBIDO» es lo que indica un STOP, no un semáforo.\n\nCLAVE: los cuatro nombres oficiales: rojo = paso prohibido; ámbar fijo = atención, para; ámbar intermitente = atención; verde = paso permitido. Compárala con la 5915 y la 5891. Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":5922,"bg":"Мигащата червена светлина или две последователно мигащи една след друга червени светлини означават, че преминаването е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44332.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"es":"La luz roja parpadeante o dos rojas parpadeando alternativamente significa que el paso está:","explain":"Rojo parpadeante en paso a nivel o cruce especial = STOP, prohibido pasar. Es la señal más urgente — hay un tren u obstáculo inminente."},{"id":5923,"bg":"Мигащата червена светлина или две последователно мигащи една след друга червени светлини означават:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44332.png","v":null,"a":[{"t":"че преминаването е забранено","ok":true,"i":null,"es":"el paso está PROHIBIDO"},{"t":"че преминаването е разрешено","ok":false,"i":null,"es":"el paso está permitido"},{"t":"че това е сигнал само за водачите на релсови превозни средства","ok":false,"i":null,"es":"es una señal solo para tranvías"},{"t":"„Внимание!”","ok":false,"i":null,"es":"'¡Atención!'"}],"es":"La luz roja parpadeante o dos rojas alternativas significa:","explain":"⚠️ TRAMPA: rojo parpadeante = PROHIBIDO sin excepciones. No es 'atención' ni señal solo para tranvías. Es la señal de mayor urgencia en paso a nivel."},{"id":5925,"bg":"При тази ситуация сигналът от бавно мигаща светлина с луннобял цвят указва на участниците в движението, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44495.png","v":null,"a":[{"t":"светофарната уредба е в изправност","ok":true,"i":null,"es":"el semáforo está en funcionamiento correcto"},{"t":"е забранено преминаването през прелеза","ok":false,"i":null,"es":"está prohibido cruzar el paso"},{"t":"бариерите ще започнат да се спускат","ok":false,"i":null,"es":"las barreras empezarán a bajar"},{"t":"че към прелеза се приближава влак","ok":false,"i":null,"es":"se aproxima un tren"}],"es":"En esta situación la señal de luz blanca parpadeante lenta indica a los participantes en el tráfico que:","explain":"Luz blanca parpadeante lenta en paso a nivel = semáforo funcionando normalmente, sin tren inminente. Es una señal de normalidad, no de alarma."},{"id":5928,"bg":"Значението на този светлинен сигнал е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44560.png","v":null,"a":[{"t":"„Навлизането е разрешено” по пътната лента, над която е поставен","ok":true,"i":null,"es":"'Entrada PERMITIDA' en el carril sobre el que está"},{"t":"„Задължителна посока за движение”","ok":false,"i":null,"es":"'Dirección obligatoria'"},{"t":"„Навлизането е забранено” по пътната лента, над която е поставен","ok":false,"i":null,"es":"'Entrada PROHIBIDA' en el carril sobre el que está"},{"t":"„Място за задължително спиране” в пътната лента, над която е поставен","ok":false,"i":null,"es":"'Lugar de parada obligatoria'"}],"es":"El significado de esta señal luminosa es:","explain":"⚠️ TRAMPA: flecha verde hacia abajo = PERMITIDA. Comparar con ID 5932 donde X roja = PROHIBIDA. Son opuestas — esta es la versión 'permitida'."},{"id":5930,"bg":"Този светлинен сигнал:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44599.png","v":null,"a":[{"t":"сигнализира, че навлизането по пътната лента, над която е поставен, е разрешено","ok":true,"i":null,"es":"indica que la entrada al carril sobre el que está es PERMITIDA"},{"t":"указва задължителна посока за движение","ok":false,"i":null,"es":"indica dirección obligatoria"},{"t":"указва място за задължително спиране","ok":false,"i":null,"es":"indica lugar de parada obligatoria"},{"t":"забранява навлизането в другите пътни ленти","ok":false,"i":null,"es":"prohíbe la entrada en los demás carriles"}],"es":"Esta señal luminosa:","explain":"INDICA QUE LA ENTRADA AL CARRIL SOBRE EL QUE ESTÁ ES PERMITIDA. Una sola correcta.\n\nQUÉ VES. Un pórtico sobre la calzada con semáforos de carril. Sobre uno de los carriles se ve una FLECHA VERDE hacia ABAJO.\n\nLOS SEMÁFOROS DE CARRIL HABLAN SOLO DE SU CARRIL. La flecha verde hacia abajo dice: «por este carril se puede circular». No dice nada de los demás.\n\n«DIRECCIÓN OBLIGATORIA», «LUGAR DE PARADA OBLIGATORIA» y «PROHÍBE ENTRAR EN LOS DEMÁS CARRILES» son cebos que leen la flecha como una orden o como una prohibición para los otros carriles.\n\nCLAVE: flecha verde hacia abajo = carril abierto; aspa roja = carril cerrado (compárala con la 5933). Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":5932,"bg":"Значението на този светлинен сигнал е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44686.png","v":null,"a":[{"t":"„Навлизането е забранено” по пътната лента, над която е поставен","ok":true,"i":null,"es":"'Entrada PROHIBIDA' en el carril sobre el que está"},{"t":"„Следва кръстовище на равнозначни пътища”","ok":false,"i":null,"es":"'Sigue intersección de vías equivalentes'"},{"t":"„Навлизането е разрешено” по пътната лента, над която е поставен","ok":false,"i":null,"es":"'Entrada PERMITIDA' en el carril sobre el que está"},{"t":"„Място за задължително спиране”","ok":false,"i":null,"es":"'Lugar de parada obligatoria'"}],"es":"El significado de esta señal luminosa es:","explain":"⚠️ TRAMPA: X roja = PROHIBIDA. Comparar con ID 5928 donde flecha verde = PERMITIDA. Esta es la versión 'prohibida' — X siempre = prohibición."},{"id":5933,"bg":"Този светлинен сигнал:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44686.png","v":null,"a":[{"t":"сигнализира, че навлизането по пътната лента, над която е поставен, е забранено","ok":true,"i":null,"es":"indica que la entrada al carril sobre el que está es PROHIBIDA"},{"t":"указва, че е забранено движението в най-лявата пътна лента","ok":false,"i":null,"es":"indica que está prohibido el carril izquierdo"},{"t":"указва място за задължително спиране","ok":false,"i":null,"es":"indica lugar de parada obligatoria"},{"t":"забранява движението по пътното платно над което е поставен","ok":false,"i":null,"es":"prohíbe la circulación en toda la calzada"}],"es":"Esta señal luminosa:","explain":"INDICA QUE LA ENTRADA AL CARRIL SOBRE EL QUE ESTÁ ES PROHIBIDA. Una sola correcta.\n\nQUÉ VES. Un pórtico sobre la calzada con semáforos de carril. Sobre el carril izquierdo se ve un ASPA ROJA (X); sobre el otro, la luz está apagada.\n\nEL ASPA ROJA CIERRA SOLO SU CARRIL. Por ese carril no se puede circular; los demás no quedan afectados por esta luz.\n\n«PROHÍBE CIRCULAR POR TODA LA CALZADA» es el cebo de quien extiende la prohibición a todos los carriles.\n\n«PROHIBIDO EL CARRIL IZQUIERDO» parece correcto en esta imagen, pero la señal no significa «el izquierdo», sino «el carril sobre el que está», sea cual sea.\n\n«LUGAR DE PARADA OBLIGATORIA» no tiene relación con esta luz.\n\nCLAVE: aspa roja = carril cerrado; flecha verde = carril abierto (compárala con la 5930). Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":5934,"bg":"Когато и двете секции на този светофар не работят и няма пътен знак за броя и посоките на движение по пътните ленти, това означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/45488.png","v":null,"a":[{"t":"навлизането по пътната лента, над която е поставен светофарът, е забранено","ok":true,"i":null,"es":"la entrada al carril sobre el que está el semáforo está PROHIBIDA"},{"t":"навлизането по пътната лента, над която е поставен светофарът, е разрешено","ok":false,"i":null,"es":"la entrada está permitida"},{"t":"водачът трябва да спре на линията, на която е поставен светофарът","ok":false,"i":null,"es":"el conductor debe parar en la línea del semáforo"}],"es":"Cuando ambas secciones de este semáforo de carril no funcionan y no hay señal de tráfico:","explain":"⚠️ TRAMPA: semáforo de carril apagado = carril CERRADO, entrada prohibida. Un semáforo apagado no significa paso libre — significa que ese carril no está disponible."},{"id":11584,"bg":"Значението на този немигащ сигнал на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1098228160.png","v":null,"a":[{"t":"„Внимание, спри!”","ok":true,"i":null,"es":"'¡Atención, para!'"},{"t":"„Преминаването е разрешено”, но водачите са длъжни да бъдат внимателни и предпазливи","ok":false,"i":null,"es":"'Paso permitido, pero con precaución'"},{"t":"„Преминаването е разрешено”","ok":false,"i":null,"es":"'El paso está permitido'"}],"es":"El significado de esta señal fija de semáforo es:","explain":"El semáforo rojo fijo (no parpadeante) significa STOP obligatorio. No es una advertencia de precaución — es prohibición total de avanzar."},{"id":6069,"bg":"При тази ситуация разположението на автомобила върху платното за движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59751.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcta"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecta"}],"es":"En esta situación la posición del vehículo en la calzada es:","explain":"Analiza si el vehículo está correctamente posicionado respecto a las líneas de carril y el lado de la calzada correspondiente."},{"id":6070,"bg":"При тази ситуация трябва да се движа:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59902.png","v":null,"a":[{"t":"в дясната пътна лента","ok":true,"i":null,"es":"en el carril DERECHO"},{"t":"в по-удобната за мен пътна лента","ok":false,"i":null,"es":"en el más cómodo"},{"t":"в лявата пътна лента","ok":false,"i":null,"es":"en el IZQUIERDO"}],"es":"En esta situación debo circular:","explain":"EN EL CARRIL DERECHO. Una sola correcta.\n\nQUÉ VES. Carretera FUERA DE POBLACIÓN con dos carriles en tu sentido. Vas por el IZQUIERDO. En el retrovisor se ve un coche ROJO detrás de ti que te hace ráfagas con las luces: quiere adelantar.\n\nFUERA DE POBLACIÓN, EL CARRIL DE LA DERECHA. Los carriles de la izquierda son para adelantar, no para viajar por ellos. Si no estás adelantando a nadie, vuelves a la derecha.\n\nQUE VENGA ALGUIEN DETRÁS NO CREA LA OBLIGACIÓN: la norma se aplica igual con la carretera vacía. El coche del retrovisor solo hace evidente el problema.\n\n«EN EL CARRIL MÁS CÓMODO» solo es posible en población y con carriles señalizados. Aquí estás fuera.\n\n«EN EL CARRIL IZQUIERDO» es la infracción que la pregunta quiere que reconozcas.\n\nCLAVE: derecha por defecto; izquierda solo mientras adelantas.\n\nMÉTODO DE CARRILES: 1) ¿estoy en población o fuera? 2) ¿cuántos carriles hay en MI sentido y están señalizados? 3) ¿estoy adelantando? Fuera de población, sin adelantar, siempre el carril derecho. Ver Leyes → «Carril: dónde debes circular»."},{"id":6071,"bg":"Кой от автомобилите се движи неправилно по пътното платно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59984.png","v":null,"a":[{"t":"синият автомобил","ok":true,"i":null,"es":"el coche azul"},{"t":"червеният автомобил","ok":false,"i":null,"es":"el coche rojo"},{"t":"и двата автомобила","ok":false,"i":null,"es":"los dos vehículos"}],"es":"¿Qué vehículo circula incorrectamente por la calzada?","explain":"El azul circula incorrectamente — probablemente por el carril equivocado, en sentido contrario o demasiado al centro. El rojo sí va bien."},{"id":6072,"bg":"На двупосочен път, с по една пътна лента за движение във всяка посока, превозните средства трябва да се движат:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/123692.png","v":null,"a":[{"t":"в дясната пътна лента","ok":true,"i":null,"es":"en el carril DERECHO"},{"t":"в средната част на пътя","ok":false,"i":null,"es":"por el centro del camino"},{"t":"в лявата пътна лента","ok":false,"i":null,"es":"en el carril IZQUIERDO"}],"es":"En vía de doble sentido con un carril por sentido, los vehículos deben circular:","explain":"EN EL CARRIL DERECHO. Una sola correcta.\n\nQUÉ VES. Una carretera de DOBLE SENTIDO con un carril para cada sentido, separados por la línea central.\n\nCADA UNO POR SU DERECHA. En una vía de doble sentido con un carril por sentido, tu carril es el de la derecha; el izquierdo es el de los vehículos que vienen de frente.\n\n«POR EL CENTRO DEL CAMINO» es el cebo de quien se separa del borde por comodidad: invades parcialmente el carril contrario.\n\n«EN EL CARRIL IZQUIERDO» es circular en sentido contrario.\n\nCLAVE: doble sentido + un carril por sentido = siempre el derecho. Ver Leyes → «Carril: dónde debes circular»."},{"id":6073,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60166.png","v":null,"a":[{"t":"следва участък от пътя с двупосочно движение","ok":true,"i":null,"es":"sigue un tramo de doble sentido"},{"t":"лявата част на пътното платно е за автомобилите от насрещното движение","ok":true,"i":null,"es":"la parte izquierda es para el tráfico contrario"},{"t":"движещите се насреща автомобили са с предимство","ok":false,"i":null,"es":"los vehículos de frente tienen prioridad"},{"t":"навлизаме в участък от пътя, в който е забранено разминаването","ok":false,"i":null,"es":"entramos en tramo donde está prohibido el cruce"}],"es":"En esta situación: (2 correctas)","explain":"SIGUE UN TRAMO DE DOBLE SENTIDO Y LA PARTE IZQUIERDA ES PARA EL TRÁFICO CONTRARIO. Dos correctas.\n\nQUÉ VES. Una calzada por la que vas detrás de un coche rojo. A la derecha, una señal TRIANGULAR de peligro con dos flechas, una hacia arriba y otra hacia abajo: TRÁFICO EN DOBLE SENTIDO.\n\nLA SEÑAL AVISA DE QUE SE ACABA EL SENTIDO ÚNICO. A partir de aquí vendrán vehículos de frente, y la parte izquierda de la calzada será la suya.\n\n«LOS DE FRENTE TIENEN PRIORIDAD» es el cebo: la señal es de PELIGRO (triángulo), no de prioridad. No da preferencia a nadie.\n\n«PROHIBIDO CRUZARSE» es lo contrario: en un tramo de doble sentido precisamente te vas a cruzar con otros vehículos.\n\nCLAVE: triángulo con flechas opuestas = viene tráfico de frente; ocupa solo tu mitad. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6075,"bg":"На двулентов път с двупосочно движение водачът трябва да се движи:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"възможно най-вдясно по платното за движение, когато лентите не са очертани с пътна маркировка","ok":true,"i":null,"es":"todo lo posible a la derecha cuando no hay marcas"},{"t":"в дясната лента, когато лентите са очертани с пътна маркировка","ok":true,"i":null,"es":"en el carril derecho cuando hay marcas"},{"t":"в по-удобната за него пътна лента","ok":false,"i":null,"es":"en el carril más cómodo"},{"t":"в лявата пътна лента винаги, когато е свободна","ok":false,"i":null,"es":"en el izquierdo siempre que esté libre"}],"es":"En vía de dos carriles de doble sentido el conductor debe circular: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: siempre por la derecha — con marcas en el carril derecho, sin marcas todo lo posible a la derecha. El izquierdo nunca salvo para adelantar."},{"id":6076,"bg":"Разположението върху пътя на червения автомобил, движещ се извън населено място е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60500.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"incorrecta"},{"t":"правилно","ok":false,"i":null,"es":"correcta"}],"es":"La posición del coche rojo que circula fuera de población es:","explain":"INCORRECTA.\n\nQUÉ VES. Carretera FUERA DE POBLACIÓN con dos carriles en el mismo sentido (la señal azul con flecha blanca hacia arriba lo confirma). El coche ROJO circula por el carril IZQUIERDO y el carril DERECHO está completamente libre.\n\nFUERA DE POBLACIÓN SE VA POR LA DERECHA. Cuando hay varios carriles en tu sentido, circulas por el de la derecha y usas los demás para adelantar, volviendo a la derecha al terminar. El rojo no está adelantando a nadie: ocupa el carril izquierdo sin motivo.\n\n«CORRECTA» es el cebo: no molesta a nadie en ese momento. Pero la obligación de ir por la derecha no depende de que haya tráfico.\n\nCLAVE: carril derecho libre + nadie a quien adelantar = el izquierdo está mal ocupado.\n\nMÉTODO: 1) ¿dentro o fuera de población? 2) ¿hay carril derecho libre? 3) ¿está adelantando? Si no, posición incorrecta. Ver Leyes → «Carril: dónde debes circular»."},{"id":6077,"bg":"По този път извън населено място водачът трябва да се движи:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/102157.png","v":null,"a":[{"t":"възможно най-вдясно по платното за движение, когато лентите не са очертани с пътна маркировка","ok":true,"i":null,"es":"todo lo posible a la derecha cuando los carriles no están marcados"},{"t":"в дясната пътна лента, когато лентите са очертани с пътна маркировка","ok":true,"i":null,"es":"en el carril derecho cuando los carriles están marcados"},{"t":"в по-удобната за него пътна лента","ok":false,"i":null,"es":"en el carril más cómodo"},{"t":"в лявата пътна лента винаги, когато е свободна","ok":false,"i":null,"es":"siempre en el carril izquierdo cuando esté libre"}],"es":"Por esta carretera fuera de población el conductor debe circular: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: fuera de población debes ir a la derecha — tanto si hay marcas (carril derecho) como si no las hay (todo lo posible a la derecha). El carril izquierdo solo para adelantar."},{"id":6084,"bg":"Кой от автомобилите се движи правилно по този път извън населеното място?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61432.png","v":null,"a":[{"t":"синият автомобил","ok":true,"i":null,"es":"el coche azul"},{"t":"червеният автомобил","ok":false,"i":null,"es":"el coche rojo"},{"t":"двата автомобила","ok":false,"i":null,"es":"los dos"}],"es":"¿Qué vehículo circula correctamente por esta carretera fuera de población?","explain":"El azul va correctamente — circula por el carril derecho o todo lo posible a la derecha, que es la norma fuera de población. El rojo infringe."},{"id":6085,"bg":"При тази ситуация, на път извън населено място, на водачите е разрешено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/140619.png","v":null,"a":[{"t":"да се движат в най-дясната свободна лента","ok":true,"i":null,"es":"circular en el carril disponible más a la derecha"},{"t":"да се движат в средната пътна лента, когато дясната е заета","ok":true,"i":null,"es":"circular en el carril central cuando el derecho está ocupado"},{"t":"да се движат в най удобната за тях пътна лента","ok":false,"i":null,"es":"circular en el carril más cómodo"},{"t":"да се движат в средната пътна лента винаги, когато е свободна","ok":false,"i":null,"es":"circular en el central siempre que esté libre"}],"es":"En esta situación fuera de población, está PERMITIDO: (2 correctas)","explain":"CIRCULAR POR EL CARRIL LIBRE MÁS A LA DERECHA Y POR EL CENTRAL CUANDO EL DERECHO ESTÁ OCUPADO. Dos correctas.\n\nQUÉ VES. Carretera FUERA DE POBLACIÓN con TRES carriles. La señal azul de la derecha muestra dos flechas hacia arriba y una hacia abajo: DOS carriles en tu sentido y UNO para el sentido contrario (el de la izquierda).\n\nFUERA DE POBLACIÓN, EL CARRIL LIBRE MÁS A LA DERECHA. Si el derecho está ocupado, puedes usar el central (el segundo de tu sentido).\n\n«EL CARRIL MÁS CÓMODO» solo se permite en población con carriles señalizados.\n\n«EL CENTRAL SIEMPRE QUE ESTÉ LIBRE» es el cebo: si el derecho está libre, tienes que ir por él.\n\nCLAVE: fuera de población, la derecha libre manda; el siguiente carril solo cuando el derecho está ocupado o para adelantar (compárala con la 6087). Ver Leyes → «Carril: dónde debes circular»."},{"id":6087,"bg":"При тази ситуация, на път извън населено място, на водачите е разрешено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/140619.png","v":null,"a":[{"t":"да се движат в най-дясната свободна пътна лента","ok":true,"i":null,"es":"circular en el carril derecho disponible"},{"t":"да се движат в средната пътна лента, когато дясната е заета","ok":true,"i":null,"es":"usar el carril central cuando el derecho está ocupado"},{"t":"да навлизат в средната лента при изпреварване","ok":true,"i":null,"es":"entrar en el carril central para adelantar"},{"t":"да навлизат в крайната лява лента при изпреварване","ok":false,"i":null,"es":"entrar en el carril izquierdo para adelantar"}],"es":"En esta situación fuera de población, en 3 carriles, está PERMITIDO: (3 correctas)","explain":"CIRCULAR POR EL CARRIL DERECHO DISPONIBLE, USAR EL CENTRAL CUANDO EL DERECHO ESTÁ OCUPADO Y ENTRAR EN EL CENTRAL PARA ADELANTAR. Tres correctas.\n\nQUÉ VES. La misma escena que la 6085: fuera de población, TRES carriles; la señal azul indica DOS carriles en tu sentido (flechas hacia arriba) y UNO en sentido contrario (flecha hacia abajo, el de la izquierda).\n\nTUS CARRILES SON EL DERECHO Y EL CENTRAL. Vas por el derecho si está libre; usas el central cuando el derecho está ocupado o para adelantar.\n\n«ENTRAR EN EL CARRIL IZQUIERDO PARA ADELANTAR» es el cebo: según la señal, ese carril es del sentido contrario.\n\nCLAVE: lee primero la señal de carriles: cuántas flechas son tuyas y cuántas del otro sentido. Ver Leyes → «Carril: dónde debes circular»."},{"id":6090,"bg":"При тази ситуация навлизанетo в лентите за насрещното движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62058.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено без ограничения","ok":false,"i":null,"es":"permitido sin restricciones"},{"t":"разрешено, но само при изпреварване","ok":false,"i":null,"es":"permitido solo para adelantar"},{"t":"разрешено, когато са свободни","ok":false,"i":null,"es":"permitido cuando están libres"}],"es":"En esta situación entrar en los carriles del sentido contrario está:","explain":"PROHIBIDO — la imagen muestra una situación (4 carriles, doble sentido, con línea continua o señal) donde invadir el contrario está completamente prohibido."},{"id":6091,"bg":"На двупосочен път с четири пътни ленти навлизанетo в лента за насрещното движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62094.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено без ограничения","ok":false,"i":null,"es":"permitido sin restricciones"},{"t":"разрешено при изпреварване","ok":false,"i":null,"es":"permitido para adelantar"},{"t":"разрешено при заобикаляне","ok":false,"i":null,"es":"permitido para rodear obstáculos"}],"es":"En vía de doble sentido con cuatro carriles, entrar en el carril contrario está:","explain":"PROHIBIDO — en vías con 4 carriles de doble sentido hay línea continua central que prohíbe invadir el sentido contrario. Con 2 carriles de doble sentido sí se permite para adelantar."},{"id":6095,"bg":"При тази ситуация задължени ли сте да преминете в крайната дясна лента, ако не успеете да изпреварите двата автомобила?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63478.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"En esta situación ¿está obligado a pasar al carril derecho si no puede adelantar?","explain":"NO.\n\nQUÉ VES. Calle EN POBLACIÓN con TRES carriles en tu sentido, señalizados con la señal de carriles (tres flechas hacia arriba). Vas por el carril de la IZQUIERDA (flecha). En los otros carriles hay un coche rojo y uno azul.\n\nEN POBLACIÓN, CON CARRILES SEÑALIZADOS, PUEDES ELEGIR CARRIL. Es la excepción a la regla de ir por la derecha: puedes seguir por el carril que estás usando aunque no hayas adelantado a esos coches. No estás obligado a cambiarte al de la derecha.\n\n«SÍ» es el cebo de quien aplica la regla de fuera de población (volver a la derecha después de adelantar).\n\n(Corrección: la explicación anterior lo justificaba por la seguridad de la maniobra; el motivo real es que en población, con carriles señalizados, se puede elegir carril).\n\nLAS DOS CONDICIONES DE ESTA EXCEPCIÓN: dos o más carriles en tu sentido y velocidad máxima permitida no superior a 80 km/h (aquí se cumplen; compárala con la 11686).\n\nCLAVE: población + carriles señalizados = libertad de carril. Compárala con la 6097. Ver Leyes → «Carril: dónde debes circular»."},{"id":6096,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63543.png","v":null,"a":[{"t":"е разрешено да използвам за движение най-удобната за мен пътна лента","ok":true,"i":null,"es":"está permitido usar el carril más cómodo"},{"t":"длъжен съм да се движа възможно най-вдясно на платното за движение","ok":false,"i":null,"es":"estoy obligado a circular todo lo posible a la derecha"},{"t":"трябва да се движа в най-дясната свободна лента","ok":false,"i":null,"es":"debo circular en el carril derecho más libre"}],"es":"En esta situación:","explain":"En esta situación específica (calzada de varios carriles en zona urbana con límite ≤80 km/h y marcas) está permitido usar el carril más cómodo. Las normas de carril derecho obligatorio no aplican aquí."},{"id":6097,"bg":"При тази ситуация разположението на червения автомобил върху платното за движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63641.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcta"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecta"}],"es":"En esta situación la posición del coche rojo en la calzada es:","explain":"CORRECTA.\n\nQUÉ VES. Calle EN POBLACIÓN, con la señal de carriles a la derecha (dos flechas hacia arriba para tu sentido). El coche ROJO circula por un carril que no es el de más a la derecha.\n\nEN POBLACIÓN, CON CARRILES SEÑALIZADOS, PUEDES ELEGIR CARRIL. Es la excepción a la regla general de ir por la derecha: en ciudad, con varios carriles en tu sentido marcados, el conductor puede usar el que le convenga.\n\nPOR ESO NO ES INFRACCIÓN AQUÍ, aunque lo sería en la misma escena fuera de población (compárala con la 6076).\n\nEL INSTINTO ENGAÑA: uno tiende a marcar «incorrecta» porque tiene grabado «siempre por la derecha». Esa es la regla general; en población con carriles señalizados admite excepción.\n\nLAS DOS CONDICIONES DE ESTA EXCEPCIÓN: dos o más carriles en tu sentido y velocidad máxima permitida no superior a 80 km/h (aquí se cumplen; compárala con la 11686).\n\nCLAVE: población + carriles señalizados = puedes elegir carril.\n\nMÉTODO: 1) ¿estoy en población? 2) ¿hay varios carriles en mi sentido señalizados? 3) si las dos son «sí», cualquier carril de mi sentido vale. Ver Leyes → «Carril: dónde debes circular»."},{"id":6098,"bg":"Кой от автомобилите се движи прaвилно по този път в населено място?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63723.png","v":null,"a":[{"t":"само синият автомобил","ok":false,"i":null,"es":"solo el azul"},{"t":"само червеният автомобил","ok":false,"i":null,"es":"solo el rojo"},{"t":"и двата автомобила","ok":true,"i":null,"es":"los dos"}],"es":"¿Qué vehículo circula correctamente por esta vía en zona urbana?","explain":"LOS DOS. Una sola correcta.\n\nQUÉ VES. Una calle EN POBLACIÓN con dos carriles en tu sentido, marcados con flechas en el suelo, y una señal de máxima 60. El coche ROJO va por el carril IZQUIERDO y el AZUL por el DERECHO.\n\nEN POBLACIÓN, CON VARIOS CARRILES MARCADOS EN TU SENTIDO, PUEDES ELEGIR CARRIL. Ninguno de los dos tiene que ir obligatoriamente por la derecha: cada uno circula por un carril de su sentido.\n\n«SOLO EL AZUL» es el cebo de quien aplica la regla de fuera de población (siempre a la derecha).\n\n«SOLO EL ROJO» no tiene ninguna base.\n\nLAS DOS CONDICIONES DE ESTA EXCEPCIÓN: dos o más carriles en tu sentido y velocidad máxima permitida no superior a 80 km/h (aquí se cumplen; compárala con la 11686).\n\nCLAVE: población + varios carriles en tu sentido = libertad de carril. Compárala con la 6097 y la 6095. Ver Leyes → «Carril: dónde debes circular»."},{"id":6099,"bg":"При тази ситуация водачът на червения автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63839.png","v":null,"a":[{"t":"може да продължи да се движи в лявата лента","ok":true,"i":null,"es":"puede continuar en el carril izquierdo"},{"t":"може да използва за движение по-удобната за него пътна лента","ok":true,"i":null,"es":"puede usar el carril más cómodo"},{"t":"трябва да премине в дясната лента","ok":false,"i":null,"es":"debe pasar al carril derecho"},{"t":"трябва да се движи в най-дясната свободна лента","ok":false,"i":null,"es":"debe circular en el carril derecho más libre"}],"es":"En esta situación el conductor del coche rojo: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: en calzada de varios carriles con condiciones específicas, el rojo puede quedarse en el izquierdo Y puede usar el más cómodo. No es obligatorio ir al derecho."},{"id":6100,"bg":"Разположението на автомобила върху платното за движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64020.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcta"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecta"}],"es":"La posición del vehículo en la calzada es:","explain":"CORRECTA.\n\nQUÉ VES. Un pórtico con semáforos de carril sobre una calzada de tres carriles. Sobre el carril IZQUIERDO hay un ASPA ROJA; sobre los otros dos, FLECHAS VERDES hacia abajo. Tu coche circula por el carril CENTRAL (flecha).\n\nESTÁS EN UN CARRIL ABIERTO. La flecha verde sobre tu carril indica que se puede circular por él. Solo el carril izquierdo está cerrado.\n\n«INCORRECTA» sería si estuvieras bajo el aspa roja.\n\nCLAVE: aspa roja = carril cerrado; flecha verde = carril abierto (compárala con la 5930 y la 5933). Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":6404,"bg":"При тази ситуация няма да извърша нарушение ако:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64182.png","v":null,"a":[{"t":"премина в дясната пътна лента","ok":true,"i":null,"es":"paso al carril derecho"},{"t":"продължа движението си в същата пътна лента","ok":true,"i":null,"es":"continúo en el mismo carril"},{"t":"премина в лявата пътна лента","ok":false,"i":null,"es":"paso al carril izquierdo"},{"t":"спра пред светофара, в лентата, над която е поставен","ok":false,"i":null,"es":"paro ante el semáforo en mi carril"}],"es":"En esta situación no cometo infracción si: (2 correctas)","explain":"⚠️ TRAMPA: puedo quedarme en mi carril O pasar al derecho. El izquierdo y parar en el carril incorrecto son infracciones."},{"id":6432,"bg":"При тази ситуация ще извърша нарушение ако:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64279.png","v":null,"a":[{"t":"продължа движението си в същата пътна лента","ok":true,"i":null,"es":"continúo en el mismo carril"},{"t":"премина в лявата пътна лента","ok":true,"i":null,"es":"paso al carril izquierdo"},{"t":"спра пред светофара, в лентата, над която е поставен","ok":true,"i":null,"es":"paro ante el semáforo en mi carril"},{"t":"премина в дясната пътна лента","ok":false,"i":null,"es":"paso al carril derecho"}],"es":"En esta situación COMETERÉ infracción si: (3 correctas)","explain":"SEGUIR EN EL MISMO CARRIL, PASAR AL CARRIL IZQUIERDO Y PARARSE ANTE EL SEMÁFORO EN SU CARRIL. Tres correctas (son las tres infracciones).\n\nQUÉ VES. Un pórtico con semáforos de carril. Sobre TU carril hay un ASPA ROJA: ese carril está cerrado. El carril de tu derecha no tiene aspa.\n\nEL ASPA ROJA TE OBLIGA A SALIR DE ESE CARRIL hacia uno abierto. Por eso son infracción:\n• seguir por el mismo carril (está cerrado);\n• pasar al carril izquierdo (no es el carril abierto que te corresponde);\n• pararte bajo el aspa (el aspa no significa «para», significa «deja este carril»).\n\nLO ÚNICO CORRECTO es pasar al carril DERECHO.\n\nCLAVE: la pregunta pide las infracciones; marca todo lo que NO sea cambiarte al carril abierto. Compárala con la 5933 y la 6443. Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":6435,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64344.png","v":null,"a":[{"t":"трябва да премина в дясната пътна лента","ok":true,"i":null,"es":"debo cambiar al carril DERECHO"},{"t":"трябва да премина в лявата пътна лента","ok":false,"i":null,"es":"debo cambiar al carril IZQUIERDO"},{"t":"мога да продължа движението си в същата пътна лента","ok":false,"i":null,"es":"puedo continuar en el mismo carril"}],"es":"En esta situación:","explain":"⚠️ TRAMPA: la señal indica que debes moverte al carril DERECHO (el actual carril termina o está reservado). No al izquierdo ni continuar igual."},{"id":6438,"bg":"При тази ситуация, на водача на червения автомобил е разрешено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64417.png","v":null,"a":[{"t":"да продължи движението си в същата пътна лента","ok":true,"i":null,"es":"continuar en el mismo carril"},{"t":"да премине в дясната пътна лента","ok":true,"i":null,"es":"pasar al carril DERECHO"},{"t":"да премине в лявата пътна лента","ok":false,"i":null,"es":"pasar al carril IZQUIERDO"}],"es":"En esta situación al conductor del coche rojo le está PERMITIDO: (2 correctas)","explain":"⚠️ TRAMPA: puede quedarse en su carril O pasar al DERECHO. El izquierdo está prohibido en esta situación específica."},{"id":6446,"bg":"На кои ППС е разрешено движението в BUS - лентата след този знак?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64672.png","v":null,"a":[{"t":"на ППС от редовните линии за обществен превоз на пътници","ok":true,"i":null,"es":"a los vehículos de líneas regulares de transporte público"},{"t":"на всички автобуси","ok":false,"i":null,"es":"a todos los autobuses"},{"t":"на таксиметровите автомобили","ok":false,"i":null,"es":"a los taxis"},{"t":"на бавнодвижещите се превозни средства","ok":false,"i":null,"es":"a los vehículos lentos"}],"es":"¿A qué vehículos está permitido circular por el carril BUS después de esta señal?","explain":"Solo los vehículos de líneas regulares de transporte público (autobuses de línea). No todos los autobuses — los privados o de alquiler no pueden. Los taxis tampoco."},{"id":6449,"bg":"С този пътен знак се обозначава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66102.png","v":null,"a":[{"t":"пътна лента за движение само на превозни средства от редовните линии за обществен превоз на пътници","ok":true,"i":null,"es":"carril exclusivo para transporte público de línea regular"},{"t":"платно за движение само на превозни средства от редовните линии за обществен превоз на пътници","ok":true,"i":null,"es":"calzada exclusiva para transporte público de línea regular"},{"t":"автомобилен път","ok":false,"i":null,"es":"vía rápida"},{"t":"път за движение само на автобуси","ok":false,"i":null,"es":"camino exclusivo para autobuses"}],"es":"Esta señal designa: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: la señal puede designar tanto un carril específico como una calzada completa de uso exclusivo para transporte público regular. No es vía rápida ni solo autobuses."},{"id":6455,"bg":"При тази ситуация в средната пътна лента е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65112.png","v":null,"a":[{"t":"разрешено движението на автобуси с ремаркета","ok":false,"i":null,"es":"permitida la circulación de autobuses con remolque"},{"t":"разрешено движението на леки автомобили с ремаркета","ok":false,"i":null,"es":"permitida la circulación de turismos con remolque"},{"t":"забранено движението на товарни автомобили с ремаркета","ok":true,"i":null,"es":"PROHIBIDA la circulación de camiones con remolque"},{"t":"забранено движението на товарни автомобили с полуремаркета","ok":true,"i":null,"es":"PROHIBIDA la circulación de camiones con semirremolque"}],"es":"En esta situación en el carril central está: (2 correctas)","explain":"⚠️ TRAMPA: el carril central prohíbe camiones con remolque Y semirremolque. Los autobuses y turismos con remolque SÍ pueden — no son camiones."},{"id":6458,"bg":"Кои от посочените условия е необходимо да бъдат налице за да може водачите на мотопеди да използват за движение пътния банкет?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"пътният банкет да е разположен отдясно по посока на движението им и да е годен за това","ok":true,"i":null,"es":"el arcén debe estar a la derecha en el sentido de marcha y apto para ello"},{"t":"да няма специално предназначена за тях пътна лента","ok":true,"i":null,"es":"no debe haber carril especial destinado a ellos"},{"t":"да не пречат на другите участници в движението","ok":true,"i":null,"es":"no deben molestar a los demás participantes en el tráfico"},{"t":"пътният банкет да е сигнализиран с пътен знак","ok":false,"i":null,"es":"el arcén debe estar señalizado con señal de tráfico"}],"es":"¿Qué condiciones deben cumplirse para que los ciclomotores usen el arcén? (3 correctas)","explain":"⚠️ MULTIRESPUESTA: los ciclomotores pueden usar el arcén si: está a la derecha + es apto para circular + no hay carril propio + no molestan. La señalización específica del arcén NO es requisito."},{"id":6462,"bg":"Мотопедистите могат да използват за движение пътния банкет, който:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"се намира отдясно по посока на движението им","ok":true,"i":null,"es":"está a la DERECHA en su sentido de marcha"},{"t":"се намира отляво по посока на движението им","ok":false,"i":null,"es":"está a la IZQUIERDA en su sentido de marcha"},{"t":"е по-удобен за тях, независимо от коя страна на пътя се намира","ok":false,"i":null,"es":"sea más cómodo independientemente del lado"}],"es":"Los ciclomotores pueden usar el arcén que:","explain":"⚠️ TRAMPA: solo el arcén DERECHO. Los ciclomotores siempre circulan por la derecha — nunca usan el arcén izquierdo aunque sea más cómodo."},{"id":6468,"bg":"Когато има обозначена с пътен знак пътна лента за бавнодвижещи се ППС, водачите на такива ППС:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"са длъжни да използват за движение тази лента","ok":true,"i":null,"es":"están obligados a usar ese carril"},{"t":"използват тази лента само когато тя е свободна","ok":false,"i":null,"es":"lo usan solo cuando está libre"},{"t":"не са задължени да я използват","ok":false,"i":null,"es":"no están obligados a usarlo"}],"es":"Cuando hay un carril señalizado para vehículos lentos, los conductores de esos vehículos:","explain":"Están OBLIGADOS a usarlo — el carril para vehículos lentos es de uso obligatorio para quienes no pueden alcanzar la velocidad del resto del tráfico."},{"id":6492,"bg":"При тази ситуация водачът на бавнодвижещото се ППС:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65857.png","v":null,"a":[{"t":"е задължен да използва най-дясната пътна лента","ok":true,"i":null,"es":"está obligado a usar el carril más a la derecha"},{"t":"може да използва средната пътна лента при заобикаляне","ok":true,"i":null,"es":"puede usar el carril central al rodear un obstáculo"},{"t":"може да използва крайната лява лента при завиване","ok":true,"i":null,"es":"puede usar el carril izquierdo al girar"},{"t":"може да използва крайната лява лента при изпреварване","ok":false,"i":null,"es":"puede usar el carril izquierdo al ADELANTAR"}],"es":"En esta situación el conductor del vehículo lento: (3 correctas)","explain":"⚠️ TRAMPA: el carril izquierdo se puede usar para GIRAR pero NO para adelantar. Los vehículos lentos tienen acceso limitado al carril izquierdo — solo para giros, no para adelantamientos."},{"id":6495,"bg":"Водачът на бавнодвижещо се пътно превозно средство задължително се движи в най-дясната пътна лента, освен при:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"завиване","ok":true,"i":null,"es":"girar"},{"t":"заобикаляне","ok":true,"i":null,"es":"rodear un obstáculo"},{"t":"изпреварване","ok":false,"i":null,"es":"adelantar"}],"es":"El conductor de vehículo lento circula obligatoriamente en el carril más a la derecha, EXCEPTO para: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: los vehículos lentos van en el carril derecho EXCEPTO para girar Y para rodear obstáculos. El adelantamiento no es excepción permitida."},{"id":6497,"bg":"При тази ситуация разрешено ли е да преминете по трамвайните линии, за да изпреварите товарния автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65922.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"En esta situación ¿está permitido circular por las vías del tranvía para adelantar al camión?","explain":"SÍ.\n\nQUÉ VES. Calle urbana con VÍAS DE TRANVÍA a tu izquierda, al mismo nivel que la calzada y en tu mismo sentido. No viene ningún tranvía. Delante va un CAMIÓN y llevas el intermitente IZQUIERDO para adelantarlo pasando por las vías. Más allá, por el otro lado, circula un coche rojo en sentido contrario.\n\nLAS VÍAS DEL TRANVÍA EN TU SENTIDO SE PUEDEN USAR si están al mismo nivel que la calzada y no estorbas a ningún tranvía. Aquí se cumplen ambas cosas, así que puedes adelantar por ellas.\n\n«NO» es el cebo de quien cree que las vías del tranvía nunca se pueden pisar.\n\nCLAVE: vías en tu sentido, a nivel y sin tranvía = se pueden usar para adelantar. Ver Leyes → «Carril: dónde debes circular»."},{"id":9835,"bg":"Разрешено ли е да навлезете и да се движите по BUS-лентата?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043012.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"¿Está permitido entrar y circular por el carril BUS?","explain":"NO — el carril BUS es exclusivo para transporte público de línea regular. Los vehículos privados no pueden circular por él."},{"id":9837,"bg":"При тази ситуация, на водача е разрешено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043111.png","v":null,"a":[{"t":"да навлиза в средната пътна лента при изпреварване","ok":true,"i":null,"es":"entrar en el carril central para adelantar"},{"t":"да навлиза в средната пътна лента при заобикаляне","ok":true,"i":null,"es":"entrar en el carril central para rodear un obstáculo"},{"t":"да се движи в най-удобната за него пътна лента","ok":false,"i":null,"es":"circular en el carril más cómodo"},{"t":"да навлизат в крайната лява лента при изпреварване","ok":false,"i":null,"es":"entrar en el carril izquierdo para adelantar"}],"es":"En esta situación, al conductor le está PERMITIDO: (2 correctas)","explain":"ENTRAR EN EL CARRIL CENTRAL PARA ADELANTAR Y ENTRAR EN EL CARRIL CENTRAL PARA RODEAR UN OBSTÁCULO. Dos correctas.\n\nQUÉ VES. Una carretera fuera de población con TRES CARRILES y DOBLE SENTIDO: uno para cada sentido y el CENTRAL, separado por líneas discontinuas. Delante circula un coche ROJO.\n\nEL CENTRAL ES EL CARRIL COMPARTIDO. En una vía de tres carriles con doble sentido, el del centro sirve a los dos sentidos para dos maniobras concretas: ADELANTAR (изпреварване, a alguien que se mueve) y RODEAR (заобикаляне, algo parado en tu carril). No es un carril para viajar.\n\n«ENTRAR EN EL CARRIL IZQUIERDO PARA ADELANTAR» es el cebo: el carril de la izquierda es el del sentido contrario. Se adelanta por el central.\n\n«CIRCULAR POR EL CARRIL MÁS CÓMODO» es la excepción de la población con carriles señalizados en tu sentido; aquí no aplica.\n\nCLAVE: en tres carriles con doble sentido, el central es de préstamo: entras, haces la maniobra y vuelves. El izquierdo nunca es tuyo.\n\nMÉTODO: 1) ¿cuántos carriles hay y de qué sentido es cada uno? 2) ¿el central es compartido? 3) solo lo uso para adelantar o rodear. Ver Leyes → «Carril: dónde debes circular»."},{"id":9838,"bg":"При тази ситуация разположението на червения автомобил върху платното за движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043160.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"incorrecta"},{"t":"правилно","ok":false,"i":null,"es":"correcta"}],"es":"En esta situación la posición del coche rojo en la calzada es:","explain":"INCORRECTA — el coche rojo no está en el carril correcto o circula de forma que no cumple con las normas de posicionamiento."},{"id":9839,"bg":"На двулентов път с двупосочно движение навлизането в лентата за насрещно движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043211.png","v":null,"a":[{"t":"разрешено при изпреварване","ok":true,"i":null,"es":"permitido para adelantar"},{"t":"разрешено при заобикаляне","ok":true,"i":null,"es":"permitido para rodear un obstáculo"},{"t":"забранено във всички случаи","ok":false,"i":null,"es":"prohibido en todos los casos"},{"t":"разрешено винаги, когато е свободна","ok":false,"i":null,"es":"permitido siempre que esté libre"}],"es":"En vía de dos carriles con doble sentido, entrar en el carril contrario está: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: en vía de dos carriles puedes invadir el contrario para adelantar Y para rodear obstáculos. No cuando esté libre en general — solo para esas maniobras específicas."},{"id":9840,"bg":"При тази ситуация навлизането в BUS-лентата е разрешено за:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043260.png","v":null,"a":[{"t":"превозни средства от редовните линии за обществен превоз на пътници","ok":true,"i":null,"es":"vehículos de líneas regulares de transporte público"},{"t":"спиране за престой за всички автобуси","ok":false,"i":null,"es":"parada breve para todos los autobuses"},{"t":"придвижване на повредено МПС","ok":false,"i":null,"es":"traslado de vehículos averiados"},{"t":"движение на бавнодвижещи се МПС","ok":false,"i":null,"es":"vehículos lentos"}],"es":"En esta situación entrar en el carril BUS está permitido para:","explain":"Solo los vehículos de LÍNEAS REGULARES de transporte público. No todos los autobuses, no los averiados ni los lentos."},{"id":11585,"bg":"На път с три пътни ленти за движение в една посока, указани с пътен знак, в крайната лява лента е забранено движението на:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65145.png","v":null,"a":[{"t":"превозни средства, които не могат да развиват максималната за пътя скорост","ok":true,"i":null,"es":"por vehículos que no pueden alcanzar la velocidad máxima de esa vía"},{"t":"превозни средства, на които е забранено да развиват разрешената за пътя максимална скорост","ok":true,"i":null,"es":"por vehículos a los que está prohibido circular a la velocidad máxima"},{"t":"превозни средства, водачите на които са със стаж по-малко от 1 година","ok":false,"i":null,"es":"por vehículos cuyos conductores tienen menos de 1 año de permiso"}],"es":"En vía de 3 carriles en un sentido señalizados, el carril izquierdo NO puede usarse: (2 correctas)","explain":"LOS VEHÍCULOS QUE NO PUEDEN ALCANZAR LA VELOCIDAD MÁXIMA DE LA VÍA Y AQUELLOS A LOS QUE ESTÁ PROHIBIDO ALCANZARLA. Dos correctas.\n\nQUÉ VES. Una vía de TRES CARRILES en tu sentido, con la señal azul de carriles (tres flechas) a la derecha.\n\nEL CARRIL IZQUIERDO ES EL MÁS RÁPIDO, y por eso se cierra a quien no puede seguir su ritmo, por dos motivos:\n\nNO PODER: el vehículo, por su construcción, no llega a la velocidad máxima de la vía (por ejemplo, un tractor o un ciclomotor).\n\nNO TENER PERMITIDO: el vehículo podría ir más rápido, pero tiene un límite propio inferior al de la vía (por ejemplo, camiones pesados o vehículos con remolque).\n\n«CONDUCTORES CON MENOS DE 1 AÑO DE PERMISO» es el cebo: los conductores noveles tienen otras limitaciones, pero esta norma mira el VEHÍCULO, no la antigüedad del carné.\n\nCLAVE: el carril izquierdo se cierra por velocidad: a quien no puede y a quien no debe.\n\nMÉTODO: 1) ¿cuántos carriles hay en mi sentido? 2) ¿mi vehículo puede y tiene permitido ir a la máxima de la vía? 3) si no, el carril izquierdo no es para mí. Ver Leyes → «Carril: dónde debes circular»."},{"id":11684,"bg":"Кои от посочените условия е необходимо да бъдат налице за да може при движение в населено място водачът да използва най-удобната за него пътна лента?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62168.png","v":null,"a":[{"t":"пътното платно да е с две и повече пътни ленти за движение в една посока","ok":true,"i":null,"es":"la calzada tiene dos o más carriles en una dirección"},{"t":"лентите за двиние да са обозначени с пътна маркировка","ok":true,"i":null,"es":"los carriles están marcados con señalización horizontal"},{"t":"разрешената скорост за движение да е не по-голяма от 80 km/h","ok":true,"i":null,"es":"la velocidad máxima permitida es no superior a 80 km/h"},{"t":"общата маса на превозното средство да е не повече от 3,5 тона","ok":false,"i":null,"es":"la masa total del vehículo no supera 3.5 toneladas"}],"es":"¿Qué condiciones deben cumplirse para que en zona urbana se pueda circular por carriles distintos al derecho? (3 correctas)","explain":"⚠️ MULTIRESPUESTA: 2+ carriles + marcas + máximo 80 km/h. La masa del vehículo NO es una condición para usar carriles distintos."},{"id":11685,"bg":"Кои от посочените условия е необходимо да бъдат налице за да може при движение в населено място водачът да използва най-удобната за него пътна лента?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62284.png","v":null,"a":[{"t":"пътното платно да е с две и повече пътни ленти за движение в една посока","ok":true,"i":null,"es":"la calzada tiene dos o más carriles en una dirección"},{"t":"броят на пътните ленти и посоките за движение по тях да са обозначени с пътен знак","ok":true,"i":null,"es":"el número de carriles y las direcciones están señalizados"},{"t":"разрешената скорост за движение да е не по-голяма от 80 km/h","ok":true,"i":null,"es":"la velocidad máxima permitida es no superior a 80 km/h"},{"t":"пътят да е с две платна за движение","ok":false,"i":null,"es":"la vía tiene dos calzadas de circulación"}],"es":"¿Qué condiciones deben cumplirse para circular por carriles distintos al derecho en zona urbana? (3 correctas)","explain":"⚠️ MULTIRESPUESTA: 2+ carriles + señalización de carriles + máximo 80 km/h. Tener dos calzadas separadas NO es una condición para esto."},{"id":11686,"bg":"Кои от посочените условия е необходимо да бъдат налице за да може при движение в населено място водачът да използва най-удобната за него пътна лента?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62875.png","v":null,"a":[{"t":"пътното платно да е с две и повече пътни ленти за движение в една посока","ok":true,"i":null,"es":"la calzada tiene dos o más carriles en una dirección"},{"t":"разрешената скорост за движение да е не по-голяма от 80 km/h","ok":true,"i":null,"es":"la velocidad máxima permitida es no superior a 80 km/h"},{"t":"пътното платно да е с не по-малко от три пътни ленти за движение в една посока","ok":false,"i":null,"es":"la calzada tiene no menos de tres carriles en una dirección"},{"t":"разрешената скорост за движение да е не по-голяма от 50 km/h","ok":false,"i":null,"es":"la velocidad máxima es no superior a 50 km/h"}],"es":"¿Qué condiciones deben darse para poder usar carriles distintos al derecho en zona urbana? (2 correctas)","explain":"QUE LA CALZADA TENGA DOS O MÁS CARRILES EN UN SENTIDO Y QUE LA VELOCIDAD MÁXIMA PERMITIDA NO SUPERE 80 km/h. Dos correctas.\n\nQUÉ VES. Calle urbana con señales de máxima 60 y placas que indican TRES carriles en tu sentido.\n\nLA EXCEPCIÓN DE LA POBLACIÓN TIENE DOS CONDICIONES. En población puedes usar el carril que te resulte más cómodo (no solo el derecho) si: hay dos o más carriles en tu sentido y la velocidad máxima permitida no pasa de 80 km/h. Aquí se cumplen las dos.\n\n«NO MENOS DE TRES CARRILES» exige de más: bastan dos.\n\n«VELOCIDAD MÁXIMA NO SUPERIOR A 50 km/h» también exige de más: el límite de la condición es 80.\n\nCLAVE: población + 2 carriles o más en tu sentido + máximo ≤ 80 km/h = libertad de carril. Ver Leyes → «Carril: dónde debes circular»."},{"id":11687,"bg":"При тази ситуация, движението по обозначената с пътен знак лента за бавнодвижещи се ППС е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123801986.png","v":null,"a":[{"t":"разрешено за автомобили обозначени с опознавателен знак „бавнодвижещи се ППС”","ok":true,"i":null,"es":"permitida para vehículos marcados con señal de vehículo lento"},{"t":"разрешено за автомобили, които не могат да се движат със скорост по-висока от 30 km/h","ok":true,"i":null,"es":"permitida para vehículos que no pueden superar 30 km/h"},{"t":"забранено за трактори","ok":false,"i":null,"es":"prohibida para tractores"},{"t":"забранено за товарни автомобили","ok":false,"i":null,"es":"prohibida para camiones"}],"es":"En esta situación, la circulación por el carril señalizado para vehículos lentos está: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el carril lento es para vehículos con señal de lento Y para los que no superan 30 km/h. Tractores y camiones SÍ pueden usarlo si cumplen esas condiciones."},{"id":11688,"bg":"При тази ситуация, движението по обозначената с пътен знак лента за бавнодвижещи се ППС е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123801988.png","v":null,"a":[{"t":"разрешено за автомобили обозначени с опознавателен знак „бавнодвижещи се ППС”","ok":true,"i":null,"es":"permitido para vehículos marcados con señal de vehículo lento"},{"t":"разрешено за автомобили, които не могат да се движат със скорост по-висока от 30 km/h","ok":true,"i":null,"es":"permitido para vehículos que no pueden superar 30 km/h"},{"t":"забранено за велосипеди","ok":false,"i":null,"es":"prohibido para bicicletas"},{"t":"забранено за мотопеди","ok":false,"i":null,"es":"prohibido para ciclomotores"}],"es":"En esta situación, circular por el carril señalizado para vehículos lentos está: (2 correctas)","explain":"PERMITIDO PARA LOS VEHÍCULOS CON EL DISTINTIVO DE «VEHÍCULO LENTO» Y PARA LOS QUE NO PUEDEN SUPERAR 30 km/h. Dos correctas.\n\nQUÉ VES. Una carretera en subida. A la derecha, un panel AZUL que dibuja los carriles: aparece un carril adicional a la derecha para VEHÍCULOS LENTOS (con su símbolo) y, sobre los demás carriles, la señal azul de VELOCIDAD MÍNIMA 40 km/h. Por el carril derecho va un vehículo amarillo con el triángulo naranja de vehículo lento en la parte trasera.\n\nQUIÉN USA EL CARRIL DE LENTOS. Los vehículos que llevan el distintivo de vehículo lento y los que, por construcción, no pueden ir a más de 30 km/h. Son justo los que no podrían cumplir el mínimo de 40 del resto de carriles.\n\n«PROHIBIDO PARA BICICLETAS» y «PROHIBIDO PARA CICLOMOTORES» son los cebos: una bicicleta y un ciclomotor son vehículos lentos; ese carril es precisamente su sitio, no un lugar prohibido para ellos.\n\nCLAVE: carril de lentos = para quien no puede seguir el ritmo del resto (distintivo o máximo 30 km/h).\n\nMÉTODO: 1) ¿qué carril indica el panel? 2) ¿qué velocidad mínima tienen los demás carriles? 3) quien no puede cumplirla va por el de lentos. Ver Leyes → «Carril: dónde debes circular»."},{"id":11821,"bg":"При тази ситуация, в крайната лява пътна лента е забранено движението на:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65242.png","v":null,"a":[{"t":"леки автомобили с ремаркета над 750 kg","ok":true,"i":null,"es":"turismos con remolque de más de 750 kg"},{"t":"мотоциклети","ok":true,"i":null,"es":"motos"},{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"всички товарни автомобили","ok":false,"i":null,"es":"todos los camiones"}],"es":"En esta situación, en el carril izquierdo está PROHIBIDO circular a: (3 correctas)","explain":"TURISMOS CON REMOLQUE DE MÁS DE 750 kg, MOTOS Y CICLOMOTORES. Tres correctas.\n\nQUÉ VES. Una autovía con TRES carriles en tu sentido (señal azul con tres flechas hacia arriba).\n\nEL CARRIL IZQUIERDO, EN VÍAS DE TRES O MÁS CARRILES POR SENTIDO, ESTÁ VEDADO A LOS MÁS LENTOS O PESADOS: entre otros, los turismos con remolque de más de 750 kg, las motos y los ciclomotores.\n\n«TODOS LOS CAMIONES» es el cebo: la prohibición no alcanza a todos los camiones sin distinción.\n\nCLAVE: compárala con la 11585 (quién no puede ir por el carril izquierdo según su velocidad). Ver Leyes → «Carril: dónde debes circular»."},{"id":11870,"bg":"При тази ситуация на кои от посочените ППС е разрешено да се движат в средната пътна лента:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64852.png","v":null,"a":[{"t":"автобуси","ok":true,"i":null,"es":"autobuses"},{"t":"леки автомобили","ok":true,"i":null,"es":"turismos"},{"t":"товарни автомобили с допустима максимална маса над 3,5 t","ok":false,"i":null,"es":"camiones con MMA superior a 3.5 t"},{"t":"товарни автомобили с допустима максимална маса до 3,5 t","ok":false,"i":null,"es":"camiones con MMA hasta 3.5 t"}],"es":"En esta situación ¿a qué vehículos está permitido circular por el carril central? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el carril central permite autobuses Y turismos. Los camiones (ambas categorías) tienen restricciones en el carril central."},{"id":11871,"bg":"На кои от изброените пътни превозни средства е разрешено движението по пътния банкет?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"велосипеди","ok":true,"i":null,"es":"bicicletas"},{"t":"мотоциклети","ok":false,"i":null,"es":"motocicletas"},{"t":"автомобили с допустима максимална маса до 1,5 t","ok":false,"i":null,"es":"automóviles hasta 1.5 t"}],"es":"¿A qué vehículos está permitido circular por el arcén? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: solo ciclomotores Y bicicletas pueden usar el arcén. Las motocicletas y los automóviles deben circular por la calzada."},{"id":5792,"bg":"Този пътен знак:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53696.png","v":null,"a":[{"t":"забранява движението със скорост по-висока от означената","ok":true,"i":null,"es":"prohíbe circular a velocidad superior a la indicada"},{"t":"указва задължителна минимална скорост за движение","ok":false,"i":null,"es":"indica velocidad mínima obligatoria"},{"t":"сигнализира препоръчителна скорост за движение","ok":false,"i":null,"es":"indica velocidad recomendada"}],"es":"Esta señal:","explain":"PROHÍBE CIRCULAR A VELOCIDAD SUPERIOR A LA INDICADA. Una sola correcta.\n\nLA SEÑAL. Círculo blanco con BORDE ROJO y «50» en negro: VELOCIDAD MÁXIMA.\n\nLAS SEÑALES DE VELOCIDAD QUE SE CONFUNDEN:\n• Círculo blanco con BORDE ROJO y cifra negra = velocidad MÁXIMA.\n• Círculo AZUL con cifra blanca = velocidad MÍNIMA obligatoria.\n• CUADRADO AZUL con cifra blanca = velocidad RECOMENDADA.\n• Círculo blanco con la cifra TACHADA = FIN de la limitación.\n\n«VELOCIDAD MÍNIMA OBLIGATORIA» sería un círculo azul. «VELOCIDAD RECOMENDADA» sería un cuadrado azul.\n\nCLAVE: borde rojo = prohibición; aquí, prohibido superar 50 km/h. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5795,"bg":"Разрешено ли е след този пътен знак движение със скорост по-висока от означената?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53771.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"¿Está permitido circular a velocidad superior a la indicada después de esta señal?","explain":"NO.\n\nQUÉ VES. Carretera fuera de población con la señal de VELOCIDAD MÁXIMA 50 (círculo de borde rojo). Delante va un coche rojo.\n\nDESPUÉS DE ESTA SEÑAL NO PUEDES SUPERAR 50 km/h, aunque fuera de población el límite general sea más alto. La señal manda sobre el límite general hasta que otra señal la cancele (fin de limitación) o la cambie.\n\n«SÍ» es el cebo de quien recuerda que fuera de población se puede ir a 90.\n\nCLAVE: la señal de máxima prevalece sobre el límite general. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5796,"bg":"Разрешено ли е след този пътен знак движение със скорост по-висока от означената?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53889.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да, във всички случаи","ok":false,"i":null,"es":"sí, en todos los casos"},{"t":"да, но само когато има необходимите условия за безопасност","ok":false,"i":null,"es":"sí, pero solo con condiciones de seguridad"},{"t":"да, но само когато пътят е сух","ok":false,"i":null,"es":"sí, pero solo con carretera seca"}],"es":"¿Está permitido circular a velocidad superior a la indicada después de esta señal?","explain":"NO.\n\nQUÉ VES. La misma escena que la 5795: señal de VELOCIDAD MÁXIMA 50 (círculo de borde rojo) en una carretera fuera de población.\n\nEL MÁXIMO NO TIENE EXCEPCIONES POR BUEN TIEMPO. Ni la carretera seca, ni la buena visibilidad, ni que haya «condiciones de seguridad» te permiten superar la cifra. Esas condiciones sirven para ir MÁS DESPACIO del máximo, nunca para pasarlo.\n\n«SÍ, EN TODOS LOS CASOS», «SÍ, CON CONDICIONES DE SEGURIDAD» y «SÍ, CON CARRETERA SECA» son tres cebos con la misma idea falsa: que el límite se puede estirar.\n\nCLAVE: las condiciones de seguridad pueden obligarte a ir por debajo del máximo, nunca te permiten superarlo. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5797,"bg":"Този пътен знак:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334711.png","v":null,"a":[{"t":"сигнализира за край на ограничението на скоростта, въведено с пътен знак","ok":true,"i":null,"es":"señaliza el final de la limitación de velocidad impuesta por señal"},{"t":"забранява движението на МПС, които не могат да развият скорост, по-голяма от означената","ok":false,"i":null,"es":"prohíbe circular a vehículos que no pueden alcanzar la velocidad indicada"},{"t":"забрананява движението със скорост, по-висока от означената","ok":false,"i":null,"es":"prohíbe circular a velocidad superior a la indicada"},{"t":"забрананява движението със скорост, по-ниска от означената","ok":false,"i":null,"es":"prohíbe circular a velocidad inferior a la indicada"}],"es":"Esta señal:","explain":"SEÑALIZA EL FINAL DE LA LIMITACIÓN DE VELOCIDAD IMPUESTA POR SEÑAL. Una sola correcta.\n\nLA SEÑAL. Círculo blanco con borde negro, la cifra 50 en negro y TACHADA con barras diagonales. Las barras significan «fin»: cancelan lo que decía la señal anterior.\n\nQUÉ PASA DESPUÉS. Vuelve a aplicarse el límite general de la vía para tu categoría (para turismos: 50 km/h en población, 90 fuera de población, 120 en vía rápida, 140 en autopista), salvo que otra señal diga otra cosa. No significa «velocidad libre».\n\n«PROHÍBE CIRCULAR A VELOCIDAD SUPERIOR A LA INDICADA» es la señal SIN tachar, con borde ROJO. Se distingue por el color del borde y por la ausencia de barras.\n\n«PROHÍBE CIRCULAR A VELOCIDAD INFERIOR» describiría un mínimo, que es una señal azul.\n\n«PROHÍBE CIRCULAR A VEHÍCULOS QUE NO ALCANZAN LA VELOCIDAD» es otra señal distinta.\n\n(Corrección: la explicación anterior daba 120 km/h como límite en autopista; para turismos en autopista es 140 km/h).\n\nCLAVE: blanco con barras = FIN de una restricción.\n\nMÉTODO: 1) ¿borde rojo o blanco/negro? 2) ¿tiene barras? 3) barras = fin de lo que indicaba. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5798,"bg":"След този пътен знак няма ограничение за скоростта на движение.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53963.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"Después de esta señal no hay ninguna limitación de velocidad. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Carretera fuera de población. A la derecha, la señal de FIN DE LA LIMITACIÓN DE 60 km/h (círculo blanco con el 60 tachado). Delante circula un coche rojo.\n\nSE ACABA EL 60, NO LOS LÍMITES. La señal cancela la restricción de 60 km/h, y vuelve a aplicarse el límite general de esa vía: fuera de población, para un turismo, 90 km/h. Siempre hay un límite.\n\n«CORRECTO» es el cebo: leer «fin de limitación» como «sin límite».\n\nCLAVE: fin de limitación = vuelve el límite general, no velocidad libre. Es la misma idea que la 5797.\n\nMÉTODO: 1) ¿qué limitación termina? 2) ¿dónde estoy (población, carretera, vía rápida, autopista)? 3) se aplica el límite general de ese tipo de vía. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5806,"bg":"След този пътен знак движението с разрешената максимална скорост е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54052.png","v":null,"a":[{"t":"разрешено само при наличие на необходимите условия за безопасност","ok":true,"i":null,"es":"permitido solo si hay condiciones de seguridad"},{"t":"разрешено във всички случаи","ok":false,"i":null,"es":"permitido siempre"},{"t":"забранено","ok":false,"i":null,"es":"prohibido"}],"es":"Después de esta señal, circular a la velocidad máxima permitida está:","explain":"PERMITIDO SOLO SI HAY LAS CONDICIONES NECESARIAS DE SEGURIDAD. Una sola correcta.\n\nQUÉ VES. Carretera fuera de población. A la derecha, señal de FIN DE LA LIMITACIÓN de 40 km/h (círculo blanco con el 40 tachado). Delante, un coche azul; de frente, un camión.\n\nDESPUÉS DE LA SEÑAL vuelve el límite general de esa vía (fuera de población, 90 km/h para un turismo con carácter general).\n\nLA VELOCIDAD MÁXIMA ES UN TECHO, NO UN DERECHO. Puedes ir hasta ese límite solo si las condiciones (visibilidad, estado de la calzada, tráfico, peatones) lo permiten con seguridad. Si no, tienes que ir más despacio.\n\n«PERMITIDO SIEMPRE» es el cebo: olvida que el límite es un máximo, no una obligación.\n\n«PROHIBIDO» es el cebo contrario: la señal precisamente levanta la restricción.\n\nCLAVE: fin de limitación = vuelve el máximo general, que solo se usa si es seguro. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5808,"bg":"При тази ситуация водачът на червения автомобил може да се движи с разрешената максимална скорост:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54069.png","v":null,"a":[{"t":"само при наличието на необходимите условия за безопасност","ok":true,"i":null,"es":"solo si hay condiciones de seguridad suficientes"},{"t":"във всички случаи","ok":false,"i":null,"es":"en todos los casos"},{"t":"само, ако има стаж като водач над 2 години","ok":false,"i":null,"es":"solo si lleva más de 2 años de permiso"}],"es":"En esta situación el conductor del coche rojo puede circular a la velocidad máxima permitida:","explain":"SOLO SI HAY LAS CONDICIONES NECESARIAS DE SEGURIDAD. Una sola correcta.\n\nQUÉ VES. Carretera con árboles a ambos lados. A la derecha, señal de FIN DE LA LIMITACIÓN de 40 km/h. Delante, el coche ROJO.\n\nDESPUÉS DE LA SEÑAL, el rojo puede volver al límite general de la vía, pero:\n\nLA VELOCIDAD MÁXIMA ES UN TECHO, NO UN DERECHO. Puedes ir hasta ese límite solo si las condiciones (visibilidad, estado de la calzada, tráfico, peatones) lo permiten con seguridad. Si no, tienes que ir más despacio.\n\n«EN TODOS LOS CASOS» es el cebo: el máximo nunca es incondicional.\n\n«SOLO SI LLEVA MÁS DE 2 AÑOS DE PERMISO» es el cebo: aunque tengas mucha experiencia, el máximo solo se usa si las condiciones lo permiten. La antigüedad del permiso no convierte el máximo en un derecho.\n\nCLAVE: igual que la 5806: máximo = techo condicionado a la seguridad. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5810,"bg":"Този пътен знак:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334712.png","v":null,"a":[{"t":"указва препоръчителна скорост за движение","ok":true,"i":null,"es":"indica velocidad RECOMENDADA"},{"t":"забранява движение със скорост, по-висока от означената","ok":false,"i":null,"es":"prohíbe circular a velocidad superior a la indicada"},{"t":"указва задължителна минимална скорост за движение","ok":false,"i":null,"es":"indica velocidad MÍNIMA obligatoria"}],"es":"Esta señal:","explain":"INDICA LA VELOCIDAD RECOMENDADA. Una sola correcta.\n\nLA SEÑAL. CUADRADO AZUL con «60» en blanco.\n\nLAS SEÑALES DE VELOCIDAD QUE SE CONFUNDEN:\n• Círculo blanco con BORDE ROJO y cifra negra = velocidad MÁXIMA.\n• Círculo AZUL con cifra blanca = velocidad MÍNIMA obligatoria.\n• CUADRADO AZUL con cifra blanca = velocidad RECOMENDADA.\n• Círculo blanco con la cifra TACHADA = FIN de la limitación.\n\n«PROHÍBE SUPERAR LA VELOCIDAD» sería el círculo de borde rojo.\n\n«VELOCIDAD MÍNIMA OBLIGATORIA» sería el círculo azul: mismo color, distinta forma. Esa es la trampa.\n\nCLAVE: azul cuadrado = recomendación; azul redondo = obligación. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5817,"bg":"При тази ситуация разрешено ли е движение със скорост, по-висока от означената?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/103539.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"En esta situación ¿está permitido circular a velocidad superior a la indicada?","explain":"SÍ.\n\nQUÉ VES. Carretera fuera de población. A la derecha, un CUADRADO AZUL con «60»: VELOCIDAD RECOMENDADA.\n\nLA RECOMENDADA NO ES UN LÍMITE. Indica la velocidad aconsejable para ese tramo, pero no prohíbe ir más rápido. El límite que se aplica sigue siendo el general de la vía (o el que fije otra señal).\n\n«NO» es el cebo de quien lee cualquier número como un máximo.\n\n(Corrección: la explicación anterior decía que era una señal de velocidad mínima; es la de velocidad RECOMENDADA, cuadrada).\n\nCLAVE: cuadrado azul con número = recomendación; puedes superarla respetando el límite de la vía.\n\nMÉTODO: 1) ¿forma redonda o cuadrada? 2) ¿borde rojo o fondo azul? 3) cuadrado azul = recomendación. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5819,"bg":"При тази ситуация разрешено ли е движение със скорост, по-ниска от означената?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54273.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"En esta situación ¿está permitido circular a velocidad inferior a la indicada?","explain":"SÍ.\n\nQUÉ VES. Carretera fuera de población. A la derecha, un CUADRADO AZUL con «60»: VELOCIDAD RECOMENDADA.\n\nUNA RECOMENDACIÓN NO OBLIGA. Puedes ir más despacio que la velocidad recomendada (y también más rápido, siempre que respetes el límite de la vía). Solo es una indicación de la velocidad aconsejable para ese tramo.\n\n«NO» es el cebo de quien la confunde con la señal de velocidad mínima (círculo azul), que sí obliga.\n\n(Corrección: la explicación anterior decía que era una señal de velocidad mínima; es la de velocidad RECOMENDADA, cuadrada).\n\nCLAVE: cuadrado azul = recomendación, no obligación. Compárala con la 5817 (la misma señal, preguntando si se puede ir más rápido). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5821,"bg":"Този пътен знак:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334713.png","v":null,"a":[{"t":"указва задължителна минимална скорост за движение","ok":true,"i":null,"es":"indica velocidad MÍNIMA obligatoria"},{"t":"забранява движение със скорост, по-висока от означената","ok":false,"i":null,"es":"prohíbe circular a velocidad superior"},{"t":"указва препоръчителна скорост за движение","ok":false,"i":null,"es":"indica velocidad RECOMENDADA"}],"es":"Esta señal:","explain":"INDICA LA VELOCIDAD MÍNIMA OBLIGATORIA. Una sola correcta.\n\nLA SEÑAL. Círculo AZUL con la cifra en BLANCO (30). El azul en una señal circular es OBLIGACIÓN.\n\nQUÉ TE OBLIGA A HACER. A no circular por debajo de esa velocidad (salvo que las condiciones de seguridad no lo permitan; compárala con la 5827). Si tu vehículo no puede alcanzarla, no debe entrar en esa vía o carril.\n\n«PROHÍBE CIRCULAR A VELOCIDAD SUPERIOR A LA INDICADA» es el cebo más elegido: el reflejo es leer cualquier número como un máximo. El máximo es un círculo con borde ROJO y la cifra en negro.\n\n«VELOCIDAD RECOMENDADA» es otra señal: cuadrada/rectangular azul, no circular.\n\nCLAVE: círculo azul con número = mínimo; círculo de borde rojo con número = máximo.\n\nMÉTODO: 1) ¿qué forma? 2) ¿qué color? 3) circular azul = obligación. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5827,"bg":"При тази ситуация разрешено ли е движение със скорост по-ниска от означената?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57482.png","v":null,"a":[{"t":"да, когато няма необходимите условия за безопасност","ok":true,"i":null,"es":"sí, cuando no hay las condiciones necesarias de seguridad"},{"t":"да, във всички случаи","ok":false,"i":null,"es":"sí, en todos los casos"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"En esta situación ¿está permitido circular a velocidad inferior a la indicada?","explain":"SÍ, CUANDO NO SE DAN LAS CONDICIONES NECESARIAS DE SEGURIDAD. Una sola correcta.\n\nQUÉ VES. Carretera fuera de población. A la derecha, señal circular AZUL con «50»: VELOCIDAD MÍNIMA obligatoria.\n\nEL MÍNIMO CEDE ANTE LA SEGURIDAD. Normalmente no puedes ir por debajo de 50 km/h. Pero si las condiciones no lo permiten con seguridad (niebla, lluvia fuerte, hielo, un obstáculo, tráfico denso), puedes ir más despacio.\n\n«SÍ, EN TODOS LOS CASOS» es el cebo que vacía la señal: si pudieras ir más lento siempre, la señal no serviría para nada.\n\n«NO» es el cebo contrario: obligaría a mantener 50 km/h aunque haya hielo o niebla.\n\nCLAVE: velocidad mínima = obligatoria, salvo que la seguridad exija ir más despacio.\n\nMÉTODO: 1) ¿la señal es un mínimo (azul) o un máximo (borde rojo)? 2) si es mínimo, ¿hay condiciones de seguridad? 3) solo sin ellas se puede bajar. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5830,"bg":"Този пътен знак:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57569.png","v":null,"a":[{"t":"означава край на задължителната минимална скорост","ok":true,"i":null,"es":"indica FIN de la velocidad mínima obligatoria"},{"t":"забранява движението със скорост по-висока от означената","ok":false,"i":null,"es":"prohíbe velocidad superior a la indicada"},{"t":"забранява движението със скорост по-ниска от означената","ok":false,"i":null,"es":"prohíbe velocidad inferior a la indicada"},{"t":"означава край на препоръчителната скорост на движение","ok":false,"i":null,"es":"indica fin de la velocidad recomendada"}],"es":"Esta señal:","explain":"INDICA EL FIN DE LA VELOCIDAD MÍNIMA OBLIGATORIA. Una sola correcta.\n\nLA SEÑAL. Círculo AZUL con «30» en blanco, cruzado por una BARRA ROJA diagonal.\n\nEL CÍRCULO AZUL CON CIFRA ES LA VELOCIDAD MÍNIMA; la barra roja lo anula. A partir de aquí ya no estás obligado a ir al menos a 30 km/h.\n\n«PROHÍBE VELOCIDAD SUPERIOR» sería un círculo de borde rojo. «PROHÍBE VELOCIDAD INFERIOR» sería la propia señal de mínimo, sin tachar.\n\n«FIN DE LA VELOCIDAD RECOMENDADA» es el cebo fino: la recomendada es CUADRADA; esta es redonda.\n\nCLAVE: redondo azul + barra = fin del mínimo. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5832,"bg":"След този пътен знак движението със скорост, по-висока от означената е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57621.png","v":null,"a":[{"t":"забранено за всички ППС","ok":true,"i":null,"es":"prohibido para todos los vehículos"},{"t":"разрешено за транзитно преминаващите ППС","ok":false,"i":null,"es":"permitido para los que hacen tránsito"},{"t":"разрешено за МПС от категория “В”","ok":false,"i":null,"es":"permitido para categoría B"},{"t":"забранено само за водачите на двуколесни ППС","ok":false,"i":null,"es":"prohibido solo para vehículos de dos ruedas"}],"es":"Después de esta señal, circular a velocidad superior a la indicada está:","explain":"PROHIBIDO PARA TODOS LOS VEHÍCULOS. Una sola correcta.\n\nLA SEÑAL. Rectángulo blanco con la palabra «ЗОНА» (ZONA) y, debajo, la señal de velocidad máxima (círculo de borde rojo).\n\nLA LIMITACIÓN DE ZONA VALE PARA TODOS. Dentro de la zona, ningún vehículo puede superar la velocidad indicada, sea de la categoría que sea y esté de paso o no.\n\n«PERMITIDO PARA LOS QUE ESTÁN DE PASO», «PERMITIDO PARA LA CATEGORÍA B» y «PROHIBIDO SOLO PARA LOS DE DOS RUEDAS» son cebos que inventan excepciones que la señal no tiene.\n\nCLAVE: si la señal no lleva una placa que diga a quién se aplica, se aplica a todos. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5833,"bg":"При тази ситуация забраната за движение със скорост, по-висока от означената се отнася:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57654.png","v":null,"a":[{"t":"за всички улици в зоната","ok":true,"i":null,"es":"todas las calles de la zona"},{"t":"само за улицата, в чието начало е поставен","ok":false,"i":null,"es":"solo la calle donde está la señal"},{"t":"за водачите на всички ППС","ok":true,"i":null,"es":"todos los conductores"},{"t":"само за водачите на леки автомобили","ok":false,"i":null,"es":"solo los conductores de turismos"}],"es":"En esta situación la prohibición de circular a velocidad superior a la indicada se refiere a: (2 correctas)","explain":"A TODAS LAS CALLES DE LA ZONA Y A LOS CONDUCTORES DE TODOS LOS VEHÍCULOS. Dos correctas.\n\nQUÉ VES. Calle urbana con peatones en las aceras. A la derecha, la señal «ЗОНА» con el límite de 40 km/h. Delante va un coche rojo.\n\nUNA SEÑAL DE ZONA NO SE ACABA EN EL SIGUIENTE CRUCE. A diferencia de una señal normal, vale para todas las calles del área hasta la señal de fin de zona. Y vale para todos los vehículos.\n\n«SOLO PARA LA CALLE DONDE ESTÁ LA SEÑAL» es el cebo de quien aplica la lógica de una señal normal.\n\n«SOLO PARA LOS TURISMOS» inventa una excepción.\n\nCLAVE: «ЗОНА» = toda el área y todos los vehículos, hasta el fin de zona. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5836,"bg":"Коефициентът на сцепление на автомобилните гуми с пътя е показател за:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"взаимодействието между автомобилната гума и пътната настилка","ok":true,"i":null,"es":"la interacción entre el neumático y el pavimento"},{"t":"аеродинамичните качества на автомобила","ok":false,"i":null,"es":"las cualidades aerodinámicas del vehículo"},{"t":"ефективността на спирачната система на автомобила","ok":false,"i":null,"es":"la eficacia del sistema de frenos"}],"es":"El coeficiente de rozamiento entre neumáticos y calzada es un indicador de:","explain":"El coeficiente de rozamiento mide la INTERACCIÓN entre el neumático y el pavimento — cuánta adherencia hay. No es aerodinámica ni eficacia de frenos, aunque influye en el frenado."},{"id":5838,"bg":"За стабилно и сигурно движение на превозното средство, стойността на коефициента на сцепление на автомобилните гуми с пътя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да е възможно по-голяма","ok":true,"i":null,"es":"lo más GRANDE posible"},{"t":"трябва да е възможно по-малка","ok":false,"i":null,"es":"lo más PEQUEÑO posible"},{"t":"е без значение","ok":false,"i":null,"es":"no tiene importancia"}],"es":"Para una circulación estable y segura, el coeficiente de rozamiento debe ser:","explain":"⚠️ TRAMPA: cuanto MAYOR es el rozamiento, mayor es la adherencia y más seguro el frenado. Mayor rozamiento = más seguro. Menor rozamiento (hielo, lluvia) = peligroso."},{"id":5840,"bg":"Коефициентът на сцепление на автомобилните гуми с пътя е най-голям когато пътната настилка е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"суха","ok":true,"i":null,"es":"seco"},{"t":"мокра","ok":false,"i":null,"es":"mojado"},{"t":"заснежена","ok":false,"i":null,"es":"con nieve"},{"t":"заледена","ok":false,"i":null,"es":"helado"}],"es":"El coeficiente de rozamiento entre neumáticos y calzada es mayor cuando el pavimento está:","explain":"Máximo rozamiento en asfalto SECO. El orden de menor a mayor adherencia: hielo < nieve < mojado < seco. En seco siempre se frena más corto."},{"id":5842,"bg":"Влияние върху големината на коефициента на сцепление на автомобилните гуми с пътя оказват:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"видът на пътната настилка","ok":true,"i":null,"es":"el tipo de pavimento"},{"t":"състоянието на пътната настилка","ok":true,"i":null,"es":"el estado del pavimento"},{"t":"видът на автомобилните гуми","ok":true,"i":null,"es":"el tipo de neumático"},{"t":"диаметърът на автомобилните гуми","ok":false,"i":null,"es":"el diámetro del neumático"}],"es":"El coeficiente de rozamiento neumático-asfalto está influido por: (3 correctas)","explain":"⚠️ TRAMPA: tipo de pavimento + estado del pavimento + tipo de neumático influyen. El DIÁMETRO del neumático no afecta significativamente al coeficiente de rozamiento."},{"id":5844,"bg":"Зависи ли коефициентът на сцепление на автомобилните гуми с пътя от състоянието на пътната настилка?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Depende el coeficiente de rozamiento del estado del pavimento?","explain":"SÍ — el estado del pavimento (seco, mojado, helado, con arena, etc.) es el factor principal que determina el coeficiente de rozamiento. Es la respuesta más básica de física del tráfico."},{"id":5846,"bg":"Как се изменя сцеплението на автомобилните гуми с пътя при мокра настилка в сравнение със суха?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"намалява","ok":true,"i":null,"es":"disminuye"},{"t":"увеличава се","ok":false,"i":null,"es":"aumenta"},{"t":"не се променя","ok":false,"i":null,"es":"no cambia"},{"t":"зависи от вида на автомобилната гума","ok":false,"i":null,"es":"depende del tipo de neumático"}],"es":"¿Cómo varía el rozamiento de los neumáticos en pavimento mojado respecto al seco?","explain":"DISMINUYE — el agua actúa como lubricante entre el neumático y el asfalto, reduciendo la adherencia. Por eso se necesita más distancia de frenado con lluvia."},{"id":5849,"bg":"При спиране на автомобила дължината на спирачния път зависи от:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"скоростта на движение","ok":true,"i":null,"es":"la velocidad"},{"t":"състоянието на гумите","ok":true,"i":null,"es":"el estado de los neumáticos"},{"t":"състоянието на пътната настилка","ok":true,"i":null,"es":"el estado del pavimento"},{"t":"диаметъра на гумите","ok":false,"i":null,"es":"el diámetro de los neumáticos"}],"es":"La distancia de frenado depende de: (3 correctas)","explain":"⚠️ TRAMPA: velocidad + estado de neumáticos + estado del pavimento determinan la distancia de frenado. El DIÁMETRO de los neumáticos no es un factor determinante."},{"id":5852,"bg":"Как се променя дължината на спирачния път при мокра настилка в сравнение със суха, когато гумите са износени?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"увеличава се","ok":true,"i":null,"es":"aumenta"},{"t":"намалява","ok":false,"i":null,"es":"disminuye"},{"t":"не се променя","ok":false,"i":null,"es":"no cambia"},{"t":"зависи от вида на автомобилната гума","ok":false,"i":null,"es":"depende del tipo de neumático"}],"es":"¿Cómo cambia la distancia de frenado en pavimento mojado respecto al seco con neumáticos normales?","explain":"AUMENTA — menos adherencia en mojado = más distancia para parar. Puede aumentar un 50-100% respecto al seco. Por eso la distancia de seguridad debe ser mayor con lluvia."},{"id":5854,"bg":"Влияе ли масата на превозното средство върху дължината на неговия спирачен път?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Afecta la masa del vehículo a su distancia de frenado?","explain":"SÍ — más masa = más inercia = más distancia para frenar. Los vehículos pesados necesitan más distancia de frenado que los ligeros a la misma velocidad."},{"id":5855,"bg":"Рязко спиране на превозното средство се допуска:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"когато е необходимо да се предотврати ПТП","ok":true,"i":null,"es":"cuando es necesario para evitar un accidente"},{"t":"при подаден сигнал със стоп-палка","ok":false,"i":null,"es":"cuando lo indique un agente con pala reflectante"},{"t":"когато зад него не се движи друго ППС","ok":false,"i":null,"es":"cuando no viene nadie detrás"},{"t":"винаги","ok":false,"i":null,"es":"siempre"}],"es":"El frenado brusco está permitido:","explain":"Solo para EVITAR UN ACCIDENTE. El frenado brusco en otras circunstancias es peligroso para los que vienen detrás. La emergencia es la única justificación."},{"id":5856,"bg":"Блокирането на колелата на превозното средство при спиране може да доведе до:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"влошаване управляемостта на превозното средство","ok":true,"i":null,"es":"EMPEORAMIENTO de la manejabilidad"},{"t":"подобряване управляемостта на превозното средство","ok":false,"i":null,"es":"MEJORA de la manejabilidad"},{"t":"увеличаване сцеплението на гумите с пътя","ok":false,"i":null,"es":"aumento del rozamiento de los neumáticos con el asfalto"}],"es":"El bloqueo de las ruedas durante el frenado puede provocar:","explain":"⚠️ TRAMPA: bloquear ruedas = EMPEORA la manejabilidad (el coche no responde a la dirección). El ABS existe precisamente para evitar el bloqueo y mantener la dirección."},{"id":5858,"bg":"Какво влияние оказва върху дължината на спирачния път блокирането на колелата при спиране?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"увеличава дължината на спирачния път","ok":true,"i":null,"es":"AUMENTA la distancia de frenado"},{"t":"не оказва влияние върху дължината на спирачния път","ok":false,"i":null,"es":"no tiene efecto"},{"t":"намалява дължината на спирачния път","ok":false,"i":null,"es":"REDUCE la distancia de frenado"}],"es":"¿Qué efecto tiene el bloqueo de ruedas en la distancia de frenado?","explain":"⚠️ TRAMPA: bloquear ruedas AUMENTA la distancia de frenado y hace patinar el coche. El frenado controlado (sin bloqueo) es más corto y efectivo."},{"id":5860,"bg":"Преди да намали значително скоростта на движение, водачът на МПС е задължен:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да се убеди, че няма да застраши останалите участници в движението","ok":true,"i":null,"es":"asegurarse de no poner en peligro a los demás participantes"},{"t":"да сигнализира с десен пътепоказател","ok":false,"i":null,"es":"señalizar con el intermitente derecho"},{"t":"да премине в най-дясната пътна лента","ok":false,"i":null,"es":"pasar al carril más a la derecha"},{"t":"да напусне платното за движение","ok":false,"i":null,"es":"abandonar la calzada"}],"es":"Antes de reducir significativamente la velocidad, el conductor está obligado a:","explain":"Asegurarse de no crear peligro — antes de frenar bruscamente debes verificar que nadie vendrá demasiado rápido por detrás. El intermitente o el carril no son requisitos para frenar."},{"id":5861,"bg":"След пътния знак движението трябва да се извършва на дистанция от предния автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57706.png","v":null,"a":[{"t":"не по-малка от 70 м","ok":true,"i":null,"es":"no MENOS de 70 m"},{"t":"не по-голяма от 70 м","ok":false,"i":null,"es":"no MÁS de 70 m"}],"es":"Después de esta señal, la distancia de seguridad con el vehículo de delante debe ser:","explain":"NO MENOS DE 70 m. Una sola correcta.\n\nQUÉ VES. Carretera con dos carriles en tu sentido. A la derecha, una señal circular de borde ROJO con DOS VEHÍCULOS y la cifra «70 m». Delante circulan un camión, un coche rojo y un coche azul.\n\nUN CÍRCULO ROJO PROHÍBE. Esta señal prohíbe circular a una distancia MENOR de 70 m del vehículo de delante. Es decir: la distancia debe ser de 70 m como mínimo.\n\n«NO MÁS DE 70 m» es el cebo: invierte el sentido. Nadie te obliga a ir más cerca; lo que se prohíbe es acercarse demasiado.\n\nCLAVE: señal de distancia mínima = «no menos de» la cifra.\n\nMÉTODO: 1) ¿qué forma y color tiene la señal? 2) círculo rojo = prohibición 3) ¿qué prohíbe? ir más cerca de lo indicado. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5862,"bg":"Кой два от изброените фактори са с най-голямо значение за определяне на дистанцията при движение зад друго ППС?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"състоянието на пътя","ok":true,"i":null,"es":"el estado de la vía"},{"t":"скоростта на движение","ok":true,"i":null,"es":"la velocidad de circulación"},{"t":"видът на движещото се отпред ППС","ok":false,"i":null,"es":"el tipo de vehículo de delante"},{"t":"видът на превозвания товар","ok":false,"i":null,"es":"el tipo de carga transportada"}],"es":"¿Qué dos factores son más importantes para determinar la distancia de seguridad? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: los dos factores principales son el estado de la vía (adherencia) Y la velocidad. El tipo de vehículo de delante y la carga son secundarios."},{"id":5863,"bg":"Най-важният фактор за избягване на сблъсък с движещия се отпред автомобил е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"поддържане на необходимата дистанция","ok":true,"i":null,"es":"mantener la distancia de seguridad necesaria"},{"t":"движението с постоянна скорост","ok":false,"i":null,"es":"circular a velocidad constante"},{"t":"автомобилът да бъде оборудван с подходящи гуми","ok":false,"i":null,"es":"llevar neumáticos adecuados"},{"t":"автомобилът да бъде с нисък център на тежестта","ok":false,"i":null,"es":"tener el centro de gravedad bajo"}],"es":"El factor más importante para evitar una colisión con el vehículo de delante es:","explain":"La DISTANCIA DE SEGURIDAD es el factor más importante — es tu margen de reacción y frenado. Sin distancia suficiente, ninguna otra medida puede evitar el choque."},{"id":5864,"bg":"Интервалът от 2 секунди между движещите се леки автомобили е достатъчен когато:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"пътят е сух","ok":true,"i":null,"es":"el camino está SECO"},{"t":"видимостта е намалена поради мъгла","ok":false,"i":null,"es":"la visibilidad está reducida por niebla"},{"t":"пътят е мокър","ok":false,"i":null,"es":"el camino está mojado"},{"t":"видимостта е ограничена","ok":false,"i":null,"es":"la visibilidad es limitada"}],"es":"El intervalo de 2 segundos entre turismos es suficiente cuando:","explain":"⚠️ TRAMPA: 2 segundos es suficiente SOLO en carretera SECA y buenas condiciones. Con lluvia, niebla o hielo la distancia debe aumentarse significativamente."},{"id":5865,"bg":"При избиране скоростта на движение, водачите на пътни превозни средства:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да се съобразяват с атмосферните условия","ok":true,"i":null,"es":"las condiciones atmosféricas"},{"t":"трябва да се съобразяват с релефа на местността","ok":true,"i":null,"es":"el relieve del terreno"},{"t":"не са длъжни да се съобразяват със състоянието на пътя","ok":false,"i":null,"es":"no están obligados a considerar el estado de la vía"},{"t":"не са длъжни да се съобразяват със състоянието на превозното средство","ok":false,"i":null,"es":"no están obligados a considerar el estado del vehículo"}],"es":"Al elegir la velocidad, los conductores deben tener en cuenta: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: condiciones atmosféricas Y relieve del terreno. También están obligados a considerar el estado de la vía y del vehículo — esas respuestas negativas son INCORRECTAS."},{"id":5866,"bg":"За безопасно движение при сух път и добра видимост, интервалът между леките автомобили трябва да бъде не по-малък от:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"2 секунди","ok":true,"i":null,"es":"2 segundos"},{"t":"дължината на един автомобил","ok":false,"i":null,"es":"la longitud de un coche"},{"t":"2 метра","ok":false,"i":null,"es":"2 metros"}],"es":"Para circular con seguridad en vía seca y buena visibilidad, el intervalo entre turismos debe ser:","explain":"2 SEGUNDOS — el intervalo temporal mínimo en condiciones óptimas. No se mide en metros (depende de la velocidad) sino en tiempo. Con 2 segundos tienes margen para reaccionar."},{"id":5868,"bg":"При избиране скоростта на движение, водачите на пътни превозни средства:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не са длъжни да се съобразяват с атмосферните условия","ok":false,"i":null,"es":"no están obligados a considerar las condiciones atmosféricas"},{"t":"не са длъжни да се съобразяват с релефа на местността","ok":false,"i":null,"es":"no están obligados a considerar el relieve"},{"t":"трябва да се съобразяват с характера и интензивността на движението","ok":true,"i":null,"es":"la intensidad y el carácter del tráfico"},{"t":"трябва да се съобразяват с конкретните условия на видимост","ok":true,"i":null,"es":"las condiciones concretas de visibilidad"}],"es":"Al elegir la velocidad, los conductores deben tener en cuenta: (2 correctas)","explain":"⚠️ TRAMPA INVERTIDA: las dos CORRECTAS son intensidad del tráfico Y condiciones de visibilidad. Las dos primeras opciones son INCORRECTAS — SÍ están obligados a considerar las condiciones atmosféricas y el relieve."},{"id":5870,"bg":"При избиране скоростта на движение, водачите на пътни превозни средства:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да се съобразяват със състоянието на превозното средство","ok":true,"i":null,"es":"el estado del vehículo"},{"t":"трябва да се съобразяват с превозвания товар","ok":true,"i":null,"es":"la carga transportada"},{"t":"не са длъжни да се съобразяват с характера и интензивността на движението","ok":false,"i":null,"es":"no están obligados a considerar la intensidad del tráfico"},{"t":"не са длъжни да се съобразяват с конкретните условия на видимост","ok":false,"i":null,"es":"no están obligados a considerar las condiciones de visibilidad"}],"es":"Al elegir la velocidad, los conductores deben tener en cuenta: (2 correctas)","explain":"⚠️ TRAMPA INVERTIDA: las dos CORRECTAS son estado del vehículo Y carga. Las otras dos son INCORRECTAS — SÍ están obligados a considerar el tráfico y la visibilidad."},{"id":5875,"bg":"Когато възникне опасност за движението водачът трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да намали скоростта","ok":true,"i":null,"es":"reducir la velocidad"},{"t":"в случай на необходимост да спре","ok":true,"i":null,"es":"si es necesario, parar"},{"t":"да включи аварийните светлини","ok":true,"i":null,"es":"activar las luces de emergencia"},{"t":"да изключи двигателя","ok":false,"i":null,"es":"apagar el motor"}],"es":"Cuando surge un peligro en la circulación, el conductor debe: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: reducir velocidad + parar si es necesario + activar luces de emergencia. Apagar el motor mientras circula NO — solo al parar definitivamente."},{"id":5877,"bg":"Движението със съобразена скорост позволява на водача:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да владее превозното средство в конкретната пътна обстановка","ok":true,"i":null,"es":"dominar el vehículo en la situación concreta"},{"t":"при необходимост безопасно да намали скоростта","ok":true,"i":null,"es":"si es necesario, reducir la velocidad con seguridad"},{"t":"при необходимост безопасно да спре","ok":true,"i":null,"es":"si es necesario, parar con seguridad"},{"t":"да предотврати настъпването на произшествие след употребата на алкохол","ok":false,"i":null,"es":"prevenir un accidente después de consumir alcohol"}],"es":"Circular a velocidad adecuada permite al conductor: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: velocidad adecuada = control + reducir seguro + parar seguro. El alcohol invalida cualquier velocidad — no hay velocidad 'adecuada' bajo los efectos del alcohol."},{"id":5881,"bg":"При тази ситуация, за да осигуря безопасността на децата, е достатъчно само да намаля скоростта.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57792.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación, para garantizar la seguridad de los niños, es suficiente con solo reducir la velocidad. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Calle urbana. En la acera DERECHA, un grupo de NIÑOS juega con un BALÓN, que ya ha rodado hacia la calzada.\n\nREDUCIR NO BASTA. Un balón en la calzada anuncia que un niño puede salir corriendo detrás de él sin mirar. Además de reducir, tienes que ir listo para frenar y, si puedes, alejarte del borde de la acera.\n\n«CORRECTO» es el cebo: la palabra «solo» (само) convierte una medida necesaria en insuficiente.\n\nCLAVE: balón en la calzada = un niño detrás. Reducir, apartarse y estar listo para frenar.\n\nMÉTODO: 1) ¿hay niños cerca? 2) ¿hay algo que los atraiga a la calzada? 3) reduzco, me aparto y voy listo para frenar. Ver Leyes → «Niños en la vía»."},{"id":5883,"bg":"Кое от изброените действия на водача е най-опасно при преминаването покрай децата?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57825.png","v":null,"a":[{"t":"стремежът бързо да се премине през опасното място","ok":true,"i":null,"es":"intentar pasar rápido por el lugar peligroso"},{"t":"подаването на звуков сигнал за предупреждаване на децата","ok":false,"i":null,"es":"tocar el claxon para advertirles"},{"t":"рязкото спиране","ok":false,"i":null,"es":"frenar bruscamente"}],"es":"¿Cuál es la acción más peligrosa al pasar junto a niños?","explain":"INTENTAR PASAR RÁPIDO POR EL LUGAR PELIGROSO. Una sola correcta.\n\nQUÉ VES. Calle urbana. En la acera DERECHA hay varios NIÑOS caminando y corriendo, algunos muy cerca del bordillo.\n\nLO MÁS PELIGROSO ES ACELERAR PARA «QUITARSE» EL PELIGRO DE ENCIMA. Si pasas rápido, cualquier movimiento imprevisto de un niño te deja sin tiempo ni distancia para frenar.\n\n«TOCAR EL CLAXON» puede asustar a los niños y provocar una reacción imprevisible, pero no es lo MÁS peligroso.\n\n«FRENAR BRUSCAMENTE» puede sorprender al de detrás, pero evita el atropello.\n\nCLAVE: con niños cerca, la velocidad es el factor más peligroso.\n\nMÉTODO: 1) ¿hay niños cerca? 2) ¿cuánto tiempo tengo para reaccionar? 3) lo gano yendo más despacio, nunca más rápido. Ver Leyes → «Niños en la vía»."},{"id":5886,"bg":"При тази ситуация няма ограничения и мога да увелича скоростта на движение.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57858.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación no hay restricciones y puedo aumentar la velocidad. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Carretera con señal de VÍA CON PRIORIDAD (rombo). A la DERECHA, un coche AMARILLO detenido junto al borde y, alrededor, varias PERSONAS, entre ellas un NIÑO junto a la señal. Más adelante, un coche rojo parado.\n\nHAY UNA RESTRICCIÓN, AUNQUE NO SEA UNA SEÑAL. Las personas junto a la calzada, y en especial el niño, pueden cruzar o bajar de la acera en cualquier momento. Eso obliga a moderar la velocidad, no a aumentarla.\n\n«CORRECTO» es el cebo: el rombo te da prioridad en los cruces, pero no te autoriza a acelerar junto a peatones.\n\nCLAVE: la prioridad no te exime de la prudencia. Compárala con la 5889 (la misma escena).\n\nMÉTODO: 1) ¿hay peatones, sobre todo niños, junto a la calzada? 2) si los hay, reduzco y voy listo para frenar. Ver Leyes → «Niños en la vía»."},{"id":5889,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57891.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir la velocidad"},{"t":"трябва да управлявам с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"пешеходците не са на платното за движение и не съм задължен да променям скоростта","ok":false,"i":null,"es":"los peatones no están en la calzada y no tengo que cambiar velocidad"},{"t":"движа се по път с предимство и не съм задължен да намалявам скоростта","ok":false,"i":null,"es":"circulo por vía preferente y no tengo que reducir"}],"es":"En esta situación: (2 correctas)","explain":"DEBO REDUCIR LA VELOCIDAD Y DEBO CIRCULAR LISTO PARA FRENAR. Dos correctas.\n\nQUÉ VES. La misma escena que la 5886: carretera con señal de VÍA CON PRIORIDAD, un coche AMARILLO detenido a la derecha con varias PERSONAS alrededor, entre ellas un NIÑO junto a la señal.\n\nPERSONAS JUNTO A LA CALZADA = REDUCIR Y PREPARARSE. Pueden cruzar o salir de detrás del coche en cualquier momento.\n\n«LOS PEATONES NO ESTÁN EN LA CALZADA, NO TENGO QUE CAMBIAR LA VELOCIDAD» es el cebo: esperar a que estén en la calzada es reaccionar tarde.\n\n«VOY POR VÍA CON PRIORIDAD Y NO TENGO QUE REDUCIR» es el otro cebo: la prioridad vale frente a otros vehículos en los cruces, no frente al peligro de los peatones.\n\nCLAVE: la prioridad no te exime de la prudencia.\n\nMÉTODO: 1) ¿hay peatones, sobre todo niños, junto a la calzada? 2) si los hay, reduzco y voy listo para frenar. Ver Leyes → «Niños en la vía»."},{"id":5892,"bg":"Как ще постъпите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57963.png","v":null,"a":[{"t":"намалявам скоростта","ok":true,"i":null,"es":"reduzco la velocidad"},{"t":"при необходимост спирам, докато се убедя, че преминаването е безопасно","ok":true,"i":null,"es":"si es necesario, paro hasta asegurarme de que es seguro pasar"},{"t":"предупреждавам децата със звуков сигнал да освободят пътя","ok":false,"i":null,"es":"aviso a los niños con el claxon para que cedan el paso"},{"t":"преминавам в съседната пътна лента","ok":false,"i":null,"es":"paso al carril adyacente"}],"es":"¿Cómo actuarás en esta situación? (2 correctas)","explain":"REDUZCO LA VELOCIDAD Y, SI ES NECESARIO, PARO HASTA ASEGURARME DE QUE ES SEGURO PASAR. Dos correctas.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO: vas a rodear un CAMIÓN rojo parado a tu derecha. Por delante del camión salen unos NIÑOS, uno de ellos en monopatín, hacia tu carril. De frente viene un coche rojo.\n\nLOS NIÑOS SALEN DE DETRÁS DEL CAMIÓN. El camión los tapa y pueden aparecer más. Reduces y, si hace falta, te detienes hasta ver que no viene nadie.\n\n«AVISO A LOS NIÑOS CON EL CLAXON PARA QUE ME DEJEN PASAR» es el cebo: el claxon no da preferencia y puede asustarlos.\n\n«PASO AL CARRIL ADYACENTE» es el otro cebo: por ahí viene un coche de frente, y los niños pueden seguir avanzando hacia ese carril.\n\nCLAVE: niños saliendo de detrás de un obstáculo = reducir y, si hace falta, parar. Ver Leyes → «Niños en la vía»."},{"id":5893,"bg":"След като преминат децата, увеличавам скоростта и продължавам движението.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58063.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"Cuando pasan los niños, aumento la velocidad y continúo. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. La misma calle: un CAMIÓN parado a tu derecha y unos NIÑOS cruzando por delante de él. En la acera de la IZQUIERDA hay más niños.\n\nQUE HAYAN PASADO UNOS NO SIGNIFICA QUE NO VENGAN OTROS. Los niños suelen ir en grupo y detrás del camión puede haber más. Además, los de la acera izquierda pueden cruzar. Sigues despacio y atento hasta haber pasado la zona.\n\n«CORRECTO» es el cebo de quien vuelve a la velocidad normal en cuanto el primer peligro desaparece.\n\nCLAVE: donde hay un niño, puede haber otro. Ver Leyes → «Niños en la vía»."},{"id":5897,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58097.png","v":null,"a":[{"t":"длъжен съм да намаля скоростта","ok":true,"i":null,"es":"estoy obligado a reducir la velocidad"},{"t":"трябва да управлявам с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"трябва да премина в лентата за насрещно движение, за да заобиколя децата","ok":false,"i":null,"es":"debo pasar al carril contrario para rodear a los niños"},{"t":"длъжен съм да подам звуков сигнал","ok":false,"i":null,"es":"estoy obligado a tocar el claxon"}],"es":"En esta situación: (2 correctas)","explain":"ESTOY OBLIGADO A REDUCIR LA VELOCIDAD Y DEBO CIRCULAR LISTO PARA FRENAR. Dos correctas.\n\nQUÉ VES. Calle urbana. Dos NIÑOS están de pie en la calzada, en tu carril, junto a la línea central. De frente viene un coche rojo. En la acera derecha hay más peatones.\n\nNIÑOS EN LA CALZADA = REDUCIR Y PREPARARSE. No sabes si van a seguir cruzando, quedarse quietos o volver atrás.\n\n«PASO AL CARRIL CONTRARIO PARA RODEAR A LOS NIÑOS» es el cebo: por ahí viene un coche y los niños pueden moverse hacia ese lado.\n\n«ESTOY OBLIGADO A TOCAR EL CLAXON» es falso: no hay tal obligación, y puede asustarlos.\n\nCLAVE: con niños en la calzada, ni claxon ni esquivas: reducir y estar listo para parar. Ver Leyes → «Niños en la vía»."},{"id":5899,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58149.png","v":null,"a":[{"t":"намалявам скоростта","ok":true,"i":null,"es":"reduzco la velocidad"},{"t":"управлявам с готовност за спиране","ok":true,"i":null,"es":"circulo listo para frenar"},{"t":"подавам звуков сигнал за да привлека вниманието на велосипедистите","ok":false,"i":null,"es":"toco el claxon para avisar a los ciclistas"},{"t":"подавам авариен сигнал","ok":false,"i":null,"es":"activo las luces de emergencia"}],"es":"En esta situación: (2 correctas)","explain":"REDUZCO LA VELOCIDAD Y CIRCULO LISTO PARA FRENAR. Dos correctas.\n\nQUÉ VES. Calle urbana. Por el lado izquierdo de la calzada vienen DOS CICLISTAS jóvenes; uno de ellos circula hacia el centro de la calzada.\n\nCICLISTAS CERCA DE TU TRAYECTORIA = REDUCIR Y PREPARARSE. Pueden desviarse, caerse o meterse en tu carril. Te das margen de tiempo y espacio.\n\n«TOCO EL CLAXON PARA AVISAR A LOS CICLISTAS» es el cebo: puede asustarlos y provocar una maniobra brusca.\n\n«ACTIVO LAS LUCES DE EMERGENCIA» no sirve aquí: esas luces son para señalar un peligro o una detención anómala de tu vehículo.\n\nCLAVE: ciclistas imprevisibles = menos velocidad y pie preparado. Compárala con la 5901 (la misma escena). Ver Leyes → «Carril: dónde debes circular»."},{"id":5901,"bg":"Кое от изброените действия трябва да предприемете при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58182.png","v":null,"a":[{"t":"да осигуря достатъчна странична дистанция","ok":true,"i":null,"es":"garantizar distancia lateral suficiente"},{"t":"да бъда внимателен и предпазлив","ok":true,"i":null,"es":"ser atento y precavido"},{"t":"да подам звуков сигнал","ok":false,"i":null,"es":"tocar el claxon"},{"t":"незабавно да спра","ok":false,"i":null,"es":"frenar de inmediato"}],"es":"¿Qué acciones debes tomar en esta situación? (2 correctas)","explain":"GARANTIZAR UNA DISTANCIA LATERAL SUFICIENTE Y SER ATENTO Y PRECAVIDO. Dos correctas.\n\nQUÉ VES. La misma escena que la 5899: dos CICLISTAS jóvenes por el lado izquierdo de la calzada, uno de ellos hacia el centro.\n\nAL CRUZARTE CON CICLISTAS, ESPACIO Y ATENCIÓN. Les dejas una distancia lateral suficiente para que un pequeño desvío no termine en choque, y vas atento a lo que hagan.\n\n«TOCAR EL CLAXON» puede asustarlos.\n\n«FRENAR DE INMEDIATO» es el cebo exagerado: no hay nada que obligue a detenerse en seco, y una frenada brusca sin motivo puede provocar un alcance.\n\nCLAVE: con ciclistas, la distancia lateral es la medida clave. Ver Leyes → «Carril: dónde debes circular»."},{"id":5904,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58249.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir la velocidad"},{"t":"трябва да се движа с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"мога да премина зад децата, без да намалявам скоростта","ok":false,"i":null,"es":"puedo pasar detrás de los niños sin reducir"},{"t":"трябва да подам звуков сигнал, за да предупредя децата","ok":false,"i":null,"es":"debo tocar el claxon para advertir a los niños"}],"es":"En esta situación: (2 correctas)","explain":"DEBO REDUCIR LA VELOCIDAD Y DEBO CIRCULAR LISTO PARA FRENAR. Dos correctas.\n\nQUÉ VES. Vas recto (flecha). Delante, una mujer y una NIÑA cruzan la calzada de izquierda a derecha. En la acera derecha, un NIÑO corre. De frente viene un coche rojo.\n\nPEATONES CRUZANDO Y UN NIÑO CORRIENDO = REDUCIR Y PREPARARSE. La niña puede soltarse o volver atrás, y el niño de la derecha puede bajar a la calzada.\n\n«PUEDO PASAR POR DETRÁS DE LOS NIÑOS SIN REDUCIR» es el cebo: calcular que «ya habrán pasado» es apostar con la vida de otro.\n\n«DEBO TOCAR EL CLAXON PARA ADVERTIR A LOS NIÑOS» es el otro cebo: puede asustarlos y provocar justo el movimiento que temes.\n\nCLAVE: con niños, ni claxon ni cálculos: reducir y estar listo para parar. Ver Leyes → «Niños en la vía»."},{"id":5905,"bg":"При тази ситуация, за да осигуря по-голяма безопасност за децата, е достатъчно само да увелича страничната дистанция.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58320.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación, para garantizar la seguridad de los niños es suficiente con solo aumentar la atención. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Calle urbana. A la DERECHA hay coches aparcados y, entre ellos y la acera, un grupo de NIÑOS, algunos ya junto a la calzada.\n\nAPARTARSE NO BASTA. Dejar más distancia lateral ayuda, pero los niños pueden salir corriendo de entre los coches sin mirar. Lo que de verdad te protege es REDUCIR LA VELOCIDAD e ir listo para frenar. Las dos cosas juntas: más distancia y menos velocidad.\n\n«CORRECTO» es el cebo: la palabra «solo» (само) convierte una medida útil en insuficiente.\n\nCLAVE: con niños cerca de la calzada, la respuesta siempre incluye reducir.\n\nMÉTODO: 1) ¿hay niños cerca? 2) ¿algo los tapa? 3) reduzco, me aparto si puedo y voy listo para frenar. Ver Leyes → «Niños en la vía»."},{"id":5907,"bg":"При тази ситуация, за да осигуря безопасността за велосипедиста при изпреварването, е достатъчно само да намаля скоростта.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58514.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"Para garantizar la seguridad del ciclista al adelantarlo, es suficiente con solo aumentar la atención. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Calle con un carril por sentido. Delante, por tu carril, va un CICLISTA. Llevas el intermitente IZQUIERDO: vas a adelantarlo. En la acera izquierda hay peatones.\n\nREDUCIR NO BASTA. Al adelantar a un ciclista, lo que lo protege es dejarle una DISTANCIA LATERAL SUFICIENTE. Puedes pasarle despacio y aun así pegado, y eso sigue siendo peligroso: un pequeño desvío de la bici y lo golpeas. La obligación de asegurar esa distancia es del que adelanta.\n\n«CORRECTO» es el cebo de quien piensa que ir despacio arregla cualquier maniobra.\n\nCLAVE: con ciclistas, el problema es el ESPACIO, no solo la velocidad. Compárala con la 12022 (si no hay espacio, se espera).\n\nMÉTODO: 1) ¿puedo dejarle distancia lateral suficiente? 2) ¿está libre el carril contrario? 3) si no, no adelanto. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":5911,"bg":"При движение в мъгла, непосредствено зад друго превозно средство, водачът може да намали вероятността за произшествие като:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"намали скоростта","ok":true,"i":null,"es":"reduce la velocidad"},{"t":"увеличи дистанцията","ok":true,"i":null,"es":"aumenta la distancia"},{"t":"се придържа близо до движещото се пред него превозно средство","ok":false,"i":null,"es":"se pega al vehículo de delante"},{"t":"използва дълги светлини вместо къси светлини","ok":false,"i":null,"es":"usa luces largas en vez de cortas"}],"es":"Circulando en niebla justo detrás de otro vehículo, el conductor puede reducir la probabilidad de colisión si: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: reduce velocidad + aumenta distancia. Pegarse al de delante es exactamente lo contrario de lo correcto. Las luces largas en niebla reflejan y empeoran la visibilidad."},{"id":5913,"bg":"При преминаване през локви по платното за движение водачът е длъжен:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да се движи със скорост, с която да предпази пешеходците от изпръскване","ok":true,"i":null,"es":"circular a velocidad que no salpique a los peatones"},{"t":"да подаде сигнал, за да предупреди пешеходците да се пазят от изпръскване","ok":false,"i":null,"es":"señalizar con el claxon para advertir a los peatones"}],"es":"Al pasar por charcos en la calzada, el conductor está obligado a:","explain":"Velocidad que no salpique — es una obligación legal explícita en Bulgaria. Salpicar a peatones al pasar por charcos es una infracción."},{"id":6600,"bg":"Водачът на пътно превозно средство:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не трябва да намалява скоростта рязко, освен ако това е необходимо за предотвратяване на произшествие","ok":true,"i":null,"es":"no debe frenar bruscamente salvo para evitar un accidente"},{"t":"трябва да намали скоростта и при необходимост да спре, когато възникне опасност за движението","ok":true,"i":null,"es":"debe reducir y si es necesario parar cuando surja un peligro"},{"t":"е задължен да намали скоростта и при необходимост да спре при заслепяване","ok":true,"i":null,"es":"está obligado a reducir y parar cuando le deslumbren"},{"t":"не е задължен да намали скоростта за да предпази пешеходците от нараняване, когато на платното за движение има дребни камъни","ok":false,"i":null,"es":"no está obligado a reducir para proteger a peatones de salpicaduras"}],"es":"El conductor de un vehículo: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: frenada brusca solo en emergencia + reducir ante peligro + reducir al ser deslumbrado. Sí está obligado a reducir para no salpicar a peatones — esa última opción es INCORRECTA."},{"id":6694,"bg":"При тази ситуация разрешено ли е движение със скорост, по-висока от означената?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54350.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"En esta situación ¿está permitido circular a velocidad superior a la indicada?","explain":"SÍ.\n\nQUÉ VES. Carretera fuera de población. A la derecha, una señal circular AZUL con «40»: VELOCIDAD MÍNIMA OBLIGATORIA. Delante va un coche gris.\n\nEL MÍNIMO NO LIMITA POR ARRIBA. Esta señal te obliga a no ir por debajo de 40 km/h; puedes ir más rápido, respetando el límite general de la vía.\n\n«NO» es el cebo de quien lee cualquier número como un máximo. El máximo es el círculo de borde rojo.\n\nCLAVE: círculo azul = mínimo; círculo de borde rojo = máximo. Compárala con la 5821. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6695,"bg":"Влияние върху големината на коефициента на сцепление на автомобилните гуми с пътя оказват:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"видът на пътната настилка","ok":true,"i":null,"es":"el tipo de pavimento"},{"t":"видът на автомобилната гума","ok":true,"i":null,"es":"el tipo de neumático"},{"t":"разположението на двигателя","ok":false,"i":null,"es":"la posición del motor"},{"t":"диаметърът на автомобилните гуми","ok":false,"i":null,"es":"el diámetro de los neumáticos"}],"es":"El coeficiente de rozamiento está influido por: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: tipo de pavimento + tipo de neumático. La posición del motor y el diámetro del neumático no son factores determinantes del rozamiento."},{"id":6696,"bg":"Най-силно влияние върху големината на коефициента на сцепление на автомобилните гуми с пътя оказват:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"състоянието на пътната настилка","ok":true,"i":null,"es":"el estado del pavimento"},{"t":"състоянието на автомобилната гума","ok":true,"i":null,"es":"el estado del neumático"},{"t":"видът на окачването на автомобила","ok":false,"i":null,"es":"el tipo de suspensión del vehículo"},{"t":"диаметърът на автомобилните гуми","ok":false,"i":null,"es":"el diámetro de los neumáticos"}],"es":"¿Qué factor influye más en el coeficiente de rozamiento de los neumáticos con el pavimento? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el rozamiento depende principalmente del estado del pavimento (seco, mojado, helado) Y del estado del neumático (dibujo, presión). La suspensión y el diámetro tienen influencia menor."},{"id":6697,"bg":"Как се изменя сцеплението на автомобилните гуми с пътя при заледена настилка в сравнение със суха?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"намалява","ok":true,"i":null,"es":"disminuye"},{"t":"увеличава се","ok":false,"i":null,"es":"aumenta"},{"t":"не се променя","ok":false,"i":null,"es":"no cambia"},{"t":"зависи от вида на автомобилната гума","ok":false,"i":null,"es":"depende del tipo de neumático"}],"es":"¿Cómo varía el rozamiento en pavimento helado respecto al seco?","explain":"DISMINUYE drásticamente — el hielo puede reducir el rozamiento hasta 10 veces respecto al asfalto seco. Es la condición de menor adherencia posible en carretera."},{"id":6699,"bg":"При заобикаляне на спрелия пред пешеходната пътека автобус:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58433.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir la velocidad"},{"t":"трябва да управлявам с готовност да спра пред пешеходната пътека","ok":true,"i":null,"es":"debo estar listo para parar ante el paso de peatones"},{"t":"не съм задължен да намалявам скоростта","ok":false,"i":null,"es":"no estoy obligado a reducir"}],"es":"Al rodear un autobús parado antes del paso de peatones: (2 correctas)","explain":"DEBO REDUCIR LA VELOCIDAD Y DEBO ESTAR LISTO PARA PARAR ANTE EL PASO DE PEATONES. Dos correctas.\n\nQUÉ VES. Calle urbana. A tu derecha hay un AUTOBÚS detenido justo antes de un PASO DE PEATONES (señal azul). Llevas el intermitente IZQUIERDO para rodearlo.\n\nEL AUTOBÚS TE TAPA EL PASO DE PEATONES. Puede haberse detenido precisamente para dejar cruzar a alguien que tú no ves. Reduces y vas preparado para parar antes del paso.\n\n«NO ESTOY OBLIGADO A REDUCIR» es el cebo: pasar junto a un vehículo detenido ante un paso de peatones es una de las situaciones más peligrosas para un peatón.\n\nCLAVE: vehículo parado ante un paso de peatones = alguien puede estar cruzando delante de él. Ver Leyes → «Paso de peatones»."},{"id":6700,"bg":"Когато поради вида на превозвания товар, центърът на тежестта на автомобила е по-висок от конструктивния, водачът трябва да намали скоростта:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"преди навлизане в завой","ok":true,"i":null,"es":"antes de entrar en una curva"},{"t":"при неравности на платното за движение","ok":true,"i":null,"es":"con irregularidades en el pavimento"},{"t":"при силен страничен вятър","ok":true,"i":null,"es":"con viento lateral fuerte"},{"t":"при движение по стръмен наклон при изкачване","ok":false,"i":null,"es":"en subida pronunciada"}],"es":"Con el centro de gravedad más alto de lo normal, mayor riesgo de vuelco hay: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: mayor riesgo en curvas + irregularidades + viento lateral. En subidas pronunciadas el riesgo no aumenta por el centro de gravedad alto."},{"id":8262,"bg":"Как ще постъпите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/125071123.png","v":null,"a":[{"t":"намалявам скоростта","ok":true,"i":null,"es":"reduzco la velocidad"},{"t":"движа се с готовност за спиране","ok":true,"i":null,"es":"circulo listo para frenar"},{"t":"продължавам движението, без да намалявам скоростта","ok":false,"i":null,"es":"continúo sin reducir"},{"t":"подавам сигнал, за да привлека вниманието на детето","ok":false,"i":null,"es":"toco el claxon para atraer la atención del niño"}],"es":"¿Cómo actuarás en esta situación? (2 correctas)","explain":"REDUZCO LA VELOCIDAD Y CIRCULO LISTO PARA FRENAR. Dos correctas.\n\nQUÉ VES. Calle urbana con un PASO DE PEATONES (señales azules a ambos lados). A la derecha, junto al paso, un NIÑO está a punto de bajar a la calzada. Al otro lado hay más peatones.\n\nNIÑO JUNTO AL PASO = REDUCIR Y PREPARARSE. Va a cruzar, y los niños no calculan bien distancias ni velocidades.\n\n«CONTINÚO SIN REDUCIR» ignora el peligro.\n\n«TOCO EL CLAXON PARA ATRAER LA ATENCIÓN DEL NIÑO» es el cebo: puede asustarlo y provocar una reacción imprevisible.\n\nCLAVE: con niños, ni claxon ni prisa: reducir y estar listo para parar. Ver Leyes → «Niños en la vía»."},{"id":11587,"bg":"Водачът на пътно превозно средство:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не трябва да намалява скоростта рязко, освен ако това е необходимо за предотвратяване на произшествие","ok":true,"i":null,"es":"no debe frenar bruscamente salvo para evitar un accidente"},{"t":"трябва да намали скоростта и при необходимост да спре, когато възникне опасност за движението","ok":true,"i":null,"es":"debe reducir y parar si surge un peligro"},{"t":"е задължен да намали скоростта и при необходимост да спре при заслепяване","ok":true,"i":null,"es":"está obligado a reducir y parar si le deslumbran"},{"t":"не е задължен да намали скоростта за да предпази пешеходците от изцапване, когато на платното за движение има вода или кал","ok":false,"i":null,"es":"no está obligado a reducir para no salpicar a peatones"}],"es":"El conductor: (3 correctas)","explain":"⚠️ TRAMPA INVERTIDA: sí está obligado a no salpicar — esa última opción es INCORRECTA. Las tres primeras son correctas."},{"id":11689,"bg":"Когато няма други ограничения, водачът на мотопед при движение в населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"45 km/h","ok":true,"i":null,"es":"45 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"50 km/h","ok":false,"i":null,"es":"50 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"}],"es":"Sin otras restricciones, el conductor de un ciclomotor en zona urbana no debe superar:","explain":"Los ciclomotores tienen límite propio de 45 km/h (su velocidad máxima de construcción). En ciudad, aunque el límite general sea 50, el ciclomotor no puede superar 45 km/h."},{"id":11691,"bg":"Когато няма други ограничения, водачът на мотопед при движение извън населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"45 km/h","ok":true,"i":null,"es":"45 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"70 km/h","ok":false,"i":null,"es":"70 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"}],"es":"Sin otras restricciones, el conductor de un ciclomotor fuera de población no debe superar:","explain":"45 km/h — los ciclomotores tienen el mismo límite fuera de ciudad que dentro: su velocidad máxima de construcción (45 km/h). No pueden ir más rápido en ningún tipo de vía."},{"id":11692,"bg":"Когато няма други ограничения, водачите на леки моторни превозни средства с четири колела от категория АМ, при движение извън населено място, не трябва да превишават:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"45 km/h","ok":true,"i":null,"es":"45 km/h"},{"t":"50 km/h","ok":false,"i":null,"es":"50 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"}],"es":"Sin otras restricciones, el conductor de un cuatriciclo ligero (categoría AM) no debe superar:","explain":"45 km/h — igual que los ciclomotores, los cuatriciclos ligeros de categoría AM tienen la velocidad máxima limitada a 45 km/h por su construcción."},{"id":11693,"bg":"Когато няма други ограничения, водачът на мотоциклет при движение в населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 km/h","ok":true,"i":null,"es":"50 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"}],"es":"Sin otras restricciones, el conductor de moto en zona urbana no debe superar:","explain":"50 km/h — las motos tienen el mismo límite que los coches en ciudad: 50 km/h. Sin límite específico reducido como los ciclomotores."},{"id":11694,"bg":"Когато няма други ограничения, водачът на мотоциклет при движение извън населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"80 km/h","ok":true,"i":null,"es":"80 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"70 km/h","ok":false,"i":null,"es":"70 km/h"},{"t":"90 km/h","ok":false,"i":null,"es":"90 km/h"}],"es":"Sin otras restricciones, el conductor de moto fuera de población no debe superar:","explain":"80 km/h — las motos fuera de ciudad tienen límite de 80 km/h (no 90 como los turismos). Esta diferencia es importante para el examen."},{"id":11695,"bg":"Когато няма други ограничения, водачът на триколесно МПС от категория А при движение извън населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"80 km/h","ok":true,"i":null,"es":"80 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"70 km/h","ok":false,"i":null,"es":"70 km/h"},{"t":"90 km/h","ok":false,"i":null,"es":"90 km/h"}],"es":"Sin otras restricciones, el conductor de vehículo de tres ruedas categoría A fuera de población no debe superar:","explain":"80 km/h — igual que las motos. Los vehículos de tres ruedas de categoría A tienen el mismo límite que las motocicletas fuera de ciudad."},{"id":11696,"bg":"Когато няма други ограничения, водачът на автомобил от категория В при движение в населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 km/h","ok":true,"i":null,"es":"50 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"}],"es":"Sin otras restricciones, el conductor de turismo categoría B en zona urbana no debe superar:","explain":"50 km/h — el límite general en zona urbana para turismos. Este es el límite básico que debe saberse perfectamente."},{"id":11697,"bg":"Когато няма други ограничения, водачът на автомобил от категория В при движение извън населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"90 km/h","ok":true,"i":null,"es":"90 km/h"},{"t":"80 km/h","ok":false,"i":null,"es":"80 km/h"},{"t":"100 km/h","ok":false,"i":null,"es":"100 km/h"},{"t":"70 km/h","ok":false,"i":null,"es":"70 km/h"}],"es":"Sin otras restricciones, el conductor de categoría B fuera de población puede circular a máximo:","explain":"Fuera de población el límite general es 90 km/h para turismos categoría B. Memoriza: ciudad=50, carretera=90, vía rápida=120, autopista=140."},{"id":11698,"bg":"Когато разрешената максимална скорост за движение в населено място не е сигнализирана с пътен знак, водачите на леки автомобили не трябва да превишават:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 km/h","ok":true,"i":null,"es":"50 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"45 km/h","ok":false,"i":null,"es":"45 km/h"}],"es":"Cuando la velocidad máxima en zona urbana no está señalizada con señal de tráfico, el límite es:","explain":"50 km/h — es el límite urbano por defecto en Bulgaria cuando no hay señal específica. Memoriza: sin señal en ciudad = 50 km/h."},{"id":11699,"bg":"Когато няма други ограничения, водачът на автомобил от категория В1 при движение в населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 km/h","ok":true,"i":null,"es":"50 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"}],"es":"Sin otras restricciones, el conductor de vehículo categoría B1 en zona urbana puede circular a máximo:","explain":"El límite en zona urbana es 50 km/h para todos los turismos, incluyendo categoría B1. Memoriza: ciudad=50, carretera=90, vía rápida=120, autopista=140."},{"id":11700,"bg":"Когато няма други ограничения, водачът на автомобил от категория В1 при движение извън населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"90 km/h","ok":true,"i":null,"es":"90 km/h"},{"t":"80 km/h","ok":false,"i":null,"es":"80 km/h"},{"t":"100 km/h","ok":false,"i":null,"es":"100 km/h"},{"t":"70 km/h","ok":false,"i":null,"es":"70 km/h"}],"es":"Sin otras restricciones, el conductor de turismo categoría B1 fuera de población no debe superar:","explain":"90 km/h — los vehículos B1 (cuadriciclos pesados) tienen el mismo límite que los turismos normales fuera de ciudad: 90 km/h."},{"id":11701,"bg":"Когато няма други ограничения, водачът на състав от ППС от категория ВЕ при движение в населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 km/h","ok":true,"i":null,"es":"50 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"}],"es":"Sin otras restricciones, el conductor de convoy categoría BE en zona urbana no debe superar:","explain":"50 km/h — en ciudad el convoy (turismo + remolque) tiene el mismo límite urbano general: 50 km/h."},{"id":11702,"bg":"Когато няма други ограничения, водачът на състав от ППС от категория ВЕ при движение извън населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"70 km/h","ok":true,"i":null,"es":"70 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"80 km/h","ok":false,"i":null,"es":"80 km/h"},{"t":"90 km/h","ok":false,"i":null,"es":"90 km/h"}],"es":"Sin otras restricciones, el conductor de convoy categoría BE fuera de población no debe superar:","explain":"70 km/h — el convoy (turismo + remolque) fuera de ciudad tiene el límite reducido de 70 km/h (vs 90 del turismo solo). El remolque reduce el límite permitido."},{"id":11703,"bg":"Когато няма други ограничения, водачът на товарен автомобил с допустима максимална маса 3 t., при движение извън населено място, не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"90 km/h","ok":true,"i":null,"es":"90 km/h"},{"t":"70 km/h","ok":false,"i":null,"es":"70 km/h"},{"t":"80 km/h","ok":false,"i":null,"es":"80 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"}],"es":"Sin otras restricciones, el conductor de camión de 3 t fuera de población no debe superar:","explain":"90 km/h — los camiones de hasta ~3.5t tienen el mismo límite que los turismos fuera de ciudad: 90 km/h. Solo los camiones más pesados tienen límites más bajos."},{"id":11704,"bg":"Когато няма други ограничения, водачът на товарен автомобил с допустима максимална маса 3 t., при движение в населено място, не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 km/h","ok":true,"i":null,"es":"50 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"}],"es":"Sin otras restricciones, el conductor de camión de 3 t en zona urbana no debe superar:","explain":"50 km/h — en ciudad el límite para camiones ligeros es el mismo que para turismos: 50 km/h."},{"id":11705,"bg":"След този пътен знак разрешената максимална скорост за движение извън населено място е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54016.png","v":null,"a":[{"t":"в зависимост от категорията на превозното средство","ok":true,"i":null,"es":"según la categoría del vehículo"},{"t":"130 km/h","ok":false,"i":null,"es":"130 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"90 km/h","ok":false,"i":null,"es":"90 km/h"}],"es":"Después de esta señal la velocidad máxima permitida fuera de población es:","explain":"SEGÚN LA CATEGORÍA DEL VEHÍCULO. Una sola correcta.\n\nQUÉ VES. Carretera fuera de población. A la derecha, la señal de FIN DE LA LIMITACIÓN de 40 km/h. De frente viene un camión.\n\nDESPUÉS DE LA SEÑAL VUELVE EL LÍMITE GENERAL, y ese límite depende del tipo de vehículo: no es el mismo para un turismo que para un camión o un autobús.\n\n«90 km/h» es el cebo más tentador: es el límite general fuera de población para un TURISMO, pero la pregunta habla de cualquier vehículo.\n\n«130 km/h» y «60 km/h» no corresponden a esta vía.\n\nCLAVE: fin de limitación = vuelve el límite general de cada categoría. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":11706,"bg":"Разрешено ли е след този пътен знак да се движите със скорост 40 km/h?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57515.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Está permitido circular a 40 km/h después de esta señal?","explain":"SÍ.\n\nQUÉ VES. Carretera fuera de población. A la derecha, una señal circular AZUL con «50» TACHADA por una barra roja: FIN DE LA VELOCIDAD MÍNIMA OBLIGATORIA.\n\nYA NO HAY MÍNIMO. Después de esta señal no estás obligado a ir al menos a 50 km/h, así que circular a 40 km/h está permitido.\n\n«NO» es el cebo de quien no distingue entre el mínimo (azul) y el fin del mínimo (azul tachado).\n\nCLAVE: azul tachado = se acaba la obligación de velocidad mínima. Compárala con la 5830. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":11707,"bg":"Каква трябва да бъде скоростта на движение, когато широчината на пътя не позволява разминаване без допълнителни мерки за сигурност?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"такава, че водачът да може да спре на половината от дължината на пътя, който вижда","ok":true,"i":null,"es":"tal que el conductor pueda parar en la MITAD de la distancia que ve"},{"t":"не по-голяма от 50 km/h","ok":false,"i":null,"es":"no superior a 50 km/h"},{"t":"такава, че водачът да може да спре в зоната на пътя, който вижда","ok":false,"i":null,"es":"tal que pueda parar en toda la distancia que ve"}],"es":"¿Qué velocidad usar cuando la anchura de la vía no permite el cruce sin retroceder?","explain":"⚠️ TRAMPA: la velocidad debe ser tal que puedas frenar en la MITAD de lo que ves (para dejar margen al otro). No toda la distancia visible ni un límite fijo de 50 km/h."},{"id":12003,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да намаля скоростта и да управлявам с готовност за спиране","ok":true,"i":null,"es":"reducir velocidad y circular listo para frenar"},{"t":"да продължа движението си, без да променям скоростта си","ok":false,"i":null,"es":"continuar sin cambiar la velocidad"},{"t":"да навляза в лявата пътна лента","ok":false,"i":null,"es":"cambiar al carril izquierdo"}],"es":"¿Qué debes hacer en esta situación? (VIDEO)","explain":"🎬 VIDEO: ante obstáculo en la vía siempre reduces velocidad y te preparas para frenar. Cambiar de carril sin visibilidad es peligroso. Continuar igual tampoco."},{"id":12026,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да увелича скоростта","ok":false,"i":null,"es":"acelero"},{"t":"да спра аварийно/рязко","ok":true,"i":null,"es":"freno de emergencia"},{"t":"да продължа движението си, като подам звуков сигнал","ok":false,"i":null,"es":"continúo tocando el claxon"}],"es":"¿Qué debes hacer en esta situación?","explain":"FRENO DE EMERGENCIA — ante un peligro repentino e inevitable, la única respuesta correcta es frenar de emergencia. Ni acelerar ni el claxon pueden evitar el impacto."},{"id":12027,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"намалявам скоростта си на движение","ok":true,"i":null,"es":"reduzco la velocidad"},{"t":"рязко се отклонявам/преминавам надясно","ok":false,"i":null,"es":"me desvío bruscamente a la derecha"},{"t":"избягвам резки действия, свързани с управлението на МПС","ok":true,"i":null,"es":"evito acciones bruscas con el volante"}],"es":"¿Cuál es la actuación correcta en esta situación? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: reduces velocidad Y evitas movimientos bruscos del volante. Desviarse bruscamente puede hacer perder el control del vehículo."},{"id":12028,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да се движа възможно най-вдясно","ok":true,"i":null,"es":"circulo todo lo posible a la derecha"},{"t":"да не променям скоростта си и разположението на автомобила","ok":false,"i":null,"es":"no cambio velocidad ni posición"},{"t":"да намаля скоростта и при необходимост да спра","ok":true,"i":null,"es":"reduzco la velocidad y si es necesario paro"}],"es":"¿Cuál es la actuación correcta en esta situación? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: a la derecha + reduce y para si necesario. Mantener velocidad y posición ante un obstáculo o situación peligrosa no es correcto."},{"id":12029,"bg":"При тази ситуация трябва да управлявам с готовност за спиране заради:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трактора","ok":true,"i":null,"es":"el tractor"},{"t":"ограничението на скоростта","ok":false,"i":null,"es":"la señal de velocidad"},{"t":"мотоциклета","ok":false,"i":null,"es":"la moto"}],"es":"En esta situación debo circular listo para frenar por:","explain":"El TRACTOR — el tractor es el elemento más lento y menos predecible en esta situación. Puede girar, pararse o salir de su camino sin avisar."},{"id":12030,"bg":"Какво трябва да очаквате в тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"синият автомобил да навлезе в моята лента","ok":false,"i":null,"es":"que el coche azul invada mi carril"},{"t":"мотоциклетистът да намали скоростта си","ok":true,"i":null,"es":"que el motorista reduzca velocidad"},{"t":"тракторът да навлезе на пътя пред мен","ok":true,"i":null,"es":"que el tractor entre en la vía delante de mí"}],"es":"¿Qué debe esperar en esta situación? (VIDEO) ⚠️ 2 correctas","explain":"🎬 VIDEO ⚠️ MULTIRESPUESTA: anticipa que el motorista reduzca velocidad (moto lenta delante) Y que el tractor entre en la vía (viene de una propiedad lateral). El azul no tiene motivo para invadir."},{"id":12031,"bg":"Какъв е правилният начин на действие в тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"увеличавам скоростта си, за да осигуря безопасна дистанция","ok":false,"i":null,"es":"aumento la velocidad para crear distancia segura"},{"t":"намалявам скоростта си, за да може и водачът отзад да намали скоростта си","ok":false,"i":null,"es":"reduzco la velocidad para que el de atrás también pueda reducir"},{"t":"продължавам движението си, без да променям скоростта си","ok":true,"i":null,"es":"continúo sin cambiar la velocidad"}],"es":"¿Cuál es la actuación correcta en esta situación?","explain":"CONTINÚO sin cambiar — si la situación muestra que el camino es despejado y estás circulando correctamente, no hay razón para cambiar. Reducir innecesariamente o acelerar crearían peligros."},{"id":6219,"bg":"Преди да предприеме маневра водачът трябва да се убеди, че няма да създаде опасност за участниците в движението, като:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да се съобрази с тяхното положение","ok":true,"i":null,"es":"debe tener en cuenta su posición"},{"t":"трябва да се съобрази с посоката им на движение","ok":true,"i":null,"es":"debe tener en cuenta su dirección de circulación"},{"t":"трябва да се съобрази със скоростта им на движение","ok":true,"i":null,"es":"debe tener en cuenta su velocidad"},{"t":"не е задължен да се съобразява със сигналите, които подават","ok":false,"i":null,"es":"no está obligado a considerar las señales que dan"}],"es":"Antes de ejecutar una maniobra el conductor debe asegurarse de no crear peligro: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: posición + dirección + velocidad de los demás participantes. SÍ está obligado a considerar las señales que dan — esa opción negativa es INCORRECTA."},{"id":6221,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69470.png","v":null,"a":[{"t":"синият автомобил","ok":true,"i":null,"es":"el coche azul"},{"t":"червеният автомобил","ok":false,"i":null,"es":"el coche rojo"}],"es":"En esta situación tiene prioridad:","explain":"EL COCHE AZUL. Una sola correcta.\n\nQUÉ VES. Una vía de varios carriles. El coche AZUL circula por su carril. Por la DERECHA, desde un carril de acceso, se incorpora un coche ROJO con el intermitente izquierdo.\n\nCEDE EL QUE ENTRA. El rojo se incorpora a la calzada por la que ya circula el azul: la preferencia es del que ya está.\n\n«EL ROJO» es el cebo de quien aplica la regla de la derecha: una incorporación desde un acceso no es un cruce de vías iguales.\n\nCLAVE: es la misma escena que la 6226. Antes de aplicar la regla de la derecha, comprueba que sea un cruce. Ver Leyes → «Autopista: incorporación y vehículos lentos»."},{"id":6223,"bg":"При тази ситуация, водачът на червения автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69503.png","v":null,"a":[{"t":"трябва да пропусне синия автомобил","ok":true,"i":null,"es":"debe dejar pasar al coche azul"},{"t":"е с предимство защото се намира отдясно","ok":false,"i":null,"es":"tiene prioridad porque está a la derecha"},{"t":"е с предимство защото е подал сигнал за маневра","ok":false,"i":null,"es":"tiene prioridad porque señalizó la maniobra"}],"es":"En esta situación el conductor del coche rojo:","explain":"Debe ceder al azul — el rojo se incorpora o cambia de carril invadiendo el espacio del azul. Estar a la derecha o señalizar no da prioridad al que invade el carril ajeno."},{"id":6226,"bg":"При тази ситуация, водачът на червения автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69536.png","v":null,"a":[{"t":"трябва да пропусне синия автомобил, защото навлиза в лентата, по която той се движи","ok":true,"i":null,"es":"debe dejar pasar al azul porque entra en su carril"},{"t":"преди да се включи в движението трябва да се убеди, че няма да създаде опасност за другите участници в него","ok":true,"i":null,"es":"antes de incorporarse debe asegurarse de no crear peligro"},{"t":"е с предимство защото се намира отдясно","ok":false,"i":null,"es":"tiene prioridad porque está a la derecha"}],"es":"En esta situación el conductor del coche rojo: (2 correctas)","explain":"DEBE DEJAR PASAR AL AZUL PORQUE ENTRA EN SU CARRIL, Y ANTES DE INCORPORARSE DEBE ASEGURARSE DE NO CREAR PELIGRO. Dos correctas.\n\nQUÉ VES. Una vía de varios carriles. El coche AZUL circula por su carril. Por la DERECHA, desde un carril de acceso, se incorpora un coche ROJO con el intermitente izquierdo encendido.\n\nCEDE EL QUE ENTRA. El rojo se mete en el carril por el que ya circula el azul: la preferencia es del que ya está.\n\nY ADEMÁS TIENE UN DEBER PROPIO: antes de incorporarse debe comprobar que no crea peligro ni obliga a nadie a frenar o desviarse. Poner el intermitente informa; no autoriza.\n\n«TIENE PRIORIDAD PORQUE ESTÁ A LA DERECHA» es el cebo: es la regla de la derecha aplicada donde no toca. Una incorporación desde un acceso no es un cruce de vías iguales.\n\nCLAVE: antes de aplicar la regla de la derecha, comprueba que sea realmente un cruce. Si es una incorporación, cede el que entra.\n\nMÉTODO: 1) ¿alguien entra en un carril que ya está ocupado? 2) si es así, cede el que entra. Ver Leyes → «Autopista: incorporación y vehículos lentos»."},{"id":6227,"bg":"Преди да се включи в движението, водачът на ППС е длъжен:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да се убеди, че няма да създаде опасност за другите участници в движението","ok":true,"i":null,"es":"asegurarse de no crear peligro para los demás"},{"t":"да подаде сигнал със съответния пътепоказател","ok":true,"i":null,"es":"activar el intermitente"},{"t":"да подаде звуков или светлинен сигнал с фаровете, с което да си осигури предимство","ok":false,"i":null,"es":"dar señal acústica o de luces para asegurarse prioridad"},{"t":"да изчака сигнал от другите водачи, че може да потегли","ok":false,"i":null,"es":"esperar señal de los demás conductores"}],"es":"Antes de incorporarse al tráfico, el conductor está obligado a: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: verificar seguridad + activar intermitente. La señal acústica/de luces no da prioridad. No necesitas esperar a que los demás te indiquen que puedes ir."},{"id":6229,"bg":"Преди отклонение встрани, за навлизане в съседна пътна лента, водачът:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да подаде сигнал със съответния пътепоказател","ok":true,"i":null,"es":"debe activar el intermitente correspondiente"},{"t":"трябва да се убеди, че няма да създаде опасност за другите участници в движението","ok":true,"i":null,"es":"debe asegurarse de no crear peligro para otros participantes"},{"t":"трябва да пропусне ППС, които се движат по тази лента","ok":true,"i":null,"es":"debe dejar pasar los vehículos que circulan por ese carril"},{"t":"трябва да пропусне ППС движещи се по нея, само ако тази лента е за насрещното движение","ok":false,"i":null,"es":"debe dejar pasar solo los del carril contrario"}],"es":"Antes de desplazarse lateralmente para cambiar de carril, el conductor: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: cambio de carril requiere: señalizar con intermitente + verificar seguridad + ceder el paso a quien ya circula por ese carril. No solo al tráfico contrario."},{"id":6230,"bg":"При тази ситуация с предимство е водачът:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71987.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"el coche ROJO"},{"t":"на синия автомобил","ok":false,"i":null,"es":"el coche AZUL"}],"es":"En esta situación tiene prioridad:","explain":"EL CONDUCTOR DEL COCHE ROJO. Una sola correcta.\n\nQUÉ VES. Carretera de dos carriles en el mismo sentido. La señal azul de la derecha muestra que el carril DERECHO se ACABA y se une al izquierdo. El coche AZUL, en el carril derecho, lleva el intermitente izquierdo para pasarse al carril del ROJO.\n\nCEDE EL QUE CAMBIA DE CARRIL. Al terminarse su carril, el azul tiene que meterse en el del rojo, y para eso le cede el paso al que ya circula por él.\n\n«EL AZUL» es el cebo de quien aplica la regla de la derecha. Aquí no hay dos vehículos que convergen en un tercer carril (como en la 6233): hay uno que entra en el carril del otro.\n\nCLAVE: si tu carril se acaba, cedes al que va por el carril al que entras. Ver Leyes → «Carril: dónde debes circular»."},{"id":6231,"bg":"Кой от водачите е с предимство при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69569.png","v":null,"a":[{"t":"водачът на лекия автомобил","ok":true,"i":null,"es":"el turismo"},{"t":"водачът на товарния автомобил","ok":false,"i":null,"es":"el camión"}],"es":"¿Qué conductor tiene prioridad en esta situación?","explain":"EL CONDUCTOR DEL TURISMO. Una sola correcta.\n\nQUÉ VES. Una calzada de tres carriles en el mismo sentido. Un CAMIÓN blanco va por un carril de la izquierda y lleva el intermitente DERECHO: se cambia hacia el carril central. A la DERECHA, un turismo AZUL se cambia también hacia ese mismo carril central (la flecha lo indica).\n\nDOS CAMBIOS DE CARRIL HACIA EL MISMO CARRIL. Cuando dos vehículos quieren ocupar a la vez el mismo carril desde lados opuestos, tiene preferencia el que está a la DERECHA. El azul está a la derecha del camión: pasa él.\n\nEL TAMAÑO DEL CAMIÓN NO CUENTA. Ser grande no da ningún derecho.\n\n«EL CAMIÓN» es el cebo para quien piensa que el que puso antes el intermitente o el más grande tiene preferencia.\n\n(Corrección: la explicación anterior decía que el camión salía de un estacionamiento con las luces de emergencia. En la imagen lleva solo el intermitente derecho y está cambiando de carril).\n\nCLAVE: dos que convergen al mismo carril = pasa el de la derecha. Es la misma regla que la 6233.\n\nMÉTODO: 1) ¿hacia qué carril va cada uno? 2) si van al mismo, ¿quién está a la derecha? 3) ese pasa primero. Ver Leyes → «Regla de la derecha»."},{"id":6232,"bg":"При тази ситуация кой от водачите трябва да осигури предимство?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69636.png","v":null,"a":[{"t":"на товарния автомобил, защото навлиза в съседната пътна лента","ok":true,"i":null,"es":"el camión, porque entra en el carril adyacente"},{"t":"на товарния автомобил, защото се намира отдясно","ok":false,"i":null,"es":"el camión, porque está a la derecha"},{"t":"на лекия автомобил, защото не е подал сигнал за маневра","ok":false,"i":null,"es":"el turismo, porque no señalizó"},{"t":"на лекия автомобил, защото е по-назад от товарния","ok":false,"i":null,"es":"el turismo, porque está más atrás"}],"es":"¿Quién debe ceder el paso?","explain":"EL CAMIÓN, PORQUE ENTRA EN EL CARRIL ADYACENTE. Una sola correcta.\n\nQUÉ VES. Carretera de dos carriles en el mismo sentido. Un CAMIÓN va por el carril DERECHO con el intermitente IZQUIERDO, para pasarse al izquierdo (delante de él hay una zona rayada). Por el carril IZQUIERDO circula un turismo ROJO.\n\nCEDE EL QUE CAMBIA DE CARRIL. El camión entra en el carril por el que ya circula el rojo: le cede el paso.\n\n«EL CAMIÓN, PORQUE ESTÁ A LA DERECHA» es el cebo fino: la respuesta (el camión) es correcta, pero la razón no. La regla de la derecha no da prioridad a quien cambia de carril.\n\n«EL TURISMO, PORQUE NO SEÑALIZÓ» y «EL TURISMO, PORQUE ESTÁ MÁS ATRÁS» son cebos: el turismo no hace ninguna maniobra, sigue por su carril.\n\nCLAVE: en las preguntas con «porque», la razón tiene que ser la correcta, no solo la conclusión. Ver Leyes → «Carril: dónde debes circular»."},{"id":6233,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69669.png","v":null,"a":[{"t":"водачът на синия автомобил","ok":true,"i":null,"es":"el coche AZUL"},{"t":"водачът на червения автомобил","ok":false,"i":null,"es":"el coche ROJO"}],"es":"En esta situación tiene prioridad:","explain":"EL CONDUCTOR DEL COCHE AZUL. Una sola correcta.\n\nQUÉ VES. Calle con TRES CARRILES en el mismo sentido (señales de carriles a ambos lados). El coche ROJO va por el carril IZQUIERDO con el intermitente derecho; el coche AZUL va por el carril DERECHO con el intermitente izquierdo. Los dos se cambian al carril CENTRAL a la vez.\n\nPASA EL DE LA DERECHA. Cuando dos vehículos quieren ocupar el mismo carril desde lados opuestos, tiene preferencia el que está a la derecha. El azul está a la derecha del rojo.\n\nQUE LOS DOS MANIOBREN NO CAMBIA NADA: la ley mira la posición relativa, no quién empezó antes ni quién puso antes el intermitente.\n\n«EL COCHE ROJO» es el cebo para quien piensa que el carril izquierdo es «el rápido» y por eso manda.\n\n(Corrección: la explicación anterior hablaba de carriles contiguos; en la imagen hay un carril libre entre los dos y ambos van hacia él).\n\nCLAVE: es la gemela de la 6231 (camión y turismo) y de la 6234 (la misma regla en teoría).\n\nMÉTODO: 1) ¿hacia qué carril va cada uno? 2) si van al mismo, ¿quién está a la derecha? 3) ese pasa primero. Ver Leyes → «Regla de la derecha»."},{"id":6234,"bg":"При тази ситуация с предимство е водачът на автомобила, който:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69702.png","v":null,"a":[{"t":"се намира отдясно","ok":true,"i":null,"es":"está a la DERECHA"},{"t":"се намира отляво","ok":false,"i":null,"es":"está a la IZQUIERDA"},{"t":"първи е подал сигнал за маневра","ok":false,"i":null,"es":"primero señalizó la maniobra"},{"t":"е по-напред от другия","ok":false,"i":null,"es":"está más adelantado"}],"es":"En esta situación tiene prioridad el conductor cuyo vehículo:","explain":"⚠️ TRAMPA: a la DERECHA. La regla de la derecha es la base de las intersecciones sin señalización. Señalizar primero o estar más adelante no da prioridad."},{"id":6235,"bg":"При тази ситуация водачът на лекия автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69735.png","v":null,"a":[{"t":"трябва да пропусне товарния автомобил, защото навлиза в заеманата от него пътна лента","ok":true,"i":null,"es":"debe dejar pasar al camión porque entra en su carril"},{"t":"е с предимство при заобикалянето, защото е подал сигнал за маневрата","ok":false,"i":null,"es":"tiene prioridad porque señalizó la maniobra"},{"t":"е с предимство защото е по-близо до препятствието","ok":false,"i":null,"es":"tiene prioridad porque está más cerca del obstáculo"}],"es":"En esta situación el conductor del turismo:","explain":"DEBE DEJAR PASAR AL CAMIÓN PORQUE ENTRA EN SU CARRIL. Una sola correcta.\n\nQUÉ VES. Carretera de doble sentido. En el carril del turismo AZUL hay un OBSTÁCULO (un montón de tierra). El azul lleva el intermitente IZQUIERDO para rodearlo. De frente viene un CAMIÓN rojo por su carril.\n\nEL OBSTÁCULO ESTÁ EN TU CARRIL: CEDES TÚ. Para rodearlo, el azul tiene que meterse en el carril del camión. El que tiene el obstáculo en su lado cede al que viene de frente.\n\n«TIENE PRIORIDAD PORQUE SEÑALIZÓ» es el cebo: el intermitente avisa, no da derechos.\n\n«TIENE PRIORIDAD PORQUE ESTÁ MÁS CERCA DEL OBSTÁCULO» es otro cebo: la distancia no cambia nada.\n\nCLAVE: obstáculo en tu carril + alguien de frente = esperas. Compárala con la 11997 (vídeo) y la 6236. Ver Leyes → «Carril: dónde debes circular»."},{"id":6236,"bg":"Кой от водачите е с предимство при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69768.png","v":null,"a":[{"t":"водачът на товарния автомобил","ok":true,"i":null,"es":"el conductor del CAMIÓN"},{"t":"водачът на лекия автомобил","ok":false,"i":null,"es":"el conductor del turismo"},{"t":"водачът на автомобила, който пръв достигне до препятствието","ok":false,"i":null,"es":"el conductor que llegue primero al obstáculo"}],"es":"¿Qué conductor tiene prioridad en esta situación?","explain":"EL CONDUCTOR DEL CAMIÓN. Una sola correcta.\n\nQUÉ VES. La misma escena que la 6235: un OBSTÁCULO en el carril del turismo AZUL, que lleva el intermitente izquierdo para rodearlo, y un CAMIÓN rojo que viene de frente por su carril.\n\nEL CAMIÓN TIENE PREFERENCIA porque circula por su carril, que está libre. El azul tiene el obstáculo en su lado y, para rodearlo, invadiría el carril del camión.\n\n«EL TURISMO» es el cebo de quien piensa que el que señaliza o el más pequeño tiene preferencia.\n\n«EL QUE LLEGUE PRIMERO AL OBSTÁCULO» es una regla inventada: aquí no hay carrera.\n\nCLAVE: el obstáculo decide: quien lo tiene en su carril, cede. Ver Leyes → «Carril: dónde debes circular»."},{"id":6237,"bg":"Когато има остров в средата на пътно платно с двупосочно движение, водачът:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124137.png","v":null,"a":[{"t":"трябва да премине от неговата дясна страна","ok":true,"i":null,"es":"debe pasar por su lado DERECHO"},{"t":"трябва да премине от неговата лява страна","ok":false,"i":null,"es":"debe pasar por su lado IZQUIERDO"},{"t":"може да премине от неговата дясна или лява страна","ok":false,"i":null,"es":"puede pasar por cualquier lado"}],"es":"Cuando hay una isla en el centro de la calzada de doble sentido, el conductor:","explain":"DEBE PASAR POR SU LADO DERECHO. Una sola correcta.\n\nQUÉ VES. Una calle de DOBLE SENTIDO con una ISLETA alargada en el centro y un bolardo de señalización en su extremo.\n\nLA ISLETA SE DEJA SIEMPRE A LA IZQUIERDA. En una calzada de doble sentido, pasas por la DERECHA de la isleta: así sigues en tu mitad de la calzada.\n\n«POR SU LADO IZQUIERDO» es meterte en el sentido contrario.\n\n«POR CUALQUIER LADO» es el cebo cómodo: solo valdría si una señal lo permitiera expresamente.\n\nCLAVE: isleta en el centro de una calle de doble sentido = por la derecha. Es la misma lógica que en la rotonda (compárala con la 6378). Ver Leyes → «Carril: dónde debes circular»."},{"id":6240,"bg":"Когато на кръстовище пътните ленти не са обозначени с пътна маркировка за движение в съответна посока, завиването надясно е разрешено да се извършва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от най-дясната част на платното за движение","ok":true,"i":null,"es":"desde la parte más a la derecha de la calzada"},{"t":"от която и да е част на платното за движение, ако радиусът на завиване на автомобила е по-голям от радиуса на завоя","ok":true,"i":null,"es":"desde cualquier posición si el radio de giro lo requiere"},{"t":"във всички случаи от най-удобната за водача пътна лента","ok":false,"i":null,"es":"desde el carril más cómodo en todos los casos"}],"es":"Cuando no hay marcas de carril en intersección, girar a la derecha se hace: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: desde la derecha + desde cualquier posición si el radio de giro del vehículo lo necesita. La comodidad no es criterio válido."},{"id":6242,"bg":"Когато на кръстовище пътните ленти са обозначени за движение в съответна посока, завиването надясно може да се извърши:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от пътна лента обозначена за завиване надясно","ok":true,"i":null,"es":"desde carril marcado para girar a la derecha"},{"t":"от която и да е пътна лента, ако радиусът на завиване на автомобила е по-голям от радиуса на завоя","ok":true,"i":null,"es":"desde cualquier carril si el radio de giro lo requiere"},{"t":"от най-дясната пътна лента по посока на движението","ok":true,"i":null,"es":"desde el carril más a la derecha en el sentido de marcha"},{"t":"във всички случаи от най-удобната за водача пътна лента","ok":false,"i":null,"es":"desde el carril más cómodo en todos los casos"}],"es":"Cuando los carriles están marcados, girar a la derecha puede hacerse: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: carril marcado + si el radio lo requiere desde otro + carril más a la derecha. El criterio de comodidad no es válido."},{"id":6243,"bg":"Разрешено ли е да започнете завиването надясно от най-лявата пътна лента на платното за движение?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, но само когато радиусът на завиване на автомобила е по-голям от радиуса на завоя","ok":true,"i":null,"es":"sí, pero solo cuando el radio de giro del vehículo es mayor que el del cruce"},{"t":"да, винаги когато пътните ленти не са обозначени с пътна маркировка","ok":false,"i":null,"es":"sí, siempre cuando no hay marcas"},{"t":"да, във всички случаи","ok":false,"i":null,"es":"sí, siempre"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Está permitido iniciar un giro a la derecha desde el carril más a la izquierda?","explain":"Regla técnica importante sobre giros desde el carril izquierdo: normalmente debes girar a la derecha desde el carril más a la derecha. PERO existe una excepción: si el radio de giro de tu vehículo (la curva que traza al girar) es MAYOR que el radio de la curva de la calle, te verías obligado a invadir el carril contrario si giras desde la derecha — en ese caso específico, está permitido iniciar el giro desde un carril más a la izquierda, siempre que termines el giro en el carril derecho de la calle de destino. Es una excepción técnica para vehículos grandes (camiones, autobuses) en calles estrechas con curvas cerradas — no es una regla general para todos los conductores en cualquier situación."},{"id":6245,"bg":"Коя линия указва правилната траектория за движение при завиване надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69818.png","v":null,"a":[{"t":"червената","ok":true,"i":null,"es":"la roja"},{"t":"синята","ok":false,"i":null,"es":"la azul"}],"es":"¿Qué línea indica la trayectoria correcta al girar a la derecha?","explain":"LA ROJA. Una sola correcta.\n\nQUÉ VES. Un coche VERDE con el intermitente DERECHO, a punto de girar a la derecha. Hay dos trayectorias dibujadas: la ROJA gira ceñida a la esquina y entra pegada al borde derecho de la otra calle; la AZUL se abre hacia la izquierda y entra más lejos del borde.\n\nAL GIRAR A LA DERECHA, PEGADO A LA DERECHA. Antes de girar te colocas junto al borde derecho y, al salir del cruce, entras también por el carril de la derecha de la calle a la que giras. Esa es la roja.\n\nPOR QUÉ LA AZUL ESTÁ MAL. Abrirse invade otros carriles o el sentido contrario, sorprende a los de al lado y deja un hueco a tu derecha por el que se cuelan ciclistas y motos.\n\nCLAVE: la trayectoria correcta al girar a la derecha es la más ceñida.\n\nMÉTODO: 1) ¿hacia qué lado giro? 2) me coloco pegado a ese borde antes de girar 3) y entro pegado a ese mismo borde. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6247,"bg":"Завиването наляво може да се извършва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от най-лявата пътна лента по посока на движението","ok":true,"i":null,"es":"desde el carril más a la izquierda en el sentido de marcha"},{"t":"от всяка лента, обозначена за завиване наляво","ok":true,"i":null,"es":"desde cualquier carril señalizado para girar a la izquierda"},{"t":"от най-лявата част на еднопосочно пътно платно","ok":true,"i":null,"es":"desde la parte más a la izquierda de una calzada de sentido único"},{"t":"от най-удобната за водача пътна лента","ok":false,"i":null,"es":"desde el carril más cómodo para el conductor"}],"es":"Girar a la izquierda puede hacerse: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: giro izquierda desde: carril izquierdo + cualquier carril marcado para ello + extremo izquierdo en sentido único. El más cómodo no es criterio válido."},{"id":6250,"bg":"Коя линия указва правилната траектория за движение при завиване наляво?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69851.png","v":null,"a":[{"t":"синята","ok":true,"i":null,"es":"la azul"},{"t":"червената","ok":false,"i":null,"es":"la roja"},{"t":"и двете","ok":false,"i":null,"es":"las dos"}],"es":"¿Qué línea indica la trayectoria correcta para girar a la izquierda?","explain":"La línea AZUL — para girar a la izquierda la trayectoria correcta pasa por el centro de la intersección, no cortando. La roja es demasiado corta y peligrosa."},{"id":6252,"bg":"При тази ситуация трябва да пропусна пешеходеца.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69884.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"CORRECTO"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"es":"En esta situación debo dejar pasar al peatón. Esto es:","explain":"CORRECTO.\n\nQUÉ VES. Llevas el intermitente DERECHO y vas a girar a la derecha (flecha). En la calle a la que vas a entrar, un PEATÓN está cruzando.\n\nAL GIRAR, CEDES A LOS PEATONES QUE CRUZAN LA CALLE A LA QUE ENTRAS, aunque no haya paso pintado y aunque tengas preferencia frente a los vehículos.\n\n«INCORRECTO» es el cebo de quien piensa que solo se cede al peatón en un paso de peatones.\n\nCLAVE: es la misma escena que la 6254. Giro + peatón cruzando la calle de destino = cedo. Ver Leyes → «Paso de peatones»."},{"id":6254,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69917.png","v":null,"a":[{"t":"трябва да пропусна пешеходеца","ok":true,"i":null,"es":"debo dejar pasar al peatón"},{"t":"не съм задължен да пропусна пешеходеца, защото завивам надясно","ok":false,"i":null,"es":"no estoy obligado a ceder al peatón porque giro a la derecha"},{"t":"не съм задължен да пропусна пешеходеца, защото той не е достигнал средата на платното за движение","ok":false,"i":null,"es":"no estoy obligado porque el peatón no ha llegado al centro de la calzada"}],"es":"En esta situación:","explain":"DEBO DEJAR PASAR AL PEATÓN. Una sola correcta.\n\nQUÉ VES. Llevas el intermitente DERECHO y vas a girar a la derecha (flecha). Un PEATÓN está cruzando la calle a la que vas a entrar.\n\nAL GIRAR, CEDES A LOS PEATONES QUE CRUZAN LA CALLE A LA QUE ENTRAS. Da igual que tengas prioridad frente a los demás vehículos o que el paso esté o no pintado: al girar a la derecha o a la izquierda, los peatones que cruzan la vía en la que te metes pasan antes que tú.\n\n«NO ESTOY OBLIGADO PORQUE GIRO A LA DERECHA» es el cebo: el giro es justo lo que te obliga.\n\n«NO ESTOY OBLIGADO PORQUE NO HA LLEGADO AL CENTRO DE LA CALZADA» es el cebo fino: inventa una condición que la ley no pone. Si está cruzando, le cedes.\n\nCLAVE: giro + peatón cruzando la calle de destino = cedo.\n\nMÉTODO: 1) ¿giro? 2) ¿alguien cruza la calle a la que entro? 3) si cruza, cedo. Ver Leyes → «Paso de peatones»."},{"id":6259,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69985.png","v":null,"a":[{"t":"трябва да пропусна пешеходеца","ok":true,"i":null,"es":"debo dejar pasar al peatón"},{"t":"мога да премина преди пешеходеца, ако той се движи бавно","ok":false,"i":null,"es":"puedo pasar antes si camina despacio"},{"t":"не съм задължен да пропусна пешеходеца, защото пешеходната пътека не е маркирана","ok":false,"i":null,"es":"no estoy obligado porque el paso no está marcado"}],"es":"En esta situación:","explain":"DEBO DEJAR PASAR AL PEATÓN. Una sola correcta.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO y vas a girar a la izquierda (flecha). En la calle a la que vas a entrar, un PEATÓN está cruzando. No hay paso de peatones pintado.\n\nAL GIRAR, CEDES A LOS PEATONES QUE CRUZAN LA CALLE A LA QUE ENTRAS, haya o no paso pintado.\n\n«PUEDO PASAR ANTES SI CAMINA DESPACIO» es el cebo del cálculo: no se decide por la velocidad del peatón.\n\n«NO ESTOY OBLIGADO PORQUE EL PASO NO ESTÁ MARCADO» es el cebo principal: la obligación al girar no depende de la pintura.\n\nCLAVE: giro (a cualquier lado) + peatón cruzando la calle de destino = cedo. Compárala con la 6254 (giro a la derecha). Ver Leyes → «Paso de peatones»."},{"id":6261,"bg":"При тази ситуация съм с предимство и не съм задължен да пропусна пешеходеца:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70018.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación tengo prioridad y no estoy obligado a dejar pasar al peatón. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Llevas el intermitente DERECHO y vas a girar a la derecha. En el cruce hay un AGENTE que te muestra su COSTADO (te permite seguir recto o girar a la derecha) y a la derecha una señal de vía con prioridad (rombo). En la calle a la que giras, un PEATÓN está cruzando.\n\nTENER PASO FRENTE A LOS COCHES NO TE LIBRA DEL PEATÓN. El agente te deja girar y el rombo te da preferencia frente a otros vehículos, pero aL GIRAR, CEDES A LOS PEATONES QUE CRUZAN LA CALLE A LA QUE ENTRAS. Da igual que tengas prioridad frente a los demás vehículos o que el paso esté o no pintado: al girar a la derecha o a la izquierda, los peatones que cruzan la vía en la que te metes pasan antes que tú.\n\n«CORRECTO» es el cebo: mezcla la prioridad entre vehículos con la obligación ante los peatones.\n\nCLAVE: la prioridad frente a los vehículos y la obligación de ceder al peatón al girar son cosas distintas.\n\nMÉTODO: 1) ¿qué me permite el agente? 2) ¿giro? 3) ¿alguien cruza la calle a la que entro? Si cruza, cedo. Ver Leyes → «Paso de peatones» y «Quién manda sobre quién»."},{"id":6265,"bg":"При тази ситуация трябва да пропусна пешеходеца.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70084.png","v":null,"a":[{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":true,"i":null,"es":"CORRECTO"}],"es":"En esta situación debo dejar pasar al peatón. Esto es:","explain":"CORRECTO.\n\nQUÉ VES. Llevas el intermitente DERECHO y vas a girar a la derecha. El semáforo da VERDE con flechas (izquierda; recto y derecha). En la calle a la que vas a entrar, una PEATONA está cruzando. De frente viene un coche rojo.\n\nAL GIRAR, CEDES A LOS PEATONES QUE CRUZAN LA CALLE A LA QUE ENTRAS. El verde te deja girar, pero no pasar por delante de quien cruza.\n\n«INCORRECTO» es el cebo de quien cree que el verde le da paso libre.\n\nCLAVE: es la misma escena que la 13509. Ver Leyes → «Paso de peatones»."},{"id":6266,"bg":"При тази ситуация задължени ли сте да пропуснете червения автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70117.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Está obligado a dejar pasar al coche rojo en esta situación?","explain":"SÍ.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO y vas a girar a la izquierda. De frente viene un coche ROJO con el intermitente puesto, que gira a SU derecha. Los dos vais a entrar en la misma calle (la de tu izquierda).\n\nCUANDO DOS VEHÍCULOS QUE VIENEN DE FRENTE VAN A LA MISMA CALLE, el que gira a la DERECHA pasa antes que el que gira a la IZQUIERDA. El que gira a la izquierda cruza la trayectoria del otro y le cede.\n\n«NO» es el cebo de quien piensa que, como el rojo también gira, ya no hay que cederle.\n\nCLAVE: girar a la izquierda = ceder a lo que viene de frente, siga recto o gire a su derecha. Ver Leyes → «Giro a la izquierda»."},{"id":6267,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70117.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"ceder el paso al ROJO"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el ROJO"}],"es":"En esta situación debo:","explain":"CEDER EL PASO AL ROJO. Una sola correcta.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO y vas a girar a la izquierda. De frente viene un coche ROJO con el intermitente puesto, que gira a SU derecha. Los dos vais a entrar en la misma calle (la de tu izquierda).\n\nCUANDO DOS VEHÍCULOS QUE VIENEN DE FRENTE VAN A LA MISMA CALLE, el que gira a la DERECHA pasa antes que el que gira a la IZQUIERDA. El que gira a la izquierda cruza la trayectoria del otro y le cede.\n\n«PASAR ANTES QUE EL ROJO» es el cebo de quien piensa que, como el rojo también gira, ya no hay que cederle.\n\nCLAVE: es la misma imagen que la 6266. Girar a la izquierda = ceder a lo que viene de frente. Ver Leyes → «Giro a la izquierda»."},{"id":6268,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70117.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"ceder el paso al ROJO"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el ROJO"}],"es":"En esta situación debo:","explain":"CEDER EL PASO AL ROJO. Una sola correcta.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO y vas a girar a la izquierda. De frente viene un coche ROJO con el intermitente puesto, que gira a SU derecha. Los dos vais a entrar en la misma calle (la de tu izquierda).\n\nCUANDO DOS VEHÍCULOS QUE VIENEN DE FRENTE VAN A LA MISMA CALLE, el que gira a la DERECHA pasa antes que el que gira a la IZQUIERDA. El que gira a la izquierda cruza la trayectoria del otro y le cede.\n\n«PASAR ANTES QUE EL ROJO» es el cebo de quien piensa que, como el rojo también gira, ya no hay que cederle.\n\nCLAVE: es la misma imagen que la 6266. Girar a la izquierda = ceder a lo que viene de frente. Ver Leyes → «Giro a la izquierda»."},{"id":6269,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70217.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar ANTES que el rojo"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"ceder el paso al rojo"}],"es":"En esta situación debo:","explain":"⚠️ TRAMPA: aquí pasas ANTES que el rojo. Opuesto a las dos anteriores. La imagen determina quién tiene prioridad — lee cuidadosamente."},{"id":6270,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70250.png","v":null,"a":[{"t":"автомобилът, който завива надясно","ok":true,"i":null,"es":"el que gira a la DERECHA"},{"t":"автомобилът, който завива наляво","ok":false,"i":null,"es":"el que gira a la IZQUIERDA"}],"es":"En esta situación tiene prioridad:","explain":"EL QUE GIRA A LA DERECHA. Una sola correcta.\n\nQUÉ VES. Un coche VERDE (en primer plano) con el intermitente DERECHO, que gira a la derecha. De frente viene un coche ROJO con el intermitente, que gira a SU izquierda. Los dos van a entrar en la misma calle (la de la derecha del verde).\n\nCUANDO DOS VEHÍCULOS QUE VIENEN DE FRENTE VAN A LA MISMA CALLE, el que gira a la DERECHA pasa antes que el que gira a la IZQUIERDA. El que gira a la izquierda cruza la trayectoria del otro y le cede.\n\n«EL QUE GIRA A LA IZQUIERDA» es el cebo de quien piensa que el que llega antes al cruce tiene preferencia.\n\nCLAVE: mismo destino desde lados opuestos = el de la derecha primero. Ver Leyes → «Giro a la izquierda»."},{"id":6271,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67263.png","v":null,"a":[{"t":"водачът на зеления автомобил е задължен да пропусне червения автомобил","ok":false,"i":null,"es":"el conductor del coche verde está obligado a ceder al rojo"},{"t":"водачът на червения автомобил е задължен да пропусне зеления автомобил","ok":true,"i":null,"es":"el conductor del coche rojo está obligado a ceder al verde"}],"es":"En esta situación:","explain":"EL CONDUCTOR DEL COCHE ROJO ESTÁ OBLIGADO A CEDER AL VERDE. Una sola correcta.\n\nQUÉ VES. El coche VERDE (en primer plano) tiene una señal de CEDA EL PASO y va a girar a la derecha (intermitente y flecha). De frente viene un coche ROJO, que también llega por una vía secundaria, con el intermitente puesto para girar a SU izquierda. Los dos van a entrar en la misma calle (la de la derecha del verde).\n\nLOS DOS ESTÁN EN SECUNDARIA, así que entre ellos el ceda el paso no decide nada. Decide la regla del giro:\n\nCUANDO DOS VEHÍCULOS QUE VIENEN DE FRENTE VAN A LA MISMA CALLE, el que gira a la DERECHA pasa antes que el que gira a la IZQUIERDA. El que gira a la izquierda cruza la trayectoria del otro y le cede.\n\n«EL VERDE ESTÁ OBLIGADO A CEDER AL ROJO» es el cebo: es la misma frase con los colores cambiados.\n\nCLAVE: lee con cuidado qué color va en cada lado de la frase. Ver Leyes → «Giro a la izquierda»."},{"id":6273,"bg":"Как ще постъпите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/84437.png","v":null,"a":[{"t":"пропускам червения автомобил","ok":true,"i":null,"es":"cedo el paso al coche rojo"},{"t":"преминавам преди червения автомобил","ok":false,"i":null,"es":"paso antes que el coche rojo"}],"es":"¿Cómo actuarás en esta situación?","explain":"CEDO EL PASO AL COCHE ROJO. Una sola correcta.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO y vas a girar a la izquierda (flecha). En tu acceso hay una señal de CEDA EL PASO. De frente viene un coche ROJO.\n\nDOS RAZONES TE OBLIGAN A CEDER. Vas a girar a la izquierda, y el que gira a la izquierda cede a los que vienen de frente. Además llevas ceda el paso. En la imagen no se distingue con claridad la señal del acceso del rojo, pero da igual: aunque el rojo también llevara ceda el paso, tu giro a la izquierda te obliga a dejarle pasar.\n\n«PASO ANTES QUE EL ROJO» es el cebo de quien solo mira la distancia y piensa que le da tiempo.\n\nCLAVE: giro a la izquierda + alguien de frente = cedo.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Giro a la izquierda»."},{"id":6277,"bg":"При тази ситуация синият автомобил е с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70349.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"CORRECTO"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"es":"En esta situación el coche azul tiene prioridad. Esto es:","explain":"CORRECTO.\n\nQUÉ VES. Tienes una señal de STOP y llevas el intermitente IZQUIERDO: vas a girar a la izquierda. De frente viene un coche AZUL con el intermitente, que gira a SU derecha. Los dos vais a entrar en la misma calle (la de tu izquierda).\n\nDOS RAZONES PARA QUE PASE EL AZUL. Tú llevas STOP. Y, además, aunque los dos llevarais la misma señal: cUANDO DOS VEHÍCULOS QUE VIENEN DE FRENTE VAN A LA MISMA CALLE, el que gira a la DERECHA pasa antes que el que gira a la IZQUIERDA. El que gira a la izquierda cruza la trayectoria del otro y le cede.\n\n«INCORRECTO» es el cebo de quien piensa que el que llegó antes al STOP pasa primero.\n\nCLAVE: STOP + giro a la izquierda + alguien de frente = esperas. Ver Leyes → «Giro a la izquierda»."},{"id":6279,"bg":"При тази ситуация съм задължен да пропусна синия автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/72020.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación estoy obligado a dejar pasar al coche azul. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Tienes una señal de STOP y vas RECTO (flecha). De frente viene un coche AZUL con el intermitente, que va a girar a SU izquierda (hacia la calle de tu derecha), cruzando tu trayectoria. Las señales de los otros accesos se ven de espaldas; la respuesta del banco implica que el azul también viene por una vía secundaria.\n\nENTRE LOS DOS, CEDE EL QUE GIRA A LA IZQUIERDA. Si los dos llegáis por vías secundarias, vuestras señales no os separan, y entre vosotros decide la regla del giro: el azul gira a la izquierda y cruza tu trayectoria, así que te cede a ti, que vas recto.\n\nOjo: el STOP te obliga a detenerte antes de entrar en el cruce, pero no te obliga a ceder a quien también viene de una vía secundaria.\n\n«CORRECTO» es el cebo de quien cree que el STOP obliga a ceder a todo el mundo.\n\nCLAVE: el STOP te hace parar y ceder a los de la preferente; entre secundarias, siguen valiendo las reglas de giro y de la derecha. Ver Leyes → «Giro a la izquierda»."},{"id":6283,"bg":"При тази ситуация съм с предимство за преминаване преди червения автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70415.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación tengo prioridad sobre el coche rojo. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. En tu poste hay una señal de VÍA CON PRIORIDAD (rombo). Llevas el intermitente IZQUIERDO y vas a girar a la izquierda. De frente viene un coche ROJO con el intermitente, que gira a SU derecha. Los dos vais a entrar en la misma calle (la de tu izquierda).\n\nEL ROMBO NO OS SEPARA: el rojo viene de frente por la misma vía preferente que tú. Entre vosotros decide la regla del giro:\n\nCUANDO DOS VEHÍCULOS QUE VIENEN DE FRENTE VAN A LA MISMA CALLE, el que gira a la DERECHA pasa antes que el que gira a la IZQUIERDA. El que gira a la izquierda cruza la trayectoria del otro y le cede.\n\n«CORRECTO» es el cebo de quien cree que el rombo le da preferencia frente a todos, incluido el que viene de frente.\n\nCLAVE: el rombo te da preferencia sobre los de la secundaria, no sobre los que van por tu misma vía. Ver Leyes → «Giro a la izquierda»."},{"id":6286,"bg":"При тази ситуация съм с предимство пред червения автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70448.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación tengo prioridad sobre el coche rojo. Esto es:","explain":"INCORRECTO — el rojo tiene prioridad sobre ti, no al revés."},{"id":6290,"bg":"При тази ситуация червеният автомобил е с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70482.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación el coche rojo tiene prioridad. Esto es:","explain":"INCORRECTO — a pesar de lo que pueda parecer, el rojo NO tiene prioridad en esta situación específica."},{"id":6292,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70515.png","v":null,"a":[{"t":"червеният автомобил","ok":true,"i":null,"es":"el coche rojo"},{"t":"синият автомобил","ok":false,"i":null,"es":"el coche azul"}],"es":"En esta situación tiene prioridad:","explain":"EL COCHE ROJO. Una sola correcta.\n\nQUÉ VES. Un cruce con SEMÁFOROS en verde y señal de vía con prioridad. El coche AZUL (en primer plano) lleva el intermitente IZQUIERDO y va a girar a la izquierda. De frente viene un coche ROJO que sigue recto.\n\nCON EL VERDE PARA LOS DOS, EL QUE GIRA A LA IZQUIERDA CEDE AL QUE VIENE DE FRENTE (siga recto o gire a su derecha). El semáforo os deja pasar a la vez; entre vosotros, el que cruza la trayectoria del otro espera.\n\n«EL AZUL» es el cebo de quien piensa que el verde o el rombo le dan paso frente a todos.\n\nCLAVE: verde + giro a la izquierda + alguien de frente = esperas. Ver Leyes → «Giro a la izquierda»."},{"id":6299,"bg":"При тази ситуация трябва да пропусна синия автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70548.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"CORRECTO"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"es":"En esta situación debo dejar pasar al coche azul. Esto es:","explain":"CORRECTO.\n\nQUÉ VES. Vas a girar a la IZQUIERDA (intermitente y flecha). El semáforo da VERDE (flechas de izquierda/recto y de derecha). De frente viene un coche AZUL con el intermitente, que gira a SU derecha, hacia la misma calle a la que vas tú.\n\nCON EL VERDE PARA LOS DOS, EL QUE GIRA A LA IZQUIERDA CEDE AL QUE VIENE DE FRENTE (siga recto o gire a su derecha). El semáforo os deja pasar a la vez; entre vosotros, el que cruza la trayectoria del otro espera.\n\n«INCORRECTO» es el cebo de quien piensa que, como el azul también gira, ya no hay que cederle.\n\nCLAVE: mismo destino desde lados opuestos = el que gira a la derecha pasa primero. Ver Leyes → «Giro a la izquierda»."},{"id":6301,"bg":"При тази ситуация трябва да премина преди червения автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70581.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación debo pasar antes que el coche rojo. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO y vas a girar a la izquierda. El semáforo está en VERDE y debajo hay una señal azul de DIRECCIÓN OBLIGATORIA a la izquierda; encima, un rombo. De frente viene un coche ROJO que sigue recto.\n\nCON EL VERDE, EL QUE GIRA A LA IZQUIERDA CEDE AL DE FRENTE. El verde os deja pasar a los dos a la vez; entre vosotros, quien gira a la izquierda cruza la trayectoria del que viene de frente y le cede.\n\nLA SEÑAL AZUL NO TE DA PRIORIDAD: te obliga a girar a la izquierda, nada más. Y el rombo queda por debajo del semáforo.\n\n«CORRECTO» es el cebo de quien cree que la señal obligatoria o el rombo le dan preferencia.\n\nCLAVE: verde + giro a la izquierda + alguien de frente = esperas.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Giro a la izquierda»."},{"id":6305,"bg":"При тази ситуация водачът на товарния автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70647.png","v":null,"a":[{"t":"трябва да пропусне двата автомобила, защото излиза от гараж","ok":true,"i":null,"es":"dejar pasar a los dos coches porque sale de un garaje"},{"t":"трябва да пропусне пешеходците","ok":true,"i":null,"es":"dejar pasar a los peatones"},{"t":"е с предимство пред синия автомобил, защото се намира от дясната му страна","ok":false,"i":null,"es":"tiene prioridad sobre el azul porque está a su derecha"}],"es":"En esta situación el conductor del camión debe: (2 correctas)","explain":"DEBE DEJAR PASAR A LOS DOS COCHES PORQUE SALE DE UN GARAJE, Y DEBE DEJAR PASAR A LOS PEATONES. Dos correctas.\n\nQUÉ VES. Un CAMIÓN rojo sale de la puerta de un GARAJE con el intermitente puesto, cruzando la acera hacia la calzada. Por la acera pasan PEATONES. Por la calzada circulan un coche AMARILLO (por la izquierda del camión) y uno AZUL (por su derecha).\n\nCEDE EL QUE SALE. Salir de un garaje, un patio o un aparcamiento no es llegar a un cruce: es incorporarse a una vía por la que otros ya circulan. El que sale cede a todos los que van por ella, vengan por donde vengan.\n\nY A LOS PEATONES TAMBIÉN: al cruzar la acera, el camión tiene que dejar pasar a quien camina por ella.\n\n«TIENE PRIORIDAD SOBRE EL AZUL PORQUE ESTÁ A SU DERECHA» es el cebo: la regla de la derecha no se aplica a quien sale de un garaje.\n\nEL TAMAÑO DEL CAMIÓN NO CUENTA.\n\nCLAVE: salir de un garaje, patio o aparcamiento = ceder a todos (vehículos y peatones).\n\nMÉTODO: 1) ¿es un cruce o una salida de una propiedad? 2) si es una salida, cede el que sale. Ver Leyes → «Salir de un camino de tierra»."},{"id":6334,"bg":"При тази ситуация съм с предимство, защото се движа направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70713.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación tengo prioridad porque voy recto. Esto es:","explain":"INCORRECTO — ir recto no da prioridad automática. Quien tiene prioridad es quien está en vía preferente o a la derecha, no quien va recto."},{"id":6335,"bg":"При тази ситуация преминавам с предимство преди трамвая.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70746.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación paso con prioridad antes que el tranvía. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Un cruce SIN SEÑALES ni semáforo. Vas recto (flecha). De frente viene un TRANVÍA con el intermitente puesto, que gira por sus vías hacia tu derecha (es decir, a SU izquierda), cruzándose con tu trayectoria.\n\nEN UN CRUCE DE VÍAS IGUALES, EL TRANVÍA PASA PRIMERO. Ante un vehículo sobre raíles, los vehículos sin raíles le ceden el paso en los cruces sin señales, aunque el tranvía gire y tú sigas recto. La regla de la derecha y la del giro a la izquierda valen entre coches; con el tranvía, cede el coche.\n\n«CORRECTO» es el cebo de quien aplica la lógica de los coches: «él gira a la izquierda, yo voy recto, paso yo». Con un tranvía, no.\n\nCLAVE: cruce sin señales + tranvía = el tranvía pasa primero, haga lo que haga. Es la teoría de la 6350 y la 6352 («siempre, independientemente de su posición», también cuando gira a la izquierda) aplicada a una imagen.\n\nMÉTODO: 1) ¿hay agente, semáforo o señales? 2) si no, ¿hay un tranvía? Pasa primero. 3) entre coches, la derecha. Ver Leyes → «Quién manda sobre quién»."},{"id":6336,"bg":"При тази ситуация с предимство ли сте пред трамвая, който завива?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70779.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"¿Tiene usted prioridad sobre el tranvía que gira?","explain":"NO.\n\nQUÉ VES. En tu poste hay una señal de VÍA CON PRIORIDAD (rombo). Vas RECTO (flecha). De frente viene un TRANVÍA con el intermitente puesto, que gira por sus vías hacia tu derecha, cruzando tu trayectoria.\n\nEL ROMBO NO TE DA PREFERENCIA SOBRE EL TRANVÍA. El tranvía viene por la misma vía preferente que tú, así que la señal no os separa. Y entre los dos, el vehículo sin raíles cede al tranvía, aunque el tranvía gire y tú sigas recto.\n\n«SÍ» es el cebo de quien aplica la lógica de los coches («él gira, yo voy recto»).\n\nCLAVE: tranvía en tu misma vía = el tranvía primero. Compárala con la 6335 y la 6352. Ver Leyes → «Quién manda sobre quién»."},{"id":6337,"bg":"При тази ситуация задължени ли сте да пропуснете трамвая?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70812.png","v":null,"a":[{"t":"да, защото е релсово ППС","ok":true,"i":null,"es":"sí, porque es un vehículo ferroviario"},{"t":"не, защото се движа направо","ok":false,"i":null,"es":"no, porque voy recto"}],"es":"¿Está obligado a dejar pasar al tranvía?","explain":"SÍ, PORQUE ES UN VEHÍCULO SOBRE RAÍLES. Una sola correcta.\n\nQUÉ VES. Un cruce con SEMÁFORO en VERDE, señal de DIRECCIÓN OBLIGATORIA RECTO y rombo. Vas RECTO. De frente viene un TRANVÍA con el intermitente, que gira por sus vías hacia tu derecha, cruzando tu trayectoria.\n\nANTE UN TRANVÍA, EL COCHE CEDE. Los vehículos sin raíles dejan pasar al tranvía cuando sus trayectorias se cruzan, aunque el tranvía gire y tú sigas recto. El semáforo en verde para los dos no cambia esta regla.\n\n«NO, PORQUE VOY RECTO» es el cebo: ir recto da preferencia frente a un coche que gira a la izquierda, no frente a un tranvía.\n\nCLAVE: la razón correcta es la que da el propio banco: «porque es un vehículo sobre raíles». Ver Leyes → «Quién manda sobre quién»."},{"id":6340,"bg":"При тази ситуация с предимство е водачът на:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70846.png","v":null,"a":[{"t":"трамвая","ok":true,"i":null,"es":"el tranvía"},{"t":"лекия автомобил","ok":false,"i":null,"es":"el turismo"}],"es":"En esta situación tiene prioridad:","explain":"EL TRANVÍA. Una sola correcta.\n\nQUÉ VES. Un cruce con SEMÁFORO en VERDE. El coche AZUL lleva el intermitente DERECHO y va a girar a la derecha atravesando las VÍAS del tranvía, que quedan a su derecha. Por esas vías viene un TRANVÍA de frente.\n\nEL QUE GIRA CRUZA LAS VÍAS: CEDE. ANTE UN TRANVÍA, EL COCHE CEDE. Los vehículos sin raíles dejan pasar al tranvía cuando sus trayectorias se cruzan, aunque el tranvía gire y tú sigas recto. El semáforo en verde para los dos no cambia esta regla.\n\n«EL TURISMO» es el cebo de quien piensa que el verde o el giro a la derecha le dan preferencia.\n\nCLAVE: antes de cruzar unas vías, mira si viene un tranvía. Ver Leyes → «Quién manda sobre quién»."},{"id":6343,"bg":"При тази ситуация водачът на автомобила длъжен ли е да пропусне трамвая?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70879.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"En esta situación ¿está obligado el conductor del coche a dejar pasar al tranvía?","explain":"SÍ.\n\nQUÉ VES. Un cruce con SEMÁFORO en verde (con un rombo encima). Un coche AZUL lleva el intermitente DERECHO y va a girar a la derecha. A su DERECHA, por las vías, circula un TRANVÍA en el mismo sentido, que sigue recto.\n\nAL GIRAR, CRUZAS LAS VÍAS DEL TRANVÍA. El coche, para girar a la derecha, tiene que atravesar la trayectoria del tranvía que sigue recto a su lado. Con el mismo verde para los dos, el que gira cede al que sigue recto, y aquí además es un tranvía.\n\n«NO» es el cebo de quien piensa que, con verde, el coche ya puede girar sin más. El verde te deja girar, pero no te quita la obligación de ceder a quien cruzas.\n\nCLAVE: girar a la derecha con un tranvía a tu derecha = esperar a que pase.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Quién manda sobre quién»."},{"id":6344,"bg":"При тази ситуация водачът на автомобила задължен ли е да пропусне трамвая?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70912.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"En esta situación ¿está obligado el conductor del coche a dejar pasar al tranvía?","explain":"SÍ.\n\nQUÉ VES. Un cruce con SEMÁFORO en VERDE. Un coche AZUL sigue recto. Un TRANVÍA, con el intermitente puesto, está girando por sus vías y va a cruzar la trayectoria del coche.\n\nANTE UN TRANVÍA, EL COCHE CEDE. Los vehículos sin raíles dejan pasar al tranvía cuando sus trayectorias se cruzan, aunque el tranvía gire y tú sigas recto. El semáforo en verde para los dos no cambia esta regla.\n\n«NO» es el cebo de quien cree que el verde le da paso frente a todos.\n\nCLAVE: es la misma regla que la 6337 («sí, porque es un vehículo sobre raíles»). Ver Leyes → «Quién manda sobre quién»."},{"id":6345,"bg":"При тази ситуация водачът на лекия автомобил не е задължен да пропусне трамвая.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70945.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación el conductor del turismo no está obligado a dejar pasar al tranvía. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Un cruce SIN SEÑALES ni semáforo. A la izquierda, un TRANVÍA con el intermitente puesto gira por sus vías y va a cruzar por delante del turismo AZUL, que sigue recto.\n\nEL CONDUCTOR SÍ ESTÁ OBLIGADO A CEDER. En un cruce de vías iguales, los vehículos sin raíles ceden siempre el paso al tranvía, sea cual sea su posición y la dirección en que gire. Así que el enunciado («no está obligado») es falso.\n\n«CORRECTO» es el cebo de quien aplica la lógica de los coches (regla de la derecha o «el que gira cede»). Con el tranvía, eso no vale.\n\nCLAVE: cruce sin señales + tranvía = el tranvía pasa primero. Es la teoría de la 6352 («siempre, independientemente de su posición») aplicada a una imagen. Compárala con la 6335.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Quién manda sobre quién»."},{"id":6346,"bg":"При тази ситуация синият автомобил трябва да премине преди трамвая.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70978.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación el coche azul debe pasar antes que el tranvía. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Un AGENTE en el cruce. El coche AZUL lleva el intermitente DERECHO y va a girar a la derecha, atravesando las VÍAS del tranvía que quedan a su derecha. Por ellas avanza un TRANVÍA en el mismo sentido.\n\nEL AZUL CRUZA LA TRAYECTORIA DEL TRANVÍA: CEDE. Aunque el agente os permita pasar a los dos, entre vosotros el coche que gira deja pasar al tranvía que sigue recto.\n\n«CORRECTO» es el cebo de quien cree que el que gira a la derecha, pegado a la acera, tiene preferencia.\n\nCLAVE: girar a la derecha con un tranvía a tu derecha = esperas a que pase. Compárala con la 6343. Ver Leyes → «Quién manda sobre quién»."},{"id":6348,"bg":"Когато е разрешено едновременното им преминаване, водачът на нерелсово ППС е длъжен да пропусне релсовото:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"винаги, независимо от местоположението му","ok":true,"i":null,"es":"siempre, independientemente de su posición"},{"t":"винаги, независимо от посоката му на движение","ok":true,"i":null,"es":"siempre, independientemente de su dirección"},{"t":"само когато релсовото ППС се намира от дясната му страна","ok":false,"i":null,"es":"solo cuando está a su derecha"},{"t":"само в случаите, когато релсовото превозно средство не завива","ok":false,"i":null,"es":"solo cuando no gira"}],"es":"Cuando está permitido el paso simultáneo, el conductor no ferroviario debe ceder al ferroviario: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: siempre independientemente de posición Y de dirección. El tranvía tiene prioridad absoluta — su posición o dirección no cambian la obligación de cederle."},{"id":6350,"bg":"На кръстовище на равнозначни пътища водачът на нерелсово ППС:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да пропусне релсовите ППС, когато те завиват надясно","ok":true,"i":null,"es":"debe ceder al tranvía cuando gira a la derecha"},{"t":"не е длъжен да пропусне релсовите ППС, когато те завиват наляво","ok":false,"i":null,"es":"no está obligado a ceder al tranvía cuando gira a la izquierda"},{"t":"трябва да пропусне релсовите ППС, когато те продължават направо","ok":true,"i":null,"es":"debe ceder al tranvía cuando continúa recto"}],"es":"En intersección de vías equivalentes, el conductor no ferroviario: (2 correctas)","explain":"⚠️ TRAMPA: debes ceder al tranvía cuando gira a la derecha Y cuando va recto. Cuando el tranvía gira a la izquierda, la situación es diferente — NO estás obligado a cederle."},{"id":6352,"bg":"На кръстовище на равнозначни пътища водачът на нерелсово пътно превозно средство е длъжен да пропусне релсовите ППС:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"само когато релсовите ППС се намират от дясната му страна","ok":false,"i":null,"es":"solo cuando está a su derecha"},{"t":"само когато релсовите ППС се намира от лявата му страна","ok":false,"i":null,"es":"solo cuando está a su izquierda"},{"t":"само когато релсовите ППС са в насрещното движение","ok":false,"i":null,"es":"solo cuando viene de frente"},{"t":"винаги, независимо от местоположението им","ok":true,"i":null,"es":"siempre, independientemente de su posición"}],"es":"En intersección de vías equivalentes, el conductor no ferroviario debe dejar pasar al tranvía:","explain":"SIEMPRE, independientemente de dónde venga. El tranvía tiene prioridad absoluta en intersecciones equivalentes, sin importar su posición relativa."},{"id":6356,"bg":"При завиване наляво за навлизане в друг път водачът на завиващото релсово ППС е длъжен да пропусне насрещно движещите се:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трамваи","ok":true,"i":null,"es":"tranvías"},{"t":"тролейбуси","ok":false,"i":null,"es":"trolebuses"},{"t":"леки автомобили","ok":false,"i":null,"es":"turismos"},{"t":"мотоциклети","ok":false,"i":null,"es":"motos"}],"es":"Al girar a la izquierda para entrar en otro camino, el tranvía que gira a la izquierda debe ceder el paso a:","explain":"A otros TRANVÍAS — cuando dos tranvías coinciden, se aplican las reglas entre tranvías. Los trolebuses, turismos y motos no tienen prioridad sobre el tranvía."},{"id":6358,"bg":"Как се извършва завиването в обратна посока?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"чрез движение със завиване наляво","ok":true,"i":null,"es":"mediante un giro a la IZQUIERDA"},{"t":"чрез движение със завиване надясно","ok":false,"i":null,"es":"mediante un giro a la DERECHA"}],"es":"¿Cómo se realiza el cambio de sentido?","explain":"⚠️ TRAMPA: siempre por la IZQUIERDA. Dar la vuelta = giro a la izquierda. Nunca a la derecha (eso sería dar una vuelta completa a la manzana)."},{"id":6360,"bg":"Завиването в обратна посока може да започне:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от най-лявата пътна лента по посока на движението","ok":true,"i":null,"es":"desde el carril más a la izquierda"},{"t":"от дясната част на платното за движение, когато е с недостатъчна широчина","ok":true,"i":null,"es":"desde la derecha cuando la anchura es insuficiente"},{"t":"от най-удобната за водача пътна лента","ok":false,"i":null,"es":"desde el carril más cómodo"}],"es":"El cambio de sentido puede iniciarse: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: desde el carril izquierdo (normal) + desde la derecha cuando no cabe de la forma normal. Nunca desde el carril más cómodo — la maniobra tiene reglas de posición."},{"id":6361,"bg":"Завиването в обратна посока от крайната дясна лента е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"разрешено при недостатъчна широчина на платното за движение","ok":true,"i":null,"es":"permitido cuando la anchura de la vía es insuficiente"},{"t":"разрешено във всички случаи","ok":false,"i":null,"es":"permitido siempre"},{"t":"забранено","ok":false,"i":null,"es":"prohibido"}],"es":"El cambio de sentido desde el carril derecho está:","explain":"Permitido cuando la anchura es insuficiente para hacerlo desde la izquierda. Es la excepción a la norma general (iniciarlo desde la izquierda)."},{"id":6362,"bg":"Когато при недостатъчна широчина на платното за движение завиването в обратна посока започва от дясната пътна лента, водачът на завиващото ППС:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71077.png","v":null,"a":[{"t":"трябва да пропусне насрещно движещите се ППС","ok":true,"i":null,"es":"ceder al tráfico de frente"},{"t":"трябва да пропусне попътно движещите се от лявата му страна ППС","ok":true,"i":null,"es":"ceder al tráfico que viene por su izquierda"},{"t":"е с предимство пред насрещно движещите се ППС","ok":false,"i":null,"es":"tiene prioridad sobre el tráfico de frente"},{"t":"е с предимство пред попътно движещите се от лявата му страна ППС","ok":false,"i":null,"es":"tiene prioridad sobre el que viene por su izquierda"}],"es":"Cuando se da la vuelta desde la derecha por falta de anchura, el conductor debe: (2 correctas)","explain":"CEDER AL TRÁFICO DE FRENTE Y CEDER AL TRÁFICO QUE VIENE POR SU IZQUIERDA EN SU MISMO SENTIDO. Dos correctas.\n\nQUÉ VES. Un CAMIÓN en el carril DERECHO con el intermitente IZQUIERDO: por falta de anchura, va a dar la vuelta (cambio de sentido) empezando desde el carril derecho. Por el carril izquierdo, en su mismo sentido, va un coche ROJO.\n\nEL QUE HACE EL CAMBIO DE SENTIDO CEDE A TODOS. Al dar la vuelta desde la derecha atraviesa el carril de su izquierda (por donde va el rojo) y luego el carril contrario. Tiene que ceder a los que van en su sentido por la izquierda y a los que vienen de frente.\n\n«TIENE PRIORIDAD SOBRE LOS DE FRENTE» y «TIENE PRIORIDAD SOBRE LOS DE SU IZQUIERDA» son los cebos: el cambio de sentido no da prioridad sobre nadie.\n\nCLAVE: cambio de sentido = la maniobra que más cruza, y la que más cede. Compárala con la 6363 (la misma escena). Ver Leyes → «Cambio de sentido o media vuelta»."},{"id":6363,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71077.png","v":null,"a":[{"t":"водачът на лекия автомобил","ok":true,"i":null,"es":"el conductor del TURISMO"},{"t":"водачът на товарния автомобил","ok":false,"i":null,"es":"el conductor del CAMIÓN"}],"es":"En esta situación tiene prioridad:","explain":"EL CONDUCTOR DEL TURISMO. Una sola correcta.\n\nQUÉ VES. La misma escena que la 6362: un CAMIÓN en el carril derecho, con el intermitente izquierdo, va a dar la vuelta desde ese carril; por el carril izquierdo, en el mismo sentido, va un turismo ROJO.\n\nEL QUE DA LA VUELTA CEDE. El camión, para cambiar de sentido, tiene que cruzar el carril del turismo. El turismo sigue recto por su carril: tiene preferencia.\n\n«EL CAMIÓN» es el cebo de quien piensa que el camión, por estar a la derecha o por haber señalizado, pasa primero.\n\nCLAVE: cambio de sentido = cede a todos. Ver Leyes → «Cambio de sentido o media vuelta»."},{"id":6365,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/142934.png","v":null,"a":[{"t":"водачът на товарния автомобил","ok":true,"i":null,"es":"el conductor del CAMIÓN"},{"t":"водачът на лекия автомобил","ok":false,"i":null,"es":"el conductor del turismo"}],"es":"En esta situación tiene prioridad:","explain":"EL CONDUCTOR DEL CAMIÓN. Una sola correcta.\n\nQUÉ VES. Una carretera con mediana. En una abertura de la mediana hay una señal azul que PERMITE el CAMBIO DE SENTIDO. El coche AZUL lleva el intermitente izquierdo y va a dar la vuelta por ahí. Por el otro lado viene un CAMIÓN rojo.\n\nLA SEÑAL PERMITE LA MANIOBRA, NO DA PRIORIDAD. Puedes dar la vuelta en ese punto, pero cediendo a los que circulan por la calzada a la que entras, como el camión.\n\n«EL TURISMO» es el cebo de quien confunde «está permitido» con «tengo preferencia».\n\nCLAVE: señal de cambio de sentido permitido = puedo hacerlo, cediendo el paso. Ver Leyes → «Cambio de sentido o media vuelta»."},{"id":6366,"bg":"При тази ситуация с предимство е водачът на:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71177.png","v":null,"a":[{"t":"червения автомобил","ok":true,"i":null,"es":"el coche rojo"},{"t":"синия автомобил","ok":false,"i":null,"es":"el coche azul"}],"es":"En esta situación tiene prioridad:","explain":"EL COCHE ROJO. Una sola correcta.\n\nQUÉ VES. Un cruce con SEMÁFORO en verde y señal de vía con prioridad. El coche AZUL (en primer plano) lleva el intermitente IZQUIERDO y va a girar a la izquierda. De frente viene un coche ROJO que sigue recto.\n\nCON EL VERDE PARA LOS DOS, EL QUE GIRA A LA IZQUIERDA CEDE AL QUE VIENE DE FRENTE (siga recto o gire a su derecha). El semáforo os deja pasar a la vez; entre vosotros, el que cruza la trayectoria del otro espera.\n\n«EL AZUL» es el cebo de quien piensa que el verde o el rombo le dan paso frente a todos.\n\nCLAVE: es la misma regla que la 6292. Ver Leyes → «Giro a la izquierda»."},{"id":6368,"bg":"Завиването в обратна посока е забранено, когато видимостта е намалена под:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 м","ok":true,"i":null,"es":"50 m"},{"t":"250 м","ok":false,"i":null,"es":"250 m"},{"t":"150 м","ok":false,"i":null,"es":"150 m"},{"t":"100 м","ok":false,"i":null,"es":"100 m"}],"es":"El cambio de sentido está prohibido cuando la visibilidad es inferior a:","explain":"50 metros — con visibilidad inferior a 50m el cambio de sentido está prohibido. Memoriza este número específico para las preguntas sobre prohibiciones por visibilidad."},{"id":6369,"bg":"Завиването в обратна посока е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на жп прелез","ok":true,"i":null,"es":"en paso a nivel"},{"t":"когато видимостта е намалена под 50 м","ok":true,"i":null,"es":"con visibilidad inferior a 50 m"},{"t":"в тунел","ok":true,"i":null,"es":"en túnel"},{"t":"на участък от пътя с наклон","ok":false,"i":null,"es":"en tramo con pendiente"}],"es":"El cambio de sentido está PROHIBIDO: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: paso a nivel + visibilidad <50m + túnel. En tramos con pendiente NO está automáticamente prohibido el cambio de sentido."},{"id":6370,"bg":"Завиването в обратна посока е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на мост","ok":true,"i":null,"es":"en puente"},{"t":"на пешеходна пътека","ok":true,"i":null,"es":"en paso de peatones"},{"t":"при ограничена видимост","ok":true,"i":null,"es":"con visibilidad limitada"},{"t":"на участък от пътя в ремонт","ok":false,"i":null,"es":"en tramo en obras"}],"es":"El cambio de sentido está PROHIBIDO: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: puente + paso de peatones + visibilidad limitada. En tramos en obras NO está prohibido el cambio de sentido per se."},{"id":6371,"bg":"Завиването в обратна посока е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на жп прелез","ok":true,"i":null,"es":"en paso a nivel"},{"t":"на надлез","ok":true,"i":null,"es":"en paso elevado"},{"t":"на пешеходна пътека","ok":true,"i":null,"es":"en paso de peatones"},{"t":"на път с интензивно движение","ok":false,"i":null,"es":"en vía de intenso tráfico"}],"es":"El cambio de sentido está PROHIBIDO: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: paso a nivel + paso elevado (viaducto) + paso de peatones. El tráfico intenso no prohíbe el cambio de sentido."},{"id":6372,"bg":"Завиването в обратна посока е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на жп прелез","ok":true,"i":null,"es":"en paso a nivel"},{"t":"в тунел","ok":true,"i":null,"es":"en túnel"},{"t":"когато с пътен знак е ограничена скоростта на движение","ok":false,"i":null,"es":"cuando hay señal de limitación de velocidad"},{"t":"на 10 м преди пешеходна пътека","ok":false,"i":null,"es":"a 10 m antes de paso de peatones"}],"es":"El cambio de sentido está PROHIBIDO: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: prohibido dar la vuelta en paso a nivel Y en túnel. La señal de velocidad y la distancia al paso de peatones NO prohíben el cambio de sentido."},{"id":6373,"bg":"Завиването в обратна посока е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на пешеходна пътека","ok":true,"i":null,"es":"en paso de peatones"},{"t":"при ограничена видимост","ok":true,"i":null,"es":"con visibilidad limitada"},{"t":"на участък от пътя в ремонт","ok":false,"i":null,"es":"en tramo de vía en obras"},{"t":"на 160 м преди жп прелез","ok":false,"i":null,"es":"a 160 m antes del paso a nivel"}],"es":"El cambio de sentido está PROHIBIDO: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: prohibido dar la vuelta en paso de peatones Y con visibilidad limitada. Las obras y la distancia al paso a nivel no prohíben el cambio de sentido."},{"id":6374,"bg":"Завиването в обратна посока е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"в тунел","ok":true,"i":null,"es":"en túnel"},{"t":"при ограничена видимост","ok":true,"i":null,"es":"con visibilidad limitada"},{"t":"на участък от пътя в ремонт","ok":false,"i":null,"es":"en tramo en obras"},{"t":"на път с интензивно движение","ok":false,"i":null,"es":"en vía de intenso tráfico"}],"es":"El cambio de sentido está PROHIBIDO: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: túnel + visibilidad limitada. Obras e intenso tráfico no prohíben el cambio de sentido."},{"id":6375,"bg":"При тази ситуация разрешено ли е да завиете в обратна посока?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71210.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"¿Está permitido dar la vuelta en esta situación?","explain":"NO.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO y la flecha dibuja un cambio de sentido. El semáforo está en VERDE y encima hay una señal circular AZUL con flecha de giro a la IZQUIERDA: DIRECCIÓN OBLIGATORIA A LA IZQUIERDA.\n\nLA SEÑAL OBLIGATORIA SOLO PERMITE LO QUE DIBUJA. Te obliga a girar a la izquierda; dar la vuelta (cambio de sentido) es otra maniobra, y en el examen búlgaro esta señal no la autoriza.\n\n«SÍ» es el cebo de quien piensa que, si se puede girar a la izquierda, también se puede dar la vuelta.\n\nCLAVE (regla del banco que conviene memorizar): señal AZUL de giro obligatorio a la izquierda = NO se puede dar la vuelta; señal ROJA de prohibido girar a la izquierda = SÍ se puede dar la vuelta (compárala con la 6377). Ver Leyes → «Dónde está prohibido cambiar de sentido»."},{"id":6376,"bg":"При тази ситуация разрешено ли е да завиете в обратна посока?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71243.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"¿Está permitido dar la vuelta en esta situación?","explain":"NO.\n\nQUÉ VES. El coche ROJO lleva el intermitente IZQUIERDO y la flecha dibuja un cambio de sentido. A la derecha hay una señal circular AZUL con flecha de giro a la IZQUIERDA: DIRECCIÓN OBLIGATORIA A LA IZQUIERDA.\n\nLA SEÑAL OBLIGATORIA SOLO PERMITE GIRAR A LA IZQUIERDA. Dar la vuelta no está incluido.\n\n«SÍ» es el cebo de quien confunde «girar a la izquierda» con «dar la vuelta».\n\nCLAVE: es la misma regla que la 6375. Azul obligatoria a la izquierda = sin cambio de sentido. Ver Leyes → «Dónde está prohibido cambiar de sentido»."},{"id":6377,"bg":"При тази ситуация разрешено ли е да завиете в обратна посока?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71276.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Está permitido dar la vuelta en esta situación?","explain":"SÍ.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO y la flecha dibuja un cambio de sentido. El semáforo está en VERDE y encima hay una señal de borde ROJO con la flecha de giro a la izquierda TACHADA: PROHIBIDO GIRAR A LA IZQUIERDA.\n\nLA PROHIBICIÓN SOLO PROHÍBE LO QUE DIBUJA. Esta señal prohíbe el giro a la izquierda, pero en el examen búlgaro no prohíbe el cambio de sentido. Para prohibir la vuelta existe otra señal distinta (la de la flecha en U tachada).\n\n«NO» es el cebo de quien piensa que, si no se puede girar a la izquierda, tampoco se puede dar la vuelta.\n\nCLAVE: roja de prohibido girar a la izquierda = SÍ se puede dar la vuelta; azul de giro obligatorio a la izquierda = NO (compárala con la 6375). Ver Leyes → «Dónde está prohibido cambiar de sentido»."},{"id":6378,"bg":"При тази ситуация водачът на червения автомобил извършва ли нарушение?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71309.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"En esta situación ¿comete infracción el conductor del coche rojo?","explain":"SÍ.\n\nQUÉ VES. Una ROTONDA con su señal (círculo azul con flechas) y un ceda el paso a la entrada. El coche ROJO entra con el intermitente IZQUIERDO y la flecha muestra que gira directamente a la izquierda, pasando por delante de la isleta central en sentido contrario al de la rotonda.\n\nEN LA ROTONDA SE CIRCULA ALREDEDOR DE LA ISLETA, dejándola a tu IZQUIERDA (sentido contrario a las agujas del reloj). Aunque vayas a salir por la izquierda, entras girando a la derecha y das la vuelta. Atajar por la izquierda es circular en sentido contrario dentro de la rotonda.\n\n«NO» es el cebo de quien piensa que, si la rotonda está vacía, el atajo no molesta a nadie. La norma no depende de que haya tráfico.\n\nCLAVE: en la rotonda, la isleta siempre a tu izquierda; nunca se ataja.\n\nMÉTODO: 1) ¿es una rotonda (señal azul de flechas en círculo)? 2) ¿el coche rodea la isleta dejándola a su izquierda? 3) si no, comete infracción."},{"id":6379,"bg":"При разминаване на два автомобила задължението за осигуряване на необходимата странична дистанция е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на двамата водачи","ok":true,"i":null,"es":"de ambos conductores"},{"t":"на водача на автомобила с по-големи габарити","ok":false,"i":null,"es":"del conductor del vehículo más grande"},{"t":"на водача на автомобила, който се движи с по-висока скорост","ok":false,"i":null,"es":"del que va más rápido"},{"t":"на водача на автомобила с по-голяма обща маса","ok":false,"i":null,"es":"del de mayor masa total"}],"es":"La obligación de garantizar la distancia lateral necesaria al cruzarse es:","explain":"De AMBOS — al cruzarse en la calzada, la obligación de guardar distancia lateral suficiente es compartida entre los dos conductores. No es responsabilidad de uno solo."},{"id":6380,"bg":"Когато, при голям надлъжен наклон, за разминаване на единично ППС със състав от ППС е необходимо движение назад, то се извършва от:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"единичното превозно средство","ok":true,"i":null,"es":"el vehículo individual"},{"t":"ППС, което се изкачва по наклона","ok":false,"i":null,"es":"el vehículo que sube"},{"t":"ППС, което се спуска по наклона","ok":false,"i":null,"es":"el vehículo que baja"},{"t":"състава от ППС","ok":false,"i":null,"es":"el convoy"}],"es":"Cuando en pendiente pronunciada un vehículo individual debe ceder el paso a un convoy, ¿quién retrocede?","explain":"El vehículo INDIVIDUAL retrocede ante el convoy. Entre mismo tipo: el que baja retrocede (el que sube tiene prioridad). El convoy es más difícil de maniobrar."},{"id":6381,"bg":"Когато, на път с голям надлъжен наклон, за разминаването на лек с товарен автомобил е необходимо движение назад, то се извършва от:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"лекия автомобил","ok":true,"i":null,"es":"el turismo"},{"t":"товарния автомобил","ok":false,"i":null,"es":"el camión"},{"t":"автомобила, който се изкачва по наклона","ok":false,"i":null,"es":"el que sube"},{"t":"автомобила, който се спуска по наклона","ok":false,"i":null,"es":"el que baja"}],"es":"Cuando en pendiente pronunciada un turismo debe ceder el paso a un camión, ¿quién retrocede?","explain":"El TURISMO retrocede — es más fácil de maniobrar. El tamaño y la maniobrabilidad determinan quién retrocede cuando la norma no lo especifica."},{"id":6382,"bg":"Когато, при голям надлъжен наклон, за разминаване на товарен автомобил с автобус е необходимо движение назад, то се извършва от:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"товарния автомобил","ok":true,"i":null,"es":"el camión"},{"t":"ППС, което се изкачва по наклона","ok":false,"i":null,"es":"el que sube"},{"t":"ППС, което се спуска по наклона","ok":false,"i":null,"es":"el que baja"},{"t":"автобуса","ok":false,"i":null,"es":"el autobús"}],"es":"En pendiente con camión y autobús que necesitan que uno retroceda, ¿quién retrocede?","explain":"El CAMIÓN — es más fácil de maniobrar que un autobús lleno de pasajeros. Entre vehículos distintos, retrocede el que cause menos inconveniente general."},{"id":6383,"bg":"На път с голям надлъжен наклон, когато разминаването е невъзможно и редът за преминаване не е уреден с пътни знаци, предимство има ППС, което:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"се изкачва по наклона","ok":true,"i":null,"es":"SUBE la pendiente"},{"t":"се спуска по наклона","ok":false,"i":null,"es":"BAJA la pendiente"},{"t":"се движи по-бързо","ok":false,"i":null,"es":"va más rápido"},{"t":"се намира по-близо до стеснения участък","ok":false,"i":null,"es":"está más cerca del tramo estrecho"}],"es":"En vía con gran pendiente, cuando el cruce es imposible y no hay norma establecida, tiene prioridad el que:","explain":"⚠️ TRAMPA: prioridad para el que SUBE. Reanudar la marcha cuesta arriba es más difícil — por eso tiene prioridad. El que baja puede retroceder más fácilmente."},{"id":6384,"bg":"При тази ситуация задължен да пропусне насрещно движещото се превозно средство е водачът на:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71342.png","v":null,"a":[{"t":"червения автомобил","ok":true,"i":null,"es":"coche rojo"},{"t":"синия автомобил","ok":false,"i":null,"es":"coche azul"}],"es":"En esta situación está obligado a ceder al vehículo que viene de frente el conductor del:","explain":"EL CONDUCTOR DEL COCHE ROJO. Una sola correcta.\n\nQUÉ VES. Un puente ESTRECHO, donde no caben dos vehículos a la vez. A la derecha hay dos señales de peligro: ESTRECHAMIENTO de la calzada por ambos lados y PENDIENTE PRONUNCIADA (18 %). El dibujo de la pendiente sube de izquierda a derecha: para el coche AZUL (el tuyo, en primer plano) es una SUBIDA. De frente, al otro lado del puente, viene un coche ROJO, que por tanto va CUESTA ABAJO.\n\nEN UNA PENDIENTE ESTRECHA, CEDE EL QUE BAJA. Al que sube le cuesta más detenerse y volver a arrancar; al que baja, menos. Por eso, cuando no caben los dos, el que desciende deja pasar al que asciende.\n\n«EL COCHE AZUL» es el cebo de quien piensa que el que está más cerca del estrechamiento tiene que esperar.\n\nCLAVE: fíjate en el dibujo de la señal de pendiente para saber quién sube y quién baja. Es la teoría de la 6383 («tiene preferencia el que sube») aplicada a una imagen.\n\nMÉTODO: 1) ¿caben los dos? 2) si no, ¿hay señal de prioridad en el estrechamiento? 3) si no la hay y hay pendiente, cede el que baja."},{"id":6386,"bg":"При тази ситуация червеният автомобил е с предимство за преминаване през стеснения участък от пътя.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71375.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"CORRECTO"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"es":"En esta situación el coche rojo tiene prioridad para pasar por el tramo estrecho. Esto es:","explain":"CORRECTO.\n\nQUÉ VES. Un puente ESTRECHO donde no caben dos vehículos. A la derecha hay una señal circular de borde ROJO con una flecha NEGRA hacia abajo y una ROJA hacia arriba: PREFERENCIA PARA LOS QUE VIENEN DE FRENTE. Al otro lado del puente viene un coche ROJO.\n\nLA SEÑAL TE DICE QUE CEDES TÚ. La flecha roja (la tuya) es la que cede; la negra (la del que viene de frente) tiene preferencia. El rojo pasa primero.\n\n«INCORRECTO» es el cebo de quien confunde esta señal (círculo de borde rojo, cedes tú) con la cuadrada azul (preferencia tuya).\n\nCLAVE: círculo rojo con flechas = cedo; cuadrado azul con flechas = tengo preferencia. Compárala con la 6387. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6387,"bg":"Как трябва да постъпите при тази ситуация, след като червеният автомобил е навлязъл в стеснения участък?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71408.png","v":null,"a":[{"t":"длъжен съм да пропусна червения автомобил","ok":true,"i":null,"es":"estoy obligado a ceder al rojo"},{"t":"трябва да продължа движението си, защото съм с предимство","ok":false,"i":null,"es":"debo continuar porque tengo prioridad"},{"t":"трябва да подам сигнал към червения автомобил за да ми осигури предимство","ok":false,"i":null,"es":"debo señalizarle que me deje pasar"}],"es":"¿Cómo debes actuar cuando el coche rojo ya ha entrado en el tramo estrecho?","explain":"ESTOY OBLIGADO A CEDER AL ROJO. Una sola correcta.\n\nQUÉ VES. Un paso ESTRECHO bajo un puente, donde solo cabe un vehículo. A la derecha, la señal azul de PRIORIDAD SOBRE LOS VEHÍCULOS QUE VIENEN DE FRENTE (flecha blanca grande hacia arriba, flecha roja hacia abajo): en principio, tú tienes preferencia. Pero el coche ROJO ya está DENTRO del tramo estrecho, viniendo hacia ti.\n\nLA PRIORIDAD NO TE AUTORIZA A PROVOCAR UN CHOQUE. La señal te da preferencia para ENTRAR antes que él. Si él ya ha entrado, la situación ha cambiado: tienes que esperar a que salga.\n\n«DEBO CONTINUAR PORQUE TENGO PRIORIDAD» es el cebo: confunde tener prioridad con tener el paso libre.\n\n«DEBO SEÑALIZARLE QUE ME DEJE PASAR» tampoco sirve: no puede dar marcha atrás dentro del tramo estrecho, y las señales acústicas o luminosas no dan ningún derecho.\n\nCLAVE: la prioridad en un estrechamiento se aplica a la entrada; si el otro ya está dentro, se espera.\n\nMÉTODO: 1) ¿quién tiene prioridad según la señal? 2) ¿el otro ya ha entrado? 3) si ha entrado, espero aunque la prioridad fuera mía. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6388,"bg":"При тази ситуация водачът на синия автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/72053.png","v":null,"a":[{"t":"трябва да пропусне автомобила, който вече е навлязъл в стеснения участък","ok":true,"i":null,"es":"debe dejar pasar al vehículo que ya entró en el tramo estrecho"},{"t":"е с предимство и трябва да продължи движението си","ok":false,"i":null,"es":"tiene prioridad y debe continuar"}],"es":"En esta situación el conductor del coche azul:","explain":"DEBE DEJAR PASAR AL VEHÍCULO QUE YA HA ENTRADO EN EL TRAMO ESTRECHO. Una sola correcta.\n\nQUÉ VES. Un paso ESTRECHO bajo un puente. A la derecha, la señal CUADRADA AZUL de PREFERENCIA sobre los que vienen de frente: en principio, el AZUL tiene preferencia. Pero un coche ROJO ya está DENTRO del tramo estrecho, viniendo hacia él.\n\nLA PREFERENCIA SE APLICA A LA ENTRADA. Si el otro ya ha entrado, el azul espera a que salga. Tener preferencia no autoriza a provocar un choque.\n\n«TIENE PRIORIDAD Y DEBE CONTINUAR» es el cebo: confunde tener preferencia con tener el paso libre.\n\nCLAVE: es la misma regla que la 6387. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6389,"bg":"Този пътен знак сигнализира, че:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67460.png","v":null,"a":[{"t":"навлизането след него е разрешено, ако пътят е свободен","ok":true,"i":null,"es":"entrar después de ella está permitido si el camino está libre"},{"t":"навлизането след него е забранено","ok":false,"i":null,"es":"entrar después de ella está prohibido"},{"t":"навлизането след него е разрешено във всички случаи","ok":false,"i":null,"es":"entrar está permitido en todos los casos"},{"t":"движението след знака е двупосочно","ok":false,"i":null,"es":"la circulación es bidireccional"}],"es":"Esta señal indica que:","explain":"Esta señal (probablemente 'ceda el paso' o similar) permite entrar SOLO si el camino está libre. No es prohibición total pero tampoco permiso incondicional."},{"id":6390,"bg":"Кое от изброените действия е задължително при маневрата изпреварване?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"подаване на сигнал за отклонение наляво","ok":true,"i":null,"es":"señalizar desviación a la izquierda"},{"t":"подаване на сигнал за отклонение надясно","ok":true,"i":null,"es":"señalizar desviación a la derecha"},{"t":"подаване на звуков сигнал, когато маневрата се извършва в населено място","ok":false,"i":null,"es":"tocar el claxon en zona urbana"},{"t":"включване на дългите светлини","ok":false,"i":null,"es":"activar las luces largas"}],"es":"¿Qué acciones son obligatorias en la maniobra de adelantamiento? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: señalizar a la izquierda (al iniciar) Y señalizar a la derecha (al reincorporarse). Las dos fases del adelantamiento requieren señalización. El claxon y las largas son opcionales."},{"id":6393,"bg":"Изпреварването на товарен автомобил е по-рисковано от изпреварването на лек автомобил защото:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"дължината на товарните автомобили е по-голяма от тази на леките автомобили","ok":true,"i":null,"es":"los camiones son más largos que los turismos"},{"t":"видимостта напред при движение зад товарен автомобил е по-ограничена","ok":true,"i":null,"es":"la visibilidad hacia adelante detrás de un camión es más limitada"},{"t":"спирачките на товарните автомобили не са толкова ефективни","ok":false,"i":null,"es":"los frenos de los camiones no son tan eficaces"},{"t":"товарните автомобили изкачват стръмните наклони по-бавно","ok":false,"i":null,"es":"los camiones suben las pendientes más despacio"}],"es":"Adelantar un camión es más arriesgado que adelantar un turismo porque: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: los camiones son más largos (necesitas más distancia) Y la visibilidad detrás de ellos es muy limitada. Los frenos de los camiones modernos son eficaces y la velocidad en pendiente no es determinante."},{"id":6394,"bg":"Как трябва да постъпите когато автомобилът който ви изпреварва се прибере в лентата, по която се движите, без да осигури необходимата дистанция?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir la velocidad"},{"t":"трябва да премина в лявата лента","ok":false,"i":null,"es":"debo pasar al carril izquierdo"},{"t":"трябва да продължа движението си със същата скорост","ok":false,"i":null,"es":"debo continuar igual"},{"t":"трябва да подам светлинен сигнал","ok":false,"i":null,"es":"debo señalizar con luces"}],"es":"¿Cómo actúas cuando el vehículo que te adelantó vuelve a su carril delante de ti?","explain":"Debo REDUCIR — cuando otro se reincorpora delante de ti, reduce para mantener la distancia de seguridad. Pasar al izquierdo o continuar igual son peligrosos."},{"id":6395,"bg":"Този пътен знак забранява изпреварването:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67557.png","v":null,"a":[{"t":"на МПС, с изключение на мотоциклети без кош и мотопеди","ok":true,"i":null,"es":"de vehículos a motor excepto motos sin sidecar y ciclomotores"},{"t":"на всички ППС","ok":false,"i":null,"es":"de todos los vehículos"},{"t":"само на леки автомобили","ok":false,"i":null,"es":"solo de turismos"}],"es":"Esta señal prohíbe el adelantamiento:","explain":"DE VEHÍCULOS A MOTOR, EXCEPTO MOTOS SIN SIDECAR Y CICLOMOTORES. Una sola correcta.\n\nLA SEÑAL. Círculo de borde ROJO con dos coches, uno ROJO y otro NEGRO: PROHIBIDO ADELANTAR.\n\nQUÉ PROHÍBE. Adelantar a vehículos de motor. La excepción son las motos sin sidecar y los ciclomotores: a ellos sí se les puede adelantar bajo esta señal (son estrechos y se les puede pasar sin invadir mucho el carril contrario).\n\n«A TODOS LOS VEHÍCULOS» es el cebo de leerla como absoluta.\n\n«SOLO A TURISMOS» es el cebo de leer el dibujo al pie de la letra: el dibujo muestra coches, pero la prohibición va más allá.\n\nCLAVE: prohibido adelantar = no a los vehículos de motor, salvo motos sin sidecar y ciclomotores.\n\nMÉTODO: 1) círculo rojo = prohibición 2) ¿qué dibuja? 3) recuerda la excepción de las dos ruedas. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6396,"bg":"Кое от изброените ППС е разрешено да изпреварвате след този пътен знак?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67607.png","v":null,"a":[{"t":"мотоциклет без кош","ok":true,"i":null,"es":"moto sin sidecar"},{"t":"мотопед","ok":true,"i":null,"es":"ciclomotor"},{"t":"трактор","ok":false,"i":null,"es":"tractor"},{"t":"съчленен автобус","ok":false,"i":null,"es":"autobús articulado"}],"es":"¿Qué vehículo está PERMITIDO adelantar después de esta señal? (2 correctas)","explain":"LA MOTO SIN SIDECAR Y EL CICLOMOTOR. Dos correctas.\n\nLA SEÑAL. Círculo de borde ROJO con un coche ROJO y uno NEGRO: PROHIBIDO ADELANTAR.\n\nLA SEÑAL DE PROHIBIDO ADELANTAR (círculo de borde rojo con un coche rojo y uno negro) prohíbe adelantar a los vehículos de MOTOR, salvo a las motos sin sidecar y a los ciclomotores. Los vehículos sin motor (bicicletas, carros) tampoco están incluidos.\n\n«TRACTOR» y «AUTOBÚS ARTICULADO» son vehículos de motor: no puedes adelantarlos bajo esta señal.\n\nCLAVE: las excepciones son las dos ruedas estrechas con motor (moto sin sidecar y ciclomotor). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6397,"bg":"Кое от изброените ППС е разрешено да изпреварвате след този пътен знак?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67607.png","v":null,"a":[{"t":"велосипед","ok":true,"i":null,"es":"bicicleta"},{"t":"каруца","ok":true,"i":null,"es":"carruaje (carro de caballos)"},{"t":"трактор","ok":false,"i":null,"es":"tractor"},{"t":"товарен автомобил","ok":false,"i":null,"es":"camión"}],"es":"¿Qué vehículo está PERMITIDO adelantar después de esta señal? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: puedes adelantar a la bicicleta Y al carruaje — no son vehículos a motor, están exentos de la prohibición. El tractor y el camión son vehículos a motor = prohibido adelantarlos."},{"id":6398,"bg":"Кое от изброените ППС е забранено да изпреварвате след този пътен знак?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67607.png","v":null,"a":[{"t":"трактор","ok":true,"i":null,"es":"tractor"},{"t":"товарен автомобил","ok":true,"i":null,"es":"camión"},{"t":"мотопед","ok":false,"i":null,"es":"ciclomotor"},{"t":"велосипед","ok":false,"i":null,"es":"bicicleta"}],"es":"¿Qué vehículo está PROHIBIDO adelantar después de esta señal? (2 correctas)","explain":"EL TRACTOR Y EL CAMIÓN. Dos correctas.\n\nLA SEÑAL. Círculo de borde ROJO con un coche ROJO y uno NEGRO: PROHIBIDO ADELANTAR.\n\nLA SEÑAL DE PROHIBIDO ADELANTAR (círculo de borde rojo con un coche rojo y uno negro) prohíbe adelantar a los vehículos de MOTOR, salvo a las motos sin sidecar y a los ciclomotores. Los vehículos sin motor (bicicletas, carros) tampoco están incluidos.\n\n«CICLOMOTOR» es una de las excepciones: sí puedes adelantarlo. «BICICLETA» no es un vehículo de motor: tampoco está incluida.\n\nCLAVE: compárala con la 6396 (la misma señal, preguntando qué SÍ se puede adelantar). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6399,"bg":"Кое от изброените ППС е забранено да изпреварвате след този пътен знак?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67607.png","v":null,"a":[{"t":"лек автомобил","ok":true,"i":null,"es":"turismo"},{"t":"съчленен автобус","ok":true,"i":null,"es":"autobús articulado"},{"t":"мотоциклет без кош","ok":false,"i":null,"es":"moto sin sidecar"},{"t":"каруца","ok":false,"i":null,"es":"carruaje"}],"es":"¿Qué vehículo está PROHIBIDO adelantar después de esta señal? (2 correctas)","explain":"EL TURISMO Y EL AUTOBÚS ARTICULADO. Dos correctas.\n\nLA SEÑAL. Círculo de borde ROJO con dos coches, uno rojo y otro negro: PROHIBIDO ADELANTAR.\n\nQUÉ PROHÍBE. Adelantar a los vehículos de MOTOR, salvo las motos sin sidecar y los ciclomotores. El turismo y el autobús articulado son vehículos de motor: no puedes adelantarlos.\n\n«MOTO SIN SIDECAR» es la excepción expresa de la señal: a ella sí puedes adelantarla.\n\n«CARRO» (каруца, de tracción animal) no es un vehículo de motor, así que la señal no te impide adelantarlo.\n\nCLAVE: la prohibición alcanza a los vehículos de motor; fuera quedan las dos ruedas estrechas (moto sin sidecar, ciclomotor) y lo que no tiene motor.\n\nMÉTODO: 1) ¿el vehículo tiene motor? 2) ¿es una moto sin sidecar o un ciclomotor? 3) motor y no excepción = prohibido adelantarlo. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6401,"bg":"След този пътен знак на водачите на товарни автомобили с допустима максимална маса над 3,5 т е разрешено да изпреварват:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67956.png","v":null,"a":[{"t":"мотоциклети без кош","ok":true,"i":null,"es":"motos sin sidecar"},{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"леки автомобили","ok":false,"i":null,"es":"turismos"},{"t":"автобуси","ok":false,"i":null,"es":"autobuses"}],"es":"Después de esta señal, los conductores de camiones con MMA >3.5t PUEDEN adelantar a: (2 correctas)","explain":"LAS MOTOS SIN SIDECAR Y LOS CICLOMOTORES. Dos correctas.\n\nLA SEÑAL. Círculo de borde ROJO con un CAMIÓN rojo y un coche negro: PROHIBIDO ADELANTAR PARA LOS CAMIONES de más de 3,5 t.\n\nQUÉ PROHÍBE. A los camiones de más de 3,5 t, adelantar a vehículos de motor. Igual que en la señal general, las motos sin sidecar y los ciclomotores quedan fuera: a ellos sí pueden adelantarlos.\n\n«TURISMOS» y «AUTOBUSES» son vehículos de motor: el camión no puede adelantarlos bajo esta señal.\n\nCLAVE: esta señal solo afecta a los camiones pesados; a un turismo como el tuyo no le prohíbe nada. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6402,"bg":"След този пътен знак на водачите на товарни автомобили с допустима максимална маса до 3,5 т е разрешено да изпреварват:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67607.png","v":null,"a":[{"t":"мотоциклети без кош","ok":true,"i":null,"es":"motos sin sidecar"},{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"автобуси","ok":false,"i":null,"es":"autobuses"},{"t":"трактори","ok":false,"i":null,"es":"tractores"}],"es":"Después de esta señal, los conductores de camiones con MMA ≤3.5t PUEDEN adelantar a: (2 correctas)","explain":"LAS MOTOS SIN SIDECAR Y LOS CICLOMOTORES. Dos correctas.\n\nLA SEÑAL. Círculo de borde ROJO con un coche ROJO y uno NEGRO: PROHIBIDO ADELANTAR (para todos los conductores, incluidos los de camiones de hasta 3,5 t).\n\nLA SEÑAL DE PROHIBIDO ADELANTAR (círculo de borde rojo con un coche rojo y uno negro) prohíbe adelantar a los vehículos de MOTOR, salvo a las motos sin sidecar y a los ciclomotores. Los vehículos sin motor (bicicletas, carros) tampoco están incluidos.\n\n«AUTOBUSES» y «TRACTORES» son vehículos de motor: no se pueden adelantar bajo esta señal.\n\nCLAVE: la señal general se aplica a todos los conductores, conduzcan lo que conduzcan. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6403,"bg":"След този пътен знак на водачите на товарни автомобили с допустима максимална маса до 3,5 т е разрешено да изпреварват:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67607.png","v":null,"a":[{"t":"велосипеди","ok":true,"i":null,"es":"bicicletas"},{"t":"каруци","ok":true,"i":null,"es":"carruajes"},{"t":"леки автомобили","ok":false,"i":null,"es":"turismos"},{"t":"товарни автомобили","ok":false,"i":null,"es":"camiones"}],"es":"Después de esta señal, los conductores de camiones con MMA ≤3.5t PUEDEN adelantar a: (2 correctas)","explain":"LAS BICICLETAS Y LOS CARROS. Dos correctas.\n\nLA SEÑAL. Círculo de borde ROJO con un coche ROJO y uno NEGRO: PROHIBIDO ADELANTAR (también para los camiones de hasta 3,5 t).\n\nLA SEÑAL DE PROHIBIDO ADELANTAR (círculo de borde rojo con un coche rojo y uno negro) prohíbe adelantar a los vehículos de MOTOR, salvo a las motos sin sidecar y a los ciclomotores. Los vehículos sin motor (bicicletas, carros) tampoco están incluidos.\n\nPOR ESO SE PUEDE ADELANTAR a las bicicletas y a los carros (каруци): no son vehículos de motor.\n\n«TURISMOS» y «CAMIONES» son vehículos de motor: prohibido adelantarlos.\n\nCLAVE: compárala con la 6402 (la misma señal: allí las excepciones con motor, aquí los vehículos sin motor). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6405,"bg":"След този пътен знак разрешено ли е на водачите на товарни автомобили да изпреварват други автомобили?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68072.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Está permitido a los conductores de camiones adelantar otros vehículos después de esta señal?","explain":"SÍ.\n\nLA SEÑAL. Círculo blanco con borde negro, con los dos coches dibujados en gris/negro y TACHADOS por barras diagonales: FIN DE LA PROHIBICIÓN DE ADELANTAR.\n\nLAS BARRAS SIGNIFICAN «FIN». Se acaba la prohibición general de adelantar, que afectaba a todos los conductores, también a los de camiones. A partir de aquí pueden adelantar respetando las normas generales.\n\n«NO» es el cebo de quien confunde esta señal con la de prohibido adelantar (borde rojo, sin barras).\n\nCLAVE: blanco y negro con barras = fin de la restricción. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6406,"bg":"Разрешено ли е да продължите изпреварването при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71507.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"¿Está permitido continuar el adelantamiento en esta situación?","explain":"NO.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO: estás adelantando. Delante va una MOTO CON SIDECAR. A la derecha, la señal de PROHIBIDO ADELANTAR (borde rojo, coche rojo y coche negro).\n\nEL SIDECAR LA SACA DE LA EXCEPCIÓN. Bajo esta señal solo se puede adelantar a motos SIN sidecar y a ciclomotores. Una moto con sidecar es más ancha y está incluida en la prohibición.\n\n«SÍ» es el cebo de quien recuerda «las motos se pueden adelantar» y no se fija en el sidecar.\n\nCLAVE: moto sin sidecar = se puede; moto con sidecar = no. Compárala con la 6396. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6407,"bg":"Разрешено ли е да продължите изпреварването при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71540.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"¿Está permitido continuar el adelantamiento en esta situación?","explain":"NO.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO: estás adelantando. Delante va un TRACTOR rojo. A la derecha, la señal de PROHIBIDO ADELANTAR.\n\nEL TRACTOR ES UN VEHÍCULO DE MOTOR, y la señal prohíbe adelantar a los vehículos de motor (salvo motos sin sidecar y ciclomotores). Aunque vaya despacio, no puedes adelantarlo aquí.\n\n«SÍ» es el cebo de quien piensa que un vehículo lento se puede adelantar siempre.\n\nCLAVE: la lentitud no es una excepción; la excepción son las motos sin sidecar y los ciclomotores. Compárala con la 6398. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6408,"bg":"Разрешено ли е да изпреварите мотоциклетиста при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71573.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Está permitido adelantar al motorista en esta situación?","explain":"SÍ — la situación mostrada (línea discontinua, visibilidad suficiente, sin prohibición) permite el adelantamiento con seguridad."},{"id":6409,"bg":"Разрешено ли е да предприемете изпреварване, когато автомобилът зад вас е подал сигнал за отклонение наляво?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69437.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"¿Está permitido adelantar cuando el vehículo de detrás ya señalizó que va a cambiar de dirección?","explain":"NO.\n\nQUÉ VES. Delante circula un coche ROJO. En los retrovisores se ve un coche AZUL detrás de ti con el intermitente IZQUIERDO: ya ha empezado a adelantarte. A la derecha, la señal de FIN DE TODAS LAS PROHIBICIONES.\n\nANTES DE ADELANTAR, MIRA SI TE ESTÁN ADELANTANDO A TI. Si el de detrás ya ha señalizado que se desplaza a la izquierda, no puedes iniciar tu adelantamiento: os encontraríais los dos en el carril izquierdo.\n\n«SÍ» es el cebo: la señal de fin de prohibiciones te hace pensar que ya puedes adelantar, pero no te libra de comprobar lo que viene detrás.\n\nCLAVE: antes de adelantar: el de delante no adelanta, el de detrás no me adelanta, y tengo hueco para volver. Compárala con la 12051 (vídeo). Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6410,"bg":"Разрешено ли е изпреварването при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71672.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"¿Está permitido el adelantamiento en esta situación?","explain":"NO.\n\nQUÉ VES. Carretera fuera de población. Llevas el intermitente IZQUIERDO y la flecha muestra que quieres adelantar a un coche ROJO. A la derecha, la señal de FIN DE LA LIMITACIÓN de 60 km/h. En el centro de la calzada hay una LÍNEA DOBLE, y la línea de tu lado parece CONTINUA.\n\nLA LÍNEA CONTINUA NO SE CRUZA. Con una línea doble, manda la que está de tu lado: si es continua, no puedes pasar al otro carril para adelantar.\n\n«SÍ» es el cebo: el fin de la limitación de velocidad no tiene nada que ver con la prohibición de adelantar.\n\nCLAVE: fin de limitación de velocidad ≠ permiso para adelantar; mira las marcas del suelo. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6411,"bg":"Изпреварването е забранено, когато:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"при използване на пътна лента за насрещното движение не е възможно безпрепятственото връщане в напуснатата лента","ok":true,"i":null,"es":"usando el carril contrario no es posible volver sin obstaculizar"},{"t":"видимостта е ограничена","ok":true,"i":null,"es":"la visibilidad es limitada"},{"t":"изпреварващият автомобил е с повредени пътепоказатели","ok":false,"i":null,"es":"el adelantante tiene los intermitentes averiados"},{"t":"се извършва по двулентов двупосочен път","ok":false,"i":null,"es":"se realiza en vía de dos carriles de doble sentido"}],"es":"El adelantamiento está PROHIBIDO cuando: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: prohibido cuando no puedes reincorporarte sin obstaculizar Y con visibilidad limitada. Los intermitentes averiados y el tipo de vía no son condiciones de prohibición automática."},{"id":6412,"bg":"Разрешено ли е да предприемете изпреварване на колоната от МПС при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71738.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"¿Está permitido adelantar toda la columna de vehículos en esta situación?","explain":"NO.\n\nQUÉ VES. Carretera de montaña con una pared de roca a la derecha. Delante hay una COLUMNA de vehículos (un coche amarillo, uno rojo, uno azul y un camión). Llevas el intermitente IZQUIERDO y detrás de ti viene otro coche azul.\n\nADELANTAR A TODA LA COLUMNA ES UNA MANIOBRA DEMASIADO LARGA. Para adelantar tienes que poder hacerlo en poco tiempo y tener sitio para volver a tu carril. Con varios vehículos seguidos y poco espacio entre ellos, estarías mucho tiempo en el carril contrario sin saber si podrás volver a tiempo, en una carretera donde no se ve lejos.\n\n«SÍ» es el cebo de la impaciencia.\n\nCLAVE: no se adelanta a una fila entera si no hay sitio seguro para volver entre ellos. Compárala con la 12051 (vídeo). Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6413,"bg":"Изпреварването на МПС, с изключение на мотопеди и мотоциклети без кош, е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"при използване на пътна лента за насрещно движение, когато изпреварващият не може да се върне безпрепятствено в напуснатата пътна лента","ok":true,"i":null,"es":"usando el carril contrario no es posible volver al carril sin obstaculizar"},{"t":"пред и върху сигнализирана пешеходна пътека","ok":true,"i":null,"es":"la visibilidad es limitada"},{"t":"в стеснен участък от пътя","ok":false,"i":null,"es":"el vehículo adelantante tiene los intermitentes averiados"},{"t":"на железопътен прелез с бариери","ok":false,"i":null,"es":"se realiza en vía de dos carriles de doble sentido"}],"es":"El adelantamiento está PROHIBIDO cuando: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: prohibido cuando no puedes reincorporarte sin obstaculizar Y cuando la visibilidad es limitada. Los intermitentes averiados y la vía de doble sentido no son prohibiciones automáticas."},{"id":6414,"bg":"Изпреварването на МПС, с изключение на мотопеди и мотоциклети без кош, е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"при ограничена видимост, когато разстоянието е по-малко от необходимото за изпреварване","ok":true,"i":null,"es":"con visibilidad limitada y distancia insuficiente para adelantar"},{"t":"пред и върху сигнализирана пешеходна пътека","ok":true,"i":null,"es":"ante y sobre paso de peatones señalizado"},{"t":"на път с еднопосочно движение","ok":false,"i":null,"es":"en vía de un solo sentido"},{"t":"на мост","ok":false,"i":null,"es":"en puente"}],"es":"El adelantamiento está PROHIBIDO: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: visibilidad limitada con distancia insuficiente + ante/sobre paso de peatones señalizado. La vía de sentido único y el puente no prohíben el adelantamiento per se."},{"id":6415,"bg":"Изпреварването на МПС, с изключение на мотопеди и мотоциклети без кош, е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на кръстовище на равнозначни пътища","ok":true,"i":null,"es":"en intersección de vías equivalentes"},{"t":"на железопътен прелез без бариери","ok":true,"i":null,"es":"en paso a nivel sin barreras"},{"t":"при използване на пътна лента за насрещно движение, когато изпреварващият не може да се върне безпрепятствено в напуснатата пътна лента","ok":true,"i":null,"es":"usando el carril contrario cuando no puedes reincorporarte sin peligro"},{"t":"в тунел","ok":false,"i":null,"es":"en túnel"}],"es":"El adelantamiento está PROHIBIDO: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: prohibido en intersección equivalente + paso a nivel sin barreras + cuando no puedes reincorporarte. En túneles NO está prohibido per se si la visibilidad es suficiente."},{"id":6416,"bg":"Изпреварването на МПС, с изключение на мотопеди и мотоциклети без кош, е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"при намалена видимост, когато разстоянието е по-малко от необходимото за изпреварване","ok":true,"i":null,"es":"con visibilidad reducida y distancia insuficiente"},{"t":"пред и върху сигнализирана пешеходна пътека","ok":true,"i":null,"es":"ante y sobre paso de peatones señalizado"},{"t":"на надлез","ok":false,"i":null,"es":"en paso elevado"},{"t":"при движение през нощта","ok":false,"i":null,"es":"de noche"}],"es":"El adelantamiento está PROHIBIDO: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: visibilidad reducida insuficiente + ante/sobre paso de peatones. Los pasos elevados y la noche no prohíben adelantar."},{"id":6417,"bg":"Изпреварването на МПС, с изключение на мотопеди и мотоциклети без кош, е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на кръстовище на равнозначни пътища","ok":true,"i":null,"es":"en intersección de vías equivalentes"},{"t":"на железопътен прелез без бариери","ok":true,"i":null,"es":"en paso a nivel sin barreras"},{"t":"пред пешеходна пътека, когато изпреварваното превозно средство закрива видимостта към пешеходната пътека","ok":true,"i":null,"es":"ante un paso de peatones cuando el vehículo adelantado oculta la visibilidad"},{"t":"на пътища с двупосочно движение","ok":false,"i":null,"es":"en vías con doble sentido de circulación"}],"es":"El adelantamiento de vehículos (excepto ciclomotores y motos sin sidecar) está PROHIBIDO: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: prohibido adelantar en intersecciones equivalentes + paso a nivel sin barreras + ante paso de peatones con visibilidad oculta. En vías de doble sentido NO está prohibido per se."},{"id":6418,"bg":"Разрешено ли е изпреварването при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71819.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"¿Está permitido adelantar en esta situación?","explain":"NO — la situación mostrada (curva, cima, paso a nivel, señal prohibitiva) impide el adelantamiento con seguridad."},{"id":6419,"bg":"При тази ситуация изпреварването е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71852.png","v":null,"a":[{"t":"забранено, защото видимостта е ограничена","ok":true,"i":null,"es":"prohibido, porque la visibilidad es limitada"},{"t":"забранено, защото пътят е неравен","ok":false,"i":null,"es":"prohibido, porque el camino es irregular"},{"t":"забранено, защото пътят е с голям наклон","ok":false,"i":null,"es":"prohibido, porque hay gran pendiente"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"es":"En esta situación el adelantamiento está:","explain":"PROHIBIDO, PORQUE LA VISIBILIDAD ES LIMITADA. Una sola correcta.\n\nQUÉ VES. Carretera de montaña. A la izquierda, balizas rojas con flechas blancas que marcan una CURVA cerrada. A la derecha, dos señales de peligro: PENDIENTE PRONUNCIADA y CALZADA IRREGULAR. Delante va un coche rojo.\n\nEL MOTIVO ES LA CURVA: en ella no ves lo que viene de frente. Adelantar sin visibilidad está prohibido.\n\n«PORQUE EL CAMINO ES IRREGULAR» y «PORQUE HAY GRAN PENDIENTE» son los cebos: las señales están en la imagen, pero son de PELIGRO (triángulos) y no prohíben adelantar.\n\n«PERMITIDO» ignora la curva.\n\nCLAVE: un triángulo avisa; lo que prohíbe aquí es la falta de visibilidad. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6420,"bg":"Разрешено ли е при изпреварване да използвате превключването на светлините като допълнителен сигнал?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Está permitido usar el parpadeo de luces como señal adicional al adelantar?","explain":"SÍ — el parpadeo de luces (cambio corto a largas) está permitido como señal adicional al adelantar fuera de zona urbana."},{"id":6421,"bg":"При тази ситуация разрешено ли е да продължите изпреварването?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71885.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"En esta situación ¿está permitido continuar el adelantamiento?","explain":"NO.\n\nQUÉ VES. Calle urbana. Llevas el intermitente IZQUIERDO: estás adelantando a una FURGONETA blanca. Justo delante hay un PASO DE PEATONES (señales azules a ambos lados).\n\nANTES DE UN PASO DE PEATONES NO SE ADELANTA. Está prohibido adelantar sobre el paso de peatones e inmediatamente antes de él: el vehículo al que adelantas puede estar tapándote a alguien que cruza. La furgoneta, alta y ancha, tapa completamente lo que hay a su derecha.\n\n«SÍ» es el cebo de quien no ve peatones y cree que la vía está libre.\n\nCLAVE: paso de peatones delante = no se adelanta, se vea o no a alguien. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6423,"bg":"При тази ситуация, когато пешеходецът напуска платното за движение и имам видимост към пешеходната пътека, е разрешено да продължа изпреварването.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71919.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación, cuando el peatón abandona la calzada y tengo visibilidad, puedo adelantar. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Calle urbana. Llevas el intermitente IZQUIERDO y estás adelantando a un coche ROJO. Delante hay un PASO DE PEATONES. Un peatón está terminando de cruzar por la derecha.\n\nQUE ESE PEATÓN SALGA NO CAMBIA LA REGLA. ANTES DE UN PASO DE PEATONES NO SE ADELANTA. Está prohibido adelantar sobre el paso de peatones e inmediatamente antes de él: el vehículo al que adelantas puede estar tapándote a alguien que cruza. Aunque el peatón que ves ya esté saliendo y tengas visibilidad, la prohibición sigue en pie.\n\n«CORRECTO» es el cebo: la frase suena razonable («ya no hay nadie, ya veo»), pero la norma no depende de eso.\n\nCLAVE: compárala con la 6421: la prohibición de adelantar junto al paso de peatones es absoluta. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6424,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71954.png","v":null,"a":[{"t":"прекратявам изпреварването","ok":true,"i":null,"es":"abandono el adelantamiento"},{"t":"продължавам изпреварването, за да премина преди пешеходците да са навлезли в лявата лента","ok":false,"i":null,"es":"continúo para pasar antes que los peatones entren en el carril izquierdo"},{"t":"продължавам изпреварването, като предупреждавам пешеходците със звуков сигнал","ok":false,"i":null,"es":"continúo avisando a los peatones con el claxon"}],"es":"En esta situación:","explain":"ABANDONO EL ADELANTAMIENTO. Una sola correcta.\n\nQUÉ VES. Calle urbana. Llevas el intermitente IZQUIERDO y estás adelantando a un coche AZUL. Delante hay un PASO DE PEATONES y dos personas están cruzando.\n\nANTES DE UN PASO DE PEATONES NO SE ADELANTA. Está prohibido adelantar sobre el paso de peatones e inmediatamente antes de él: el vehículo al que adelantas puede estar tapándote a alguien que cruza. Con peatones ya cruzando, lo único correcto es renunciar a la maniobra y volver detrás del azul.\n\n«CONTINÚO PARA PASAR ANTES DE QUE LOS PEATONES LLEGUEN AL CARRIL IZQUIERDO» es el cebo de la carrera contra el peatón.\n\n«CONTINÚO AVISANDO CON EL CLAXON» es el otro cebo: el claxon no da preferencia sobre los peatones.\n\nCLAVE: peatones en el paso = se cancela el adelantamiento. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6425,"bg":"При изпреварване се преминава от лявата страна на изпреварваното ППС:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"CORRECTO"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"es":"Al adelantar se pasa por el lado IZQUIERDO del vehículo adelantado. Esto es:","explain":"CORRECTO — el adelantamiento siempre se hace por la izquierda (en tráfico de la derecha). Excepción: solo se puede adelantar por la derecha en casos muy específicos."},{"id":6426,"bg":"При изпреварване водачът на изпреварваното ППС длъжен ли е да не увеличава скоростта?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"Al adelantar, ¿está obligado el conductor del vehículo adelantado a no aumentar la velocidad?","explain":"SÍ — cuando te están adelantando, estás prohibido de aumentar la velocidad. Hacerlo dificulta o impide el adelantamiento y es una infracción."},{"id":6427,"bg":"Водачът на изпреварваното ППС е длъжен :","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да не увеличава скоростта","ok":true,"i":null,"es":"no aumentar la velocidad"},{"t":"да не пречи на изпреварването","ok":true,"i":null,"es":"no obstaculizar el adelantamiento"},{"t":"да намали скоростта","ok":false,"i":null,"es":"reducir la velocidad"},{"t":"да премине плътно вдясно","ok":false,"i":null,"es":"desplazarse totalmente a la derecha"}],"es":"El conductor del vehículo adelantado está obligado a: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: no acelerar + no obstaculizar. NO está obligado a reducir velocidad ni a pegarse totalmente a la derecha — solo a no dificultar activamente el adelantamiento."},{"id":6428,"bg":"При изпреварване задължението за осигуряване на достатъчно странично разстояние е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на водача на изпреварващото ППС","ok":true,"i":null,"es":"del conductor del vehículo ADELANTANTE"},{"t":"на водача на изпреварваното ППС","ok":false,"i":null,"es":"del conductor del vehículo ADELANTADO"},{"t":"на двамата водачи","ok":false,"i":null,"es":"de ambos conductores"}],"es":"La obligación de garantizar distancia lateral suficiente al adelantar es:","explain":"⚠️ TRAMPA: responsabilidad exclusiva del que ADELANTA. El vehículo adelantado no tiene obligación de proporcionar espacio — la responsabilidad es completamente del adelantante."},{"id":6429,"bg":"Водач, който ще предприеме изпреварване, преди да подаде сигнал е длъжен да се убеди, че:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не го изпреварва друго пътно превозно средство","ok":true,"i":null,"es":"nadie le está adelantando a él"},{"t":"движещото се след него ППС не е подало сигнал за изменение на посоката си на движение наляво","ok":true,"i":null,"es":"el de detrás no señalizó un cambio de dirección"},{"t":"ППС, което ще изпреварва, не е подало сигнал за изменение на посоката си на движение наляво","ok":true,"i":null,"es":"el vehículo a adelantar no señalizó un cambio"},{"t":"че водачите от насрещното движение ще спрат за да го пропуснат","ok":false,"i":null,"es":"los del tráfico contrario van a parar para dejarle"}],"es":"Antes de señalizar para adelantar, el conductor debe asegurarse de que: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: nadie le adelanta + el de detrás no maniobra + el de delante no maniobra. El tráfico contrario NO va a parar — esa idea es completamente incorrecta."},{"id":6430,"bg":"Водач, който ще предприеме изпреварване, след като подаде сигнал е длъжен да се убеди, че:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"има видимост на достатъчно разстояние","ok":true,"i":null,"es":"hay visibilidad suficiente"},{"t":"има свободен път на разстояние, достатъчно за изпреварване","ok":true,"i":null,"es":"hay espacio libre suficiente para adelantar"},{"t":"няма да принуждава изпреварваното ППС да намалява скоростта или да изменя посоката на движение","ok":true,"i":null,"es":"no obligará al adelantado a reducir o cambiar de trayectoria"},{"t":"че водачът на изпреварвания автомобил е започнал да намалява скоростта на движение","ok":false,"i":null,"es":"el adelantado ya ha empezado a reducir velocidad"}],"es":"Después de señalizar para adelantar, el conductor debe asegurarse de que: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: visibilidad + espacio libre + no forzar al otro. El estado de la velocidad del adelantado no es un requisito para iniciar el adelantamiento."},{"id":6431,"bg":"Водач, който ще предприеме изпреварване, след като подаде сигнал е длъжен да се убеди, че:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"има свободен път на разстояние, достатъчно за изпреварване","ok":true,"i":null,"es":"hay vía libre a distancia suficiente para adelantar"},{"t":"може да заеме място в пътната лента пред изпреварваното пътно превозно средство","ok":true,"i":null,"es":"puede ocupar el carril delante del vehículo adelantado"},{"t":"няма да принуждава изпреварваното ППС да намалява скоростта или да изменя посоката на движение","ok":true,"i":null,"es":"no obliga al vehículo adelantado a reducir velocidad ni cambiar de trayectoria"},{"t":"че водачът на изпреварвания автомобил е превключил на по-ниска предавка","ok":false,"i":null,"es":"el conductor adelantado ha puesto una marcha inferior"}],"es":"El conductor que va a adelantar, después de señalizar, debe asegurarse de que: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: antes de adelantar verifica: distancia libre suficiente + puedes reincorporarte delante + no fuerzas al otro a frenar o desviarse. La marcha que usa el otro no es tu responsabilidad."},{"id":6433,"bg":"Водач, който изпреварва, е длъжен:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да осигури достатъчно странично разстояние между своето и изпреварваното ППС","ok":true,"i":null,"es":"garantizar distancia lateral suficiente entre su vehículo y el adelantado"},{"t":"когато навлиза в лента за насрещното движение, да не създава опасност за превозните средства, движещи се по нея","ok":true,"i":null,"es":"al invadir el carril contrario, no crear peligro para los vehículos de frente"},{"t":"да се убеди, че с безопасна скорост, може да извърши изпреварването за кратко време","ok":true,"i":null,"es":"asegurarse de que a velocidad segura puede completar el adelantamiento rápidamente"},{"t":"да се движи в непосредствена близост до изпреварваното превозно средство","ok":false,"i":null,"es":"circular muy próximo al vehículo adelantado"}],"es":"El conductor que adelanta está obligado a: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: al adelantar debes: mantener distancia lateral + no poner en peligro el tráfico contrario + poder completar el adelantamiento a velocidad segura. Circular muy próximo es incorrecto y peligroso."},{"id":6434,"bg":"Как ще постъпите при тази ситуация, когато автомобилът зад вас е подал сигнал за отклонение вляво?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124384.png","v":null,"a":[{"t":"намалявам скоростта и пропускам автомобила зад мен","ok":true,"i":null,"es":"reduzco velocidad y dejo pasar al coche de detrás"},{"t":"подавам сигнал и заобикалям повредения автомобил, преди автомобила, който се движи зад мен","ok":false,"i":null,"es":"señalizo y rodeo el coche averiado antes que el de detrás"}],"es":"¿Cómo actuarás en esta situación cuando el coche detrás señaliza desplazarse a la izquierda?","explain":"Reduces velocidad y dejas pasar al de detrás — él ya ha señalizado que va a adelantar. Adelantarte tú cuando él ya señalizó crearía un peligro real."},{"id":6436,"bg":"Разрешено ли е изпреварването при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128556.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Está permitido adelantar en esta situación?","explain":"SÍ.\n\nQUÉ VES. Calle de doble sentido. Llevas el intermitente IZQUIERDO para adelantar a un coche AZUL. A la derecha hay una señal TRIANGULAR de peligro, ESTRECHAMIENTO de la calzada, con una placa debajo que indica la distancia hasta él (300 m). No hay línea continua ni señal de prohibido adelantar.\n\nUN TRIÁNGULO NO PROHÍBE. Es una señal de PELIGRO: avisa de lo que viene y te pide atención. Las prohibiciones son círculos rojos, y aquí no hay ninguno.\n\nLA PLACA TAMPOCO PROHÍBE: solo indica a qué distancia está el peligro. Tienes margen para adelantar y volver a tu carril antes del estrechamiento, siempre que se cumplan las condiciones normales de un adelantamiento.\n\n«NO» es el cebo de quien convierte el aviso en prohibición.\n\nCLAVE: triángulo = aviso; círculo rojo = prohibición.\n\nMÉTODO: 1) ¿qué forma tiene la señal? 2) ¿hay línea continua o señal de prohibido adelantar? 3) si no, se puede adelantar con las precauciones habituales. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo» y «Adelantar y colocarse antes de una maniobra»."},{"id":6437,"bg":"Разрешено ли е да предприемете изпреварване при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124482.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Está permitido adelantar en esta situación?","explain":"SÍ.\n\nQUÉ VES. Carretera fuera de población con línea central discontinua. Delante va un coche AZUL. A la derecha, una señal azul informativa con la palabra «ПОЛИЦИЯ / POLICE». En el retrovisor se ve un coche rojo detrás.\n\nLA SEÑAL DE POLICÍA SOLO INFORMA de que hay un puesto policial cerca. No prohíbe adelantar ni obliga a nada.\n\n«NO» es el cebo de quien se cohíbe al ver la palabra «policía».\n\nCLAVE: señal informativa (rectangular azul) = información, no prohibición. Si la línea es discontinua y hay visibilidad, puedes adelantar con las precauciones normales. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6439,"bg":"Разрешено ли е да продължите изпреварването при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124449.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Está permitido continuar el adelantamiento en esta situación?","explain":"SÍ.\n\nQUÉ VES. Carretera fuera de población. Estás adelantando a un coche AZUL (intermitente izquierdo). A la derecha, una señal TRIANGULAR de OBRAS (trabajador con pala). Las máquinas están trabajando en el campo, fuera de la calzada.\n\nUN TRIÁNGULO AVISA, NO PROHÍBE. La señal de obras te pide atención, pero no prohíbe adelantar. Las máquinas no ocupan la calzada y la línea es discontinua.\n\n«NO» es el cebo de quien convierte cualquier señal de peligro en una prohibición.\n\nCLAVE: triángulo = aviso; círculo rojo = prohibición. Compárala con la 6436. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6442,"bg":"Длъжни ли сте при тази ситуация да сигнализирате с ляв пътепоказател, че започвате изпреварването?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124581.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Está obligado a señalizar con el intermitente izquierdo al iniciar el adelantamiento?","explain":"SÍ.\n\nQUÉ VES. Calle de SENTIDO ÚNICO (señal cuadrada azul con flecha blanca hacia arriba) con dos carriles. Delante va un coche ROJO al que quieres adelantar.\n\nEL INTERMITENTE ES OBLIGATORIO SIEMPRE QUE CAMBIAS DE CARRIL. Aunque sea una calle de sentido único y no venga nadie de frente, al desplazarte a la izquierda para adelantar tienes que avisar con el intermitente izquierdo.\n\n«NO» es el cebo de quien piensa que el intermitente solo hace falta cuando hay tráfico de frente.\n\nCLAVE: cada cambio de carril se señaliza, haya o no alguien. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6443,"bg":"Разрешено ли е да предприемете изпреварване при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124548.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"¿Está permitido adelantar en esta situación?","explain":"NO.\n\nQUÉ VES. Un pórtico con semáforos de carril: sobre el carril IZQUIERDO hay un ASPA ROJA y sobre los otros dos, FLECHAS VERDES. Llevas el intermitente IZQUIERDO y la flecha muestra que quieres pasar al carril izquierdo para adelantar a un coche ROJO.\n\nEL CARRIL IZQUIERDO ESTÁ CERRADO. No puedes entrar en un carril con el aspa roja, tampoco para adelantar.\n\n«SÍ» es el cebo de quien solo mira al coche de delante y no al pórtico.\n\nCLAVE: aspa roja = carril cerrado para todo, incluido adelantar. Compárala con la 6432. Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":6447,"bg":"При тази ситуация разрешено ли е да преминете по трамвайните линии, за да изпреварите товарния автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128523.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"En esta situación ¿está permitido circular por las vías del tranvía para adelantar al camión?","explain":"NO — en esta situación específica las vías del tranvía no pueden usarse para adelantar (quizás por señal prohibitiva, presencia de tranvía o visibilidad)."},{"id":6448,"bg":"При тази ситуация разрешено ли е да заобиколите трамвая отляво за да не пречите на слизащите и качващите се пътници?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124301.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"En esta situación ¿está permitido rodear el tranvía por la izquierda para no molestar a los que bajan y suben?","explain":"NO.\n\nQUÉ VES. Un TRANVÍA está detenido en una parada SIN ISLETA: los viajeros bajan y suben cruzando la calzada entre el tranvía y la acera derecha. Llevas el intermitente IZQUIERDO y la flecha dibuja la idea de rodear el tranvía por la izquierda.\n\nPOR LA IZQUIERDA NO. Rodear el tranvía por la izquierda te mete en el lado de la vía contraria, donde no te esperan. Y cuando el tranvía está parado en una parada sin isleta y la gente cruza para subir o bajar, lo que tienes que hacer es DETENERTE y esperar a que terminen, no buscar un hueco por otro lado.\n\n«SÍ, PARA NO ESTORBAR A LOS VIAJEROS» es el cebo: la buena intención disfrazada. No estorbas esperando; estorbas (y pones en peligro) metiéndote donde no debes.\n\nCLAVE: tranvía parado + viajeros cruzando sin isleta = paro detrás y espero.\n\nMÉTODO: 1) ¿el tranvía está en una parada? 2) ¿hay isleta para los viajeros? 3) si no la hay y cruzan, me detengo."},{"id":6450,"bg":"Какво трябва да направи водачът на МПС когато видимостта при движение назад е ограничена?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да осигури човек, който да сигнализира за опасност","ok":true,"i":null,"es":"asegurar una persona que señalice el peligro"},{"t":"да отвори вратата и да гледа назад","ok":false,"i":null,"es":"abrir la puerta y mirar hacia atrás"},{"t":"да отвори страничното стъкло за да гледа назад","ok":false,"i":null,"es":"abrir la ventanilla lateral y mirar atrás"}],"es":"¿Qué debe hacer el conductor cuando la visibilidad al hacer marcha atrás es limitada?","explain":"Debe haber una persona que vigile y señalice. Abrir la puerta o la ventanilla no resuelve el problema de visibilidad — se necesita un observador físico en el exterior."},{"id":6451,"bg":"Движението назад при ограничена видимост е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"разрешено само ако е осигурено лице, което да сигнализира при поява на опасност","ok":true,"i":null,"es":"permitida solo si hay alguien que señalice el peligro"},{"t":"разрешено, ако има огледало за виждане назад","ok":false,"i":null,"es":"permitida si hay espejo retrovisor"},{"t":"забранено","ok":false,"i":null,"es":"prohibida"}],"es":"La marcha atrás con visibilidad limitada está:","explain":"Permitida SOLO con ayudante que vigile y señalice. No basta con el espejo retrovisor cuando la visibilidad es limitada — se necesita un observador físico."},{"id":6452,"bg":"Разрешено ли е движение назад при завиване в обратна посока на кръстовище?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"¿Está permitido ir marcha atrás al dar la vuelta en una intersección?","explain":"NO — el cambio de sentido se realiza siempre con maniobras hacia adelante (giro a la izquierda). La marcha atrás en intersecciones está prohibida."},{"id":6454,"bg":"Разрешено ли е движение назад при завиване в обратна посока на път извън кръстовище?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Está permitido ir marcha atrás para dar la vuelta en una vía fuera de intersección?","explain":"SÍ — fuera de intersecciones está permitido usar la marcha atrás como parte del cambio de sentido cuando no hay espacio suficiente para hacerlo hacia adelante."},{"id":6601,"bg":"При тази ситуация водачът на синия автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124334.png","v":null,"a":[{"t":"трябва да прекрати изпреварването","ok":true,"i":null,"es":"debe abandonar el adelantamiento"},{"t":"може да продължи изпреварването, като премине по трамвайната линия","ok":false,"i":null,"es":"puede continuar por las vías del tranvía"}],"es":"En esta situación el conductor del coche azul:","explain":"DEBE ABANDONAR EL ADELANTAMIENTO. Una sola correcta.\n\nQUÉ VES. El coche AZUL (en primer plano) lleva el intermitente IZQUIERDO y está adelantando a un coche ROJO. A la izquierda hay un TRANVÍA. Delante, junto a la señal de parada, varias PERSONAS cruzan la calzada hacia el tranvía.\n\nCON PEATONES CRUZANDO DELANTE, SE CANCELA EL ADELANTAMIENTO. El coche rojo te tapa a quien cruza, y la gente que va o viene del tranvía puede aparecer en cualquier punto.\n\n«PUEDE CONTINUAR POR LAS VÍAS DEL TRANVÍA» es el cebo: aunque las vías se puedan usar a veces, aquí hay un tranvía y peatones cruzando hacia él.\n\nCLAVE: peatones cruzando delante = no se adelanta. Compárala con la 6424. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6701,"bg":"При тази ситуация трябва да пропусна пешеходеца.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70051.png","v":null,"a":[{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":true,"i":null,"es":"CORRECTO"}],"es":"En esta situación debo ceder el paso al peatón. Esto es:","explain":"CORRECTO.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO y vas a girar a la izquierda (flecha). El semáforo da VERDE con flechas. En la calle a la que vas a entrar, un PEATÓN está cruzando.\n\nAL GIRAR, CEDES A LOS PEATONES QUE CRUZAN LA CALLE A LA QUE ENTRAS, también con el semáforo en verde.\n\n«INCORRECTO» es el cebo de quien cree que el verde le da paso libre.\n\nCLAVE: compárala con la 6265 (giro a la derecha) y la 6259 (sin semáforo). Ver Leyes → «Paso de peatones»."},{"id":6702,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70614.png","v":null,"a":[{"t":"да премина преди автомобила и пешеходеца","ok":false,"i":null,"es":"pasar antes que el coche y el peatón"},{"t":"да пропусна автомобила","ok":true,"i":null,"es":"ceder el paso al coche"},{"t":"да пропусна пешеходеца","ok":true,"i":null,"es":"ceder el paso al peatón"}],"es":"En esta situación debo: (2 correctas)","explain":"CEDER EL PASO AL COCHE Y CEDER EL PASO AL PEATÓN. Dos correctas.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO y vas a girar a la izquierda. El semáforo da VERDE (flechas). De frente viene un coche ROJO. En la calle a la que vas a entrar, una PEATONA está cruzando.\n\nAL COCHE, POR EL GIRO: el que gira a la izquierda cede al que viene de frente, también con el verde.\n\nAL PEATÓN, POR EL GIRO: al girar cedes a quien cruza la calle a la que entras.\n\n«PASAR ANTES QUE EL COCHE Y EL PEATÓN» es el cebo de quien solo mira el verde.\n\nCLAVE: verde + giro a la izquierda = cedes al de frente y al peatón. Ver Leyes → «Giro a la izquierda» y «Paso de peatones»."},{"id":6704,"bg":"Разрешено ли е да предприемете изпреварване при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71606.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"¿Está permitido adelantar en esta situación?","explain":"NO.\n\nQUÉ VES. Carretera fuera de población. Delante va un coche ROJO. A la derecha, la señal de PROHIBIDO ADELANTAR (borde rojo, coche rojo y coche negro).\n\nEL COCHE ROJO ES UN VEHÍCULO DE MOTOR, así que la señal te prohíbe adelantarlo.\n\n«SÍ» es el cebo de quien solo mira la línea discontinua: la señal manda sobre la pintura.\n\nCLAVE: compárala con la 6459: si señal y marca se contradicen, manda la señal. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6705,"bg":"Ако през нощта, при започване на изпреварване, водачът на превозното средство бъде заслепен, той трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да прекрати изпреварването и се върне в дясната лента","ok":true,"i":null,"es":"abandonar el adelantamiento y volver al carril derecho"},{"t":"да продължи изпреварването, като се приближи до изпреварваното превозно средство","ok":false,"i":null,"es":"continuar acercándose al vehículo adelantado"},{"t":"да продължи изпреварването, като включи дългите светлини","ok":false,"i":null,"es":"continuar con las largas activadas"},{"t":"да прекрати изпреварването, като спре незабавно в лентата в която се движи","ok":false,"i":null,"es":"abandonar y parar inmediatamente en su carril"}],"es":"Si de noche al iniciar el adelantamiento el conductor queda deslumbrado, debe:","explain":"Abandonar y volver al carril derecho — el deslumbramiento hace imposible completar el adelantamiento con seguridad. Volver al derecho es la única opción correcta."},{"id":9829,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270041864.png","v":null,"a":[{"t":"да пропусна пешеходеца","ok":true,"i":null,"es":"ceder el paso al peatón"},{"t":"да премина преди пешеходеца","ok":false,"i":null,"es":"pasar antes que el peatón"}],"es":"En esta situación debo:","explain":"CEDER EL PASO AL PEATÓN. Una sola correcta.\n\nQUÉ VES. Llevas el intermitente DERECHO y vas a girar a la derecha (flecha). En la calle a la que vas a entrar, un PEATÓN está cruzando.\n\nAL GIRAR, CEDES A LOS PEATONES QUE CRUZAN LA CALLE A LA QUE ENTRAS, haya o no paso pintado.\n\n«PASAR ANTES QUE EL PEATÓN» es el cebo de quien calcula que le da tiempo.\n\nCLAVE: es la misma regla que la 6254. Ver Leyes → «Paso de peatones»."},{"id":9831,"bg":"Разрешено ли е да изпреварите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270042809.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Está permitido adelantar en esta situación?","explain":"SÍ.\n\nQUÉ VES. Carretera fuera de población con línea discontinua. Delante va un coche ROJO. A la derecha, una señal TRIANGULAR de peligro con una VACA: posible presencia de ANIMALES en la vía. En el retrovisor se ve un coche azul lejos.\n\nUN TRIÁNGULO AVISA, NO PROHÍBE. La señal te pide atención por si aparecen animales, pero no prohíbe adelantar. Con línea discontinua y visibilidad, puedes hacerlo con las precauciones normales.\n\n«NO» es el cebo de quien convierte el aviso en prohibición.\n\nCLAVE: triángulo = aviso; círculo rojo = prohibición. Compárala con la 6436 y la 6439. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":11872,"bg":"След този пътен знак забраната да изпреварват се отнася за водачите на товарни автомобили с допустима максимална маса над:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123828545.png","v":null,"a":[{"t":"1,5 t","ok":false,"i":null,"es":"1.5 t"},{"t":"3,5 t","ok":true,"i":null,"es":"3.5 t"},{"t":"5,5 t","ok":false,"i":null,"es":"5.5 t"},{"t":"7,5 t","ok":false,"i":null,"es":"7.5 t"}],"es":"Después de esta señal la prohibición de adelantar para camiones aplica a los de MMA superior a:","explain":"3,5 t. Una sola correcta.\n\nLA SEÑAL. Círculo de borde ROJO con un CAMIÓN rojo y un coche negro: PROHIBIDO ADELANTAR PARA LOS CAMIONES.\n\nA QUIÉN AFECTA. A los camiones con masa máxima autorizada superior a 3,5 t. Los turismos y las furgonetas ligeras no están afectados por esta señal.\n\n«1,5 t», «5,5 t» y «7,5 t» son cifras inventadas para confundir.\n\nCLAVE: en las señales de camiones, la frontera es 3,5 t. Compárala con la 6401. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":11890,"bg":"Завиването в обратна посока на мост е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено, когато широчината на платното за движение е над 12 метра","ok":false,"i":null,"es":"permitido cuando la anchura supera 12 metros"},{"t":"разрешено, когато видимостта е над 50 метра","ok":false,"i":null,"es":"permitido con visibilidad superior a 50 metros"},{"t":"разрешено, без ограничение","ok":false,"i":null,"es":"permitido sin restricciones"}],"es":"El cambio de sentido en puente está:","explain":"PROHIBIDO — en puente el cambio de sentido está siempre prohibido, independientemente de la anchura o la visibilidad."},{"id":11997,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да продължа да намалявам скоростта","ok":true,"i":null,"es":"continúo reduciendo la velocidad"},{"t":"да премина в лявата лента","ok":false,"i":null,"es":"paso al carril izquierdo"},{"t":"да изчакам преди препятствието","ok":true,"i":null,"es":"espero antes del obstáculo"}],"es":"¿Cuál es la actuación correcta en esta situación? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: continúas reduciendo Y esperas antes del obstáculo. Cambiar al izquierdo podría crear un nuevo peligro."},{"id":11998,"bg":"Какво е правилното действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"прекратявам изпреварването и се връщам в дясната лента","ok":true,"i":null,"es":"abandono el adelantamiento y vuelvo al carril derecho"},{"t":"продължавам изпреварването с непроменена скорост","ok":false,"i":null,"es":"continúo el adelantamiento sin cambiar velocidad"},{"t":"увеличавам скоростта си и продължавам изпреварването","ok":false,"i":null,"es":"acelero y completo el adelantamiento"}],"es":"¿Cuál es la actuación correcta?","explain":"Abandono y vuelvo — si durante el adelantamiento surge una situación de peligro, la única respuesta correcta es abortar y volver al carril derecho. Nunca aceleres para completarlo."},{"id":12005,"bg":"На кои участници в движението трябва да осигурите предимство преди да завиете надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на велосипедиста","ok":true,"i":null,"es":"al ciclista"},{"t":"на водача на черния автомобил","ok":false,"i":null,"es":"al conductor del coche negro"},{"t":"на пешеходеца","ok":true,"i":null,"es":"al peatón"}],"es":"¿A qué participantes debes ceder el paso antes de girar a la derecha? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: al girar a la derecha cedes al ciclista Y al peatón que cruzan la vía a la que entras. El coche negro no tiene prioridad sobre ti en esta maniobra."},{"id":12007,"bg":"При тази ситуация управлявате с готовност за спиране заради:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"товарния автомобил","ok":true,"i":null,"es":"el camión"},{"t":"мотоциклетиста","ok":false,"i":null,"es":"el motorista"}],"es":"En esta situación debes circular listo para frenar por:","explain":"El CAMIÓN — es el elemento de mayor riesgo en esta situación (más lento, más ancho, puede frenar imprevistamente o derramar carga)."},{"id":12008,"bg":"При тази ситуация не трябва да предприема изпреварване, поради?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"състоянието на пътната настилка","ok":false,"i":null,"es":"el estado del pavimento"},{"t":"ограничената видимост","ok":true,"i":null,"es":"la visibilidad limitada"},{"t":"наличието на превозни средства от насрещното движение","ok":true,"i":null,"es":"la presencia de vehículos en sentido contrario"}],"es":"En esta situación no debo adelantar por: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: visibilidad limitada + vehículos en sentido contrario. El estado del pavimento no prohíbe el adelantamiento per se."},{"id":12009,"bg":"Преди да преминете през кръстовището трябва да имате готовност да спрете заради:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"автомобила със специално предназначение","ok":true,"i":null,"es":"el vehículo de emergencia"},{"t":"велосипедиста","ok":false,"i":null,"es":"el ciclista"},{"t":"състава от пътни превозни средства","ok":true,"i":null,"es":"el convoy de vehículos"}],"es":"Antes de pasar la intersección debes estar listo para frenar por: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el vehículo de emergencia (prioridad absoluta) Y el convoy (más lento, puede frenar inesperadamente). El ciclista ya está en la vía y no presenta el mismo riesgo súbito."},{"id":12011,"bg":"При тази ситуация трябва да осигурите предимство на:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трамвая","ok":true,"i":null,"es":"el tranvía"},{"t":"белия автомобил","ok":false,"i":null,"es":"el coche blanco"},{"t":"велосипедиста","ok":false,"i":null,"es":"el ciclista"}],"es":"En esta situación debes ceder el paso a:","explain":"Al TRANVÍA — tiene prioridad sobre todos los vehículos de motor. El coche blanco y el ciclista no tienen prioridad especial en esta situación."},{"id":12032,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"изпреварвам велосипедиста преди той да заобиколи товарния автомобил","ok":false,"i":null,"es":"adelanto al ciclista antes de que rodee el camión"},{"t":"изпреварвам велосипедиста, след като той премине през завоя","ok":true,"i":null,"es":"adelanto al ciclista DESPUÉS de que pase el giro"},{"t":"изпреварвам велосипедиста веднага, след като заобиколи товарния автомобил (преди да премине през завоя)","ok":false,"i":null,"es":"adelanto al ciclista justo al salir del giro"}],"es":"¿Cuál es la actuación correcta en esta situación?","explain":"DESPUÉS de que complete el giro — el ciclista rodeando un camión es imprevisible. Esperas hasta que termine completamente la maniobra para adelantar con seguridad."},{"id":12033,"bg":"При тази ситуация кое действие на водача на автомобила от насрещното движение трябва да предвидите?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да изпревари велосипедиста без да навлиза във вашата лента","ok":false,"i":null,"es":"adelantará al ciclista sin invadir tu carril"},{"t":"да изчака велосипедистът да се размине с автомобилите от насрещното движение","ok":false,"i":null,"es":"esperará al ciclista"},{"t":"да изпревари велосипедиста, като навлезе частично в лентата за насрещно движение","ok":true,"i":null,"es":"adelantará al ciclista invadiendo parcialmente tu carril"}],"es":"¿Qué acción del conductor contrario debes anticipar?","explain":"Adelantará invadiendo tu carril — el conductor contrario probablemente intentará adelantar al ciclista y para hacerlo necesitará invadir parcialmente tu carril. Anticípalo reduciendo velocidad."},{"id":12034,"bg":"При тази ситуация трябва да предвидите, че товарният автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"ще остане в дясната лента","ok":false,"i":null,"es":"permanecerá en el carril derecho"},{"t":"ще навлезе още повече в съседната лява лента","ok":true,"i":null,"es":"invadirá aún más el carril izquierdo adyacente"},{"t":"ще спре","ok":true,"i":null,"es":"parará"}],"es":"En esta situación debes anticipar que el camión: (2 correctas)","explain":"⚠️ TRAMPA: invadirá MÁS el carril izquierdo (en curva los camiones necesitan más espacio) Y también podría parar (obstáculo). No esperarás que se quede en su carril."},{"id":12035,"bg":"Защо трябва да спрете при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"заради велосипедиста","ok":true,"i":null,"es":"por el ciclista"},{"t":"заради зеленият автомобил","ok":false,"i":null,"es":"por el coche verde"},{"t":"заради пешеходеца","ok":false,"i":null,"es":"por el peatón"}],"es":"¿Por qué debes parar en esta situación?","explain":"Por el CICLISTA — tiene prioridad de paso en esta intersección o paso específico."},{"id":12036,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"продължавам движението си, без да променям скоростта си","ok":false,"i":null,"es":"continúo sin cambiar velocidad"},{"t":"продължавам движението си в лентата за паркиране","ok":false,"i":null,"es":"continúo por el carril de estacionamiento"},{"t":"продължавам движението си, като увеличавам скоростта си","ok":false,"i":null,"es":"acelero"},{"t":"намалявам скоростта си","ok":true,"i":null,"es":"reduzco la velocidad"}],"es":"¿Cuál es la actuación correcta en esta situación? (VIDEO)","explain":"🎬 VIDEO: reduce velocidad. Sea cual sea el obstáculo o situación mostrada, la reducción de velocidad es siempre la respuesta correcta ante la incertidumbre."},{"id":12037,"bg":"При тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"намалявам скоростта си, за да може изпреварващото превозно средство да се прибере пред мен","ok":true,"i":null,"es":"reduzco para que el adelantante pueda reincorporarse"},{"t":"ускорявам, за да може изпреварващото превозно средство да премине в дясната лента зад мен","ok":false,"i":null,"es":"acelero para que pueda pasar al derecho"},{"t":"поддържам скоростта си, защото има достатъчно безопасно разстояние","ok":false,"i":null,"es":"mantengo la velocidad porque hay distancia suficiente"}],"es":"En esta situación:","explain":"Reduzco — cuando un vehículo te está adelantando y necesita espacio para reincorporarse, reducir levemente facilita y acelera la maniobra de forma segura."},{"id":12038,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да остана в средата на заеманата лента","ok":false,"i":null,"es":"me quedo en el centro del carril"},{"t":"да намаля скоростта","ok":true,"i":null,"es":"reduzco la velocidad"},{"t":"да премина възможно най-вдясно","ok":true,"i":null,"es":"me desplazo todo lo posible a la derecha"}],"es":"¿Cuál es la actuación correcta en esta situación? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: reduces + vas a la derecha. Quedarse en el centro del carril no facilita el paso seguro del vehículo de emergencia o del obstáculo."},{"id":12039,"bg":"Какъв е правилният начин на действие?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"продължавам изпреварването","ok":true,"i":null,"es":"continúo el adelantamiento"},{"t":"прекратявам изпреварването и се връщам в дясната лента","ok":false,"i":null,"es":"abandono y vuelvo al carril derecho"},{"t":"намалявам скоростта, но продължавам изпреварването","ok":false,"i":null,"es":"reduzco pero continúo"}],"es":"¿Cuál es la actuación correcta?","explain":"CONTINÚO el adelantamiento — la situación mostrada (espacio libre, visibilidad suficiente) permite completar el adelantamiento con seguridad."},{"id":12040,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да подам сигнал с превключване на дългите светлини","ok":false,"i":null,"es":"señalizo con las largas"},{"t":"да продължа без да променям скоростта, като се движа възможно най-вдясно","ok":false,"i":null,"es":"continúo sin cambiar velocidad, todo a la derecha"},{"t":"да намаля скоростта своевременно","ok":true,"i":null,"es":"reduzco la velocidad a tiempo"}],"es":"¿Cuál es la actuación correcta en esta situación?","explain":"Reduzco a tiempo — la situación mostrada (obstáculo, curva, vehículo que surge) requiere reducir la velocidad anticipadamente, antes de que sea demasiado tarde."},{"id":12041,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да увелича скоростта","ok":false,"i":null,"es":"aumentar la velocidad"},{"t":"да се движа възможно най-вдясно","ok":true,"i":null,"es":"circular todo lo posible a la DERECHA"},{"t":"да намаля скоростта","ok":true,"i":null,"es":"reducir la velocidad"}],"es":"¿Qué debes hacer en esta situación? (2 correctas)","explain":"⚠️ TRAMPA: circula a la derecha Y reduce velocidad. Acelerar nunca es la respuesta ante una situación de peligro o incertidumbre."},{"id":12042,"bg":"Защо трябва да прекратите изпреварването?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"защото тракторът е подал сигнал за завой наляво","ok":true,"i":null,"es":"el tractor señalizó girar a la izquierda"},{"t":"защото в този участък изпреварването е забранено","ok":false,"i":null,"es":"en este tramo el adelantamiento está prohibido"},{"t":"защото в лентата за насрещно движение приближава автомобил","ok":true,"i":null,"es":"en el carril contrario se aproxima un vehículo"}],"es":"¿Por qué debes abandonar el adelantamiento? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el tractor gira a la izquierda (cruzará tu trayectoria) + viene un vehículo de frente. Ambos hacen el adelantamiento imposible. La señal prohibitiva no es el motivo aquí."},{"id":12043,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"изпреварвам трактора, защото свободното разстояние пред него е достатъчно за изпреварване","ok":false,"i":null,"es":"adelanto al tractor porque hay espacio delante de él"},{"t":"изпреварвам внимателно, защото тракторът ми сигнализира за това","ok":false,"i":null,"es":"adelanto con cuidado porque el tractor me señaliza para ello"},{"t":"не предприемам изпреварване, защото тракторът иска да премине наляво","ok":true,"i":null,"es":"no adelanto porque el tractor quiere girar a la izquierda"}],"es":"¿Cuál es la actuación correcta?","explain":"NO adelanto — el tractor señaliza que va a girar a la izquierda, cruzando exactamente donde tú querías adelantar. Esperas a que complete su maniobra."},{"id":12044,"bg":"Позволено ли е да предприемете изпреварване при тази ситуация сега?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не, защото видимостта е ограничена","ok":true,"i":null,"es":"no, porque la visibilidad es limitada"},{"t":"да, защото при разминаването с велосипеда и мотоциклета мога да осигуря достатъчно странично разстояние","ok":false,"i":null,"es":"sí, con distancia para el ciclista y la moto"},{"t":"не, защото в лентата за насрещно движение има превозно средство","ok":true,"i":null,"es":"no, porque hay un vehículo en el carril contrario"}],"es":"¿Está permitido adelantar ahora en esta situación? (2 correctas son PROHIBICIONES)","explain":"⚠️ MULTIRESPUESTA: dos razones para NO adelantar — visibilidad limitada + vehículo en sentido contrario. Aunque hubiera distancia para los vehículos lentos, estas dos condiciones prohíben el adelantamiento."},{"id":12045,"bg":"Какъв е правилният начин на действие в тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да намаля скоростта","ok":true,"i":null,"es":"reduzco la velocidad"},{"t":"да увелича скоростта си","ok":false,"i":null,"es":"aumento la velocidad"},{"t":"да продължа движението си, без да променям скоростта","ok":false,"i":null,"es":"continúo sin cambiar velocidad"}],"es":"¿Cuál es la actuación correcta?","explain":"Reduzco — ante cualquier situación de incertidumbre o peligro, la respuesta siempre es reducir la velocidad. Nunca acelerar."},{"id":12046,"bg":"Какво трябва да направите в тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"продължавам движението си в заеманата лента","ok":true,"i":null,"es":"continúo en mi carril"},{"t":"отклонявам се наляво","ok":false,"i":null,"es":"me desvío a la izquierda"},{"t":"рязко намалявам скоростта/аварийно спиране","ok":true,"i":null,"es":"freno de emergencia/reduzco bruscamente"}],"es":"¿Qué debes hacer en esta situación? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: te quedas en tu carril (no te desvías hacia el peligro) Y frenas de emergencia. Desviarse a la izquierda podría crear un accidente con el tráfico contrario."},{"id":12047,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да намаля скоростта и да продължа движението си в заеманата лента","ok":true,"i":null,"es":"reduzco y continúo en mi carril"},{"t":"да премина в лявата лента","ok":false,"i":null,"es":"paso al carril izquierdo"},{"t":"продължавам движението си в заеманата лента, без да намалявам скоростта","ok":false,"i":null,"es":"continúo sin reducir"}],"es":"¿Qué debes hacer en esta situación?","explain":"Reduzco y continúo en mi carril — la combinación de reducir velocidad y mantenerse en el carril correcto es la respuesta más segura ante obstáculos laterales."},{"id":12048,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir la velocidad"},{"t":"трябва да включа аварийните светлини","ok":true,"i":null,"es":"debo activar las luces de emergencia"},{"t":"продължавам движението си в свободната лента","ok":false,"i":null,"es":"continúo por el carril libre"}],"es":"¿Qué debes hacer en esta situación? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: reduces + activas las luces de emergencia. La situación (retención, obstáculo repentino) requiere avisar a los que vienen detrás. No cambias de carril sin verificar."},{"id":12049,"bg":"При тази ситуация трябва да намалите скоростта си заради:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"ограничението на скоростта","ok":false,"i":null,"es":"la señal de velocidad"},{"t":"жълтия автомобил","ok":false,"i":null,"es":"el coche amarillo"},{"t":"синия автомобил","ok":true,"i":null,"es":"el coche azul"}],"es":"En esta situación debes reducir la velocidad por:","explain":"Por el coche AZUL — es el elemento de mayor riesgo inmediato en esta situación (puede frenar, cambiar de carril, etc.). La señal de velocidad ya la cumplías y el amarillo no presenta el riesgo inmediato."},{"id":12050,"bg":"При тази ситуация не трябва да предприемате изпреварване заради:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"превозните средства от насрещното движение","ok":true,"i":null,"es":"los vehículos del tráfico contrario"},{"t":"завоя на пътя","ok":true,"i":null,"es":"la curva de la vía"},{"t":"състоянието на пътната настилка","ok":false,"i":null,"es":"el estado del pavimento"}],"es":"En esta situación no debes adelantar por: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: tráfico contrario + curva. El estado del pavimento no prohíbe el adelantamiento per se."},{"id":12051,"bg":"Искате да изпреварите. При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"изпреварвам трите превозни средства, които се движат пред мен, наведнъж (с една маневра)","ok":false,"i":null,"es":"adelanto los tres vehículos de una vez"},{"t":"не предприемам изпреварване, преди да се убедя, че водачът на синия автомобил няма да изпреварва","ok":true,"i":null,"es":"no adelanto hasta confirmar que el coche azul no va a adelantar"},{"t":"когато синият автомобил започне изпреварването, изпреварвам, като се движа зад него","ok":false,"i":null,"es":"cuando el azul empiece a adelantar, me pongo detrás de él"}],"es":"Quiere adelantar. En esta situación: (VIDEO)","explain":"🎬 VIDEO: NO adelantes hasta confirmar que el azul no va a hacer lo mismo. Adelantar por encima de otro que ya adelanta es una maniobra peligrosísima."},{"id":12052,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"продължавам движението си, без да променям скоростта","ok":false,"i":null,"es":"continúo sin cambiar velocidad"},{"t":"преминавам в дясната лента","ok":false,"i":null,"es":"paso al carril derecho"},{"t":"намалявам скоростта си","ok":true,"i":null,"es":"reduzco la velocidad"}],"es":"¿Cuál es la actuación correcta?","explain":"Reduzco — la situación mostrada requiere reducir la velocidad por la presencia de un obstáculo, ciclista u otro elemento de riesgo."},{"id":5330,"bg":"При приближаване към кръстовище водачът трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"своевременно да прецени как се определя реда за преминаване през кръстовището","ok":true,"i":null,"es":"evaluar a tiempo cómo se determina el orden de paso"},{"t":"своевременно да заеме пътна лента, която е предназначена за неговата посока на движение","ok":true,"i":null,"es":"ocupar a tiempo el carril correspondiente a su dirección"},{"t":"да има готовност за намаляване на скоростта","ok":true,"i":null,"es":"estar listo para reducir velocidad"},{"t":"да увеличи скоростта за да премине по-бързо през кръстовището","ok":false,"i":null,"es":"acelerar para pasar más rápido"}],"es":"Al aproximarse a una intersección el conductor debe: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: antes de una intersección debes: evaluar las prioridades + colocarte en el carril correcto + estar listo para frenar. Nunca aceleras en una intersección."},{"id":5878,"bg":"В кой от изброените случаи при този сигнал на светофара е забранено да навлезете в кръстовището?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/102946.png","v":null,"a":[{"t":"когато ще се наложи да остана в кръстовището поради задръстване","ok":true,"i":null,"es":"cuando voy a quedarme dentro por un atasco"},{"t":"когато на платното за движение има стоп-линия","ok":false,"i":null,"es":"cuando hay línea de stop en la calzada"},{"t":"когато на кръстовището са поставени пътни знаци относно предимството","ok":false,"i":null,"es":"cuando hay señales de prioridad en la intersección"}],"es":"¿En qué caso con semáforo verde está PROHIBIDO entrar en la intersección?","explain":"CUANDO VOY A QUEDARME DENTRO DEL CRUCE POR UN ATASCO. Una sola correcta.\n\nQUÉ VES. Un cruce regulado con SEMÁFORO en VERDE. Encima del semáforo hay una señal de ceda el paso, y en los demás accesos hay otras señales de prioridad.\n\nEL VERDE NO TE DEJA BLOQUEAR EL CRUCE. Aunque tengas verde, está prohibido entrar si, por el tráfico de delante, vas a quedarte parado dentro del cruce. Bloquearías a los que reciban el verde después.\n\n«CUANDO HAY LÍNEA DE STOP» es el cebo: la línea de detención marca dónde parar si el semáforo está en rojo, pero con verde no te impide pasar.\n\n«CUANDO HAY SEÑALES DE PRIORIDAD» es el cebo del método: con el semáforo funcionando, las señales de prioridad que haya en el cruce quedan en segundo plano. Manda el semáforo.\n\nCLAVE: verde + atasco al otro lado = esperas fuera del cruce.\n\nMÉTODO: 1) ¿qué me dice el semáforo? 2) ¿hay sitio al otro lado para salir del cruce? 3) si no, no entro. Ver Leyes → «Quién manda sobre quién»."},{"id":5884,"bg":"При този сигнал на светофара навлизането в кръстовището е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/102995.png","v":null,"a":[{"t":"разрешено, освен когато водачът може да остане в кръстовището поради задръстване","ok":true,"i":null,"es":"permitido, excepto si quedaras bloqueado dentro por retención"},{"t":"разрешено без ограничения","ok":false,"i":null,"es":"permitido sin restricciones"},{"t":"забранено","ok":false,"i":null,"es":"prohibido"}],"es":"Con esta señal del semáforo entrar en la intersección está:","explain":"Verde = permitido, PERO no puedes entrar si al otro lado hay retención y vas a quedarte bloqueado en la intersección. El semáforo verde no es carta blanca para bloquear el cruce."},{"id":5887,"bg":"Ще извърши ли нарушение водачът, ако при тази ситуация завие в обратна посока?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48171.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Cometerá infracción el conductor si da la vuelta en esta situación?","explain":"SÍ — la situación mostrada (curva, cima, visibilidad limitada, zona prohibida) hace que el cambio de sentido sea una infracción."},{"id":5890,"bg":"При тази ситуация разрешено ли е червеният автомобил да продължи движението си направо?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48188.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"En esta situación ¿está permitido al coche rojo continuar recto?","explain":"NO.\n\nQUÉ VES. Un cruce con semáforos y, arriba, señal de vía con prioridad. El coche ROJO está en el carril IZQUIERDO, que tiene pintada en el suelo una FLECHA hacia la IZQUIERDA. Encima de ese carril, el semáforo muestra una flecha verde a la izquierda; el carril derecho tiene flechas de recto y derecha.\n\nLA FLECHA DEL SUELO TE OBLIGA. Si entras en un carril marcado con una flecha de giro a la izquierda, tienes que girar a la izquierda. El rojo ha elegido ese carril: no puede seguir recto.\n\n«SÍ» es el cebo de quien solo mira el semáforo (verde) y olvida que el carril ya decide la dirección.\n\nCLAVE: el carril elegido manda la dirección; para seguir recto había que estar en el carril derecho.\n\nMÉTODO: 1) ¿qué flecha hay en el suelo de mi carril? 2) esa es la única dirección permitida desde ahí. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":5894,"bg":"При тази ситуация разрешено ли е да завиете надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48207.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"En esta situación ¿está permitido girar a la derecha?","explain":"NO — hay una señal o condición que prohíbe girar a la derecha en esta situación específica (semáforo, señal prohibitiva, agente)."},{"id":5896,"bg":"При тази ситуация разрешено ли е да завиете надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48224.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"En esta situación ¿está permitido girar a la derecha?","explain":"NO.\n\nQUÉ VES. En el cruce hay un AGENTE de tráfico que te muestra su COSTADO con el brazo extendido. Delante de ti, un coche ROJO lleva el intermitente DERECHO. A la derecha hay una señal de PROHIBIDO GIRAR A LA DERECHA (círculo rojo con flecha a la derecha tachada).\n\nEL AGENTE MANDA SOBRE LA PRIORIDAD, NO SOBRE LAS PROHIBICIONES. Las señales del agente prevalecen sobre el semáforo y sobre las señales que regulan la prioridad (STOP, ceda el paso, rombo). Pero una señal de PROHIBICIÓN de giro sigue en vigor. El costado del agente te permitiría seguir recto o girar a la derecha, y la señal te prohíbe girar a la derecha: puedes seguir recto, no girar.\n\n«SÍ» es el cebo: pensar que el agente lo anula todo.\n\nCLAVE: el agente decide QUIÉN pasa, no te autoriza una dirección prohibida por una señal.\n\nMÉTODO: 1) ¿qué me permite el agente? 2) ¿hay alguna señal de prohibición? 3) me quedo con lo que permitan los dos. Ver Leyes → «Quién manda sobre quién»."},{"id":5916,"bg":"При тази ситуация разрешено ли е да завиете надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48258.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"es":"En esta situación ¿está permitido girar a la derecha?","explain":"NO.\n\nQUÉ VES. Llevas el intermitente DERECHO y quieres girar a la derecha (flecha). El semáforo está en VERDE, pero encima hay una señal circular AZUL con una flecha HACIA ARRIBA: DIRECCIÓN OBLIGATORIA RECTO.\n\nEL VERDE NO ANULA LA SEÑAL DE DIRECCIÓN OBLIGATORIA. El semáforo te deja pasar, pero solo en la dirección que permite la señal: recto. Girar a la derecha está prohibido.\n\n«SÍ» es el cebo de quien solo mira el verde.\n\nCLAVE: el semáforo decide CUÁNDO pasas; las señales de dirección obligatoria deciden HACIA DÓNDE.\n\nMÉTODO: 1) ¿qué dice el semáforo? 2) ¿hay señal de dirección obligatoria o de prohibición de giro? 3) solo puedo ir hacia donde lo permitan los dos. Ver Leyes → «Quién manda sobre quién»."},{"id":5924,"bg":"Редът за преминаване на автомобила и мотоциклета през това кръстовище се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48275.png","v":null,"a":[{"t":"с правилото за „предимството на дясностоящия”","ok":true,"i":null,"es":"la regla de prioridad a la derecha"},{"t":"в зависимост от посоката им на движение","ok":false,"i":null,"es":"la dirección en que van"},{"t":"в зависимост от категорията на превозните средства","ok":false,"i":null,"es":"la categoría del vehículo"}],"es":"El orden de paso del coche y la moto en esta intersección lo determina:","explain":"CON LA REGLA DE PRIORIDAD A LA DERECHA. Una sola correcta.\n\nQUÉ VES. Un cruce SIN agente, SIN semáforo y SIN señales. Un coche ROJO con el intermitente izquierdo va a girar a la izquierda. Por su IZQUIERDA llega una MOTO que sigue recto.\n\nSIN NADIE EN LOS ESCALONES SUPERIORES, DECIDE LA DERECHA. No hay agente, ni semáforo, ni señales: el orden de paso lo decide la regla de la derecha. Aquí la moto tiene al coche a su derecha, así que es la moto la que cede.\n\n«LA DIRECCIÓN EN QUE VAN» es el cebo: la dirección no decide el orden entre dos vehículos que llegan por vías distintas.\n\n«LA CATEGORÍA DEL VEHÍCULO» es el otro cebo: ser moto, camión o turismo no da ni quita prioridad (solo los vehículos de emergencia con sus señales encendidas tienen un régimen especial).\n\nCLAVE: la derecha manda solo cuando arriba no hay nadie, y manda igual para una moto que para un camión.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Regla de la derecha»."},{"id":5926,"bg":"Редът за преминаване на тези автомобили през кръстовището се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48294.png","v":null,"a":[{"t":"от пътните знаци относно предимството","ok":true,"i":null,"es":"las señales de prioridad"},{"t":"с правилото за „предимството на дясностоящия”","ok":false,"i":null,"es":"la regla de prioridad a la derecha"},{"t":"в зависимост от посоката на движение на автомобилите","ok":false,"i":null,"es":"la dirección de circulación"}],"es":"El orden de paso de estos vehículos en la intersección lo determinan:","explain":"LAS SEÑALES DE PRIORIDAD. Una sola correcta.\n\nQUÉ VES. Un cruce sin agente ni semáforo. En el poste de la derecha hay un ROMBO amarillo (vía con prioridad). En los otros accesos se ven señales de ceda el paso y otro rombo al fondo. De frente viene un coche VERDE y por la derecha llega una furgoneta AZUL.\n\nLAS SEÑALES DECIDEN. No hay agente ni semáforo, así que el primer escalón que aparece son las señales de prioridad: el rombo marca la vía preferente y los triángulos de ceda el paso marcan las secundarias. Ellas deciden el orden.\n\n«LA REGLA DE LA DERECHA» es el cebo, y es el error de método más repetido: saltar al último escalón sin mirar los anteriores. La derecha solo decide cuando ninguna señal separa a los implicados.\n\n«LA DIRECCIÓN DE CIRCULACIÓN» no determina el orden de paso en ningún caso.\n\nCLAVE: si hay señales de prioridad y nada por encima de ellas, deciden las señales.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Quién manda sobre quién» y «Vía con prioridad»."},{"id":5927,"bg":"При тази ситуация, при определяне на реда за преминаване през кръстовището, се прилагат следните правила:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48311.png","v":null,"a":[{"t":"ППС, които са на пътя с предимство, трябва да преминат преди ППС от другия път","ok":true,"i":null,"es":"los vehículos de la vía preferente pasan antes que los del otro camino"},{"t":"завиващите наляво ППС от пътя с предимство пропускат насрещнодвижещите се ППС","ok":true,"i":null,"es":"los que giran a la izquierda desde la preferente ceden a los de frente"},{"t":"ППС на пътя с предимство, помежду си прилагат правилото за „предимството на дясностоящия”","ok":false,"i":null,"es":"los de la preferente entre sí aplican la regla de la derecha"}],"es":"En esta situación con vía preferente se aplican las siguientes reglas: (2 correctas)","explain":"LOS DE LA VÍA PREFERENTE PASAN ANTES QUE LOS DEL OTRO CAMINO, Y LOS QUE GIRAN A LA IZQUIERDA DESDE LA PREFERENTE CEDEN A LOS DE FRENTE. Dos correctas.\n\nQUÉ VES. Tu acceso tiene un CEDA EL PASO SIN PANEL. El acceso de enfrente (por donde viene un coche VERDE) también tiene ceda el paso. Los accesos de la izquierda y la derecha tienen ROMBO: la vía preferente cruza recta de izquierda a derecha. Por la izquierda viene un coche AMARILLO que sigue recto; por la derecha, una furgoneta AZUL con el intermitente izquierdo que gira a la izquierda.\n\nPRIMERA REGLA: JERARQUÍA. Tú y el verde venís por la secundaria: cedéis a todos los que circulan por la preferente.\n\nSEGUNDA REGLA: ENTRE LOS DE LA PREFERENTE, EL QUE GIRA A LA IZQUIERDA CEDE AL DE FRENTE. El amarillo y el azul van por la preferente en sentidos contrarios. El azul gira a la izquierda y cruza la trayectoria del amarillo: cede él.\n\n«ENTRE LOS DE LA PREFERENTE, LA REGLA DE LA DERECHA» es el cebo: esa regla solo entra cuando la preferente CAMBIA DE DIRECCIÓN (hay panel). Aquí no hay panel: la preferente va recta y los suyos se encuentran de frente.\n\nCLAVE: sin panel, la preferente sigue recta y entre sus vehículos manda «el que gira a la izquierda cede». Con panel que tuerce, manda la derecha (compárala con la 5931).\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Vía con prioridad» y «Giro a la izquierda»."},{"id":5929,"bg":"При тази ситуация, при определяне на реда за преминаване през кръстовището, се прилагат следните правила:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48329.png","v":null,"a":[{"t":"ППС, на пътя с предимство, трябва да преминат преди ППС на другия път","ok":true,"i":null,"es":"los de la vía preferente pasan antes que los del otro camino"},{"t":"ППС на пътя с предимство, помежду си прилагат правилото за „предимството на дясностоящия”","ok":true,"i":null,"es":"entre sí los de la preferente aplican la regla de la derecha"},{"t":"завиващите наляво ППС от пътя с предимство пропускат насрещнодвижещите се ППС","ok":false,"i":null,"es":"los que giran a la izquierda desde la preferente ceden al tráfico contrario"}],"es":"En esta situación con vía preferente se aplican las siguientes reglas: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: preferentes pasan antes + entre ellos aplican la regla de la derecha. En esta variante los que giran a la izquierda NO ceden al contrario (diferencia respecto a la anterior)."},{"id":5931,"bg":"При тази ситуация при определяне на реда за преминаване през кръстовището се прилагат следните правила:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66850.png","v":null,"a":[{"t":"ППС на пътя с предимство, трябва да преминат преди ППС от другите пътища","ok":true,"i":null,"es":"los de la vía preferente pasan antes que los de otros caminos"},{"t":"ППС на пътя с предимство, помежду си прилагат правилото за „предимството на дясностоящия”","ok":true,"i":null,"es":"los de la preferente entre sí aplican la regla de la derecha"},{"t":"завиващите наляво ППС от пътя с предимство пропускат насрещнодвижещите се ППС","ok":false,"i":null,"es":"los que giran a la izquierda desde la preferente ceden al tráfico contrario"}],"es":"En esta situación con vía preferente se aplican las siguientes reglas: (2 correctas)","explain":"LOS DE LA VÍA PREFERENTE PASAN ANTES QUE LOS DE OTROS CAMINOS, Y ENTRE ELLOS APLICAN LA REGLA DE LA DERECHA. Dos correctas.\n\nQUÉ VES. A la derecha, señal de VÍA CON PRIORIDAD con PANEL: el trazo GRUESO sube desde abajo (el acceso del coche AMARILLO, que lleva el intermitente izquierdo) y gira a la IZQUIERDA, hacia donde está el coche ROJO. De frente viene un coche AZUL por un acceso con señal de ceda el paso.\n\nPRIMERA REGLA: JERARQUÍA. El azul viene por una rama fina: cede a los que van por la preferente (amarillo y rojo).\n\nSEGUNDA REGLA: ENTRE LOS DE LA PREFERENTE, LA DERECHA. El amarillo y el rojo están los dos en la rama gruesa. Como la vía con prioridad cambia de dirección, entre ellos vuelve a decidir la regla de la derecha.\n\n«LOS QUE GIRAN A LA IZQUIERDA DESDE LA PREFERENTE CEDEN AL TRÁFICO CONTRARIO» es el cebo: es una regla real cuando la preferente sigue recta, pero aquí la preferente tuerce y la regla que entra es la de la derecha.\n\nCLAVE: si la preferente TUERCE, entre los de la preferente decide la derecha.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":5935,"bg":"При тази ситуация при определяне на реда за преминаване през кръстовището се прилагат следните правила:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/103109.png","v":null,"a":[{"t":"през кръстовището преминават ППС, които имат разрешаващ сигнал от светофара","ok":true,"i":null,"es":"pasan los vehículos con semáforo en verde"},{"t":"завиващите наляво ППС на разрешаващ сигнал пропускат насрещнодвижещите","ok":true,"i":null,"es":"los que giran a la izquierda en verde ceden al tráfico de frente"},{"t":"ППС на разрешаващ сигнал, помежду си прилагат правилото за „предимството на дясностоящия”","ok":false,"i":null,"es":"los vehículos con verde entre sí aplican la regla de prioridad de la derecha"}],"es":"En esta situación, para determinar el orden de paso por la intersección se aplican las siguientes reglas: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: Con semáforo verde, pasan los que tienen verde Y quien gira a la izquierda cede al tráfico contrario. La regla de la derecha NO se aplica entre vehículos con semáforo — eso es incorrecto."},{"id":5938,"bg":"Редът за преминаване на тези автомобили през кръстовището се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48397.png","v":null,"a":[{"t":"от сигналите на регулировчика","ok":true,"i":null,"es":"las señales del agente regulador"},{"t":"с правилото за „предимството на дясностоящия”","ok":false,"i":null,"es":"la regla de la derecha"},{"t":"в зависимост от посоката на движение на автомобилите","ok":false,"i":null,"es":"la dirección de los vehículos"}],"es":"El orden de paso de estos vehículos en la intersección lo determinan:","explain":"LAS SEÑALES DEL AGENTE REGULADOR. Una sola correcta.\n\nQUÉ VES. Un cruce con un AGENTE en el centro. Por la izquierda llega un coche ROJO y desde abajo un coche AMARILLO con el intermitente puesto. No hay semáforo.\n\nSI HAY AGENTE, MANDA EL AGENTE. Está por encima del semáforo, de las señales y de la regla de la derecha. El orden de paso lo deciden sus gestos.\n\n«LA REGLA DE LA DERECHA» es el cebo: solo decide cuando no hay agente, ni semáforo, ni señales.\n\n«LA DIRECCIÓN DE LOS VEHÍCULOS» no decide el orden de paso en ningún caso.\n\nCLAVE: primero busca al agente; si está, la pregunta está resuelta. Ver Leyes → «Quién manda sobre quién»."},{"id":5940,"bg":"При несъответствие между сигналите на регулировчика, сигналите на светофара и пътните знаци относно предимството трябва да се съобразявате:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51102.png","v":null,"a":[{"t":"със сигналите на регулировчика","ok":true,"i":null,"es":"las señales del AGENTE"},{"t":"с предписанията на пътните знаци","ok":false,"i":null,"es":"las señales de tráfico"},{"t":"със сигналите на светофара","ok":false,"i":null,"es":"las señales del SEMÁFORO"}],"es":"Cuando hay conflicto entre agente, semáforo y señales de prioridad, debes atenerte a:","explain":"⚠️ TRAMPA: siempre el AGENTE. Orden: agente > semáforo > señales. Esta jerarquía es absoluta e inamovible."},{"id":5942,"bg":"При тази ситуация, при преминаване през кръстовището, трябва да се съобразявате:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51152.png","v":null,"a":[{"t":"със сигналите на регулировчика","ok":true,"i":null,"es":"las señales del AGENTE"},{"t":"със сигналите на светофара","ok":false,"i":null,"es":"las señales del semáforo"},{"t":"с предписанията на пътните знаци относно предимството","ok":false,"i":null,"es":"las señales de prioridad"}],"es":"En esta situación al pasar por la intersección debes atenerte a:","explain":"LAS SEÑALES DEL AGENTE REGULADOR. Una sola correcta.\n\nQUÉ VES. Los tres escalones a la vez: un AGENTE en el centro del cruce, un SEMÁFORO en verde y la señal de VÍA CON PRIORIDAD (rombo) encima del semáforo.\n\nMANDA EL PRIMERO DE LA ESCALERA, y el primero es el agente. Está por encima del semáforo y por encima de las señales de prioridad.\n\n«EL SEMÁFORO» sería correcta solo si no hubiera agente. «LAS SEÑALES DE PRIORIDAD», solo si no hubiera ni agente ni semáforo.\n\nCLAVE: no hay que evaluar los tres; hay que encontrar el más alto. En cuanto ves al agente, él decide el orden de paso (aunque sigues obligado a respetar las señales de prohibición y de dirección obligatoria).\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Quién manda sobre quién»."},{"id":5944,"bg":"При тази ситуация редът за преминаване на автомобилите през кръстовището се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/82624.png","v":null,"a":[{"t":"от сигналите на регулировчика","ok":true,"i":null,"es":"las señales del agente regulador"},{"t":"от пътните знаци относно предимството","ok":false,"i":null,"es":"las señales de prioridad"},{"t":"в зависимост от посоката на движение на автомобилите","ok":false,"i":null,"es":"la dirección de circulación de los vehículos"},{"t":"с „правилото на десния”","ok":false,"i":null,"es":"la regla de la derecha"}],"es":"En esta situación el orden de paso de los vehículos en la intersección lo determina:","explain":"Cuando hay un agente regulador, sus señales tienen PRIORIDAD ABSOLUTA sobre semáforos, señales de tráfico y regla de la derecha. El agente siempre manda."},{"id":5945,"bg":"При тази ситуация редът за преминаване на автомобилите през кръстовището се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51266.png","v":null,"a":[{"t":"от сигналите на регулировчика","ok":true,"i":null,"es":"las señales del AGENTE"},{"t":"от сигналите на светофара","ok":false,"i":null,"es":"las del semáforo"},{"t":"с „правилото на десния”","ok":false,"i":null,"es":"la regla de la derecha"},{"t":"в зависимост от посоката на движение на автомобилите","ok":false,"i":null,"es":"la dirección de los vehículos"}],"es":"En esta situación el orden de paso lo determinan:","explain":"⚠️ TRAMPA: AGENTE. Mismo principio — el agente siempre tiene prioridad sobre cualquier otro sistema de control de tráfico."},{"id":5948,"bg":"При тази ситуация разрешено ли е да преминете през кръстовището?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51366.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"sí"},{"t":"да, но след като пропусна синия автомобил","ok":false,"i":null,"es":"да, но след като пропусна синия автомобил"}],"es":"En esta situación ¿está permitido pasar por la intersección?","explain":"SÍ — el semáforo o la situación mostrada permite el paso en este momento."},{"id":5949,"bg":"При тази ситуация разрешено ли е да преминете през кръстовището?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51399.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"En esta situación ¿está permitido pasar por la intersección?","explain":"SÍ — el semáforo o la situación mostrada permite el paso en este momento."},{"id":5950,"bg":"При несъответствие между сигналите на светофара и пътните знаци относно предимството трябва да се съобразявате:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51448.png","v":null,"a":[{"t":"със светлинните сигнали","ok":true,"i":null,"es":"las señales del semáforo"},{"t":"с предписанията на пътните знаци","ok":false,"i":null,"es":"las señales de prioridad"}],"es":"Cuando hay conflicto entre semáforo y señales de prioridad, debes atenerte a:","explain":"El semáforo prevalece sobre las señales de prioridad. Orden de autoridad: agente > semáforo > señales de tráfico."},{"id":5952,"bg":"При тази ситуация, при преминаване през кръстовището, трябва да се съобразявате:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51499.png","v":null,"a":[{"t":"със сигнала на светофара","ok":true,"i":null,"es":"la señal del semáforo"},{"t":"с пьтния знак забраняващ завиването надясно","ok":true,"i":null,"es":"la señal que prohíbe girar a la derecha"},{"t":"с пьтния знак относно предимството","ok":false,"i":null,"es":"la señal de prioridad"}],"es":"En esta situación al pasar por la intersección debes atenerte a: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el semáforo + la señal prohibitiva de giro son ambos vinculantes. La señal de prioridad queda subordinada cuando hay semáforo."},{"id":6331,"bg":"Когато при преминаване през жп прелез се включат звуковия сигнал и червените светлини на светофара, водачът трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да продължи движението си и да освободи прелеза","ok":true,"i":null,"es":"continuar y abandonar el paso a nivel lo antes posible"},{"t":"да спре незабавно и да включи аварийните светлини","ok":false,"i":null,"es":"parar inmediatamente y activar las luces de emergencia"},{"t":"да завие в обратна посока за да освободи прелеза по-бързо","ok":false,"i":null,"es":"dar la vuelta para salir más rápido"}],"es":"Cuando al cruzar el paso a nivel se activan las señales de alarma, el conductor que ya está sobre las vías debe:","explain":"CONTINUAR y abandonar el paso — si ya estás sobre las vías cuando se activan las señales, la única opción segura es acelerar para salir del paso, nunca parar sobre las vías."},{"id":6332,"bg":"Когато, на жп прелез без бариери, след преминаването на влака червените светлини на светофара продължават да светят, водачът:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не трябва да навлиза с автомобила на жп прелеза","ok":true,"i":null,"es":"NO debe entrar al paso a nivel"},{"t":"може да премине внимателно през жп прелеза","ok":false,"i":null,"es":"puede cruzar con cuidado"},{"t":"трябва да слезе от автомобила и да провери какво се случва","ok":false,"i":null,"es":"debe bajar del coche a comprobar"},{"t":"може да премине, като включи аварийните светлини","ok":false,"i":null,"es":"puede cruzar con las luces de emergencia encendidas"}],"es":"En un paso a nivel sin barreras, después del paso del tren las luces rojas del semáforo siguen encendidas. El conductor:","explain":"Si el semáforo sigue rojo DESPUÉS del tren, puede venir OTRO tren. NUNCA entres al paso a nivel hasta que el semáforo se apague. Esta es una pregunta de vida o muerte."},{"id":6333,"bg":"Задължително ли е спирането на ППС пред жп прелеза, когато е включена само звуковата сигнализация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Es obligatorio parar antes del paso a nivel cuando solo suena la señal acústica?","explain":"SÍ es obligatorio. Cualquier señal activa en un paso a nivel (acústica, luminosa o barrera) obliga a detenerse. No puedes cruzar hasta que cesen todas las señales."},{"id":6338,"bg":"Задължително ли е спирането на ППС пред жп прелеза, ако бариерите са вдигнати, но светофарът подава мигаща червена светлина?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, във всички случаи","ok":true,"i":null,"es":"sí, en todos los casos"},{"t":"да, но само когато към прелеза приближава влак","ok":false,"i":null,"es":"sí, pero solo cuando se aproxima un tren"},{"t":"не е задължително","ok":false,"i":null,"es":"no es obligatorio"}],"es":"¿Es obligatorio parar ante el paso a nivel si las barreras están levantadas pero el semáforo está rojo?","explain":"SÍ, en todos los casos — si el semáforo rojo está activado, es obligatorio parar AUNQUE las barreras estén levantadas. El semáforo manda sobre las barreras."},{"id":6339,"bg":"На водача е забранено да навлиза на железопътния прелез:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"преди да се е убедил, че към прелеза не се приближава влак","ok":true,"i":null,"es":"antes de asegurarse de que no se aproxima ningún tren"},{"t":"когато от другата страна на прелеза няма достатъчно място за продължаване на движението","ok":true,"i":null,"es":"cuando al otro lado no hay espacio suficiente para continuar"},{"t":"когато на прелеза трябва да се размине с друго ППС","ok":false,"i":null,"es":"cuando en el paso debe cruzarse con otro vehículo"},{"t":"когато на прелеза няма съоръжения за подаване на звуков и светлинен сигнал","ok":false,"i":null,"es":"cuando no hay señales acústicas ni luminosas"}],"es":"Al conductor le está PROHIBIDO entrar al paso a nivel: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: prohibido entrar sin verificar que no viene tren Y cuando no cabe al otro lado. Cruzarse con otro vehículo en el paso o la falta de señales NO son razones de prohibición."},{"id":6341,"bg":"На водача е забранено да навлиза на железопътния прелез когато:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"бариерите се спускат","ok":true,"i":null,"es":"las barreras están bajando"},{"t":"бариерите са спуснати","ok":true,"i":null,"es":"las barreras están bajadas"},{"t":"на прелеза трябва да се размине с друго ППС","ok":false,"i":null,"es":"en el paso debe cruzarse con otro vehículo"},{"t":"на прелеза няма съоръжения за подаване на звуков и светлинен сигнал","ok":false,"i":null,"es":"el paso no tiene señalización"}],"es":"Al conductor le está PROHIBIDO entrar al paso a nivel cuando: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: barreras bajando + barreras bajadas. Cruzarse con otro vehículo en el paso y la falta de señalización NO son causas de prohibición."},{"id":6342,"bg":"На водача е забранено да навлиза на железопътния прелез:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"когато бариерите са спуснати и започват да се вдигат","ok":true,"i":null,"es":"cuando las barreras están bajadas y empiezan a subir"},{"t":"когато е включена звуковата сигнализация","ok":true,"i":null,"es":"cuando está activa la señal acústica"},{"t":"при мигаща червена светлина на светофара","ok":true,"i":null,"es":"con luz roja parpadeante del semáforo"},{"t":"когато светофарната уредба подава сигнал от бавно мигащата светлина с луннобял цвят","ok":false,"i":null,"es":"cuando el semáforo emite luz blanca lenta parpadeante"}],"es":"Al conductor le está PROHIBIDO entrar al paso a nivel: (3 correctas)","explain":"Memoriza esta regla como una lista de 3 prohibiciones absolutas en un paso a nivel (železopъten prelez): 1) Cuando las barreras están bajando O empezando a subir (el momento de transición es el más peligroso, no esperes a que terminen de subir del todo si siguen en movimiento) 2) Cuando suena la señal acústica (el timbre/campana) 3) Cuando el semáforo del paso a nivel parpadea en rojo. La única luz que SÍ te permite avanzar con precaución es la luz blanca lunar intermitente (lunnobyal) — esa señal indica que el sistema de detección de trenes está activo y no detecta ningún tren, así que es la señal de 'vía libre verificada', no una prohibición."},{"id":6347,"bg":"На водача е забранено да навлиза на железопътния прелез:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"преди да се е убедил, че към прелеза не се приближава влак","ok":true,"i":null,"es":"antes de asegurarse de que no se aproxima ningún tren"},{"t":"когато е включена звуковата сигнализация","ok":true,"i":null,"es":"cuando está activa la señal acústica"},{"t":"когато светофарната уредба подава сигнал от бавно мигащата светлина с луннобял цвят","ok":false,"i":null,"es":"cuando el semáforo emite luz blanca lenta parpadeante"},{"t":"когато от другата страна на прелеза няма достатъчно място за продължаване на движението","ok":true,"i":null,"es":"cuando al otro lado no hay espacio suficiente"}],"es":"Al conductor le está PROHIBIDO entrar al paso a nivel: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: verificar que no viene tren + señal acústica activa + sin espacio al otro lado. La luz blanca parpadeante lenta PERMITE el paso (señal de normalidad)."},{"id":6349,"bg":"На водача е забранено да навлиза на железопътния прелез, когато:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от другата страна на прелеза няма достатъчно място за продължаване на движението","ok":true,"i":null,"es":"al otro lado no hay espacio suficiente para continuar"},{"t":"на прелеза трябва да се размине с друго ППС","ok":false,"i":null,"es":"debe cruzarse con otro vehículo en el paso"},{"t":"на прелеза няма съоръжения за подаване на звуков и светлинен сигнал","ok":false,"i":null,"es":"el paso no tiene señalización acústica ni luminosa"}],"es":"Al conductor le está PROHIBIDO entrar al paso a nivel cuando:","explain":"Prohibido cuando no cabe al otro lado — si no hay espacio para completar el cruce, entrar al paso a nivel es extremadamente peligroso. Quedarías atrapado sobre las vías."},{"id":6351,"bg":"Как ще сигнализирате през нощта, за да спрете влака, ако автомобилът, който управлявате, поради повреда остане върху релсите?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"с кръгово движение на ръката, в която се държи запалена факла или фенер","ok":true,"i":null,"es":"con movimiento circular del brazo sosteniendo una antorcha o linterna encendida"},{"t":"със запален до релсите огън","ok":false,"i":null,"es":"con un fuego encendido junto a los raíles"},{"t":"с вдигната ръка, в която се държи привличащ вниманието предмет","ok":false,"i":null,"es":"con el brazo levantado sosteniendo un objeto llamativo"},{"t":"със светлоотразителна стоп-палка","ok":false,"i":null,"es":"con pala reflectante de stop"}],"es":"¿Cómo señalizarás de noche para detener el tren si tu vehículo está averiado en el paso a nivel?","explain":"Para detener un tren de noche: movimiento CIRCULAR del brazo con antorcha o linterna. Este gesto es el código de emergencia reconocido internacionalmente por los maquinistas."},{"id":6353,"bg":"Как ще сигнализирате през деня, за да спрете влака, ако автомобилът, който управлявате, поради повреда остане върху релсите?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"с кръгово движение на ръката, в която се държи лесно забелязващ се предмет","ok":true,"i":null,"es":"con movimiento CIRCULAR del brazo sosteniendo un objeto llamativo"},{"t":"с насочена встрани ръка","ok":false,"i":null,"es":"con el brazo extendido lateralmente"},{"t":"с вдигната ръка, в която може да се държи привличащ вниманието предмет","ok":false,"i":null,"es":"con el brazo levantado sosteniendo algo llamativo"},{"t":"със стоп-палка","ok":false,"i":null,"es":"con una pala reflectante"}],"es":"¿Cómo señalizas de día para detener el tren si tu vehículo está averiado en el paso?","explain":"Movimiento CIRCULAR con objeto llamativo — el giro circular es el código universal para detener un tren. No el brazo levantado ni extendido — solo el movimiento circular funciona."},{"id":6355,"bg":"Задължително ли е спирането пред жп прелез, когато той е без бариери?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, във всички случаи","ok":true,"i":null,"es":"sí, en todos los casos"},{"t":"да, но само когато към прелеза приближава влак","ok":false,"i":null,"es":"sí, pero solo cuando se aproxima un tren"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Es obligatorio parar ante un paso a nivel sin barreras?","explain":"SÍ, SIEMPRE — ante un paso a nivel SIN barreras es obligatoria la parada completa en todos los casos, independientemente de si ves o no un tren. Es la norma más estricta."},{"id":6359,"bg":"Когато мястото за спиране преди жп прелеза се определя по отношение на релсите, разстоянието от първата релса трябва да бъде:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не по-малко от 2 м","ok":true,"i":null,"es":"no menos de 2 m"},{"t":"не повече от 1 м","ok":false,"i":null,"es":"no más de 1 m"},{"t":"не повече от 5 м","ok":false,"i":null,"es":"no más de 5 m"},{"t":"по преценка на водача","ok":false,"i":null,"es":"a criterio del conductor"}],"es":"Cuando la posición de parada antes del paso a nivel se determina respecto a los raíles, la distancia debe ser:","explain":"Mínimo 2 metros de los raíles. Esta distancia garantiza que el coche no quede encima de la vía. Recuerda: es MÍNIMO 2m, nunca menos."},{"id":6364,"bg":"В случай на принудително спиране на превозното средство върху релсите на жп прелез, водачът е длъжен:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да изведе пътниците извън превозното средство на безопасно разстояние","ok":true,"i":null,"es":"evacuar a los pasajeros a distancia segura"},{"t":"да вземе мерки за извеждането на превозното средство извън обсега на релсовия път","ok":true,"i":null,"es":"tomar medidas para sacar el vehículo de las vías"},{"t":"да вземе мерки за своевременното предупреждаване на машинистите от двете посоки на релсовия път","ok":true,"i":null,"es":"alertar a los maquinistas de ambos sentidos"},{"t":"да остане в автомобила и да уведоми органите за контрол","ok":false,"i":null,"es":"quedarse en el vehículo y avisar a las autoridades"}],"es":"Si el vehículo para forzosamente sobre las vías del paso a nivel, el conductor está obligado a: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: evacuar pasajeros + sacar el vehículo + alertar a los maquinistas. Quedarse en el vehículo es extremadamente peligroso — es la opción incorrecta."},{"id":6459,"bg":"При несъответствие между предписанията на пътните знаци и маркировката на пътя водачите са длъжни да се съобразяват:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51535.png","v":null,"a":[{"t":"с предписанията на пътните знаци","ok":true,"i":null,"es":"las señales de tráfico"},{"t":"с маркировката на пътя","ok":false,"i":null,"es":"las marcas en la calzada"}],"es":"Cuando hay conflicto entre señales de tráfico y marcas en la calzada, los conductores deben atenerse a:","explain":"LAS SEÑALES DE TRÁFICO. Una sola correcta.\n\nQUÉ VES. En el suelo de tu carril hay pintada una FLECHA HACIA ARRIBA (recto). En el poste de la derecha hay una señal circular AZUL de DIRECCIÓN OBLIGATORIA A LA IZQUIERDA. Se contradicen.\n\nSI SEÑAL Y MARCA SE CONTRADICEN, MANDA LA SEÑAL. La escalera de autoridad es: agente, semáforo, señales verticales y, por último, marcas en la calzada.\n\n«LAS MARCAS EN LA CALZADA» es el cebo: la pintura del suelo es el último escalón.\n\nCLAVE: la señal vertical se pone después y puede corregir la pintura (por ejemplo, durante obras). Ver Leyes → «Quién manda sobre quién»."},{"id":6460,"bg":"Ще извърши ли нарушение водачът на автомобила, ако при тази ситуация завие наляво?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/82690.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Cometerá infracción el conductor si gira a la izquierda en esta situación?","explain":"SÍ — hay una señal o condición que prohíbe girar a la izquierda en esta situación."},{"id":6465,"bg":"Как трябва да постъпите при тази ситуация, ако водачът на синия автомобил, който трябва да ви пропусне, не показва с действията си, че ще спре?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/52820.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir la velocidad"},{"t":"трябва да се движа с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"не съм длъжен да се съобразявам с него, защото се движа направо","ok":false,"i":null,"es":"no tengo que considerarlo porque voy recto"}],"es":"¿Cómo actúas si el conductor del coche azul (que debe cederte el paso) no lo hace? (2 correctas)","explain":"DEBO REDUCIR LA VELOCIDAD Y DEBO CIRCULAR LISTO PARA FRENAR. Dos correctas.\n\nQUÉ VES. Un cruce con SEMÁFORO en VERDE. Vas RECTO. De frente viene un coche AZUL con el intermitente, que va a girar a SU izquierda cruzando tu trayectoria. Debería cederte el paso, pero la pregunta dice que no da señales de ir a detenerse.\n\nTENER PREFERENCIA NO TE PROTEGE DEL CHOQUE. Si el que debe cederte no da señales de ir a detenerse, reduces y vas listo para frenar. Es la obligación de evitar el accidente aunque la culpa fuera del otro.\n\n«NO TENGO QUE CONSIDERARLO PORQUE TENGO PRIORIDAD / VOY RECTO» es el cebo: tener razón no sirve de nada después de un choque.\n\nCLAVE: si el otro no frena, frenas tú. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6467,"bg":"Как трябва да постъпите при тази ситуация, ако водачът на червения автомобил, който трябва да ви пропусне, не показва с действията си, че ще спре?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53360.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir la velocidad"},{"t":"трябва да се движа с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"не съм длъжен да се съобразявам с него, защото съм с предимство","ok":false,"i":null,"es":"no tengo que considerarlo porque tengo prioridad"}],"es":"¿Cómo actúas si el conductor del coche rojo (que debe cederte el paso) no lo hace? (2 correctas)","explain":"DEBO REDUCIR LA VELOCIDAD Y DEBO CIRCULAR LISTO PARA FRENAR. Dos correctas.\n\nQUÉ VES. Un cruce. Vas RECTO. Un coche ROJO, con el intermitente puesto, va a girar y cruzar tu trayectoria; la pregunta dice que debe cederte el paso, pero no da señales de detenerse.\n\nTENER PREFERENCIA NO TE PROTEGE DEL CHOQUE. Si el que debe cederte no da señales de ir a detenerse, reduces y vas listo para frenar. Es la obligación de evitar el accidente aunque la culpa fuera del otro.\n\n«NO TENGO QUE CONSIDERARLO PORQUE TENGO PRIORIDAD / VOY RECTO» es el cebo: tener razón no sirve de nada después de un choque.\n\nCLAVE: si el otro no frena, frenas tú. Compárala con la 6465 y la 6471. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6469,"bg":"Как трябва да постъпите при тази ситуация, ако водачът на синия автомобил, който трябва да ви пропусне, не показва с действията си, че ще спре?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53047.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir velocidad"},{"t":"трябва да управлявам с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"не съм длъжен да се съобразявам с него, защото съм с предимство","ok":false,"i":null,"es":"no tengo que considerarlo porque tengo prioridad"}],"es":"¿Cómo debes actuar si el conductor del coche azul (que debe cederte el paso) no lo hace? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: incluso teniendo prioridad, si el otro no cede DEBES reducir velocidad Y circular listo para frenar. La prioridad no es excusa para ignorar el peligro real."},{"id":6471,"bg":"Как трябва да постъпите при тази ситуация, ако водачът на червения автомобил, който трябва да ви пропусне, не показва с действията си, че ще спре?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53542.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir la velocidad"},{"t":"трябва да управлявам с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"ускорявам, защото съм с предимство","ok":false,"i":null,"es":"acelero porque tengo prioridad"},{"t":"не съм длъжен да се съобразявам с него, защото съм с предимство","ok":false,"i":null,"es":"no tengo que considerarlo porque tengo prioridad"}],"es":"¿Cómo actúas si el conductor del coche rojo (que debe cederte el paso) no lo hace? (2 correctas)","explain":"DEBO REDUCIR LA VELOCIDAD Y DEBO CIRCULAR LISTO PARA FRENAR. Dos correctas.\n\nQUÉ VES. Tienes la señal de VÍA CON PRIORIDAD (rombo). Vas RECTO. De frente viene un coche ROJO que va a girar a SU izquierda, cruzando tu trayectoria. Debe cederte el paso, pero no da señales de ir a detenerse.\n\nTENER PREFERENCIA NO TE PROTEGE DEL CHOQUE. Si el que debe cederte no da señales de ir a detenerse, reduces y vas listo para frenar. Es la obligación de evitar el accidente aunque la culpa fuera del otro.\n\n«NO TENGO QUE CONSIDERARLO PORQUE TENGO PRIORIDAD / VOY RECTO» es el cebo: tener razón no sirve de nada después de un choque.\n\n«ACELERO PORQUE TENGO PRIORIDAD» es el peor cebo: acelerar hacia quien no cede es buscar el choque.\n\nCLAVE: el rombo te da preferencia, no inmunidad. Ver Leyes → «Adelantar y colocarse antes de una maniobra»."},{"id":6472,"bg":"За кои водачи са задължителни сигналите за спиране, подавани от застаналия на прелеза железопътен служител?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"за водачите от двете страни на жп прелеза","ok":true,"i":null,"es":"para los conductores de ambos lados del paso"},{"t":"само за водачите, които се приближават от тази страна на прелеза, от която се намира жп служителя","ok":false,"i":null,"es":"solo para los que se aproximan desde el lado donde está el ferroviario"},{"t":"сигналите на жп служителя не са задължителни за водачите на МПС","ok":false,"i":null,"es":"las señales del ferroviario no son obligatorias para vehículos"}],"es":"¿Para qué conductores son obligatorias las señales de stop del ferroviario en el paso a nivel?","explain":"Las señales del ferroviario en el paso son obligatorias para AMBOS lados. Todo conductor que se aproxime debe obedecer, independientemente del lado."},{"id":6475,"bg":"При спиране в тунел с дължина над 500 м, дистанцията между автомобилите трябва да е не по-малка от:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"5 м","ok":true,"i":null,"es":"5 m"},{"t":"4 м","ok":false,"i":null,"es":"4 m"},{"t":"3 м","ok":false,"i":null,"es":"3 m"},{"t":"2 м","ok":false,"i":null,"es":"2 m"}],"es":"Al parar en túnel de más de 500 m la distancia entre vehículos debe ser de no menos de:","explain":"Este es un dato numérico que conviene memorizar con un truco mnemotécnico: en túneles de más de 500 metros, la distancia mínima entre vehículos detenidos es de 5 METROS — asocia '500 metros de túnel' con '5 metros de distancia' (ambos empiezan con 5). Esta distancia de seguridad existe para que, en caso de emergencia (incendio, accidente), los servicios de rescate tengan espacio para maniobrar entre los vehículos y para que el conductor de atrás pueda salir del coche y alejarse sin quedar atrapado entre dos vehículos."},{"id":6476,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53752.png","v":null,"a":[{"t":"спирам, за да изчакам разрешаващ сигнал от регулировчика","ok":true,"i":null,"es":"paro para esperar señal de paso del agente"},{"t":"спирам за да пропусна червения автомобил и преминавам след него","ok":false,"i":null,"es":"paro para dejar al rojo y paso después"},{"t":"преминавам преди червения автомобил","ok":false,"i":null,"es":"paso antes que el rojo"}],"es":"En esta situación:","explain":"Cuando hay agente, esperamos siempre su señal. No decidimos independientemente quién pasa."},{"id":6477,"bg":"При движение в тунел с дължина над 500 м, дистанцията между леките автомобили, трябва да е равна на разстоянието, изминавано за две секунди с разрешената скорост на движение.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"es":"En túnel de más de 500 m la distancia entre turismos debe ser igual a la distancia de seguridad exterior. Esto es:","explain":"CORRECTO — en túneles largos la distancia de seguridad debe mantenerse igual que fuera. La distancia se calcula como mínimo a la velocidad de circulación."},{"id":6478,"bg":"В тунел този знак с допълнителна табела сигнализира:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/84174.png","v":null,"a":[{"t":"място за принудително спиране","ok":true,"i":null,"es":"lugar de parada forzosa"},{"t":"място за паркиране с телефон и пожарогасител","ok":false,"i":null,"es":"lugar de aparcamiento con teléfono y extintor"}],"es":"En un túnel esta señal con tablilla indica:","explain":"LUGAR DE PARADA FORZOSA. Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL que dibuja un ENSANCHAMIENTO lateral de la calzada, con una placa debajo: EXTINTOR y TELÉFONO S.O.S.\n\nEN UN TÚNEL, ESE ENSANCHAMIENTO ES PARA EMERGENCIAS. Sirve para detener el vehículo si se avería o en caso de incidente, y tiene a mano extintor y teléfono de emergencia.\n\n«APARCAMIENTO CON TELÉFONO Y EXTINTOR» es el cebo: no se puede aparcar en un túnel; ese hueco es solo para paradas forzosas.\n\nCLAVE: en un túnel, ensanchamiento + S.O.S. = parada de emergencia, nunca aparcamiento. Compárala con la 6481 y el vídeo 12060. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6479,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54367.png","v":null,"a":[{"t":"трябва да премина преди синия автомобил","ok":true,"i":null,"es":"debo pasar antes que el coche azul"},{"t":"спирам, за да пропусна синия автомобил и преминавам след него","ok":false,"i":null,"es":"paro para dejar al azul y paso después"},{"t":"спирам, за да изчакам разрешаващ сигнал от регулировчика","ok":false,"i":null,"es":"paro para esperar señal del agente"}],"es":"En esta situación:","explain":"Paso ANTES que el azul — según la imagen tienes prioridad sobre el azul en esta intersección. No hay agente presente que requiera esperar su señal."},{"id":6481,"bg":"В тунел този знак сигнализира:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/84141.png","v":null,"a":[{"t":"уширение на пътното платно с аварийна станция","ok":true,"i":null,"es":"ensanchamiento de la calzada con estación de emergencia"},{"t":"допълнителна пътна лента за принудително спиране","ok":false,"i":null,"es":"carril adicional de parada forzosa"},{"t":"място за паркиране","ok":false,"i":null,"es":"zona de aparcamiento"}],"es":"En un túnel esta señal indica:","explain":"ENSANCHAMIENTO DE LA CALZADA CON ESTACIÓN DE EMERGENCIA. Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL con la calzada, una línea discontinua y un ENSANCHAMIENTO lateral con las letras «S O S».\n\nQUÉ INDICA. Un ensanchamiento donde hay una estación de emergencia (teléfono S.O.S.). Es un espacio puntual para emergencias.\n\n«CARRIL ADICIONAL DE PARADA FORZOSA» es el cebo: no es un carril continuo, es un ensanchamiento en un punto.\n\n«ZONA DE APARCAMIENTO» es el otro cebo: en un túnel no se aparca.\n\nCLAVE: S.O.S. en la señal = emergencia, no aparcamiento. Compárala con la 6478. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6483,"bg":"При тази ситуация разрешено ли е да завиете надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/103209.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"En esta situación ¿está permitido girar a la derecha?","explain":"SÍ.\n\nQUÉ VES. Llevas el intermitente DERECHO y la flecha indica giro a la derecha. En el cruce hay un AGENTE de tráfico que te muestra su COSTADO, con el brazo extendido en horizontal. A la derecha hay además un semáforo en VERDE y una señal de vía con prioridad (rombo).\n\nMANDA EL AGENTE. Sus señales están por encima del semáforo y de las señales de prioridad. Un agente con el brazo (o los brazos) extendido y que te muestra el costado te permite seguir RECTO y girar a la DERECHA. Así que puedes girar.\n\nAQUÍ TODO COINCIDE: el semáforo en verde también lo permitiría. Pero el razonamiento correcto empieza por el agente: si el agente te mostrara el pecho o la espalda, tendrías que parar aunque el semáforo estuviera en verde.\n\n«NO» es el cebo para quien se lía con la presencia simultánea del agente y del semáforo.\n\n(Corrección: la explicación anterior hablaba solo del semáforo y no mencionaba al agente, que es quien manda).\n\nCLAVE: agente de costado = recto y derecha permitidos.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) señales. 4) regla de la derecha. Ver Leyes → «Quién manda sobre quién»."},{"id":6485,"bg":"При тази ситуация трябва задължително да завия наляво.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54487.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación estoy obligado a girar a la izquierda. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. En el cruce hay un AGENTE que te muestra su COSTADO con el brazo extendido. A la derecha hay un semáforo en verde y una señal de vía con prioridad. No llevas ningún intermitente.\n\nEL AGENTE DE COSTADO TE PERMITE SEGUIR RECTO O GIRAR A LA DERECHA. No te obliga a girar a la izquierda; de hecho, con esta posición el giro a la izquierda no está permitido.\n\n«CORRECTO» es el cebo de quien interpreta el brazo extendido como una flecha que indica hacia dónde ir.\n\nCLAVE: el brazo del agente no es una flecha; lo que cuenta es qué parte de su cuerpo te muestra. Ver Leyes → «Quién manda sobre quién»."},{"id":6493,"bg":"В тунел, завиването в обратна посока е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено само на път с три и повече пътни ленти","ok":false,"i":null,"es":"permitido solo en vías de 3 o más carriles"},{"t":"разрешено, ако няма насрещно движение","ok":false,"i":null,"es":"permitido si no hay tráfico contrario"},{"t":"разрешено, ако движението в тунела е двупосочно","ok":false,"i":null,"es":"permitido si el tráfico es bidireccional"}],"es":"En un túnel el cambio de sentido está:","explain":"PROHIBIDO — el cambio de sentido en túnel está siempre prohibido, sin excepciones. No importa el número de carriles ni el tráfico contrario."},{"id":6498,"bg":"Извършването на коя от изброените маневри е забранено в тунел?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"движение назад","ok":true,"i":null,"es":"marcha atrás"},{"t":"завиване в обратна посока","ok":true,"i":null,"es":"cambio de sentido"},{"t":"заобикаляне","ok":false,"i":null,"es":"rodeo"},{"t":"изпреварване","ok":false,"i":null,"es":"adelantamiento"}],"es":"¿Qué maniobras están PROHIBIDAS en un túnel? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: marcha atrás + cambio de sentido están prohibidos en túnel. El rodeo y el adelantamiento pueden realizarse si las condiciones lo permiten."},{"id":6499,"bg":"При принудително спиране в тунел водачът е задължен да изключи двигателя, когато:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"началото на тунела е обозначено с пътен знак","ok":true,"i":null,"es":"el inicio del túnel está señalizado con señal de tráfico"},{"t":"спирането не е кратковременно","ok":true,"i":null,"es":"la parada no es breve"},{"t":"тунелът е осветен","ok":false,"i":null,"es":"el túnel está iluminado"},{"t":"движението в тунела е еднопосочно","ok":false,"i":null,"es":"el tráfico es de un solo sentido"}],"es":"Al parar forzosamente en túnel el conductor está obligado a apagar el motor cuando: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: túnel señalizado + parada no breve. La iluminación del túnel y el sentido del tráfico no son condiciones para apagar el motor."},{"id":6502,"bg":"Задължен ли е водачът да изключи двигателя при принудително спиране в тунел, когато началото на тунела е обозначено с пътен знак?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, когато това спиране не е кратковременно","ok":true,"i":null,"es":"sí, cuando la parada no es breve"},{"t":"да, независимо от продължителността на спирането","ok":false,"i":null,"es":"sí, independientemente de la duración"}],"es":"¿Está obligado a apagar el motor al parar forzosamente en túnel señalizado?","explain":"La clave de esta pregunta está en UNA palabra: 'kratkovremenno' (de corta duración). La obligación de apagar el motor en túnel solo aplica cuando la parada NO es momentánea — es decir, cuando sabes que vas a estar detenido un tiempo prolongado (avería, atasco largo). Si es una parada breve (unos segundos, por ejemplo esperando que se mueva el tráfico), no es obligatorio apagar el motor inmediatamente. La razón de fondo: el motor en marcha en un túnel genera gases tóxicos que se acumulan rápidamente en un espacio cerrado — cuanto más tiempo estés parado, más peligroso es mantenerlo encendido."},{"id":6506,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62187.png","v":null,"a":[{"t":"червеният автомобил","ok":true,"i":null,"es":"el coche rojo"},{"t":"жълтият автомобил","ok":false,"i":null,"es":"el coche amarillo"}],"es":"En esta situación tiene prioridad:","explain":"EL COCHE ROJO. Una sola correcta.\n\nQUÉ VES. Una ROTONDA. En la entrada del coche AMARILLO hay una señal de CEDA EL PASO y la señal azul de rotonda. El coche ROJO ya circula DENTRO de la rotonda, alrededor de la isleta central, y se acerca por la izquierda del amarillo.\n\nEN ESTA ROTONDA, EL QUE ESTÁ DENTRO TIENE PREFERENCIA. El ceda el paso de la entrada obliga al amarillo a dejar pasar a quien ya circula por el anillo. Aquí no se aplica la regla de la derecha: decide la señal.\n\n«EL AMARILLO» es el cebo de quien aplica la regla de la derecha (el rojo llega por la izquierda del amarillo). Con ceda el paso a la entrada, eso no cuenta.\n\nCLAVE: rotonda con ceda el paso en la entrada = pasa primero el que ya está dentro.\n\nMÉTODO: 1) ¿hay señal en la entrada? 2) ceda el paso = cedo a los que circulan dentro. Ver Leyes → «Vía con prioridad»."},{"id":6508,"bg":"При тази ситуация преминавам преди товарния автомобил, защото се движа направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63096.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación paso antes que el camión porque voy recto. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Vas RECTO (flecha). En el poste de la derecha hay una señal de VÍA CON PRIORIDAD con PANEL: el trazo GRUESO sube desde tu posición y gira a la DERECHA. Por esa rama derecha llega un CAMIÓN azul con el intermitente puesto.\n\nLOS DOS ESTÁIS EN LA VÍA CON PRIORIDAD, y entre vosotros decide la regla de la derecha. El camión te llega por la derecha: pasa él primero.\n\n«PORQUE VOY RECTO» es la razón falsa: ir recto no da prioridad. Basta con que la razón sea falsa para que el enunciado sea неправилно.\n\nCLAVE: en los enunciados con «porque…», si la razón es «porque voy recto», casi siempre es falso. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha. Y el tranvía, en general, pasa antes que los coches. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6511,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61772.png","v":null,"a":[{"t":"да пропусна трамвая","ok":true,"i":null,"es":"ceder al TRANVÍA"},{"t":"да премина преди лекия автомобил","ok":true,"i":null,"es":"pasar antes que el TURISMO"},{"t":"да премина преди трамвая","ok":false,"i":null,"es":"pasar antes que el tranvía"},{"t":"да пропусна лекия автомобил","ok":false,"i":null,"es":"ceder al turismo"}],"es":"En esta situación debo: (2 correctas)","explain":"CEDER AL TRANVÍA Y PASAR ANTES QUE EL TURISMO. Dos correctas.\n\nQUÉ VES. En el poste de la derecha hay una señal de VÍA CON PRIORIDAD con PANEL: el trazo GRUESO sube desde tu posición y gira a la IZQUIERDA. Por la izquierda, sobre la rama gruesa, viene un TRANVÍA. Por la DERECHA, por una rama fina, llega un turismo ROJO con el intermitente puesto. Tú vas a girar a la izquierda.\n\nAL TRANVÍA LE CEDES: está en la vía preferente, como tú, y el tranvía pasa antes que los coches.\n\nAL TURISMO LE PASAS TÚ: viene por la rama fina, la secundaria, así que te cede aunque esté a tu derecha.\n\n«PASAR ANTES QUE EL TRANVÍA» y «CEDER AL TURISMO» son las dos respuestas al revés.\n\nCLAVE: primero separa ramas gruesas y finas; luego recuerda que el tranvía va primero. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha. Y el tranvía, en general, pasa antes que los coches."},{"id":6512,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62113.png","v":null,"a":[{"t":"само трамвая","ok":true,"i":null,"es":"solo al tranvía"},{"t":"само автомобила","ok":false,"i":null,"es":"solo al coche"},{"t":"двете превозни средства","ok":false,"i":null,"es":"a los dos vehículos"}],"es":"En esta situación debo ceder el paso:","explain":"SOLO AL TRANVÍA. Una sola correcta.\n\nQUÉ VES. Una escena muy parecida a la 6511: señal de VÍA CON PRIORIDAD con PANEL, cuyo trazo GRUESO sube desde tu posición y gira a la IZQUIERDA, por donde viene un TRANVÍA. Por la DERECHA, por una rama fina, llega un coche ROJO con el intermitente.\n\nEL TRANVÍA VA POR LA PREFERENTE Y PASA PRIMERO. El coche rojo viene por la secundaria y te cede a ti.\n\n«SOLO AL COCHE» y «A LOS DOS» son los cebos de quien aplica la regla de la derecha al coche rojo sin mirar el panel.\n\nCLAVE: el panel deja al rojo en la secundaria; el tranvía, en la preferente. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha. Y el tranvía, en general, pasa antes que los coches."},{"id":6513,"bg":"При тази ситуация червеният автомобил, който завива надясно, е с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63115.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación el coche rojo que gira a la derecha tiene prioridad. Esto es:","explain":"⚠️ TRAMPA: INCORRECTO — girar a la derecha no da prioridad automática. La prioridad la determina la señalización y la posición, no la dirección de giro."},{"id":6514,"bg":"При тази ситуация трябва да пропусна червения автомобил защото:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64738.png","v":null,"a":[{"t":"се намира на пътя с предимство","ok":true,"i":null,"es":"está en la vía preferente"},{"t":"се движи направо","ok":false,"i":null,"es":"va recto"},{"t":"завивам наляво","ok":false,"i":null,"es":"yo giro a la izquierda"}],"es":"En esta situación debo ceder el paso al rojo porque:","explain":"PORQUE ESTÁ EN LA VÍA PREFERENTE. Una sola correcta.\n\nQUÉ VES. En tu poste hay un CEDA EL PASO con PANEL: el trazo GRUESO viene de ARRIBA y gira a la IZQUIERDA. Tú vienes por una rama fina y vas a girar a la izquierda. De frente, por la rama gruesa, viene un coche ROJO.\n\nEL ROJO VA POR LA PREFERENTE Y TÚ NO. Por eso le cedes.\n\n«PORQUE VA RECTO» es una razón falsa: ir recto no da prioridad.\n\n«PORQUE YO GIRO A LA IZQUIERDA» es la razón que valdría entre dos vehículos de la misma vía, pero aquí lo que decide es la señal: ya cedes por llevar el ceda el paso.\n\nCLAVE: si la señal os separa, la razón es la señal; las reglas de giro solo deciden entre iguales. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha. Y el tranvía, en general, pasa antes que los coches. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6515,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61654.png","v":null,"a":[{"t":"да пропусна лекия автомобил","ok":true,"i":null,"es":"ceder al TURISMO"},{"t":"да пропусна трамвая","ok":true,"i":null,"es":"ceder al TRANVÍA"},{"t":"да премина преди лекия автомобил","ok":false,"i":null,"es":"pasar antes que el turismo"},{"t":"да премина преди трамвая","ok":false,"i":null,"es":"pasar antes que el tranvía"}],"es":"En esta situación debo: (2 correctas)","explain":"CEDER AL TURISMO Y CEDER AL TRANVÍA. Dos correctas.\n\nQUÉ VES. Un cruce SIN SEÑALES de prioridad. Por la izquierda viene un TRANVÍA. Por la DERECHA llega un turismo ROJO con el intermitente puesto.\n\nAL TURISMO, POR LA DERECHA. Sin señales, cedes al que te llega por la derecha.\n\nAL TRANVÍA, PORQUE ES UN TRANVÍA. En un cruce sin señales, el tranvía pasa antes que los vehículos sin raíles, venga por donde venga.\n\n«PASAR ANTES QUE EL TURISMO» y «PASAR ANTES QUE EL TRANVÍA» son las respuestas al revés.\n\nCLAVE: compárala con la 6511: misma escena pero SIN panel; sin señales, el rojo de la derecha recupera la prioridad. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha. Y el tranvía, en general, pasa antes que los coches."},{"id":6516,"bg":"При тази ситуация трябва да пропусна червения автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63275.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"CORRECTO"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"es":"En esta situación debo ceder el paso al rojo. Esto es:","explain":"CORRECTO.\n\nQUÉ VES. En tu poste hay un CEDA EL PASO con PANEL: el trazo GRUESO viene de ARRIBA y gira hacia un lado; tú vienes por una rama fina y vas recto. De frente, por la rama gruesa, viene un coche ROJO con el intermitente.\n\nEL ROJO VA POR LA PREFERENTE Y TÚ LLEVAS CEDA EL PASO. Le cedes, aunque tú vayas recto y él gire.\n\n«INCORRECTO» es el cebo de quien aplica «el que gira cede al que va recto»: eso vale entre vehículos de la misma vía, no cuando una señal os separa.\n\nCLAVE: compárala con la 6514 (misma señal, tú girando a la izquierda): en las dos cedes por la señal. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha. Y el tranvía, en general, pasa antes que los coches. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6518,"bg":"При тази ситуация съм с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63169.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación yo tengo prioridad. Esto es:","explain":"⚠️ TRAMPA: INCORRECTO — según la imagen no tienes prioridad. Puede que vengas por la izquierda o estés en vía secundaria."},{"id":6519,"bg":"При тази ситуация съм с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63188.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación tengo prioridad. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Vas RECTO (flecha). En tu poste hay un CEDA EL PASO con PANEL: el trazo GRUESO baja desde ARRIBA y gira a la DERECHA; los trazos finos son el de la izquierda y el de abajo (el tuyo). Por la DERECHA, sobre la rama gruesa, hay una furgoneta AZUL con el intermitente puesto.\n\nTÚ VIENES POR LA SECUNDARIA Y LA FURGONETA POR LA PREFERENTE. Le cedes el paso.\n\n«CORRECTO» es el cebo de quien ve que vas recto y cree que eso le da prioridad.\n\nCLAVE: con ceda el paso, cedes a todos los que van por la rama gruesa. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6520,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62077.png","v":null,"a":[{"t":"двете превозни средства","ok":true,"i":null,"es":"a los dos vehículos"},{"t":"само трамвая","ok":false,"i":null,"es":"solo al tranvía"},{"t":"само автомобила","ok":false,"i":null,"es":"solo al coche"}],"es":"En esta situación debo dejar pasar:","explain":"A los dos — tanto el tranvía como el coche tienen prioridad sobre ti en esta configuración específica."},{"id":6521,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64819.png","v":null,"a":[{"t":"червеният автомобил, защото приближава кръстовището от дясната страна на зеления автомобил","ok":true,"i":null,"es":"el coche rojo, porque se aproxima por la derecha del verde"},{"t":"зеленият автомобил, защото се движи направо","ok":false,"i":null,"es":"el coche verde, porque va recto"},{"t":"червеният автомобил, защото се намира на пътя с предимство","ok":false,"i":null,"es":"el coche rojo, porque está en la vía preferente"}],"es":"En esta situación tiene prioridad:","explain":"El rojo tiene prioridad porque viene por la derecha del verde. La regla de la derecha se aplica aquí — no porque esté en vía preferente ni porque el verde gire."},{"id":6522,"bg":"При тази ситуация съм с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63240.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"CORRECTO"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"es":"En esta situación yo tengo prioridad. Esto es:","explain":"CORRECTO.\n\nQUÉ VES. Llevas el intermitente DERECHO y vas a girar a la derecha. En tu poste hay un CEDA EL PASO con PANEL: el trazo GRUESO viene de ARRIBA y gira a la DERECHA. Los trazos finos son el de abajo (el tuyo) y el de la IZQUIERDA, por donde llega un coche ROJO que sigue recto.\n\nLOS DOS ESTÁIS EN LA SECUNDARIA. Tú llevas ceda el paso, pero el rojo también llega por una rama fina. Entre vosotros dos la señal no decide nada.\n\nY CUANDO LA SEÑAL NO DECIDE, DECIDE LA DERECHA. El rojo te llega por la izquierda: tú estás a su derecha, así que pasas tú.\n\n«INCORRECTO» es el cebo de quien cree que llevar un ceda el paso obliga a ceder a todo el mundo. Solo obliga a ceder a quien va por la preferente.\n\nCLAVE: es la gemela inversa de la 6518: misma señal, panel girado. Lo que decide es en qué rama está el OTRO.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Cuando la prioritaria cambia de dirección» y «Regla de la derecha»."},{"id":6523,"bg":"При тази ситуация кой от автомобилите трябва да пропуснете?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57175.png","v":null,"a":[{"t":"червения автомобил","ok":true,"i":null,"es":"al vehículo ROJO"},{"t":"синия автомобил","ok":false,"i":null,"es":"al vehículo azul"}],"es":"En esta situación, ¿a cuál vehículo debe dejar pasar?","explain":"Aplica la regla de prioridad de la derecha o las señales de la imagen. El coche rojo tiene prioridad en esta intersección específica."},{"id":6524,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57242.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el ROJO"},{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el AZUL"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"ceder al rojo"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"ceder al azul"}],"es":"En esta situación debo: (2 correctas)","explain":"⚠️ TRAMPA: pasas antes que el ROJO Y antes que el AZUL. Tienes prioridad sobre ambos en esta intersección específica."},{"id":6525,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57314.png","v":null,"a":[{"t":"само червения автомобил","ok":true,"i":null,"es":"solo al ROJO"},{"t":"само синия автомобил","ok":false,"i":null,"es":"solo al AZUL"},{"t":"и двата автомобила","ok":false,"i":null,"es":"a los DOS"}],"es":"En esta situación debo ceder el paso:","explain":"⚠️ TRAMPA: solo al ROJO. El azul no tiene prioridad sobre ti en esta imagen."},{"id":6526,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57381.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"ceder el paso al coche rojo"},{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el coche azul"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"ceder el paso al azul"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el rojo"}],"es":"En esta situación debo: (2 correctas)","explain":"CEDER EL PASO AL COCHE ROJO Y PASAR ANTES QUE EL AZUL. Dos correctas.\n\nQUÉ VES. En tu poste hay una señal de VÍA CON PRIORIDAD (rombo, sin panel). Llevas el intermitente IZQUIERDO: vas a girar a la izquierda. De frente viene un coche ROJO. Por la DERECHA, por la vía transversal, llega una furgoneta AZUL.\n\nAL ROJO LE CEDES: viene de frente por la misma vía preferente que tú, y el que gira a la izquierda cede al que viene de frente.\n\nAL AZUL LE PASAS TÚ: viene por la vía secundaria, así que te cede aunque esté a tu derecha.\n\n«CEDER AL AZUL» y «PASAR ANTES QUE EL ROJO» son las respuestas al revés.\n\nCLAVE: el rombo te da preferencia sobre la secundaria, no sobre el que viene de frente por tu misma vía. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches. Ver Leyes → «Vía con prioridad»."},{"id":6527,"bg":"При тази ситуация трябва да пропусна само червения автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57449.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación debo ceder el paso solo al rojo. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. En tu poste hay un CEDA EL PASO. Llevas el intermitente IZQUIERDO: vas a girar a la izquierda. Por la IZQUIERDA, por la vía principal, viene una MOTO. De frente viene un coche ROJO.\n\nNO SOLO AL ROJO: TAMBIÉN A LA MOTO. La moto circula por la vía principal, y tu ceda el paso te obliga a dejarla pasar aunque venga por tu izquierda. Al rojo también le cedes (vas a girar a la izquierda y viene de frente).\n\n«CORRECTO» es el cebo de quien se olvida de la moto porque llega por la izquierda y aplica la regla de la derecha.\n\nCLAVE: con ceda el paso, la regla de la derecha no te salva: cedes a todos los de la principal, vengan por donde vengan. Compárala con la 6528. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches. Ver Leyes → «Vía con prioridad»."},{"id":6528,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57534.png","v":null,"a":[{"t":"да пропусна автомобила","ok":true,"i":null,"es":"ceder al coche"},{"t":"да пропусна мотоциклетиста","ok":true,"i":null,"es":"ceder al motorista"},{"t":"да премина преди мотоциклетиста","ok":false,"i":null,"es":"pasar antes que el motorista"},{"t":"да премина преди автомобила","ok":false,"i":null,"es":"pasar antes que el coche"}],"es":"En esta situación debo: (2 correctas)","explain":"CEDER AL COCHE Y CEDER AL MOTORISTA. Dos correctas.\n\nQUÉ VES. La misma escena que la 6527: CEDA EL PASO en tu acceso, vas a girar a la IZQUIERDA, por la IZQUIERDA viene una MOTO por la vía principal y de frente un coche ROJO.\n\nA LA MOTO, POR LA SEÑAL: va por la vía principal, y tu ceda el paso te obliga a dejarla pasar aunque venga por tu izquierda.\n\nAL COCHE ROJO, POR EL GIRO: vas a girar a la izquierda y él viene de frente.\n\n«PASAR ANTES QUE EL MOTORISTA» y «PASAR ANTES QUE EL COCHE» son las respuestas al revés.\n\nCLAVE: ceda el paso + giro a la izquierda = cedes a casi todo el mundo. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches. Ver Leyes → «Vía con prioridad»."},{"id":6529,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61585.png","v":null,"a":[{"t":"да пропусна трамвая","ok":true,"i":null,"es":"ceder al TRANVÍA"},{"t":"да премина преди лекия автомобил","ok":true,"i":null,"es":"pasar antes que el TURISMO"},{"t":"да пропусна лекия автомобил","ok":false,"i":null,"es":"ceder al turismo"},{"t":"да премина преди трамвая","ok":false,"i":null,"es":"pasar antes que el tranvía"}],"es":"En esta situación debo: (2 correctas)","explain":"DEJAR PASAR AL TRANVÍA Y PASAR ANTES QUE EL TURISMO. Dos correctas.\n\nQUÉ VES. Un cruce SIN SEÑALES ni semáforo. Vas recto (flecha). De frente viene un TRANVÍA con el intermitente, que gira por sus vías hacia tu derecha, cruzando tu trayectoria. Por tu IZQUIERDA llega un turismo ROJO que sigue recto.\n\nAL TRANVÍA LE CEDES. En un cruce de vías iguales, el tranvía pasa siempre antes que los vehículos sin raíles, gire hacia donde gire.\n\nAL TURISMO LE PASAS TÚ. Llega por tu izquierda: tú estás a su derecha, así que él te cede.\n\n«DEJAR PASAR AL TURISMO» y «PASAR ANTES QUE EL TRANVÍA» son las dos respuestas al revés.\n\nCLAVE: dos reglas a la vez: tranvía = primero siempre; entre coches = la derecha.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Quién manda sobre quién» y «Regla de la derecha»."},{"id":6530,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57673.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"ceder al rojo"},{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el azul"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el rojo"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"ceder al azul"}],"es":"En esta situación debo: (2 correctas)","explain":"CEDER AL COCHE ROJO Y PASAR ANTES QUE EL AZUL. Dos correctas.\n\nQUÉ VES. En tu poste hay un CEDA EL PASO. Vas RECTO. Por la IZQUIERDA, por la vía principal, llega un coche ROJO. De frente, por la otra vía secundaria, viene un coche AZUL con el intermitente, que va a girar a SU izquierda cruzando tu trayectoria.\n\nAL ROJO LE CEDES: va por la vía principal y tú llevas ceda el paso, aunque venga por tu izquierda.\n\nAL AZUL LE PASAS TÚ: también viene por una vía secundaria, así que la señal no os separa; entre vosotros, el que gira a la izquierda (el azul) cede al que va recto (tú).\n\n«CEDER AL AZUL» y «PASAR ANTES QUE EL ROJO» son las respuestas al revés.\n\nCLAVE: primero la señal (cedo a los de la principal); entre secundarias, las reglas de giro y de la derecha. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches. Ver Leyes → «Vía con prioridad»."},{"id":6531,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61976.png","v":null,"a":[{"t":"само трамвая","ok":true,"i":null,"es":"solo al tranvía"},{"t":"само автомобила","ok":false,"i":null,"es":"solo al coche"},{"t":"двете превозни средства","ok":false,"i":null,"es":"a los dos vehículos"}],"es":"En esta situación debo dejar pasar:","explain":"Solo al tranvía — tiene prioridad sobre ti. El coche no tiene prioridad en esta configuración específica."},{"id":6532,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57775.png","v":null,"a":[{"t":"мотоциклетиста","ok":true,"i":null,"es":"el motorista"},{"t":"товарния автомобил","ok":true,"i":null,"es":"el camión"},{"t":"лекия автомобил","ok":false,"i":null,"es":"el turismo"}],"es":"En esta situación debo ceder el paso a: (2 correctas)","explain":"AL MOTORISTA Y AL CAMIÓN. Dos correctas.\n\nQUÉ VES. En tu poste hay una señal de STOP. Vas RECTO. Por la IZQUIERDA, por la vía principal, viene una MOTO. Por la DERECHA, también por la principal, viene un CAMIÓN. De frente, por la otra vía secundaria, viene un turismo ROJO con el intermitente, que va a girar.\n\nCON STOP CEDES A TODOS LOS DE LA PRINCIPAL: la moto y el camión, vengan por donde vengan.\n\nEL TURISMO NO: viene por la secundaria, como tú, y va a girar cruzando tu trayectoria; entre vosotros no decide la señal.\n\n«EL TURISMO» es el cebo de quien piensa que el STOP obliga a ceder a todo el mundo.\n\nCLAVE: STOP = parar y ceder a los de la principal; entre secundarias, siguen las reglas normales. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches. Ver Leyes → «Vía con prioridad»."},{"id":6533,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61451.png","v":null,"a":[{"t":"да пропусна трамвая","ok":true,"i":null,"es":"ceder al TRANVÍA"},{"t":"да премина преди лекия автомобил","ok":true,"i":null,"es":"pasar antes que el TURISMO"},{"t":"да пропусна лекия автомобил","ok":false,"i":null,"es":"ceder al turismo"},{"t":"да премина преди трамвая","ok":false,"i":null,"es":"pasar antes que el tranvía"}],"es":"En esta situación debo: (2 correctas)","explain":"CEDER AL TRANVÍA Y PASAR ANTES QUE EL TURISMO. Dos correctas.\n\nQUÉ VES. Un cruce SIN SEÑALES. Vas RECTO. Por la DERECHA viene un TRANVÍA. Por la IZQUIERDA, un turismo ROJO.\n\nAL TRANVÍA LE CEDES: en un cruce sin señales el tranvía pasa antes que los vehículos sin raíles (y además viene por tu derecha).\n\nAL TURISMO LE PASAS TÚ: llega por tu izquierda, así que te cede.\n\n«CEDER AL TURISMO» y «PASAR ANTES QUE EL TRANVÍA» son las respuestas al revés.\n\nCLAVE: tranvía primero; entre coches, la derecha. Compárala con la 6535. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches."},{"id":6534,"bg":"Задължени ли сте при тази ситуация да пропуснете синия автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57946.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Está obligado a ceder el paso al coche azul?","explain":"SÍ.\n\nQUÉ VES. En tu poste hay una señal de VÍA CON PRIORIDAD (sin panel) y, debajo, una señal azul de DIRECCIÓN OBLIGATORIA A LA IZQUIERDA. Llevas el intermitente izquierdo. De frente viene un coche AZUL. Por la derecha, una furgoneta roja.\n\nEL AZUL VIENE DE FRENTE POR TU MISMA VÍA PREFERENTE, así que el rombo no os separa. Entre vosotros, el que gira a la izquierda (tú) cede al que viene de frente.\n\n«NO» es el cebo de quien cree que el rombo, o la señal que le obliga a girar, le da preferencia sobre todos.\n\nCLAVE: la señal azul te obliga a girar a la izquierda, pero no te da preferencia para hacerlo. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches. Ver Leyes → «Vía con prioridad»."},{"id":6535,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61874.png","v":null,"a":[{"t":"само трамвая","ok":true,"i":null,"es":"solo al tranvía"},{"t":"само лекия автомобил","ok":false,"i":null,"es":"solo al turismo"},{"t":"и двете превозни средства","ok":false,"i":null,"es":"a los dos"}],"es":"En esta situación debo ceder el paso:","explain":"SOLO AL TRANVÍA. Una sola correcta.\n\nQUÉ VES. La misma escena que la 6533: un cruce SIN SEÑALES, vas RECTO, por la DERECHA viene un TRANVÍA y por la IZQUIERDA un turismo ROJO.\n\nAL TRANVÍA LE CEDES; AL TURISMO, NO: llega por tu izquierda, así que te cede él.\n\n«SOLO AL TURISMO» y «A LOS DOS» son los cebos: el turismo está a tu izquierda.\n\nCLAVE: tranvía primero; entre coches, la derecha. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches."},{"id":6536,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58116.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el rojo"},{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"ceder al azul"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"ceder al rojo"}],"es":"En esta situación debo: (2 correctas)","explain":"⚠️ TRAMPA color: pasas antes que el ROJO, cedes al AZUL. Inverso al anterior — lee la imagen con cuidado."},{"id":6537,"bg":"При тази ситуация водачът на зеления автомобил трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68558.png","v":null,"a":[{"t":"да пропусне синия автомобил","ok":true,"i":null,"es":"ceder al azul"},{"t":"да премине преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el rojo"},{"t":"да пропусне червения автомобил","ok":false,"i":null,"es":"ceder al rojo"},{"t":"да премине преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"}],"es":"En esta situación el conductor del coche verde debe: (2 correctas)","explain":"CEDER AL AZUL Y PASAR ANTES QUE EL ROJO. Dos correctas.\n\nQUÉ VES. Un cruce SIN SEÑALES. El coche VERDE (en primer plano) lleva el intermitente IZQUIERDO. Por su IZQUIERDA llega un coche ROJO; por su DERECHA, una furgoneta AZUL.\n\nSIN SEÑALES MANDA LA DERECHA. El azul le llega al verde por la derecha: el verde le cede. El rojo le llega por la izquierda: el verde pasa antes.\n\n«CEDER AL ROJO» y «PASAR ANTES QUE EL AZUL» son las respuestas al revés.\n\nCLAVE: el giro a la izquierda solo obliga a ceder a lo que viene de FRENTE; con los laterales decide la derecha. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches. Ver Leyes → «Regla de la derecha»."},{"id":6538,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58268.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el rojo"},{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"ceder al azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"ceder al rojo"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"}],"es":"En esta situación debo: (2 correctas)","explain":"PASAR ANTES QUE EL ROJO Y CEDER AL AZUL. Dos correctas.\n\nQUÉ VES. En tu poste hay una señal de STOP. Vas RECTO. Por la DERECHA, por la vía principal, llega un CAMIÓN azul con el intermitente puesto. De frente, por la otra vía secundaria, viene un coche ROJO con el intermitente, que va a girar a SU izquierda cruzando tu trayectoria.\n\nAL CAMIÓN LE CEDES: va por la principal y tú tienes STOP.\n\nAL ROJO LE PASAS TÚ: viene por la secundaria, como tú, así que la señal no os separa; entre vosotros, el que gira a la izquierda (el rojo) cede al que va recto.\n\n«CEDER AL ROJO» y «PASAR ANTES QUE EL AZUL» son las respuestas al revés.\n\nCLAVE: el STOP te obliga ante la principal, no ante el otro de la secundaria. Compárala con la 6532. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Vía con prioridad»."},{"id":6539,"bg":"При тази ситуация жълтият автомобил трябва да премине преди синия и червения автомобил защото:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65468.png","v":null,"a":[{"t":"се намира на пътя с предимство","ok":true,"i":null,"es":"está en la vía preferente"},{"t":"се намира от дясната страна на синия автомобил","ok":true,"i":null,"es":"está a la derecha del coche azul"},{"t":"завива надясно","ok":false,"i":null,"es":"gira a la derecha"},{"t":"не напуска пътят с предимство","ok":false,"i":null,"es":"no abandona la vía preferente"}],"es":"En esta situación el coche amarillo debe pasar antes que el azul y el rojo porque: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el amarillo tiene prioridad porque está en vía preferente Y porque está a la derecha del azul. Dos razones independientes que se suman."},{"id":6540,"bg":"При тази ситуация водачът на зеления автомобил трябва да пропусне:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68541.png","v":null,"a":[{"t":"само синия автомобил","ok":true,"i":null,"es":"solo al AZUL"},{"t":"само червения автомобил","ok":false,"i":null,"es":"solo al ROJO"},{"t":"двата автомобила","ok":false,"i":null,"es":"a los DOS"}],"es":"En esta situación el conductor del coche verde debe ceder el paso:","explain":"⚠️ TRAMPA color: verde cede solo al AZUL. El rojo no tiene prioridad sobre el verde en esta imagen."},{"id":6541,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66300.png","v":null,"a":[{"t":"само синия автомобил","ok":false,"i":null,"es":"solo al azul"},{"t":"само червения автомобил","ok":false,"i":null,"es":"solo al rojo"},{"t":"и двата автомобила","ok":true,"i":null,"es":"a los dos"}],"es":"En esta situación debo ceder el paso:","explain":"A LOS DOS. Una sola correcta.\n\nQUÉ VES. Vas RECTO. En tu poste hay un CEDA EL PASO con PANEL: el trazo GRUESO baja desde ARRIBA y gira a la IZQUIERDA; los finos son el de la derecha y el de abajo (el tuyo). De frente, por la rama gruesa, viene un coche ROJO con el intermitente. Por la DERECHA, por la rama fina, llega un coche AZUL con el intermitente.\n\nAL ROJO, POR LA SEÑAL: va por la preferente y tú llevas ceda el paso.\n\nAL AZUL, POR LA DERECHA: también viene por una secundaria, así que la señal no os separa, y te llega por la derecha.\n\n«SOLO AL AZUL» y «SOLO AL ROJO» olvidan una de las dos reglas.\n\nCLAVE: primero separa ramas gruesas y finas; entre los de la fina, la derecha. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6542,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65568.png","v":null,"a":[{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"ceder al AZUL"},{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"ceder al ROJO"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el rojo"}],"es":"En esta situación debo: (2 correctas)","explain":"CEDER AL AZUL Y CEDER AL ROJO. Dos correctas.\n\nQUÉ VES. La misma escena que la 6541: CEDA EL PASO con PANEL cuyo trazo GRUESO baja desde ARRIBA y gira a la IZQUIERDA. De frente, por la rama gruesa, el ROJO; por la DERECHA, por una rama fina, el AZUL. Tú vas recto por la otra rama fina.\n\nAL ROJO, POR LA SEÑAL. AL AZUL, POR LA DERECHA.\n\n«PASAR ANTES QUE EL AZUL» y «PASAR ANTES QUE EL ROJO» son las respuestas al revés.\n\nCLAVE: es la misma regla que la 6541, preguntada en formato de dos casillas. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6543,"bg":"При тази ситуация червеният автомобил е с предимство, защото се движи направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68524.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación el coche rojo tiene prioridad porque va recto. Esto es:","explain":"⚠️ TRAMPA CLÁSICA: INCORRECTO — ir recto nunca da prioridad automática. Esta es una de las preguntas trampa más repetidas del examen búlgaro."},{"id":6544,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66249.png","v":null,"a":[{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"dejar pasar al coche azul"},{"t":"да пропусна жълтия автомобил","ok":true,"i":null,"es":"dejar pasar al coche amarillo"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el coche rojo"}],"es":"En esta situación debo: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: cedes al azul Y al amarillo. El rojo es a quien tienes prioridad o tiene menor prioridad en esta configuración."},{"id":6545,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66249.png","v":null,"a":[{"t":"да пропусна червения автомобил, защото се намира на пътя с предимство","ok":true,"i":null,"es":"dejar pasar al rojo porque está en vía preferente"},{"t":"да пропусна жълтия автомобил, защото се намира на пътя с предимство","ok":true,"i":null,"es":"dejar pasar al amarillo porque está en vía preferente"},{"t":"да премина преди синия автомобил, защото той завива наляво","ok":false,"i":null,"es":"pasar antes que el azul porque gira a la izquierda"}],"es":"En esta situación debo: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: tanto el rojo como el amarillo están en vía preferente — debes ceder a ambos. El azul gira a la izquierda, por eso puedes pasar antes que él."},{"id":6546,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68490.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el ROJO"},{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el AZUL"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"ceder al rojo"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"ceder al azul"}],"es":"En esta situación debo: (2 correctas)","explain":"Esta es una pregunta multirespuesta (dos correctas: pasar antes que ambos coches). Eso significa que en esta intersección concreta TÚ tienes prioridad sobre los dos vehículos de colores — probablemente porque circulas por una vía con prioridad marcada con señal, o porque ambos coches están girando hacia tu trayectoria y deben cederte el paso a ti (el que va recto tiene prioridad sobre el que gira). Truco para identificarlo en la imagen: si ves que las flechas o posición de las ruedas de los otros coches indican que van a girar, y tú vas recto, tú casi siempre tienes prioridad sobre ambos."},{"id":6547,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65840.png","v":null,"a":[{"t":"синия автомобил","ok":true,"i":null,"es":"el azul"},{"t":"червения автомобил","ok":true,"i":null,"es":"el rojo"},{"t":"жълтия автомобил","ok":false,"i":null,"es":"el amarillo"}],"es":"En esta situación debo ceder el paso a: (2 correctas)","explain":"AL AZUL Y AL ROJO. Dos correctas.\n\nQUÉ VES. Vas RECTO. En tu poste hay un CEDA EL PASO con PANEL: el trazo GRUESO baja desde ARRIBA y gira a la DERECHA; los finos son el de la izquierda y el de abajo (el tuyo). Por la DERECHA, sobre la rama gruesa, una furgoneta AZUL; de frente, también por la rama gruesa, un coche ROJO. Por la IZQUIERDA, por la rama fina, un coche AMARILLO.\n\nAL AZUL Y AL ROJO LES CEDES: van por la preferente y tú llevas ceda el paso.\n\nAL AMARILLO NO: viene por una rama fina, como tú, y por tu izquierda; entre vosotros decide la derecha, y la derecha eres tú.\n\n«EL AMARILLO» es el cebo de quien cree que el ceda el paso obliga a ceder a todos.\n\nCLAVE: con ceda el paso cedes a los de la rama gruesa; con los de otra rama fina, decide la derecha. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6548,"bg":"При тази ситуация трябва да премина след:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/82756.png","v":null,"a":[{"t":"червения автомобил","ok":false,"i":null,"es":"el coche rojo"},{"t":"синия автомобил","ok":true,"i":null,"es":"el coche azul"}],"es":"En esta situación debo pasar después de:","explain":"DESPUÉS DEL COCHE AZUL.\n\nQUÉ VES. Vas recto (flecha). A la derecha hay una señal de VÍA CON PRIORIDAD (rombo) con un PANEL debajo que dibuja el trazado: la vía con prioridad viene desde tu posición y GIRA A LA DERECHA. Por esa rama derecha está el coche AZUL, con intermitente. De frente viene un coche ROJO con intermitente, que gira hacia la calle de tu izquierda.\n\nEL AZUL Y TÚ ESTÁIS EN LA VÍA CON PRIORIDAD. El trazo grueso del panel une tu acceso con el del azul. Entre dos vehículos que van por la vía con prioridad se aplica la regla de la derecha, y el azul te llega por la derecha: pasa él primero.\n\nEL ROJO VIENE DE LA VÍA SECUNDARIA (la de enfrente no es la del trazo grueso), así que te cede el paso a ti y al azul.\n\n«DESPUÉS DEL ROJO» es el cebo: está de frente y parece que va a «cruzarse» contigo, pero viene de la secundaria.\n\n(Corrección: la explicación anterior decía que el rojo seguía recto; en la imagen el rojo gira hacia la calle de tu izquierda. La respuesta no cambia).\n\nCLAVE: con panel bajo el rombo, primero localiza el trazo grueso; entre los que están en él, decide la derecha.\n\nMÉTODO: 1) ¿qué accesos une el trazo grueso? 2) ¿quién está en la secundaria? Ese cede. 3) entre los de la principal, regla de la derecha. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6549,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65617.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el rojo"},{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"ceder al azul"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"ceder al rojo"}],"es":"En esta situación debo: (2 correctas)","explain":"PASAR ANTES QUE EL ROJO Y CEDER AL AZUL. Dos correctas.\n\nQUÉ VES. Vas RECTO. A la derecha hay una señal de VÍA CON PRIORIDAD con PANEL: el trazo GRUESO sube desde tu posición y gira a la DERECHA. Por la DERECHA, sobre la rama gruesa, una furgoneta AZUL con el intermitente. De frente, por la rama fina, un coche ROJO con el intermitente.\n\nAL AZUL LE CEDES: estáis los dos en la preferente y te llega por la derecha.\n\nAL ROJO LE PASAS TÚ: viene por la secundaria.\n\n«PASAR ANTES QUE EL AZUL» y «CEDER AL ROJO» son las respuestas al revés.\n\nCLAVE: es la misma escena que la 6548 (verificada antes), con otra forma de preguntar. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6550,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68473.png","v":null,"a":[{"t":"да премина преди двата автомобила","ok":true,"i":null,"es":"pasar antes que los dos coches"},{"t":"да пропусна само червения автомобил","ok":false,"i":null,"es":"dejar pasar solo al coche rojo"},{"t":"да пропусна само синия автомобил","ok":false,"i":null,"es":"dejar pasar solo al coche azul"}],"es":"En esta situación debo:","explain":"Tienes prioridad sobre ambos coches — pasas primero que los dos según la situación mostrada."},{"id":6552,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65693.png","v":null,"a":[{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el coche azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al coche rojo"},{"t":"да премина преди жълтия автомобил","ok":true,"i":null,"es":"pasar antes que el coche amarillo"}],"es":"En esta situación debo: (2 correctas)","explain":"PASAR ANTES QUE EL COCHE AZUL Y ANTES QUE EL COCHE AMARILLO. Dos correctas.\n\nQUÉ VES. Vas a girar a la DERECHA (flecha). En el poste de la derecha hay una señal de VÍA CON PRIORIDAD con PANEL: el trazo GRUESO sube desde tu posición y gira a la IZQUIERDA, hacia donde está una furgoneta ROJA. Por la DERECHA llega un coche AZUL con el intermitente puesto y de frente uno AMARILLO; ambos vienen por ramas finas.\n\nEL AZUL Y EL AMARILLO ESTÁN EN LA SECUNDARIA. Vienen por las ramas finas del panel: te ceden el paso a ti, aunque el azul esté a tu derecha.\n\n¿Y EL ROJO? Está, como tú, en la rama gruesa. Entre los dos de la preferente decide la regla de la derecha, y el rojo te llega por la IZQUIERDA: no tienes que cederle. Por eso «dejar pasar al rojo» es falso.\n\n«DEJAR PASAR AL ROJO» es el cebo para quien ve que el rojo está en la preferente y cree que eso le da prioridad sobre ti. Tú también estás en ella, y a su derecha.\n\nCLAVE: con panel, primero separa ramas gruesas y finas; entre los de la gruesa, la derecha.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6553,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66833.png","v":null,"a":[{"t":"пропускам синия автомобил","ok":true,"i":null,"es":"cedo el paso al azul"},{"t":"преминавам преди синия автомобил","ok":false,"i":null,"es":"paso antes que el azul"}],"es":"En esta situación:","explain":"CEDO al azul — tiene prioridad según la imagen."},{"id":6554,"bg":"При тази ситуация пропускам червения автомобил, защото:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66883.png","v":null,"a":[{"t":"се намира от дясната ми страна","ok":true,"i":null,"es":"está a mi derecha"},{"t":"се движи направо","ok":false,"i":null,"es":"va recto"},{"t":"завивам наляво","ok":false,"i":null,"es":"yo giro a la izquierda"}],"es":"En esta situación dejo pasar al coche rojo porque:","explain":"El rojo está a tu derecha = tiene prioridad por la regla de la derecha. No importa que vayas recto ni que tú gires — la posición relativa es lo que determina la prioridad."},{"id":6555,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68438.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"ceder al rojo"},{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el azul"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el rojo"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"ceder al azul"}],"es":"En esta situación debo: (2 correctas)","explain":"MÉTODO PARA RESOLVER CUALQUIER PREGUNTA DE 'A QUIÉN CEDO EL PASO': Mira la imagen y sigue este orden de comprobación: 1) ¿Hay alguna señal de STOP, ceda el paso o vía prioritaria visible? Esa señal manda sobre todo lo demás. 2) Si no hay señales, ¿qué vehículo está a tu derecha? Ese tiene prioridad sobre ti (regla del dásnostoящ). 3) ¿Algún vehículo va a girar a la izquierda cruzando tu trayectoria? Ese debe cederte el paso a ti si vienes recto o girando a la derecha. 4) ¿Tu vía termina ahí o continúa? El vehículo en la vía que continúa tiene prioridad sobre el que sale de una vía que termina. En esta pregunta concreta, la respuesta correcta es ceder al rojo y pasar antes que el azul — eso te dice que el rojo está en posición de prioridad (probablemente a tu derecha o en vía con continuidad) y el azul no."},{"id":6556,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66950.png","v":null,"a":[{"t":"пропускам червения автомобил","ok":true,"i":null,"es":"cedo el paso al rojo"},{"t":"преминавам преди червения автомобил","ok":false,"i":null,"es":"paso antes que el rojo"}],"es":"En esta situación:","explain":"CEDO EL PASO AL ROJO. Una sola correcta.\n\nQUÉ VES. Un cruce SIN SEÑALES. Vas RECTO. Por la DERECHA llega una furgoneta ROJA con el intermitente puesto.\n\nSIN SEÑALES MANDA LA DERECHA. El rojo te llega por la derecha: pasa él primero, gire hacia donde gire.\n\n«PASO ANTES QUE EL ROJO» es el cebo de quien cree que ir recto da prioridad frente al que gira.\n\nCLAVE: «el que gira cede» solo vale frente a lo que viene de frente; con los laterales, la derecha. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6557,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68421.png","v":null,"a":[{"t":"червения автомобил","ok":true,"i":null,"es":"al coche rojo"},{"t":"синия автомобил","ok":false,"i":null,"es":"al coche azul"}],"es":"En esta situación debo dejar pasar:","explain":"El rojo tiene prioridad en esta intersección específica — sea por vía preferente o por regla de la derecha. El azul no tiene prioridad sobre ti."},{"id":6558,"bg":"При тази ситуация червеният автомобил е с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66983.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación el coche rojo tiene prioridad. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Un cruce sin señales ni semáforo. Vas recto (flecha). El coche ROJO llega por tu IZQUIERDA.\n\nSIN SEÑALES MANDA LA DERECHA, y el rojo no está a tu derecha, está a tu izquierda. Por tanto la prioridad es tuya y el enunciado es falso.\n\nEL ERROR TÍPICO ES DE LATERALIDAD, no de doctrina. Mucha gente sabe la regla y aun así falla estas preguntas porque desde el asiento del conductor, en una imagen, cuesta un segundo situar quién está a qué lado.\n\nTRUCO PARA NO EQUIVOCARSE. No pienses «está a la izquierda de la foto»: piensa «me llega por mi ventanilla izquierda». La referencia eres tú al volante, no el encuadre.\n\nCLAVE: compárala con la 6557, que es la misma escena con el coche cambiado de lado.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señales y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Regla de la derecha»."},{"id":6559,"bg":"При тази ситуация водачът на зеления автомобил трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68404.png","v":null,"a":[{"t":"да пропусне червения автомобил","ok":true,"i":null,"es":"ceder al ROJO"},{"t":"да пропусне синия автомобил","ok":true,"i":null,"es":"ceder al AZUL"},{"t":"да премине преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"},{"t":"да премине преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el rojo"}],"es":"En esta situación el verde debe: (2 correctas)","explain":"DEJAR PASAR AL COCHE ROJO Y DEJAR PASAR AL COCHE AZUL. Dos correctas.\n\nQUÉ VES. Un cruce SIN SEÑALES ni semáforo. El coche VERDE (el de delante de ti en la imagen) lleva el intermitente IZQUIERDO: va a girar a la izquierda. De frente viene un coche ROJO, también con intermitente, que gira hacia la calle de la izquierda. Por la DERECHA del verde llega un coche AZUL que sigue recto.\n\nAL AZUL, POR LA DERECHA. Sin señales, el verde cede al que le llega por su derecha, y ese es el azul.\n\nAL ROJO, POR EL GIRO A LA IZQUIERDA. Quien gira a la izquierda cede a los que vienen de frente y siguen recto o giran a su derecha. El rojo viene de frente y gira a SU derecha (hacia la calle de tu izquierda): tiene preferencia sobre el verde.\n\n«PASAR ANTES QUE EL AZUL» y «PASAR ANTES QUE EL ROJO» son las mismas respuestas al revés: el verde no pasa antes que ninguno.\n\nCLAVE: el que gira a la izquierda en un cruce sin señales suele ser el último: cede a la derecha y a lo que viene de frente.\n\nMÉTODO: 1) ¿quién viene por la derecha? 2) ¿quién viene de frente, y gira a la izquierda yo? 3) cedo a ambos. Ver Leyes → «Regla de la derecha» y «Giro a la izquierda»."},{"id":6560,"bg":"При тази ситуация с предимство е водачът на:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67148.png","v":null,"a":[{"t":"автомобила","ok":true,"i":null,"es":"el coche"},{"t":"мотоциклета","ok":false,"i":null,"es":"la moto"}],"es":"En esta situación tiene prioridad:","explain":"EL CONDUCTOR DEL COCHE. Una sola correcta.\n\nQUÉ VES. Un cruce SIN SEÑALES. Un coche ROJO (en primer plano) lleva el intermitente IZQUIERDO y va a girar a la izquierda. Por su IZQUIERDA llega una MOTO que sigue recto.\n\nLA MOTO TIENE AL COCHE A SU DERECHA. Sin señales, cede quien tiene al otro a su derecha: la moto cede al coche.\n\n«LA MOTO» es el cebo de quien piensa que el que gira a la izquierda siempre cede. Eso es frente a lo que viene de FRENTE; la moto llega por un lateral.\n\nCLAVE: compárala con la 5924 (la misma escena preguntando qué regla decide). MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6561,"bg":"При тази ситуация водачът на зеления автомобил трябва да пропусне:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68387.png","v":null,"a":[{"t":"двата автомобила","ok":true,"i":null,"es":"a los dos coches"},{"t":"само синия автомобил","ok":false,"i":null,"es":"solo al coche azul"},{"t":"само червения автомобил","ok":false,"i":null,"es":"solo al coche rojo"}],"es":"En esta situación el conductor del coche verde debe dejar pasar:","explain":"El verde debe ceder a ambos — sea por regla de la derecha o porque los otros están en vía preferente. Analiza la imagen para confirmar."},{"id":6562,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67115.png","v":null,"a":[{"t":"лекият автомобил е с предимство, защото е отдясно на мотоциклетиста","ok":true,"i":null,"es":"el turismo tiene prioridad porque está a la derecha del motorista"},{"t":"мотоциклетистът е с предимство, защото се движи направо","ok":false,"i":null,"es":"el motorista tiene prioridad porque va recto"},{"t":"мотоциклетистът е с предимство, защото е двуколесно МПС","ok":false,"i":null,"es":"el motorista tiene prioridad porque es vehículo de dos ruedas"}],"es":"En esta situación:","explain":"El turismo tiene prioridad por la regla de la derecha. Ir recto o ser moto no da prioridad automática — la posición relativa es lo que cuenta."},{"id":6563,"bg":"При тази ситуация първи трябва да премине:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68370.png","v":null,"a":[{"t":"червеният автомобил","ok":true,"i":null,"es":"el coche rojo"},{"t":"зеленият автомобил","ok":false,"i":null,"es":"el coche verde"},{"t":"синият автомобил","ok":false,"i":null,"es":"el coche azul"}],"es":"En esta situación el primero en pasar debe ser:","explain":"EL COCHE ROJO. Una sola correcta.\n\nQUÉ VES. Un cruce SIN SEÑALES. El coche VERDE (en primer plano) lleva el intermitente IZQUIERDO. De frente viene un coche ROJO con el intermitente, que gira a SU derecha. Por la derecha del verde llega un coche AZUL que sigue recto.\n\nAVERIGUA QUIÉN NO TIENE A NADIE A SU DERECHA:\n• El ROJO: a su derecha no viene nadie, y gira a la derecha. No tiene que ceder a nadie.\n• El AZUL: tiene al rojo a su derecha. Cede al rojo.\n• El VERDE: tiene al azul a su derecha y, además, gira a la izquierda con el rojo de frente. Cede a los dos.\n\nORDEN: rojo, azul, verde.\n\n«EL VERDE» y «EL AZUL» son los cebos de quien mira solo a un par de coches.\n\nCLAVE: en cruces con tres coches, empieza por el que tiene la derecha libre. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6564,"bg":"При тази ситуация задължени ли сте да пропуснете синия автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67198.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Está obligado a ceder el paso al coche azul?","explain":"SÍ.\n\nQUÉ VES. Un cruce SIN SEÑALES. Vas RECTO. Por la DERECHA llega una furgoneta AZUL con el intermitente izquierdo, que va a girar a la izquierda.\n\nSIN SEÑALES MANDA LA DERECHA. El azul te llega por la derecha: le cedes, aunque él gire y tú vayas recto.\n\n«NO» es el cebo de quien aplica «el que gira cede» a un vehículo que llega por un lateral.\n\nCLAVE: compárala con la 6556. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6565,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68353.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"ceder al ROJO"},{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"ceder al AZUL"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el rojo"}],"es":"En esta situación debo: (2 correctas)","explain":"CEDER AL ROJO Y CEDER AL AZUL. Dos correctas.\n\nQUÉ VES. Un cruce SIN SEÑALES. Llevas el intermitente IZQUIERDO: vas a girar a la izquierda. De frente viene un coche AZUL. Por la DERECHA llega un coche ROJO.\n\nAL ROJO, POR LA DERECHA: te llega por la derecha.\n\nAL AZUL, POR EL GIRO: vas a girar a la izquierda y viene de frente.\n\n«PASAR ANTES QUE EL AZUL» y «PASAR ANTES QUE EL ROJO» son las respuestas al revés.\n\nCLAVE: girar a la izquierda sin señales = cedes a la derecha y a lo que viene de frente. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Giro a la izquierda»."},{"id":6566,"bg":"При тази ситуация съм с предимство защото се движа направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67328.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación tengo prioridad porque voy recto. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Un cruce SIN SEÑALES. Vas RECTO. Por la DERECHA llega una furgoneta AZUL con el intermitente izquierdo.\n\nIR RECTO NO DA PRIORIDAD. Frente a un vehículo que llega por un lateral decide la regla de la derecha, gire él hacia donde gire. El azul te llega por la derecha: pasa él.\n\n«CORRECTO» es el cebo: «porque voy recto» es una razón falsa.\n\nCLAVE: en los enunciados con «porque voy recto», casi siempre es неправилно. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6567,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68303.png","v":null,"a":[{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el AZUL"},{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el ROJO"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"ceder al azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"ceder al rojo"}],"es":"En esta situación debo: (2 correctas)","explain":"PASAR ANTES QUE EL AZUL Y PASAR ANTES QUE EL ROJO. Dos correctas.\n\nQUÉ VES. Un cruce SIN SEÑALES. Vas RECTO. Por tu IZQUIERDA llega una furgoneta AZUL que sigue recto. De frente viene un coche ROJO con el intermitente, que va a girar a SU izquierda cruzando tu trayectoria.\n\nAL AZUL LE PASAS: te llega por la izquierda; tú estás a su derecha.\n\nAL ROJO LE PASAS: gira a la izquierda y tú vienes de frente recto; el que gira a la izquierda cede al de frente.\n\n«CEDER AL AZUL» y «CEDER AL ROJO» son los cebos de quien cede «por si acaso».\n\nCLAVE: aquí nadie te llega por la derecha y el de frente gira a la izquierda: pasas tú primero. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6568,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67378.png","v":null,"a":[{"t":"синият автомобил, защото се намира отдясно","ok":true,"i":null,"es":"el azul porque está a la derecha"},{"t":"червеният автомобил, защото се движи направо","ok":false,"i":null,"es":"el rojo porque va recto"},{"t":"синият автомобил, защото завива надясно","ok":false,"i":null,"es":"el azul porque gira a la derecha"}],"es":"En esta situación tiene prioridad:","explain":"EL AZUL, PORQUE ESTÁ A LA DERECHA. Una sola correcta.\n\nQUÉ VES. Un cruce SIN SEÑALES. El coche AZUL (en primer plano) lleva el intermitente DERECHO y va a girar a la derecha. Por su IZQUIERDA llega un coche ROJO que sigue recto.\n\nEL AZUL ESTÁ A LA DERECHA DEL ROJO: el rojo le cede.\n\n«EL ROJO, PORQUE VA RECTO» es una razón falsa: ir recto no da prioridad.\n\n«EL AZUL, PORQUE GIRA A LA DERECHA» acierta el coche pero no la razón: girar a la derecha tampoco da prioridad por sí mismo.\n\nCLAVE: en las preguntas con «porque», la razón tiene que ser la correcta. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6569,"bg":"При тази ситуация трябва да пропусна червения автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68269.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación debo dejar pasar al coche rojo. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Un cruce SIN SEÑALES ni semáforo. Vas recto (flecha). Por tu IZQUIERDA llega un coche ROJO que sigue recto. Por tu DERECHA llega una furgoneta AZUL con el intermitente izquierdo, que va a girar.\n\nEL ROJO ESTÁ A TU IZQUIERDA. Sin señales manda la derecha: el rojo te tiene a ti a su derecha, así que es él quien te cede. El enunciado «debo dejar pasar al rojo» es falso.\n\nOJO CON LA FURGONETA AZUL: a ella sí tienes que cederle, porque te llega por la derecha. La pregunta no te pregunta por ella; es para que no te distraigas.\n\nCLAVE: «me llega por mi ventanilla izquierda» = me cede a mí.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Regla de la derecha»."},{"id":6570,"bg":"При тази ситуация синият автомобил, е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67411.png","v":null,"a":[{"t":"без предимство","ok":true,"i":null,"es":"no tiene prioridad"},{"t":"с предимство","ok":false,"i":null,"es":"tiene prioridad"}],"es":"En esta situación el coche azul:","explain":"SIN PRIORIDAD. Una sola correcta.\n\nQUÉ VES. Un cruce SIN SEÑALES. Llevas el intermitente IZQUIERDO y vas a girar a la izquierda. Por tu IZQUIERDA llega un coche AZUL que sigue recto.\n\nEL AZUL TE TIENE A TI A SU DERECHA, así que te cede.\n\n«CON PRIORIDAD» es el cebo de quien piensa que el que gira a la izquierda siempre cede. Eso vale frente a lo que viene de FRENTE; el azul llega por un lateral.\n\nCLAVE: el giro a la izquierda no te quita la derecha. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6571,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68203.png","v":null,"a":[{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"ceder al azul"},{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el rojo"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"ceder al rojo"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"}],"es":"En esta situación debo: (2 correctas)","explain":"⚠️ TRAMPA color: cedes al AZUL, pasas antes que el ROJO. Inverso a otros — la imagen determina cuál tiene prioridad."},{"id":6572,"bg":"При тази ситуация пропускам червения автомобил защото:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67574.png","v":null,"a":[{"t":"се намира от дясната ми страна","ok":true,"i":null,"es":"está a mi DERECHA"},{"t":"пътят, по който се движа, няма продължение направо","ok":false,"i":null,"es":"el camino que llevo no tiene continuación recta"},{"t":"се движи по пътя, който продължава направо","ok":false,"i":null,"es":"circula por el camino que continúa recto"},{"t":"защото завива наляво","ok":false,"i":null,"es":"gira a la izquierda"}],"es":"En esta situación cedo el paso al rojo porque:","explain":"PORQUE ESTÁ A MI DERECHA. Una sola correcta.\n\nQUÉ VES. Un cruce en T SIN SEÑALES. Llegas por la calle que se termina y vas a girar a la IZQUIERDA. Por la DERECHA, por la calle que sigue, llega una furgoneta ROJA con el intermitente.\n\nSIN SEÑALES, AUNQUE SEA UNA T, DECIDE LA DERECHA. El rojo te llega por la derecha: le cedes.\n\n«EL CAMINO QUE LLEVO NO TIENE CONTINUACIÓN RECTA» y «CIRCULA POR EL CAMINO QUE CONTINÚA RECTO» son los cebos: en Bulgaria la forma del cruce (una T) no da prioridad; hace falta una señal.\n\n«PORQUE GIRA A LA IZQUIERDA» no es razón para cederle a nadie.\n\nCLAVE: la vía que «continúa» no es preferente si no hay señal. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6573,"bg":"При тази ситуация трябва да премина след:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68203.png","v":null,"a":[{"t":"синия автомобил","ok":true,"i":null,"es":"el coche azul"},{"t":"червения автомобил","ok":false,"i":null,"es":"el coche rojo"}],"es":"En esta situación debo pasar después de:","explain":"DESPUÉS DEL COCHE AZUL.\n\nQUÉ VES. Un cruce SIN SEÑALES ni semáforo. Vas recto (flecha). Por tu IZQUIERDA llega un coche ROJO; por tu DERECHA, un coche AZUL.\n\nSIN SEÑALES MANDA LA DERECHA. El azul te llega por la derecha: pasa antes que tú. El rojo te llega por la izquierda: para él tú eres el de la derecha, así que él pasa después de ti.\n\n«DESPUÉS DEL ROJO» es el cebo de lateralidad: el rojo está más visible en la imagen, pero llega por tu ventanilla izquierda.\n\nLA PREGUNTA ESTÁ DADA LA VUELTA: no pregunta a quién cedes, sino detrás de quién pasas. Es lo mismo: pasas detrás de aquel al que cedes.\n\nCLAVE: «debo pasar después de…» = ¿quién está a mi derecha?\n\nMÉTODO: 1) ¿hay agente, semáforo o señales? No. 2) ¿quién me llega por la derecha? Ese pasa primero. Ver Leyes → «Regla de la derecha»."},{"id":6574,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68169.png","v":null,"a":[{"t":"да пропусна мотоциклетиста","ok":true,"i":null,"es":"ceder al MOTORISTA"},{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el ROJO"},{"t":"да премина преди мотоциклетиста","ok":false,"i":null,"es":"pasar antes que el motorista"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"ceder al rojo"}],"es":"En esta situación debo: (2 correctas)","explain":"⚠️ TRAMPA: cedes al MOTORISTA (tiene prioridad) y pasas antes que el ROJO. Las motos tienen exactamente las mismas reglas de prioridad que los coches."},{"id":6575,"bg":"При тази ситуация преминавам с предимство, защото се движа направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68039.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación tengo prioridad porque voy recto. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Un cruce SIN SEÑALES. Vas RECTO. Por la DERECHA llega un CAMIÓN con el intermitente izquierdo. De frente viene un coche rojo que gira.\n\nIR RECTO NO DA PRIORIDAD. Frente a un vehículo que llega por un lateral decide la regla de la derecha, gire él hacia donde gire. El camión te llega por la derecha: pasa antes que tú.\n\n«CORRECTO» es el cebo: «porque voy recto» es una razón falsa.\n\nCLAVE: compárala con la 6566. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6576,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67906.png","v":null,"a":[{"t":"да пропусна лекия автомобил","ok":true,"i":null,"es":"ceder al TURISMO"},{"t":"да пропусна товарния автомобил","ok":true,"i":null,"es":"ceder al CAMIÓN"},{"t":"да премина преди лекия автомобил","ok":false,"i":null,"es":"pasar antes que el turismo"},{"t":"да премина преди товарния автомобил","ok":false,"i":null,"es":"pasar antes que el camión"}],"es":"En esta situación debo: (2 correctas)","explain":"⚠️ TRAMPA: cedes tanto al TURISMO como al CAMIÓN. Ambos tienen prioridad. El tamaño del vehículo no determina la prioridad."},{"id":6577,"bg":"При тази ситуация преминавам едновременно с червения автомобил и не съм задължен да пропусна синия автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67757.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación paso simultáneamente con el rojo y no tengo que ceder al azul. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Un cruce SIN SEÑALES. Vas RECTO. De frente viene un coche ROJO. Por la DERECHA llega una furgoneta AZUL.\n\nLA SEGUNDA PARTE ES FALSA. Puedes cruzarte con el rojo a la vez si ninguno corta la trayectoria del otro, pero el azul te llega por la derecha y tienes que cederle.\n\n«CORRECTO» es el cebo: la primera mitad de la frase suena bien y arrastra a la segunda.\n\nCLAVE: en los enunciados con dos afirmaciones, basta con que una sea falsa. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6578,"bg":"При тази ситуация червеният автомобил е с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67674.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación el coche rojo tiene prioridad. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Un cruce SIN SEÑALES. El coche AZUL (en primer plano) lleva el intermitente IZQUIERDO y va a girar a la izquierda. Por su IZQUIERDA llega un coche ROJO que sigue recto.\n\nEL ROJO TIENE AL AZUL A SU DERECHA: el rojo cede. Que el azul gire a la izquierda no cambia nada, porque el rojo no viene de frente.\n\n«CORRECTO» es el cebo de «el que gira a la izquierda siempre cede».\n\nCLAVE: compárala con la 6570. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6581,"bg":"След подаването на този сигнал от светофара:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/103424.png","v":null,"a":[{"t":"навлизането в кръстовището е забранено","ok":true,"i":null,"es":"está PROHIBIDO entrar en la intersección"},{"t":"трябва да се подготвя за потегляне","ok":true,"i":null,"es":"debo prepararme para ARRANCAR"},{"t":"може да завия надясно, но с повишено внимание","ok":false,"i":null,"es":"se puede girar a la derecha con precaución"},{"t":"навлизането в кръстовището е разрешено","ok":false,"i":null,"es":"está PERMITIDO entrar"}],"es":"Después de esta señal del semáforo: (2 correctas)","explain":"ESTÁ PROHIBIDO ENTRAR EN LA INTERSECCIÓN Y DEBO PREPARARME PARA ARRANCAR. Dos correctas.\n\nQUÉ VES. El semáforo de la derecha tiene encendidas a la vez la luz ROJA y la ÁMBAR.\n\nROJO + ÁMBAR = «PREPÁRATE, PERO TODAVÍA NO». Mientras el rojo siga encendido no puedes entrar. El ámbar añadido anuncia que va a llegar el verde: es el momento de preparar el arranque.\n\n«ESTÁ PERMITIDO ENTRAR» es falso mientras el rojo esté encendido.\n\n«SE PUEDE GIRAR A LA DERECHA CON PRECAUCIÓN» es el cebo: no hay flecha verde adicional que lo permita.\n\nCLAVE: rojo + ámbar = sigues parado, pero te preparas.\n\nMÉTODO: 1) ¿qué luces están encendidas? 2) ¿está el rojo? Entonces no entro. 3) ¿le acompaña el ámbar? Me preparo. Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":6582,"bg":"При този немигащ сигнал на светофара:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/103275.png","v":null,"a":[{"t":"е забранено да премина през кръстовището","ok":true,"i":null,"es":"está prohibido pasar por la intersección"},{"t":"мога да премина, но с повишено внимание","ok":false,"i":null,"es":"puedo pasar pero con precaución"},{"t":"преминаването е разрешено само за пешеходци","ok":false,"i":null,"es":"el paso está permitido solo para peatones"}],"es":"Con esta señal fija del semáforo:","explain":"ESTÁ PROHIBIDO PASAR POR LA INTERSECCIÓN. Una sola correcta.\n\nQUÉ VES. El semáforo de la derecha con la luz ÁMBAR FIJA encendida (sin parpadear).\n\nÁMBAR FIJO = «ATENCIÓN, PARA». Prohíbe entrar en el cruce, salvo a quien ya está tan cerca que no puede detenerse con seguridad.\n\n«PUEDO PASAR CON PRECAUCIÓN» describe el ámbar INTERMITENTE, que indica un cruce no regulado. Fijo e intermitente son dos señales distintas del mismo color: esa es la trampa.\n\n«SOLO PUEDEN PASAR LOS PEATONES» no tiene sentido: los peatones tienen sus propios semáforos.\n\nCLAVE: ámbar fijo = para; ámbar intermitente = pasa con precaución.\n\nMÉTODO: 1) ¿qué color? 2) ¿fijo o intermitente? 3) fijo = prohibido entrar. Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":6583,"bg":"При този немигащ сигнал на светофара навлизането в кръстовището е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/103326.png","v":null,"a":[{"t":"забранено освен в случаите, когато не можем да спрем, без да създадем опасност за движението","ok":true,"i":null,"es":"prohibido excepto cuando no puedes parar sin crear peligro"},{"t":"разрешено, без ограничения","ok":false,"i":null,"es":"permitido sin restricciones"},{"t":"забранено във всички случаи","ok":false,"i":null,"es":"prohibido en todos los casos"}],"es":"Con esta señal fija del semáforo, entrar en la intersección está:","explain":"⚠️ TRAMPA IMPORTANTE: el semáforo amarillo fijo (no el rojo) prohíbe entrar EXCEPTO si ya no puedes frenar con seguridad. Si el frenado sería más peligroso que continuar, puedes pasar."},{"id":6588,"bg":"Този знак изисква от водачите да спрат:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55422.png","v":null,"a":[{"t":"винаги, независимо дали по пресичания път се движи превозно средство","ok":true,"i":null,"es":"siempre, independientemente de si hay vehículos en la vía cruzada"},{"t":"само ако по пресичания път се движи превозно средство","ok":false,"i":null,"es":"solo si hay vehículos en la vía cruzada"},{"t":"ако те преценят, че е необходимо","ok":false,"i":null,"es":"si el conductor lo considera necesario"}],"es":"Esta señal obliga a los conductores a parar:","explain":"SIEMPRE, INDEPENDIENTEMENTE DE SI HAY VEHÍCULOS EN LA VÍA QUE CRUZAS. Una sola correcta.\n\nQUÉ VES. Un cruce. En tu poste, la señal octogonal roja de STOP. En los otros accesos se ven rombos de vía con prioridad.\n\nSTOP = DETENCIÓN OBLIGATORIA. Tienes que pararte del todo antes de entrar en el cruce, venga alguien o no. Después cedes a los que circulan por la vía principal.\n\n«SOLO SI HAY VEHÍCULOS EN LA VÍA QUE CRUZAS» es el cebo: eso sería el ceda el paso.\n\n«SI EL CONDUCTOR LO CONSIDERA NECESARIO» convierte la obligación en una opción.\n\nCLAVE: ceda el paso = cedo si viene alguien; STOP = paro siempre y luego cedo. Ver Leyes → «Vía con prioridad»."},{"id":6589,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56379.png","v":null,"a":[{"t":"трябва да спра, преди да премина през кръстовището","ok":true,"i":null,"es":"debo parar antes de cruzar la intersección"},{"t":"мога да премина, без да спирам, но трябва да пропусна ППС от другия път","ok":false,"i":null,"es":"puedo pasar sin parar pero cediendo el paso"},{"t":"мога да премина без да спирам, ако няма други ППС","ok":false,"i":null,"es":"puedo pasar sin parar si no hay otros vehículos"}],"es":"En esta situación:","explain":"Señal de STOP (octágono rojo) = parada obligatoria completa antes de cruzar, aunque no haya vehículos. No es ceda el paso — es parada total obligatoria."},{"id":6590,"bg":"При тази ситуация мога да премина без да спирам, при условие, че пропусна синия автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56446.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación puedo pasar sin detenerme si cedo al azul. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Tienes una señal de STOP. Vas RECTO. Por la IZQUIERDA, por la vía principal, llega un coche AZUL.\n\nCON STOP HAY QUE PARAR SIEMPRE. Ceder al azul es obligatorio, pero no basta: antes tienes que detenerte por completo, aunque veas que puedes pasar después de él.\n\n«CORRECTO» es el cebo: describe lo que harías con un ceda el paso, no con un STOP.\n\nCLAVE: STOP = parada total + ceder. Compárala con la 6588. Ver Leyes → «Vía con prioridad»."},{"id":6591,"bg":"При тази ситуация трябва ли да спрете, преди да преминете през кръстовището?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56497.png","v":null,"a":[{"t":"да, при наличие на този пътен знак съм задължен да спра","ok":true,"i":null,"es":"sí, la señal presente obliga a parar"},{"t":"не, защото червеният автомобил завива надясно","ok":false,"i":null,"es":"no, porque el rojo gira a la derecha"}],"es":"En esta situación ¿debe parar antes de cruzar la intersección?","explain":"SÍ, LA SEÑAL PRESENTE OBLIGA A PARAR. Una sola correcta.\n\nQUÉ VES. Vas RECTO. En tu poste hay una señal de STOP. Por la izquierda, un coche ROJO está dando la vuelta en el cruce.\n\nSTOP = PARADA SIEMPRE, haga lo que haga el otro vehículo.\n\n«NO, PORQUE EL ROJO GIRA A LA DERECHA» es el cebo: lo que hagan los demás no anula la obligación de detenerte ante el STOP (y además el rojo no gira a la derecha, está dando la vuelta).\n\nCLAVE: STOP = parar del todo, siempre. Compárala con la 6588.  Ver Leyes → «Vía con prioridad»."},{"id":6592,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56596.png","v":null,"a":[{"t":"е разрешено да премина, без да спирам, но трябва да пропусна ППС от другия път","ok":true,"i":null,"es":"está permitido pasar sin parar pero cediendo al tráfico del otro camino"},{"t":"задължен съм да спра, преди да премина през кръстовището","ok":false,"i":null,"es":"estoy obligado a parar antes de cruzar"},{"t":"мога да премина без да спирам, защото пътят, по който се движа, е с предимство","ok":false,"i":null,"es":"puedo pasar sin parar porque estoy en vía preferente"}],"es":"En esta situación:","explain":"ESTÁ PERMITIDO PASAR SIN PARAR, PERO CEDIENDO A LOS VEHÍCULOS DEL OTRO CAMINO. Una sola correcta.\n\nQUÉ VES. Vas RECTO. En tu poste hay un CEDA EL PASO (triángulo invertido). Por la DERECHA, por la vía principal, llega una furgoneta AZUL.\n\nCEDA EL PASO ≠ STOP. No estás obligado a detenerte si no viene nadie; sí estás obligado a dejar pasar a los que circulan por la vía principal, como el azul.\n\n«ESTOY OBLIGADO A PARAR» es el cebo: eso es el STOP.\n\n«PUEDO PASAR SIN PARAR PORQUE ESTOY EN VÍA PREFERENTE» es el error contrario: con un ceda el paso, la preferente es la otra.\n\nCLAVE: ceda el paso = paro solo si hace falta para ceder.  Ver Leyes → «Vía con prioridad»."},{"id":6593,"bg":"При тази ситуация автомобилът, който се движи направо, е с предимство пред автомобила, който завива надясно.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62980.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación el vehículo que va recto tiene prioridad sobre el que gira a la derecha. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Señal de VÍA CON PRIORIDAD con PANEL: el trazo GRUESO une el acceso de ABAJO con el de la IZQUIERDA. Por abajo, un coche AMARILLO con el intermitente DERECHO va a girar a la derecha. Por la izquierda, sobre la rama gruesa, una furgoneta ROJA sigue recto.\n\nLOS DOS ESTÁN EN LA VÍA CON PRIORIDAD, así que entre ellos decide la regla de la derecha. El amarillo está a la derecha del rojo: el amarillo pasa primero, aunque gire.\n\n«CORRECTO» es el cebo de quien cree que el que va recto siempre tiene preferencia sobre el que gira.\n\nCLAVE: ir recto no da prioridad; entre los de la preferente, la derecha. (Corrección: la traducción anterior del enunciado decía «el que gira a la izquierda»; el original búlgaro dice «el que gira a la DERECHA».) MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6594,"bg":"При този пътен знак:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56647.png","v":null,"a":[{"t":"е разрешено да премина, без да спирам, защото пътят, по който се движа, е с предимство","ok":true,"i":null,"es":"puedo pasar sin parar porque estoy en vía preferente"},{"t":"задължен съм да спра, преди да премина през кръстовището","ok":false,"i":null,"es":"debo parar antes de cruzar"},{"t":"мога да премина, без да спирам, но трябва да пропусна ППС от другия път","ok":false,"i":null,"es":"puedo pasar sin parar cediendo al tráfico del otro camino"}],"es":"Con esta señal:","explain":"PUEDO PASAR SIN PARAR PORQUE ESTOY EN VÍA PREFERENTE. Una sola correcta.\n\nQUÉ VES. Vas RECTO. En tu poste hay una señal de VÍA CON PRIORIDAD (rombo). Por la DERECHA, por la vía transversal, llega una furgoneta AZUL.\n\nEL ROMBO TE DA PREFERENCIA. Los de la otra vía tienen que cederte el paso, aunque vengan por tu derecha.\n\n«DEBO PARAR ANTES DE CRUZAR» es el STOP.\n\n«PUEDO PASAR SIN PARAR CEDIENDO AL TRÁFICO DEL OTRO CAMINO» es el ceda el paso.\n\nCLAVE: rombo = preferencia; triángulo invertido = cedes; octógono = paras. Compárala con la 6592 y la 6596.  Ver Leyes → «Vía con prioridad»."},{"id":6595,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57101.png","v":null,"a":[{"t":"лекият автомобил, защото се движи по пътя с предимство","ok":true,"i":null,"es":"el turismo porque circula por la vía preferente"},{"t":"мотоциклетистът, защото се намира от дясната страна на лекия автомобил","ok":false,"i":null,"es":"el motorista porque está a la derecha del turismo"},{"t":"мотоциклетистът, защото се движи направо","ok":false,"i":null,"es":"el motorista porque va recto"}],"es":"En esta situación tiene prioridad:","explain":"El turismo está en la vía preferente = tiene prioridad. Ni la posición a la derecha ni ir recto superan la vía preferente."},{"id":6596,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56768.png","v":null,"a":[{"t":"е разрешено да премина, без да спирам","ok":true,"i":null,"es":"puedo pasar sin parar"},{"t":"пътят, по който се движа, е с предимство","ok":true,"i":null,"es":"estoy en vía preferente"},{"t":"ППС от другия път трябва да ме пропуснат","ok":true,"i":null,"es":"los del otro camino deben cederme el paso"},{"t":"задължен съм да спра, преди да премина през кръстовището","ok":false,"i":null,"es":"debo parar antes de cruzar"}],"es":"En esta situación: (3 correctas)","explain":"PUEDO PASAR SIN PARAR, ESTOY EN VÍA PREFERENTE Y LOS DEL OTRO CAMINO DEBEN CEDERME EL PASO. Tres correctas.\n\nQUÉ VES. La misma escena que la 6594: vas RECTO con la señal de VÍA CON PRIORIDAD; por la DERECHA llega una furgoneta AZUL por la vía transversal.\n\nLAS TRES CORRECTAS DICEN LO MISMO DESDE TRES ÁNGULOS: estás en la preferente, no tienes que parar y los de la otra vía te ceden.\n\n«DEBO PARAR ANTES DE CRUZAR» es el único cebo: eso es el STOP.\n\nCLAVE: rombo = preferencia sobre la vía transversal.  Ver Leyes → «Vía con prioridad»."},{"id":6597,"bg":"При тази ситуация трябва да пропусна товарния автомобил, защото се движи направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56964.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación debo dejar pasar al camión porque va recto. Esto es:","explain":"INCORRECTO, por dos motivos.\n\nQUÉ VES. En tu poste de la derecha hay una señal de VÍA CON PRIORIDAD (rombo amarillo), sin panel. Llevas el intermitente IZQUIERDO: vas a girar a la izquierda. Por la DERECHA llega un CAMIÓN azul que sigue recto por la vía transversal.\n\nPRIMER MOTIVO: NO DEBES CEDERLE. Tú circulas por la vía con prioridad; el camión llega por la transversal, que no la tiene. Es él quien te cede a ti, aunque tú gires a la izquierda.\n\nSEGUNDO MOTIVO: LA RAZÓN ES FALSA. Aunque tuvieras que cederle, no sería «porque va recto». Ir recto no da prioridad por sí mismo.\n\nY OJO AL TAMAÑO: ser un camión no da preferencia. El banco usa camiones y autobuses porque intimidan.\n\nCLAVE: en los enunciados con «porque…», evalúa la conclusión y la razón por separado. Si una de las dos falla, es неправилно.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Vía con prioridad»."},{"id":6598,"bg":"При тази ситуация преминавам преди синия автомобил защото се движа направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56819.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación paso antes que el coche azul porque voy recto. Esto es:","explain":"⚠️ TRAMPA: ir recto NO garantiza prioridad automáticamente. Depende de la señalización y la regla de la derecha. En esta situación específica la afirmación es INCORRECTA."},{"id":6599,"bg":"При тази ситуация съм с предимство, защото се движа направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56891.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación tengo prioridad porque voy recto. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Vas RECTO. En tu poste hay un CEDA EL PASO. Por la IZQUIERDA, por la vía principal, llega un coche AZUL que también sigue recto.\n\nTÚ LLEVAS CEDA EL PASO: el azul va por la principal y le cedes, aunque venga por tu izquierda y aunque vayas recto.\n\n«CORRECTO» es el cebo: «porque voy recto» nunca es una razón válida.\n\nCLAVE: con ceda el paso, cedes a todos los de la principal, vengan por donde vengan.  Ver Leyes → «Vía con prioridad»."},{"id":6602,"bg":"При приближаване към кръстовище водачът трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"своевременно да заеме пътна лента, която е предназначена за неговата посока на движение","ok":true,"i":null,"es":"colocarse a tiempo en el carril correcto para su dirección"},{"t":"да управлява с готовност за спиране","ok":true,"i":null,"es":"circular listo para frenar"},{"t":"да подаде звуков или светлинен сигнал, когато е с предимство","ok":false,"i":null,"es":"dar señal acústica/luminosa cuando tiene prioridad"},{"t":"да има готовност да пропусне преминаващи през платното за движение пешеходци","ok":true,"i":null,"es":"estar listo para ceder a peatones que cruzan"}],"es":"Al aproximarse a una intersección el conductor debe: (3 correctas)","explain":"⚠️ MULTIRESPUESTA: carril correcto + listo para frenar + listo para ceder a peatones. Dar señal acústica cuando tienes prioridad NO es obligatorio."},{"id":6603,"bg":"Разрешено ли е на водача на ППС да навлезе в кръстовище, ако обстановката ще го принуди да спре в кръстовището и да възпрепятства преминаването през него?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да, при разрешаващ сигнал на светофар","ok":false,"i":null,"es":"sí, con semáforo verde"},{"t":"да, но само когато се намира на пътя с предимство","ok":false,"i":null,"es":"sí, si estás en vía preferente"}],"es":"¿Está permitido entrar en una intersección si la situación le obligará a parar dentro?","explain":"NO — nunca entres en una intersección si vas a quedarte bloqueado dentro. El semáforo verde o la vía preferente no te eximen de esta regla."},{"id":6604,"bg":"Разрешено ли е да навлезете в кръстовище, ако преди да преминете ще се наложи да спрете в кръстовището?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не, ако по този начин ще възпрепятствам преминаването през него","ok":true,"i":null,"es":"no, si obstaculizarías el paso"},{"t":"не, ако изходът на кръстовището е зает и ще остана с превозното средство в кръстовището","ok":true,"i":null,"es":"no, si la salida está ocupada y quedarías dentro"},{"t":"да, когато се намирам на пътя с предимство","ok":false,"i":null,"es":"sí, si estás en vía preferente"},{"t":"да, винаги","ok":false,"i":null,"es":"sí, siempre"}],"es":"¿Está permitido entrar en la intersección si tendrías que parar dentro? (2 correctas son PROHIBICIONES)","explain":"Esta es una de las normas más importantes y más mal entendidas del examen: NUNCA debes entrar en una intersección si no tienes garantizado poder salir de ella antes de que cambie el semáforo o llegue tráfico transversal — aunque tu semáforo esté en verde. Esto se llama 'bloqueo de intersección' (čupене на кръстовище) y está prohibido en toda Bulgaria, igual que en la mayoría de países europeos. Pregúntate siempre: si el tráfico de delante está parado y la intersección se llena, ¿voy a quedar atrapado en medio cruzando otras vías? Si la respuesta es sí, debes quedarte esperando ANTES de la línea de stop, aunque tengas el semáforo a favor. Las dos excepciones donde SÍ puedes parar dentro son: si vas a girar y solo esperas el hueco para girar (no bloqueas el cruce transversal), o si un agente de tráfico te indica avanzar."},{"id":6605,"bg":"В кой от случаите водачът не трябва да навлиза в кръстовище?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"когато обстановката ще го принуди да спре в кръстовището, при което ще възпрепятства напречното движение","ok":true,"i":null,"es":"cuando tendría que parar en la intersección obstaculizando el paso"},{"t":"когато по напречния път приближава автомобил със специален режим на движение","ok":true,"i":null,"es":"cuando se acerca un vehículo de emergencia por la vía cruzada"},{"t":"когато преминаването се регулира от светофар със жълта мигаща светлина","ok":false,"i":null,"es":"cuando el semáforo tiene luz amarilla parpadeante"}],"es":"¿En qué casos el conductor NO debe entrar en la intersección? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: obstaculizar la intersección + vehículo de emergencia aproximándose. La luz amarilla parpadeante no prohíbe entrar — solo exige precaución."},{"id":6606,"bg":"Редът за преминаване на тези автомобили през кръстовището се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48346.png","v":null,"a":[{"t":"с правилото за „предимството на дясностоящия”","ok":true,"i":null,"es":"la regla de prioridad a la derecha"},{"t":"в зависимост от посоката на движение на автомобилите","ok":false,"i":null,"es":"la dirección de circulación"}],"es":"El orden de paso de estos coches en la intersección lo determinan:","explain":"Sin señalización = regla de la derecha. La dirección de marcha no determina la prioridad en intersecciones no señalizadas."},{"id":6607,"bg":"Редът за преминаване на тези автомобили през кръстовището се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48363.png","v":null,"a":[{"t":"с правилото за „предимството на дясностоящия”","ok":true,"i":null,"es":"la regla de la derecha"},{"t":"в зависимост от посоката на движение на автомобилите","ok":false,"i":null,"es":"la dirección de los vehículos"}],"es":"El orden de paso de estos vehículos lo determinan:","explain":"CON LA REGLA DE LA DERECHA. Una sola correcta.\n\nQUÉ VES. El coche AMARILLO (en primer plano) tiene un CEDA EL PASO con PANEL: el trazo GRUESO baja desde ARRIBA y gira a la IZQUIERDA. El amarillo llega por la rama fina de abajo. Por la DERECHA, también por una rama fina, llega un coche ROJO.\n\nLOS DOS ESTÁN EN LA SECUNDARIA. La señal no los separa entre sí, así que entre ellos decide la regla de la derecha: el rojo, que está a la derecha del amarillo, pasa primero.\n\n«LA DIRECCIÓN DE LOS VEHÍCULOS» no decide el orden de paso.\n\nCLAVE: el ceda el paso solo ordena frente a la rama gruesa; entre ramas finas, la derecha. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6608,"bg":"При тази ситуация, при преминаване през кръстовището, трябва да се съобразявате:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51516.png","v":null,"a":[{"t":"със сигнала на светофара","ok":true,"i":null,"es":"la señal del semáforo"},{"t":"с пьтния знак за задължителна посока за движение в кръстовището","ok":true,"i":null,"es":"la señal de dirección obligatoria en la intersección"},{"t":"с пьтния знак относно предимството","ok":false,"i":null,"es":"la señal de prioridad"}],"es":"En esta situación, al pasar por la intersección debes atenerte a: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: cuando hay semáforo Y señal de dirección obligatoria, ambos son vinculantes. La señal de prioridad queda subordinada a estos dos."},{"id":6612,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53713.png","v":null,"a":[{"t":"спирам, за да изчакам разрешаващ сигнал от регулировчика","ok":true,"i":null,"es":"paro para esperar señal de paso del agente"},{"t":"пропускам синия автомобил и преминавам след него","ok":false,"i":null,"es":"dejo pasar al coche azul y paso después"},{"t":"преминавам преди синия автомобил","ok":false,"i":null,"es":"paso antes que el coche azul"}],"es":"En esta situación:","explain":"Cuando hay agente, esperamos su señal. Nada de decidir independientemente quién pasa primero — el agente dirige."},{"id":6668,"bg":"Преминавайки през кръстовището при този сигнал на регулировчика няма да извърша нарушение, при условие, че:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54674.png","v":null,"a":[{"t":"преди подаването на този сигнал е било разрешено преминаването ми","ok":true,"i":null,"es":"antes de la señal me estaba permitido pasar"},{"t":"в момента на подаването на сигнала съм толкова близо, че не мога да спра безопасно","ok":true,"i":null,"es":"en el momento de la señal estoy tan cerca que no puedo parar con seguridad"},{"t":"подам звуков или светлинен сигнал за това, че ще премина през кръстовището","ok":false,"i":null,"es":"doy una señal acústica o luminosa de que voy a pasar"}],"es":"Al pasar por la intersección con esta señal del agente no cometo infracción si: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: puedes continuar si ya tenías paso autorizado ANTES de la señal o si estás tan cerca que frenar sería peligroso. Tocar el claxon NO te da derecho a pasar."},{"id":6673,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53658.png","v":null,"a":[{"t":"спирам, за да изчакам разрешаващ сигнал от регулировчика","ok":true,"i":null,"es":"paro para esperar señal del agente"},{"t":"спирам, за да пропусна червения автомобил и преминавам след него","ok":false,"i":null,"es":"paro para dejar al rojo y paso después"},{"t":"преминавам преди червения автомобил, защото съм отдясно и се движа по път с предимство","ok":false,"i":null,"es":"paso antes que el rojo porque estoy a la derecha y en vía preferente"}],"es":"En esta situación:","explain":"PARO PARA ESPERAR LA SEÑAL QUE ME PERMITA PASAR DEL AGENTE. Una sola correcta.\n\nQUÉ VES. En el cruce hay un AGENTE de pie, de CARA a ti (te muestra el pecho), con los brazos bajados. A la derecha hay un rombo y una señal azul de dirección obligatoria (recto o derecha). Llevas el intermitente DERECHO. Por la izquierda hay un coche ROJO.\n\nAGENTE DE CARA = PROHIBIDO PASAR. Mientras te muestre el pecho, esperas. El agente manda sobre las señales, así que el rombo no te sirve.\n\n«PARO PARA DEJAR PASAR AL ROJO Y PASO DESPUÉS» es el cebo: no pasas cuando se va el rojo, sino cuando el agente te lo permita.\n\n«PASO ANTES QUE EL ROJO PORQUE ESTOY A LA DERECHA Y EN VÍA PREFERENTE» ignora al agente.\n\nCLAVE: con agente, lo que cuenta es su posición respecto a ti. Ver Leyes → «Quién manda sobre quién»."},{"id":6674,"bg":"Преминавайки през кръстовището при този сигнал на регулировчика няма да извърша нарушение, при условие, че:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54571.png","v":null,"a":[{"t":"преди подаването на този сигнал е било разрешено преминаването ми","ok":true,"i":null,"es":"antes de la señal me estaba permitido pasar"},{"t":"в момента на подаването на сигнала съм толкова близо, че не мога да спра безопасно","ok":true,"i":null,"es":"en el momento de la señal estoy tan cerca que no puedo parar con seguridad"},{"t":"подам звуков или светлинен сигнал за това, че ще премина през кръстовището","ok":false,"i":null,"es":"doy señal acústica o luminosa"}],"es":"Al pasar por la intersección con esta señal del agente no cometo infracción si: (2 correctas)","explain":"ANTES DE LA SEÑAL ME ESTABA PERMITIDO PASAR, Y ESTOY TAN CERCA QUE NO PUEDO PARAR CON SEGURIDAD. Dos correctas.\n\nQUÉ VES. Un AGENTE en el cruce con el BRAZO LEVANTADO hacia arriba (con la porra en alto).\n\nEL BRAZO EN ALTO ES COMO EL ÁMBAR. Significa «atención, prohibido entrar» para todos, salvo para quien ya no puede detenerse con seguridad. Por eso no cometes infracción si se dan las dos condiciones: ya tenías permitido pasar antes de esa señal, y estás tan cerca que frenar sería peligroso.\n\n«DOY SEÑAL ACÚSTICA O LUMINOSA DE QUE VOY A PASAR» es el cebo: el claxon o las luces avisan, pero no te dan ningún derecho. Avisar no convierte una infracción en una maniobra permitida.\n\nCLAVE: brazo en alto = ámbar; solo sigue quien no puede parar con seguridad.\n\nMÉTODO: 1) ¿qué me permitía el agente antes? 2) ¿puedo parar sin peligro? 3) si puedo, paro. Ver Leyes → «Quién manda sobre quién»."},{"id":6679,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62132.png","v":null,"a":[{"t":"червеният автомобил","ok":false,"i":null,"es":"el coche rojo"},{"t":"жълтият автомобил","ok":true,"i":null,"es":"el coche amarillo"}],"es":"En esta situación tiene prioridad:","explain":"EL COCHE AMARILLO. Una sola correcta.\n\nQUÉ VES. Una ROTONDA con la señal azul de rotonda, pero SIN señal de ceda el paso en la entrada. El coche AMARILLO va a entrar. El coche ROJO ya circula por el anillo y se acerca por la IZQUIERDA del amarillo.\n\nSIN CEDA EL PASO EN LA ENTRADA, DECIDE LA REGLA DE LA DERECHA. El amarillo está a la derecha del rojo, así que tiene preferencia, aunque el rojo ya esté dentro.\n\n«EL ROJO» es el cebo de quien da por hecho que el que está dentro de una rotonda siempre tiene preferencia. Eso solo ocurre cuando la entrada tiene ceda el paso (compárala con la 6506).\n\nCLAVE: rotonda con ceda el paso en la entrada = el de dentro primero; rotonda sin él = la derecha (el que entra). MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha. Ver Leyes → «Regla de la derecha»."},{"id":6680,"bg":"При тази ситуация трябва да премина преди червения автомобил защото:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64639.png","v":null,"a":[{"t":"съм на пътя с предимство","ok":true,"i":null,"es":"estoy en vía preferente"},{"t":"се движа направо","ok":false,"i":null,"es":"voy recto"},{"t":"червеният автомобил завива наляво","ok":false,"i":null,"es":"el rojo gira a la izquierda"}],"es":"En esta situación paso antes que el rojo porque:","explain":"PORQUE ESTOY EN VÍA PREFERENTE. Una sola correcta.\n\nQUÉ VES. Vas RECTO. A la derecha hay una señal de VÍA CON PRIORIDAD con PANEL: el trazo GRUESO sube desde tu posición y gira a la DERECHA. De frente, por una rama fina, viene un coche ROJO con el intermitente.\n\nEL ROJO VIENE DE LA SECUNDARIA Y TÚ DE LA PREFERENTE. Por eso pasas antes que él.\n\n«PORQUE VOY RECTO» es una razón falsa: ir recto no da prioridad.\n\n«PORQUE EL ROJO GIRA A LA IZQUIERDA» sería la razón entre dos vehículos de la misma vía; aquí lo que decide es la señal.\n\nCLAVE: si la señal os separa, la razón es la señal. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6716,"bg":"Как трябва да постъпите при тази ситуация, ако водачът на червения автомобил, който трябва да ви пропусне, не показва с действията си, че ще спре?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51552.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir la velocidad"},{"t":"трябва да управлявам с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"не съм длъжен да се съобразявам с него, защото съм с предимство","ok":false,"i":null,"es":"no tengo que considerarlo porque tengo prioridad"}],"es":"¿Cómo actúas si el conductor del rojo (que debe cederte el paso) no lo hace? (2 correctas)","explain":"DEBO REDUCIR LA VELOCIDAD Y DEBO CIRCULAR LISTO PARA FRENAR. Dos correctas.\n\nQUÉ VES. Un cruce con SEMÁFORO en VERDE; encima del semáforo hay una señal de STOP. Vas RECTO. De frente viene un coche ROJO con el intermitente, que va a girar a SU izquierda cruzando tu trayectoria.\n\nEL SEMÁFORO MANDA SOBRE EL STOP: con verde no tienes que detenerte. El rojo, que gira a la izquierda, debe cederte el paso, pero la pregunta dice que no da señales de ir a parar.\n\nTENER PREFERENCIA NO TE PROTEGE DEL CHOQUE. Si el que debe cederte no da señales de detenerse, reduces y vas listo para frenar.\n\n«NO TENGO QUE CONSIDERARLO PORQUE TENGO PRIORIDAD» es el cebo: tener razón no sirve de nada después de un choque.\n\nCLAVE: si el otro no frena, frenas tú. Compárala con la 6465. Ver Leyes → «Quién manda sobre quién»."},{"id":7962,"bg":"При тази ситуация задължени ли сте да пропуснете товарния автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64917864.png","v":null,"a":[{"t":"да, независимо от посоката, в която ще продължи да се движи","ok":true,"i":null,"es":"sí, independientemente de la dirección en que continúe"},{"t":"зависи от посоката, в която ще продължи да се движи","ok":false,"i":null,"es":"depende de la dirección"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"En esta situación ¿está obligado a ceder el paso al camión?","explain":"SÍ, INDEPENDIENTEMENTE DE LA DIRECCIÓN EN QUE CONTINÚE.\n\nQUÉ VES. Vas recto (flecha). En el poste de la derecha hay una señal de VÍA CON PRIORIDAD con PANEL: el trazo GRUESO sube desde tu posición y gira a la DERECHA. Por la derecha llega un CAMIÓN azul. En los accesos de la izquierda y de enfrente hay señales de ceda el paso.\n\nLOS DOS ESTÁIS EN LA VÍA CON PRIORIDAD. El trazo grueso une tu acceso con el del camión. Entre dos vehículos que circulan por la preferente decide la regla de la derecha, y el camión está a tu derecha: pasa él primero.\n\nNO DEPENDE DE ADÓNDE VAYA ÉL. El orden de paso se decide por la vía y la posición, no por la trayectoria que el otro vaya a tomar.\n\n«DEPENDE DE LA DIRECCIÓN» es el cebo: parece lógico pensar que, si gira hacia otro lado, no te estorba. Pero el orden de paso no cambia según su maniobra.\n\n«NO» ignora el panel: si solo miraras el rombo, creerías que tienes prioridad sobre todos.\n\nCLAVE: es la misma escena que la 7963, preguntada de otra forma.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":7963,"bg":"При тази ситуация задължени ли сте да пропуснете товарния автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64917897.png","v":null,"a":[{"t":"да, защото се намира на пътя с предимство","ok":true,"i":null,"es":"sí, porque está en la vía preferente"},{"t":"да, защото се намира отдясно","ok":true,"i":null,"es":"sí, porque está a su derecha"},{"t":"не, защото се движа направо","ok":false,"i":null,"es":"no, porque voy recto"}],"es":"En esta situación ¿está obligado a dejar pasar al camión? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: sí debes ceder — el camión está en vía preferente Y a tu derecha. Son dos razones independientes que justifican la prioridad del camión."},{"id":7964,"bg":"При тази ситуация червеният автомобил е с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64917931.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"CORRECTO"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"es":"En esta situación el coche rojo tiene prioridad. Esto es:","explain":"CORRECTO.\n\nQUÉ VES. Vas RECTO. A la derecha hay una señal de VÍA CON PRIORIDAD con PANEL: el trazo GRUESO sube desde tu posición y gira a la DERECHA. Por la derecha, sobre esa rama gruesa, llega un coche ROJO.\n\nLOS DOS ESTÁIS EN LA PREFERENTE y el rojo te llega por la derecha: entre vosotros decide la regla de la derecha y el rojo pasa primero.\n\n«INCORRECTO» es el cebo de quien solo ve el rombo y cree que tiene preferencia sobre todos.\n\nCLAVE: es la familia de la 7962 y la 7963. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":7965,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64917965.png","v":null,"a":[{"t":"трябва да премина преди лекия автомобил","ok":true,"i":null,"es":"debo pasar antes que el turismo"},{"t":"трябва да пропусна лекия автомобил, който се движи направо","ok":false,"i":null,"es":"debo ceder el paso al turismo que va recto"}],"es":"En esta situación:","explain":"DEBO PASAR ANTES QUE EL TURISMO. Una sola correcta.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO y vas a girar a la izquierda. A la derecha hay una señal de VÍA CON PRIORIDAD con PANEL: el trazo GRUESO sube desde tu posición y gira a la DERECHA; las ramas de la izquierda y de enfrente son finas. Por la IZQUIERDA, por la rama fina, llega un turismo ROJO que sigue recto.\n\nTÚ VIENES POR LA PREFERENTE Y EL ROJO POR LA SECUNDARIA. Aunque tú salgas de la preferente girando a la izquierda, el rojo te cede.\n\n«DEBO CEDER AL TURISMO QUE VA RECTO» es el cebo: ir recto no le da prioridad, y además viene por la secundaria.\n\nCLAVE: lo que decide es por qué rama llega cada uno, no hacia dónde va. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":7966,"bg":"При тази ситуация преминавам преди синия автомобил защото се движа направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64917998.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"es":"En esta situación paso antes que el azul porque voy recto. Esto es:","explain":"INCORRECTO.\n\nQUÉ VES. Vas RECTO. En tu poste hay un CEDA EL PASO con PANEL: el trazo GRUESO baja desde ARRIBA y gira a la DERECHA. Tú vienes por la rama fina de abajo. De frente, por la rama gruesa, viene un coche AZUL con el intermitente, que va a girar hacia la rama derecha.\n\nEL AZUL VA POR LA PREFERENTE Y TÚ LLEVAS CEDA EL PASO: le cedes, aunque tú vayas recto y él gire.\n\n«CORRECTO» es el cebo: «porque voy recto» es una razón falsa.\n\nCLAVE: compárala con la 6516: con la señal en contra, ir recto no te salva. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":7967,"bg":"При тази ситуация трябва да премина преди:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64918031.png","v":null,"a":[{"t":"синия автомобил","ok":true,"i":null,"es":"el coche azul"},{"t":"червения автомобил","ok":true,"i":null,"es":"el coche rojo"},{"t":"жълтия автомобил","ok":false,"i":null,"es":"el coche amarillo"}],"es":"En esta situación debes pasar antes que: (2 correctas)","explain":"ANTES QUE EL COCHE AZUL Y ANTES QUE EL COCHE ROJO. Dos correctas.\n\nQUÉ VES. Vas recto (flecha). En el poste de la derecha hay una señal de VÍA CON PRIORIDAD con PANEL: el trazo GRUESO sube desde tu posición y gira a la DERECHA. Por la derecha, sobre esa rama gruesa, llega un coche AMARILLO. Por la izquierda llega un coche AZUL y de frente uno ROJO; en sus accesos hay señales de ceda el paso.\n\nPASAS ANTES QUE LOS DE LA SECUNDARIA. El azul (izquierda) y el rojo (enfrente) vienen por las ramas finas del panel: no tienen prioridad y te ceden a ti.\n\nPERO NO ANTES QUE EL AMARILLO. El amarillo está, como tú, en la vía con prioridad (rama gruesa) y te llega por la derecha: entre vosotros decide la regla de la derecha y pasa él primero.\n\n«ANTES QUE EL AMARILLO» es el cebo para quien solo ve el rombo y no lee el panel.\n\nCLAVE: con panel, primero separa a los de la rama gruesa de los de las ramas finas. Los finos ceden; entre los gruesos, la derecha.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":11347,"bg":"При навлизане в тунел, на който началото е обозначено с пътен знак, водачът задължен ли е да включи късите светлини на автомобила?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"Al entrar en un túnel señalizado con señal de tráfico ¿está obligado el conductor a encender las luces?","explain":"SÍ — en túneles señalizados es obligatorio encender las luces al entrar, independientemente de la visibilidad. Es una norma de seguridad obligatoria."},{"id":11484,"bg":"При тази ситуация при определяне на реда за преминаване през кръстовището се прилагат следните правила:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/578632772.png","v":null,"a":[{"t":"през кръстовището преминават ППС, които имат разрешаващ сигнал от светофара","ok":true,"i":null,"es":"pasan los que tienen semáforo verde"},{"t":"ППС завиващо наляво пропуска насрещнодвижещото се","ok":true,"i":null,"es":"el que gira a la izquierda en verde cede al tráfico contrario"},{"t":"ППС на пътя с предимство, трябва да премине преди ППС от другия път","ok":false,"i":null,"es":"los de vía preferente pasan antes que los del otro camino"},{"t":"ППС преминаващи при разрешаващ сигнал, прилагат правилото за „предимството на дясностоящия”","ok":false,"i":null,"es":"los que tienen verde entre sí aplican la regla de la derecha"}],"es":"En esta situación con semáforo se aplican las siguientes reglas: (2 correctas)","explain":"PASAN LOS QUE TIENEN SEMÁFORO VERDE, Y EL QUE GIRA A LA IZQUIERDA EN VERDE CEDE AL TRÁFICO CONTRARIO. Dos correctas.\n\nQUÉ VES. Un cruce con SEMÁFORO en VERDE para el coche AMARILLO (en primer plano), que sigue recto; encima del semáforo hay una señal de STOP. De frente viene un coche AZUL con el intermitente, que gira a SU izquierda. Por la izquierda hay un coche rojo. En otros postes se ven rombos y ceda el paso.\n\nCUANDO FUNCIONA EL SEMÁFORO, MANDA EL SEMÁFORO. Pasan los que tienen verde, y las señales de prioridad (STOP, rombo, ceda el paso) quedan en segundo plano. Entre los que tienen verde a la vez, el que gira a la izquierda cede al que viene de frente.\n\n«LOS DE LA VÍA PREFERENTE PASAN ANTES» es el cebo: con semáforo, las señales de prioridad no deciden.\n\n«ENTRE LOS QUE TIENEN VERDE, LA REGLA DE LA DERECHA» es el otro cebo: los que tienen verde a la vez vienen de frente, y entre ellos decide el giro.\n\nCLAVE: semáforo > señales; con el mismo verde, el que gira a la izquierda espera. Ver Leyes → «Quién manda sobre quién»."},{"id":11588,"bg":"Задължен ли е водачът да изключи двигателя при принудително спиране в тунел?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, когато началото на тунела е обозначено с пътен знак","ok":true,"i":null,"es":"sí, cuando el inicio del túnel está señalizado"},{"t":"да, когато спирането не е кратковременно","ok":true,"i":null,"es":"sí, cuando la parada no es breve"},{"t":"да, независимо от причината за спирането и продължителността на спирането","ok":false,"i":null,"es":"sí, independientemente de la causa y duración"},{"t":"не","ok":false,"i":null,"es":"no"}],"es":"¿Está obligado a apagar el motor al parar forzosamente en túnel señalizado? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: túnel señalizado + parada no breve son las dos condiciones. No es independientemente de la duración (una parada muy breve puede no requerir apagar el motor)."},{"id":11618,"bg":"При тази ситуация посоката, в която на червения автомобил е разрешено да премине, се определя от:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123584872.png","v":null,"a":[{"t":"пътната маркировка","ok":false,"i":null,"es":"la marcación del pavimento"},{"t":"пътния знак","ok":true,"i":null,"es":"la señal de tráfico"},{"t":"светлинния сигнал","ok":false,"i":null,"es":"la señal luminosa"}],"es":"En esta situación la dirección en que el rojo puede continuar la determina:","explain":"LA SEÑAL DE TRÁFICO. Una sola correcta.\n\nQUÉ VES. Un cruce con SEMÁFORO en verde. Encima del semáforo hay una señal azul de DIRECCIÓN OBLIGATORIA: RECTO O DERECHA. En el suelo hay flechas pintadas en los carriles. El coche ROJO lleva el intermitente IZQUIERDO.\n\nLA SEÑAL VERTICAL MANDA SOBRE LA MARCA DEL SUELO. Las direcciones permitidas las fija la señal: recto o a la derecha. El rojo no puede girar a la izquierda aunque lo intente.\n\n«LA MARCACIÓN DEL PAVIMENTO» es el último escalón de la escalera.\n\n«LA SEÑAL LUMINOSA» (el semáforo) dice cuándo pasar, no hacia dónde, porque es un disco verde sin flechas.\n\nCLAVE: semáforo = cuándo; señal de dirección = hacia dónde; pintura = lo último. Compárala con la 6459. Ver Leyes → «Quién manda sobre quién»."},{"id":11891,"bg":"Когато мястото за спиране преди жп прелеза се определя по отношение на релсите, разстоянието от първата релса трябва да бъде:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не по-малко от 2 метра","ok":true,"i":null,"es":"no MENOS de 2 metros"},{"t":"не повече от 2 метра","ok":false,"i":null,"es":"no MÁS de 2 metros"},{"t":"възможно най-малкото","ok":false,"i":null,"es":"la menor posible"},{"t":"по преценка на водача","ok":false,"i":null,"es":"a criterio del conductor"}],"es":"La distancia de parada antes del paso a nivel respecto a los raíles debe ser:","explain":"⚠️ TRAMPA: MÍNIMO 2 metros (no máximo). 'No menos de' = mínimo. Parar a menos de 2m de los raíles es insuficiente e ilegal."},{"id":12053,"bg":"При тази ситуация трябва да:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"осигурите предимство на зеления автомобил","ok":true,"i":null,"es":"ceder el paso al coche verde"},{"t":"осигурите предимство на червения автомобил","ok":false,"i":null,"es":"ceder el paso al coche rojo"},{"t":"изчакате преминаването на велосипедиста","ok":true,"i":null,"es":"esperar al ciclista"}],"es":"En esta situación debes: (2 correctas)","explain":"⚠️ TRAMPA: cedes al verde Y esperas al ciclista. El rojo NO tiene prioridad aquí. Lee la situación con cuidado."},{"id":12054,"bg":"При тази ситуация трябва да намалите скоростта, с готовност за спиране заради:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"мотоциклета","ok":true,"i":null,"es":"la moto"},{"t":"синия автомобил","ok":false,"i":null,"es":"el coche azul"},{"t":"велосипедиста","ok":false,"i":null,"es":"el ciclista"}],"es":"En esta situación debe reducir velocidad con disposición de frenar por: (VIDEO)","explain":"🎬 VIDEO: La moto es el elemento de mayor riesgo en esta situación — puede estar en tu ángulo muerto o moverse imprevistamente. Siempre presta especial atención a las motos."},{"id":12055,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да намаля скоростта и при необходимост да спра","ok":true,"i":null,"es":"reducir velocidad y si es necesario parar"},{"t":"да осигуря предимство на автомобила, който се движи в кръстовището с кръгово движение","ok":true,"i":null,"es":"ceder el paso al vehículo que circula dentro de la glorieta"},{"t":"да включа десен пътепоказател","ok":false,"i":null,"es":"activar el intermitente derecho"}],"es":"¿Qué debe hacer en esta situación? (VIDEO - glorieta) ⚠️ 2 correctas","explain":"🎬 VIDEO ⚠️ MULTIRESPUESTA: Al entrar en glorieta: reduces velocidad Y cedes el paso a quien ya está dentro. El intermitente derecho NO se activa al entrar (se usa al salir)."},{"id":12056,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да спра в разделителната ивица между платната на релсовия път, където е спрял другият автомобил","ok":false,"i":null,"es":"parar en la mediana donde está parado el otro coche"},{"t":"да спра, преди да завия наляво","ok":true,"i":null,"es":"parar ANTES de girar a la izquierda"},{"t":"да завия наляво, за да не възпрепятствам движението на автомобилите зад мен","ok":false,"i":null,"es":"girar a la izquierda para no obstaculizar el tráfico de atrás"}],"es":"¿Qué debe hacer en esta situación? (VIDEO)","explain":"🎬 VIDEO: Debes PARAR antes de girar a la izquierda y esperar a que el semáforo/situación lo permita. Nunca bloquees el cruce ni la mediana. La seguridad es prioritaria sobre no obstaculizar."},{"id":12057,"bg":"Искате да продължите движението си направо. Как трябва да постъпите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"спирам непосредствено зад жълтото превозно средство","ok":false,"i":null,"es":"paro inmediatamente detrás del vehículo amarillo"},{"t":"спирам пред кръстовището","ok":true,"i":null,"es":"paro ANTES de la intersección"},{"t":"спирам между жълтото и синьото превозно средство","ok":false,"i":null,"es":"paro entre el amarillo y el azul"}],"es":"Quiere continuar recto. ¿Cómo debe actuar en esta situación? (VIDEO - semáforo)","explain":"🎬 VIDEO: Con el semáforo en rojo o la intersección bloqueada, debes parar ANTES de la línea de stop, no dentro de la intersección. Nunca bloquees el cruce."},{"id":12058,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"изчаквам на коловозите","ok":false,"i":null,"es":"espero sobre las vías"},{"t":"внимателно пресичам релсите","ok":false,"i":null,"es":"cruzo las vías con cuidado"},{"t":"изчаквам пред прелеза","ok":true,"i":null,"es":"espero ANTES del paso a nivel"}],"es":"¿Cuál es la actuación correcta en esta situación? (VIDEO - paso a nivel)","explain":"🎬 VIDEO: En un paso a nivel SIEMPRE debes esperar ANTES de las vías, nunca sobre ellas. Si el semáforo rojo continúa después del tren, puede venir otro tren."},{"id":12060,"bg":"Какъв е правилният начин на действие при тази ситуация? Спирам, изключвам двигателя и:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"напускам тунела през най-близкия авариен изход","ok":true,"i":null,"es":"abandono el túnel por la salida de emergencia más cercana"},{"t":"изчаквам в превозното средство на мястото на инцидента, докато пътят се освободи","ok":false,"i":null,"es":"espero en el vehículo hasta que se despeje la vía"},{"t":"спирам автомобила извън лентата за принудително спиране","ok":true,"i":null,"es":"paro el coche fuera del carril de emergencia"}],"es":"¿Cuál es la actuación correcta? Paro, apago el motor y... (VIDEO) ⚠️ 2 correctas","explain":"🎬 VIDEO ⚠️ MULTIRESPUESTA: en emergencia en túnel — apagas el motor Y sales por la salida de emergencia. No esperes dentro del vehículo. El coche debe quedar fuera del carril de emergencia."},{"id":12061,"bg":"На кое превозно средство трябва да осигурите предимство, преди да завиете надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на трактора","ok":false,"i":null,"es":"al tractor"},{"t":"на мотоциклета","ok":true,"i":null,"es":"a la moto"},{"t":"на превозните средства, идващи отляво","ok":true,"i":null,"es":"a los vehículos que vienen por la izquierda"}],"es":"¿A qué vehículo debes ceder el paso antes de girar a la derecha? (VIDEO) ⚠️ 2 correctas","explain":"🎬 VIDEO ⚠️ MULTIRESPUESTA: al girar a la derecha cedes el paso a la moto (ya en la intersección) Y a todo el tráfico que viene por la izquierda. El tractor va en tu misma dirección."},{"id":12062,"bg":"Искате да продължите по пътя с предимство. Какво трябва да очаквате при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"че децата ще слязат на платното за движение","ok":true,"i":null,"es":"que los niños bajen a la calzada"},{"t":"че микробусът ще продължи движението си по пътя с предимство","ok":false,"i":null,"es":"que el microbús continúe por la vía preferente"},{"t":"че водачът на червения автомобил няма да ме види навреме","ok":true,"i":null,"es":"que el conductor del coche rojo no me vea a tiempo"}],"es":"Quiere continuar por la vía preferente. ¿Qué debe esperar? (VIDEO) ⚠️ 2 correctas","explain":"🎬 VIDEO ⚠️ MULTIRESPUESTA: Los niños pueden bajar imprevistamente Y el coche rojo puede no verte. Aunque tengas preferencia, anticipa ambos peligros."}];